    public bool TryGetCompletedStatusSnapshot(
        out DesignConversionLocalArtifactDbStatusSnapshot? snapshot)
        => TryReadCompletedStatusSnapshot(VisualJudgeStatus, out snapshot);

    public bool TryGetImprovementLoopAttemptHistory(
        out DesignConversionImprovementLoopAttemptHistorySnapshot? snapshot)
    {
        snapshot = null;
        return Metadata is not null &&
               Metadata.TryGetValue(
                   ImprovementLoopRefMetadataKey,
                   out var outerLoopRef) &&
               Metadata.TryGetValue(
                   ImprovementLoopAttemptHistoryMetadataKey,
                   out var serializedSnapshot) &&
               TryReadImprovementLoopAttemptHistory(
                   serializedSnapshot,
                   out snapshot) &&
               snapshot is not null &&
               string.Equals(
                   snapshot.LoopRef,
                   outerLoopRef,
                   StringComparison.Ordinal);
    }

    public static bool TryBuildImprovementLoopAttemptHistory(
        string? loopRef,
        IReadOnlyList<DesignConversionImprovementLoopAttemptTelemetry>? attempts,
        out DesignConversionImprovementLoopAttemptHistorySnapshot? snapshot,
        out string? canonicalSnapshotJson)
    {
        snapshot = null;
        canonicalSnapshotJson = null;
        if (attempts is null ||
            attempts.Count == 0 ||
            attempts.Count > MaxImprovementLoopAttemptHistoryAttempts)
        {
            return false;
        }

        var items = attempts
            .Select(attempt => new DesignConversionImprovementLoopAttemptHistoryItem(
                AttemptNumber: attempt.AttemptNumber,
                CandidateRef: attempt.CandidateRef,
                JobRef: attempt.JobRef,
                RequestRef: attempt.RequestRef,
                StopReason: attempt.StopReason,
                ShouldContinue: attempt.ShouldContinue,
                BestScore: attempt.BestScore,
                RequiredScore: attempt.RequiredScore,
                EstimatedCostUsd: attempt.EstimatedCostUsd,
                BudgetUsd: attempt.BudgetUsd,
                PolicyAttemptCount: attempt.PolicyAttemptCount,
                MaxImprovementCandidates: attempt.MaxImprovementCandidates,
                RenderResultRefs: attempt.RenderResultRefs,
                ComparisonArtifactRefs: attempt.ComparisonArtifactRefs,
                VisualJudgeResultRefs: attempt.VisualJudgeResultRefs,
                EvidenceRefs: attempt.EvidenceRefs,
                PublicMetadata: attempt.PublicMetadata,
                VisualCostMeasurementComplete:
                    attempt.VisualCostMeasurementComplete,
                VisualCostMissingMeasurementCount:
                    attempt.VisualCostMissingMeasurementCount,
                VisualCostSource: attempt.VisualCostSource))
            .ToArray();
        return TryCreateCanonicalImprovementLoopAttemptHistory(
            loopRef,
            items,
            out snapshot,
            out canonicalSnapshotJson);
    }

    public static bool TryReadImprovementLoopAttemptHistory(
        string? serializedSnapshot,
        out DesignConversionImprovementLoopAttemptHistorySnapshot? snapshot)
    {
        snapshot = null;
        if (!IsWithinImprovementLoopAttemptHistoryEnvelope(serializedSnapshot) ||
            string.IsNullOrWhiteSpace(serializedSnapshot))
        {
            return false;
        }

        try
        {
            using var document = JsonDocument.Parse(serializedSnapshot);
            var root = document.RootElement;
            if (!HasExactJsonProperties(
                    root,
                    ImprovementLoopAttemptHistoryRootProperties) ||
                !root.TryGetProperty("attempts", out var attemptsElement) ||
                attemptsElement.ValueKind != JsonValueKind.Array)
            {
                return false;
            }

            foreach (var item in attemptsElement.EnumerateArray())
            {
                if (!HasExactJsonProperties(
                        item,
                        ImprovementLoopAttemptHistoryItemProperties) ||
                    !item.TryGetProperty("publicMetadata", out var metadata) ||
                    metadata.ValueKind != JsonValueKind.Object ||
                    HasDuplicateJsonProperty(metadata))
                {
                    return false;
                }
            }

            var parsed = root.Deserialize<
                DesignConversionImprovementLoopAttemptHistorySnapshot>(
                ImprovementLoopAttemptHistoryJsonOptions);
            if (parsed is null ||
                !string.Equals(
                    parsed.Schema,
                    ImprovementLoopAttemptHistorySchema,
                    StringComparison.Ordinal) ||
                parsed.Version != ImprovementLoopAttemptHistoryVersion ||
                !IsCanonicalImprovementLoopRef(parsed.LoopRef) ||
                parsed.AttemptCount <= 0 ||
                parsed.AttemptCount > MaxImprovementLoopAttemptHistoryAttempts ||
                parsed.RedactionCodes is null ||
                parsed.RedactionCodes.Count >
                    MaxImprovementLoopAttemptHistoryRedactionCodes ||
                parsed.Attempts is null ||
                parsed.AttemptCount != parsed.Attempts.Count ||
                !IsSha256RefValue(parsed.HistorySha256))
            {
                return false;
            }

            if (!TryCreateCanonicalImprovementLoopAttemptHistory(
                    parsed.LoopRef,
                    parsed.Attempts,
                    out var canonical,
                    out var canonicalJson) ||
                canonical is null ||
                canonicalJson is null ||
                !string.Equals(
                    parsed.HistorySha256,
                    canonical.HistorySha256,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    serializedSnapshot,
                    canonicalJson,
                    StringComparison.Ordinal))
            {
                return false;
            }

            snapshot = canonical;
            return true;
        }
        catch (JsonException)
        {
            return false;
        }
        catch (NotSupportedException)
        {
            return false;
        }
    }

    internal static bool TryCanonicalizeImprovementLoopAttemptHistoryMetadata(
        string? serializedSnapshot,
        string? expectedLoopRef,
        out string? canonicalSnapshotJson,
        out DesignConversionImprovementLoopAttemptHistorySnapshot? snapshot)
    {
        canonicalSnapshotJson = null;
        if (!TryReadImprovementLoopAttemptHistory(
                serializedSnapshot,
                out snapshot) ||
            snapshot is null)
        {
            return false;
        }

        if (!string.Equals(
                snapshot.LoopRef,
                expectedLoopRef,
                StringComparison.Ordinal))
        {
            snapshot = null;
            return false;
        }

        canonicalSnapshotJson = JsonSerializer.Serialize(
            snapshot,
            ImprovementLoopAttemptHistoryJsonOptions);
        return string.Equals(
            serializedSnapshot,
            canonicalSnapshotJson,
            StringComparison.Ordinal);
    }

    internal static bool HasValidImprovementLoopAttemptHistoryMetadata(
        DesignConversionLocalArtifactDbRecord? record)
    {
        if (record?.Metadata is null ||
            !record.Metadata.TryGetValue(
                ImprovementLoopAttemptHistoryMetadataKey,
                out var serializedSnapshot))
        {
            // Legacy rows remain explicitly not recorded.  Never synthesize
            // attempt history from final-only record fields.
            return true;
        }

        return record.Metadata.TryGetValue(
                   ImprovementLoopRefMetadataKey,
                   out var outerLoopRef) &&
               TryCanonicalizeImprovementLoopAttemptHistoryMetadata(
                   serializedSnapshot,
                   outerLoopRef,
                   out _,
                   out _);
    }

    private static bool TryPreflightImprovementLoopAttemptHistoryRawInput(
        IReadOnlyList<DesignConversionImprovementLoopAttemptHistoryItem> attempts)
    {
        var aggregateCharacters = 0;
        var aggregateUtf8Bytes = 0;
        foreach (var attempt in attempts)
        {
            if (attempt is null ||
                !TryAccumulateImprovementLoopAttemptHistoryRawValue(
                    attempt.CandidateRef,
                    MaxImprovementLoopAttemptHistoryRawReferenceCharacters,
                    MaxImprovementLoopAttemptHistoryRawReferenceUtf8Bytes,
                    MaxImprovementLoopAttemptHistoryRawCharacters,
                    MaxImprovementLoopAttemptHistoryRawUtf8Bytes,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryAccumulateImprovementLoopAttemptHistoryRawValue(
                    attempt.JobRef,
                    MaxImprovementLoopAttemptHistoryRawReferenceCharacters,
                    MaxImprovementLoopAttemptHistoryRawReferenceUtf8Bytes,
                    MaxImprovementLoopAttemptHistoryRawCharacters,
                    MaxImprovementLoopAttemptHistoryRawUtf8Bytes,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryAccumulateImprovementLoopAttemptHistoryRawValue(
                    attempt.RequestRef,
                    MaxImprovementLoopAttemptHistoryRawReferenceCharacters,
                    MaxImprovementLoopAttemptHistoryRawReferenceUtf8Bytes,
                    MaxImprovementLoopAttemptHistoryRawCharacters,
                    MaxImprovementLoopAttemptHistoryRawUtf8Bytes,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryAccumulateImprovementLoopAttemptHistoryRawValue(
                    attempt.StopReason,
                    MaxImprovementLoopAttemptHistoryRawReferenceCharacters,
                    MaxImprovementLoopAttemptHistoryRawReferenceUtf8Bytes,
                    MaxImprovementLoopAttemptHistoryRawCharacters,
                    MaxImprovementLoopAttemptHistoryRawUtf8Bytes,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryAccumulateImprovementLoopAttemptHistoryRawValue(
                    attempt.VisualCostSource,
                    MaxImprovementLoopAttemptHistoryRawReferenceCharacters,
                    MaxImprovementLoopAttemptHistoryRawReferenceUtf8Bytes,
                    MaxImprovementLoopAttemptHistoryRawCharacters,
                    MaxImprovementLoopAttemptHistoryRawUtf8Bytes,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryPreflightImprovementLoopAttemptHistoryRawReferences(
                    attempt.RenderResultRefs,
                    MaxImprovementLoopAttemptHistoryRenderRefs,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryPreflightImprovementLoopAttemptHistoryRawReferences(
                    attempt.ComparisonArtifactRefs,
                    MaxImprovementLoopAttemptHistoryComparisonRefs,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryPreflightImprovementLoopAttemptHistoryRawReferences(
                    attempt.VisualJudgeResultRefs,
                    MaxImprovementLoopAttemptHistoryVisualJudgeRefs,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryPreflightImprovementLoopAttemptHistoryRawReferences(
                    attempt.EvidenceRefs,
                    MaxImprovementLoopAttemptHistoryEvidenceRefs,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryPreflightImprovementLoopAttemptHistoryRawMetadata(
                    attempt.PublicMetadata,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes))
            {
                return false;
            }
        }

        return true;
    }

    private static bool TryPreflightImprovementLoopAttemptHistoryRawReferences(
        IReadOnlyList<string>? references,
        int maximumCount,
        ref int aggregateCharacters,
        ref int aggregateUtf8Bytes)
    {
        if (references is null || references.Count > maximumCount)
            return false;

        foreach (var reference in references)
        {
            if (!TryAccumulateImprovementLoopAttemptHistoryRawValue(
                    reference,
                    MaxImprovementLoopAttemptHistoryRawReferenceCharacters,
                    MaxImprovementLoopAttemptHistoryRawReferenceUtf8Bytes,
                    MaxImprovementLoopAttemptHistoryRawCharacters,
                    MaxImprovementLoopAttemptHistoryRawUtf8Bytes,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes))
            {
                return false;
            }
        }

        return true;
    }

    private static bool TryPreflightImprovementLoopAttemptHistoryRawMetadata(
        IReadOnlyDictionary<string, string>? metadata,
        ref int aggregateCharacters,
        ref int aggregateUtf8Bytes)
    {
        if (metadata is null ||
            metadata.Count > MaxImprovementLoopAttemptHistoryMetadataEntries)
        {
            return false;
        }

        foreach (var pair in metadata)
        {
            if (!TryAccumulateImprovementLoopAttemptHistoryRawValue(
                    pair.Key,
                    MaxImprovementLoopAttemptHistoryMetadataKeyCharacters,
                    MaxImprovementLoopAttemptHistoryMetadataKeyUtf8Bytes,
                    MaxImprovementLoopAttemptHistoryRawCharacters,
                    MaxImprovementLoopAttemptHistoryRawUtf8Bytes,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes) ||
                !TryAccumulateImprovementLoopAttemptHistoryRawValue(
                    pair.Value,
                    MaxImprovementLoopAttemptHistoryMetadataValueCharacters,
                    MaxImprovementLoopAttemptHistoryMetadataValueUtf8Bytes,
                    MaxImprovementLoopAttemptHistoryRawCharacters,
                    MaxImprovementLoopAttemptHistoryRawUtf8Bytes,
                    ref aggregateCharacters,
                    ref aggregateUtf8Bytes))
            {
                return false;
            }
        }

        return true;
    }

    private static bool TryAccumulateImprovementLoopAttemptHistoryRawValue(
        string? value,
        int maximumCharacters,
        int maximumUtf8Bytes,
        int maximumAggregateCharacters,
        int maximumAggregateUtf8Bytes,
        ref int aggregateCharacters,
        ref int aggregateUtf8Bytes)
    {
        if (value is null)
            return false;

        var characterCount = value.Length;
        if (characterCount > maximumCharacters)
            return false;

        var utf8ByteCount = Encoding.UTF8.GetByteCount(value);
        if (utf8ByteCount > maximumUtf8Bytes)
            return false;

        try
        {
            var nextAggregateCharacters = checked(
                aggregateCharacters + characterCount);
            var nextAggregateUtf8Bytes = checked(
                aggregateUtf8Bytes + utf8ByteCount);
            if (nextAggregateCharacters > maximumAggregateCharacters ||
                nextAggregateUtf8Bytes > maximumAggregateUtf8Bytes)
            {
                return false;
            }

            aggregateCharacters = nextAggregateCharacters;
            aggregateUtf8Bytes = nextAggregateUtf8Bytes;
            return true;
        }
        catch (OverflowException)
        {
            return false;
        }
    }

    private static bool TryCreateCanonicalImprovementLoopAttemptHistory(
        string? loopRef,
        IReadOnlyList<DesignConversionImprovementLoopAttemptHistoryItem>? attempts,
        out DesignConversionImprovementLoopAttemptHistorySnapshot? snapshot,
        out string? canonicalSnapshotJson)
    {
        snapshot = null;
        canonicalSnapshotJson = null;
        if (!IsCanonicalImprovementLoopRef(loopRef) ||
            attempts is null ||
            attempts.Count == 0 ||
            attempts.Count > MaxImprovementLoopAttemptHistoryAttempts ||
            !TryPreflightImprovementLoopAttemptHistoryRawInput(attempts))
        {
            return false;
        }

        var canonicalAttempts = new List<
            DesignConversionImprovementLoopAttemptHistoryItem>(attempts.Count);
        var redactionCodes = new SortedSet<string>(StringComparer.Ordinal);
        for (var index = 0; index < attempts.Count; index++)
        {
            var attempt = attempts[index];
            if (!TryCanonicalizeImprovementLoopAttemptHistoryItem(
                    attempt,
                    index + 1,
                    redactionCodes,
                    out var canonicalAttempt) ||
                canonicalAttempt is null)
            {
                return false;
            }

            canonicalAttempts.Add(canonicalAttempt);
        }

        var frozenAttempts = canonicalAttempts.ToArray();
        var frozenRedactionCodes = redactionCodes.ToArray();
        var hashPayload = new ImprovementLoopAttemptHistoryHashPayload(
            Schema: ImprovementLoopAttemptHistorySchema,
            Version: ImprovementLoopAttemptHistoryVersion,
            LoopRef: loopRef!,
            AttemptCount: frozenAttempts.Length,
            RedactionCodes: frozenRedactionCodes,
            Attempts: frozenAttempts);
        var hashPayloadJson = JsonSerializer.Serialize(
            hashPayload,
            ImprovementLoopAttemptHistoryJsonOptions);
        var historySha256 = "sha256:" + Convert.ToHexString(
                SHA256.HashData(Encoding.UTF8.GetBytes(hashPayloadJson)))
            .ToLowerInvariant();
        var candidate = new DesignConversionImprovementLoopAttemptHistorySnapshot(
            Schema: ImprovementLoopAttemptHistorySchema,
            Version: ImprovementLoopAttemptHistoryVersion,
            LoopRef: loopRef!,
            AttemptCount: frozenAttempts.Length,
            RedactionCodes: frozenRedactionCodes,
            HistorySha256: historySha256,
            Attempts: frozenAttempts);
        var serialized = JsonSerializer.Serialize(
            candidate,
            ImprovementLoopAttemptHistoryJsonOptions);
        if (!IsWithinImprovementLoopAttemptHistoryEnvelope(serialized))
            return false;

        snapshot = candidate;
        canonicalSnapshotJson = serialized;
        return true;
    }

    private static bool TryCanonicalizeImprovementLoopAttemptHistoryItem(
        DesignConversionImprovementLoopAttemptHistoryItem? attempt,
        int expectedAttemptNumber,
        SortedSet<string> redactionCodes,
        out DesignConversionImprovementLoopAttemptHistoryItem? canonical)
    {
        canonical = null;
        if (attempt is null ||
            attempt.AttemptNumber != expectedAttemptNumber ||
            !double.IsFinite(attempt.BestScore) ||
            !double.IsFinite(attempt.RequiredScore) ||
            attempt.EstimatedCostUsd < 0m ||
            attempt.BudgetUsd < 0m ||
            attempt.PolicyAttemptCount < 0 ||
            attempt.MaxImprovementCandidates < 0 ||
            attempt.VisualCostMissingMeasurementCount < 0 ||
            !ImprovementLoopAttemptHistoryStopReasons.Contains(attempt.StopReason) ||
            !ImprovementLoopAttemptHistoryVisualCostSources.Contains(
                attempt.VisualCostSource) ||
            !TryCanonicalizeImprovementLoopAttemptHistoryReference(
                attempt.CandidateRef,
                "dcm-loop-candidate-",
                ImprovementLoopAttemptHistoryCandidateRefRedactionCode,
                redactionCodes,
                out var candidateRef) ||
            !TryCanonicalizeImprovementLoopAttemptHistoryReference(
                attempt.JobRef,
                "dcm-loop-job-",
                ImprovementLoopAttemptHistoryJobRefRedactionCode,
                redactionCodes,
                out var jobRef) ||
            !TryCanonicalizeImprovementLoopAttemptHistoryReference(
                attempt.RequestRef,
                "dcm-loop-request-",
                ImprovementLoopAttemptHistoryRequestRefRedactionCode,
                redactionCodes,
                out var requestRef) ||
            !TryCanonicalizeImprovementLoopAttemptHistoryRefs(
                attempt.RenderResultRefs,
                MaxImprovementLoopAttemptHistoryRenderRefs,
                "dcm-loop-render-",
                ImprovementLoopAttemptHistoryRenderRefRedactionCode,
                redactionCodes,
                out var renderResultRefs) ||
            !TryCanonicalizeImprovementLoopAttemptHistoryRefs(
                attempt.ComparisonArtifactRefs,
                MaxImprovementLoopAttemptHistoryComparisonRefs,
                "dcm-loop-comparison-",
                ImprovementLoopAttemptHistoryComparisonRefRedactionCode,
                redactionCodes,
                out var comparisonArtifactRefs) ||
            !TryCanonicalizeImprovementLoopAttemptHistoryRefs(
                attempt.VisualJudgeResultRefs,
                MaxImprovementLoopAttemptHistoryVisualJudgeRefs,
                "dcm-loop-visual-judge-",
                ImprovementLoopAttemptHistoryVisualJudgeRefRedactionCode,
                redactionCodes,
                out var visualJudgeResultRefs) ||
            !TryCanonicalizeImprovementLoopAttemptHistoryRefs(
                attempt.EvidenceRefs,
                MaxImprovementLoopAttemptHistoryEvidenceRefs,
                "dcm-loop-evidence-",
                ImprovementLoopAttemptHistoryEvidenceRefRedactionCode,
                redactionCodes,
                out var evidenceRefs) ||
            !TryCanonicalizeImprovementLoopAttemptHistoryMetadata(
                attempt,
                candidateRef,
                jobRef,
                requestRef,
                redactionCodes,
                out var publicMetadata))
        {
            return false;
        }

        canonical = attempt with
        {
            CandidateRef = candidateRef,
            JobRef = jobRef,
            RequestRef = requestRef,
            RenderResultRefs = renderResultRefs,
            ComparisonArtifactRefs = comparisonArtifactRefs,
            VisualJudgeResultRefs = visualJudgeResultRefs,
            EvidenceRefs = evidenceRefs,
            PublicMetadata = publicMetadata
        };
        return true;
    }

    private static bool TryCanonicalizeImprovementLoopAttemptHistoryRefs(
        IReadOnlyList<string>? refs,
        int maximumCount,
        string requiredDcmPrefix,
        string redactionCode,
        SortedSet<string> redactionCodes,
        out IReadOnlyList<string> canonical)
    {
        canonical = [];
        if (refs is null ||
            refs.Count > maximumCount)
        {
            return false;
        }

        var canonicalRefs = new List<string>(refs.Count);
        foreach (var reference in refs)
        {
            if (!TryCanonicalizeImprovementLoopAttemptHistoryReference(
                    reference,
                    requiredDcmPrefix,
                    redactionCode,
                    redactionCodes,
                    out var canonicalReference))
            {
                return false;
            }

            canonicalRefs.Add(canonicalReference);
        }

        canonical = canonicalRefs.ToArray();
        return true;
    }

    private static bool TryCanonicalizeImprovementLoopAttemptHistoryMetadata(
        DesignConversionImprovementLoopAttemptHistoryItem attempt,
        string candidateRef,
        string jobRef,
        string requestRef,
        SortedSet<string> redactionCodes,
        out IReadOnlyDictionary<string, string> canonical)
    {
        canonical = new SortedDictionary<string, string>(StringComparer.Ordinal);
        var metadata = attempt.PublicMetadata;
        if (metadata is null ||
            metadata.Count > MaxImprovementLoopAttemptHistoryMetadataEntries)
        {
            return false;
        }

        var supplied = new SortedDictionary<string, string>(StringComparer.Ordinal);
        foreach (var pair in metadata)
        {
            if (string.IsNullOrWhiteSpace(pair.Key) ||
                pair.Key.Length > MaxImprovementLoopAttemptHistoryMetadataKeyCharacters ||
                pair.Key.Any(char.IsControl) ||
                pair.Value is null ||
                !supplied.TryAdd(pair.Key, pair.Value))
            {
                return false;
            }
        }

        if (!HasExactAttemptMetadataValue(
                supplied,
                "attempt_number",
                attempt.AttemptNumber.ToString(CultureInfo.InvariantCulture)) ||
            !HasExactAttemptMetadataValue(
                supplied,
                "loop_candidate_ref",
                attempt.CandidateRef) ||
            !HasExactAttemptMetadataValue(supplied, "job_ref", attempt.JobRef) ||
            !HasExactAttemptMetadataValue(supplied, "request_ref", attempt.RequestRef) ||
            !HasExactAttemptMetadataValue(supplied, "stop_reason", attempt.StopReason) ||
            !HasExactAttemptMetadataValue(
                supplied,
                "should_continue",
                attempt.ShouldContinue.ToString()) ||
            !HasExactAttemptMetadataValue(
                supplied,
                "refs_or_hashes_only",
                bool.TrueString) ||
            !HasExactAttemptMetadataValue(
                supplied,
                "raw_html_included",
                bool.FalseString) ||
            !HasExactAttemptMetadataValue(
                supplied,
                "raw_css_included",
                bool.FalseString) ||
            !HasExactAttemptMetadataValue(
                supplied,
                "raw_design_tree_included",
                bool.FalseString) ||
            !HasExactAttemptMetadataValue(
                supplied,
                "screenshot_bytes_included",
                bool.FalseString))
        {
            return false;
        }

        var sorted = new SortedDictionary<string, string>(StringComparer.Ordinal)
        {
            ["attempt_number"] = attempt.AttemptNumber.ToString(CultureInfo.InvariantCulture),
            ["loop_candidate_ref"] = candidateRef,
            ["job_ref"] = jobRef,
            ["request_ref"] = requestRef,
            ["stop_reason"] = attempt.StopReason,
            ["should_continue"] = attempt.ShouldContinue.ToString(),
            ["refs_or_hashes_only"] = bool.TrueString,
            ["raw_html_included"] = bool.FalseString,
            ["raw_css_included"] = bool.FalseString,
            ["raw_design_tree_included"] = bool.FalseString,
            ["screenshot_bytes_included"] = bool.FalseString
        };
        foreach (var pair in supplied)
        {
            if (ImprovementLoopAttemptHistoryRequiredMetadataKeys.Contains(pair.Key))
                continue;

            string canonicalKey;
            if (ImprovementLoopAttemptHistoryAdditionalMetadataKeys.Contains(pair.Key))
            {
                canonicalKey = pair.Key;
            }
            else if (IsCanonicalImprovementLoopAttemptHistoryRedactedMetadataKey(
                         pair.Key))
            {
                canonicalKey = pair.Key;
                redactionCodes.Add(
                    ImprovementLoopAttemptHistoryMetadataKeyRedactionCode);
            }
            else
            {
                canonicalKey = ImprovementLoopAttemptHistoryRedactedMetadataKeyPrefix +
                               HashImprovementLoopAttemptHistoryValueHex(pair.Key);
                redactionCodes.Add(
                    ImprovementLoopAttemptHistoryMetadataKeyRedactionCode);
            }

            var canonicalValue = IsSha256RefValue(pair.Value)
                ? pair.Value
                : HashImprovementLoopAttemptHistoryValue(pair.Value);
            redactionCodes.Add(
                ImprovementLoopAttemptHistoryMetadataValueRedactionCode);
            if (!sorted.TryAdd(canonicalKey, canonicalValue))
                return false;
        }

        canonical = sorted;
        return true;
    }

    private static bool HasExactAttemptMetadataValue(
        IReadOnlyDictionary<string, string> metadata,
        string key,
        string expected)
        => metadata.TryGetValue(key, out var actual) &&
           string.Equals(actual, expected, StringComparison.Ordinal);

    internal static bool TryCanonicalizeImprovementLoopAttemptsForPublicProjection(
        string? loopRef,
        IReadOnlyList<DesignConversionImprovementLoopAttemptTelemetry>? attempts,
        out IReadOnlyList<DesignConversionImprovementLoopAttemptHistoryItem> canonicalAttempts)
    {
        canonicalAttempts = [];
        if (!TryBuildImprovementLoopAttemptHistory(
                loopRef,
                attempts,
                out var snapshot,
                out _) ||
            snapshot is null)
        {
            return false;
        }

        canonicalAttempts = snapshot.Attempts;
        return true;
    }

    private static bool TryCanonicalizeImprovementLoopAttemptHistoryReference(
        string? value,
        string requiredDcmPrefix,
        string redactionCode,
        SortedSet<string> redactionCodes,
        out string canonical)
    {
        canonical = string.Empty;
        if (string.IsNullOrWhiteSpace(value))
            return false;

        if (IsCanonicalDcmHashRef(value, requiredDcmPrefix))
        {
            canonical = value;
            return true;
        }

        canonical = IsSha256RefValue(value)
            ? value
            : HashImprovementLoopAttemptHistoryValue(value);
        redactionCodes.Add(redactionCode);
        return true;
    }

    private static bool IsCanonicalImprovementLoopRef(string? value)
        => IsCanonicalDcmHashRef(value, "dcm-loop-");

    private static bool IsCanonicalDcmHashRef(
        string? value,
        string requiredPrefix)
        => value is not null &&
           value.Length == requiredPrefix.Length + 16 &&
           value.StartsWith(requiredPrefix, StringComparison.Ordinal) &&
           value.Skip(requiredPrefix.Length).All(character =>
               character is (>= '0' and <= '9') or (>= 'a' and <= 'f'));

    private static bool IsCanonicalImprovementLoopAttemptHistoryRedactedMetadataKey(
        string key)
        => key.Length ==
               ImprovementLoopAttemptHistoryRedactedMetadataKeyPrefix.Length + 64 &&
           key.StartsWith(
               ImprovementLoopAttemptHistoryRedactedMetadataKeyPrefix,
               StringComparison.Ordinal) &&
           key.Skip(ImprovementLoopAttemptHistoryRedactedMetadataKeyPrefix.Length)
               .All(character =>
                   character is (>= '0' and <= '9') or (>= 'a' and <= 'f'));

    private static string HashImprovementLoopAttemptHistoryValue(string value)
        => "sha256:" + HashImprovementLoopAttemptHistoryValueHex(value);

    private static string HashImprovementLoopAttemptHistoryValueHex(string value)
        => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)))
            .ToLowerInvariant();

    private static bool IsWithinImprovementLoopAttemptHistoryEnvelope(string? value)
        => !string.IsNullOrEmpty(value) &&
           value.Length <= MaxImprovementLoopAttemptHistorySerializedCharacters &&
           Encoding.UTF8.GetByteCount(value) <=
           MaxImprovementLoopAttemptHistorySerializedUtf8Bytes;

    private static bool HasDuplicateJsonProperty(JsonElement element)
    {
        var names = new HashSet<string>(StringComparer.Ordinal);
        foreach (var property in element.EnumerateObject())
        {
            if (!names.Add(property.Name))
                return true;
        }

        return false;
    }

    private static bool IsSha256RefValue(string? value)
        => value is not null &&
           value.Length == "sha256:".Length + 64 &&
           value.StartsWith("sha256:", StringComparison.Ordinal) &&
           value.Skip("sha256:".Length).All(character =>
               character is (>= '0' and <= '9') or (>= 'a' and <= 'f'));

    public static bool TryReadCompletedStatusSnapshot(
        DesignConversionVisualJudgeArtifactDbStatus? visualJudgeStatus,
        out DesignConversionLocalArtifactDbStatusSnapshot? snapshot)
    {
        snapshot = null;
        if (visualJudgeStatus?.Metadata is null ||
            !visualJudgeStatus.Metadata.TryGetValue(CompletedStatusSnapshotMetadataKey, out var serializedSnapshot))
        {
            return false;
        }

        return TryParseCompletedStatusSnapshot(serializedSnapshot, out snapshot);
    }

    internal static bool TryCanonicalizeCompletedStatusSnapshotMetadata(
        string? serializedSnapshot,
        out string? canonicalSnapshotJson)
    {
        canonicalSnapshotJson = null;
        if (!TryParseCompletedStatusSnapshot(serializedSnapshot, out var snapshot) || snapshot is null)
            return false;

        return TrySerializeCompletedStatusSnapshot(snapshot, out canonicalSnapshotJson);
    }

    private static bool TryBuildCompletedStatusSnapshotJson(
        DesignConversionThinClientStatusQualityMetrics? qualityMetrics,
        IReadOnlyList<DesignConversionThinClientStatusDefect>? defects,
        out string? snapshotJson)
    {
        snapshotJson = null;
        if (!TryBuildCompletedStatusSnapshot(qualityMetrics, defects, out var snapshot) || snapshot is null)
            return false;

        return TrySerializeCompletedStatusSnapshot(snapshot, out snapshotJson);
    }

    private static bool TrySerializeCompletedStatusSnapshot(
        DesignConversionLocalArtifactDbStatusSnapshot snapshot,
        out string? snapshotJson)
    {
        snapshotJson = JsonSerializer.Serialize(snapshot, CompletedStatusSnapshotJsonOptions);
        if (IsWithinCompletedStatusSnapshotEnvelope(snapshotJson))
            return true;

        snapshotJson = null;
        return false;
    }

    private static bool TryParseCompletedStatusSnapshot(
        string? serializedSnapshot,
        out DesignConversionLocalArtifactDbStatusSnapshot? snapshot)
    {
        snapshot = null;
        if (!IsWithinCompletedStatusSnapshotEnvelope(serializedSnapshot) ||
            string.IsNullOrWhiteSpace(serializedSnapshot) ||
            HasForbiddenCompletedStatusSnapshotText(serializedSnapshot))
        {
            return false;
        }

        try
        {
            using var document = JsonDocument.Parse(serializedSnapshot);
            var root = document.RootElement;
            if (!HasExactJsonProperties(root, CompletedStatusSnapshotRootProperties) ||
                !root.TryGetProperty("qualityMetrics", out var metricsElement) ||
                !HasExactJsonProperties(metricsElement, CompletedStatusSnapshotMetricsProperties) ||
                !root.TryGetProperty("defects", out var defectsElement) ||
                defectsElement.ValueKind != JsonValueKind.Array ||
                defectsElement.GetArrayLength() > MaxCompletedStatusSnapshotDefects)
            {
                return false;
            }

            var aggregateEvidenceRefCount = 0;
            foreach (var defectElement in defectsElement.EnumerateArray())
            {
                if (!HasExactJsonProperties(defectElement, CompletedStatusSnapshotDefectProperties) ||
                    !defectElement.TryGetProperty("evidenceRefs", out var evidenceRefsElement) ||
                    evidenceRefsElement.ValueKind != JsonValueKind.Array)
                {
                    return false;
                }

                var evidenceRefCount = evidenceRefsElement.GetArrayLength();
                if (evidenceRefCount == 0 ||
                    evidenceRefCount >
                    MaxCompletedStatusSnapshotAggregateEvidenceRefs - aggregateEvidenceRefCount)
                {
                    return false;
                }

                aggregateEvidenceRefCount += evidenceRefCount;
            }

            var parsed = root.Deserialize<DesignConversionLocalArtifactDbStatusSnapshot>(
                CompletedStatusSnapshotJsonOptions);
            if (parsed is null ||
                !string.Equals(parsed.Schema, CompletedStatusSnapshotSchema, StringComparison.Ordinal) ||
                parsed.Version != CompletedStatusSnapshotVersion ||
                !TryBuildCompletedStatusSnapshot(parsed.QualityMetrics, parsed.Defects, out var canonical) ||
                canonical is null)
            {
                return false;
            }

            snapshot = canonical;
            return true;
        }
        catch (JsonException)
        {
            return false;
        }
    }

    private static bool TryBuildCompletedStatusSnapshot(
        DesignConversionThinClientStatusQualityMetrics? qualityMetrics,
        IReadOnlyList<DesignConversionThinClientStatusDefect>? defects,
        out DesignConversionLocalArtifactDbStatusSnapshot? snapshot)
    {
        snapshot = null;
        var sourceDefects = defects ?? [];
        if (qualityMetrics is null ||
            !qualityMetrics.Available ||
            qualityMetrics.Score is not { } score ||
            qualityMetrics.RequiredThreshold is not { } threshold ||
            qualityMetrics.Passed is not { } passed ||
            qualityMetrics.ThresholdMet is not { } thresholdMet ||
            !IsFiniteUnitInterval(score) ||
            !IsFiniteUnitInterval(threshold) ||
            !string.Equals(qualityMetrics.Source, CompletedStatusSnapshotQualitySource, StringComparison.Ordinal) ||
            !string.Equals(qualityMetrics.ThresholdSource, CompletedStatusSnapshotThresholdSource, StringComparison.Ordinal) ||
            qualityMetrics.UnavailableReason is not null ||
            qualityMetrics.DefectCount != sourceDefects.Count ||
            sourceDefects.Count > MaxCompletedStatusSnapshotDefects)
        {
            return false;
        }

        if (!HasValidCompletedStatusSnapshotAggregateEvidenceRefCount(sourceDefects))
            return false;

        var canonicalDefects = new List<DesignConversionThinClientStatusDefect>(sourceDefects.Count);
        for (var index = 0; index < sourceDefects.Count; index++)
        {
            var defect = sourceDefects[index];
            if (defect is null ||
                defect.Ordinal != index + 1 ||
                !TryValidateCompletedStatusSnapshotLabel(
                    defect.Category,
                    CompletedStatusSnapshotCategories,
                    out var category) ||
                !TryValidateCompletedStatusSnapshotLabel(
                    defect.Severity,
                    CompletedStatusSnapshotSeverities,
                    out var severity) ||
                !string.Equals(
                    defect.Message,
                    BuildCompletedStatusSnapshotDefectMessage(severity, category),
                    StringComparison.Ordinal) ||
                !TryValidateCompletedStatusSnapshotHashRef(defect.DefectRef, out var defectRef))
            {
                return false;
            }

            var sourceEvidenceRefs = defect.EvidenceRefs;
            if (sourceEvidenceRefs is null ||
                sourceEvidenceRefs.Count == 0)
            {
                return false;
            }

            var evidenceRefs = new List<string>(sourceEvidenceRefs.Count);
            var uniqueEvidenceRefs = new HashSet<string>(StringComparer.Ordinal);
            for (var evidenceIndex = 0; evidenceIndex < sourceEvidenceRefs.Count; evidenceIndex++)
            {
                if (!TryValidateCompletedStatusSnapshotHashRef(
                        sourceEvidenceRefs[evidenceIndex],
                        out var evidenceRef) ||
                    !uniqueEvidenceRefs.Add(evidenceRef))
                {
                    return false;
                }

                evidenceRefs.Add(evidenceRef);
            }

            canonicalDefects.Add(new DesignConversionThinClientStatusDefect(
                DefectRef: defectRef,
                Category: category,
                Severity: severity,
                Message: BuildCompletedStatusSnapshotDefectMessage(severity, category),
                Ordinal: index + 1,
                EvidenceRefs: evidenceRefs.ToArray()));
        }

        snapshot = new DesignConversionLocalArtifactDbStatusSnapshot(
            Schema: CompletedStatusSnapshotSchema,
            Version: CompletedStatusSnapshotVersion,
            QualityMetrics: new DesignConversionThinClientStatusQualityMetrics(
                Available: true,
                Score: score,
                RequiredThreshold: threshold,
                Passed: passed,
                ThresholdMet: thresholdMet,
                DefectCount: canonicalDefects.Count,
                Source: CompletedStatusSnapshotQualitySource,
                ThresholdSource: CompletedStatusSnapshotThresholdSource,
                UnavailableReason: null),
            Defects: canonicalDefects.ToArray());
        return true;
    }

    private static bool HasValidCompletedStatusSnapshotAggregateEvidenceRefCount(
        IReadOnlyList<DesignConversionThinClientStatusDefect> defects)
    {
        var aggregateEvidenceRefCount = 0;
        for (var index = 0; index < defects.Count; index++)
        {
            var evidenceRefs = defects[index]?.EvidenceRefs;
            if (evidenceRefs is null ||
                evidenceRefs.Count == 0 ||
                evidenceRefs.Count >
                MaxCompletedStatusSnapshotAggregateEvidenceRefs - aggregateEvidenceRefCount)
            {
                return false;
            }

            aggregateEvidenceRefCount += evidenceRefs.Count;
        }

        return true;
    }

    private static bool IsWithinCompletedStatusSnapshotEnvelope(string? value)
    {
        if (string.IsNullOrEmpty(value) ||
            value.Length > MaxCompletedStatusSnapshotSerializedCharacters)
        {
            return false;
        }

        return Encoding.UTF8.GetByteCount(value) <= MaxCompletedStatusSnapshotSerializedUtf8Bytes;
    }

    private static bool HasExactJsonProperties(
        JsonElement element,
        IReadOnlySet<string> expectedProperties)
    {
        if (element.ValueKind != JsonValueKind.Object)
            return false;

        var actualProperties = new HashSet<string>(StringComparer.Ordinal);
        foreach (var property in element.EnumerateObject())
        {
            if (!actualProperties.Add(property.Name))
                return false;
        }

        return actualProperties.SetEquals(expectedProperties);
    }

    private static bool TryValidateCompletedStatusSnapshotLabel(
        string? value,
        IReadOnlySet<string> allowedValues,
        out string normalized)
    {
        normalized = string.Empty;
        if (string.IsNullOrWhiteSpace(value) || HasForbiddenCompletedStatusSnapshotText(value))
            return false;

        normalized = value.Trim();
        return string.Equals(value, normalized, StringComparison.Ordinal) &&
               allowedValues.Contains(normalized);
    }

    private static bool TryValidateCompletedStatusSnapshotHashRef(
        string? value,
        out string normalized)
    {
        normalized = string.Empty;
        if (string.IsNullOrWhiteSpace(value) || HasForbiddenCompletedStatusSnapshotText(value))
            return false;

        normalized = value.Trim();
        if (!string.Equals(value, normalized, StringComparison.Ordinal) ||
            normalized.Length != CompletedStatusSnapshotCanonicalHashRefLength ||
            !normalized.StartsWith("sha256:", StringComparison.Ordinal))
        {
            return false;
        }

        for (var index = "sha256:".Length; index < normalized.Length; index++)
        {
            var c = normalized[index];
            if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')))
                return false;
        }

        return true;
    }

    private static bool HasForbiddenCompletedStatusSnapshotText(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return false;

        return LooksLikeCompletedStatusSnapshotLocalPath(value) ||
               value.Contains("private", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("secret", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("raw_html", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("raw_css", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("raw_design_tree", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("raw_original_tree", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("design_tree", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("original_tree", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("provider_payload", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("payload", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("<html", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("</", StringComparison.OrdinalIgnoreCase);
    }

    private static bool LooksLikeCompletedStatusSnapshotLocalPath(string value)
        => value.Contains("file://", StringComparison.OrdinalIgnoreCase) ||
           value.Contains(@":\", StringComparison.Ordinal) ||
           value.StartsWith(@"\\", StringComparison.Ordinal) ||
           value.Contains("/Users/", StringComparison.OrdinalIgnoreCase) ||
           value.Contains("/home/", StringComparison.OrdinalIgnoreCase);

    private static string BuildCompletedStatusSnapshotDefectMessage(
        string severity,
        string category)
        => $"{ToCompletedStatusSnapshotDisplayLabel(severity)} {category.Replace('_', ' ')} issue reported by visual QA.";

    private static string ToCompletedStatusSnapshotDisplayLabel(string value)
        => string.IsNullOrEmpty(value)
            ? "Other"
            : char.ToUpperInvariant(value[0]) + value[1..];

    private static bool IsFiniteUnitInterval(double value)
        => double.IsFinite(value) && value >= 0.0 && value <= 1.0;

    public static DesignConversionLocalArtifactDbRecord FromEvaluation(
        DesignConversionInternalEvaluationResult evaluation,
        IReadOnlyList<DesignConversionDpoTrainingRecord> dpoCandidates,
        DateTimeOffset? createdAtUtc = null,
        IReadOnlyDictionary<string, string>? metadata = null,
        DesignConversionThinClientStatusQualityMetrics? completedStatusQualityMetrics = null,
        IReadOnlyList<DesignConversionThinClientStatusDefect>? completedStatusDefects = null)
    {
        if (evaluation is null)
            throw new ArgumentNullException(nameof(evaluation));

        var request = evaluation.SubmittedRequest;
        var sourceRefs = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["design_tree_payload_ref"] = request.DesignTreePayload.Sha256,
            ["original_tree_payload_ref"] = request.OriginalTreePayload.Sha256,
            ["source_manifest_ref"] = request.Provenance.TryGetValue("source_manifest_ref", out var sourceManifestRef)
                ? sourceManifestRef
                : request.DesignTreePayload.PayloadId
        };

        foreach (var artifact in request.Screenshots.Concat(request.DesignRenders))
            sourceRefs[$"source_artifact:{artifact.ArtifactId}"] = artifact.Sha256;

        var visualJudge = evaluation.VisualJudgeResults.LastOrDefault();
        var status = visualJudge is null
            ? DesignConversionVisualQaBoundaryPolicy.ProviderRequired
            : visualJudge.Provider.Metadata.TryGetValue(
                DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker,
                out var testProviderOnly)
                && IsTruthy(testProviderOnly)
                    ? DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker
                    : visualJudge.Status;
        var visualJudgeMetadata = new Dictionary<string, string>(
            BuildVisualJudgeDbMetadata(evaluation, visualJudge, status),
            StringComparer.Ordinal);
        if (TryBuildCompletedStatusSnapshotJson(
            completedStatusQualityMetrics,
            completedStatusDefects,
            out var completedStatusSnapshotJson) &&
            completedStatusSnapshotJson is not null)
        {
            visualJudgeMetadata[CompletedStatusSnapshotMetadataKey] = completedStatusSnapshotJson;
        }

        return new DesignConversionLocalArtifactDbRecord(
            RecordId: $"{evaluation.JobId}:storage_training_artifact_db",
            DatabaseKind: JsonlDesignConversionLocalArtifactDb.LocalArtifactDbKind,
            JobId: evaluation.JobId,
            RequestId: request.RequestId,
            SourceKind: request.SourceKind.ToString(),
            Tier: request.Budget.Tier,
            SanitizedSourceRefs: sourceRefs,
            ConversionResult: new DesignConversionConversionResultArtifact(
                ResultId: evaluation.RuntimeFlowResult.Output.OutputId,
                HtmlRef: evaluation.ImprovedHtml,
                HtmlSha256: string.Empty,
                CssRef: evaluation.ImprovedCss,
                CssSha256: string.Empty,
                Metadata: new Dictionary<string, string>
                {
                    ["conversion_result"] = "html_css_result_refs_or_hashes"
                }),
            RenderArtifactRefs: evaluation.RenderResults.Select(ToRenderArtifactRef).ToArray(),
            VisualJudgeStatus: new DesignConversionVisualJudgeArtifactDbStatus(
                Status: status,
                ProviderBoundary: evaluation.VisualQaBoundaryTrace.VisualJudgeProviderBoundary,
                ExternalCallExecuted: evaluation.VisualQaBoundaryTrace.ExternalAiVisualJudgeExecuted,
                EstimatedCostUsd: visualJudge?.EstimatedCostUsd,
                TierDecision: evaluation.VisualQaBoundaryTrace.TierPolicy.StopReason,
                EvidenceRefs: evaluation.VisualQaBoundaryTrace.EvidenceRefs
                    .Concat(visualJudge?.EvidenceRefs ?? [])
                    .Distinct(StringComparer.Ordinal)
                    .ToArray(),
                Metadata: visualJudgeMetadata),
            DpoCandidates: dpoCandidates.Select(record =>
                DesignConversionLocalArtifactDbDpoCandidate.FromTrainingRecord(record)).ToArray(),
            CreatedAtUtc: createdAtUtc ?? DateTimeOffset.UtcNow,
            EvidenceRefs: evaluation.EvidenceRefs
                .Append(JsonlDesignConversionLocalArtifactDb.StorageTrainingArtifactDbMarker)
                .Append(JsonlDesignConversionLocalArtifactDb.LocalArtifactDbKind)
                .Append("conversion_result")
                .Append("render_artifact_refs")
                .Append("visual_judge_status")
                .Append("dpo_candidate")
                .Append(dpoCandidates.Count > 0
                    ? "training_candidate_only=true"
                    : "training_candidate_only=false")
                .Append("training_grade=false")
                .Append("not_training_grade=true")
                .Append("product_not_ready")
                .Distinct(StringComparer.Ordinal)
                .ToArray(),
            Metadata: metadata ?? new Dictionary<string, string>());
    }

    private static IReadOnlyDictionary<string, string> BuildVisualJudgeDbMetadata(
        DesignConversionInternalEvaluationResult evaluation,
        DesignConversionVisualJudgeResult? visualJudge,
        string status)
    {
        var metadata = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["visual_judge_status"] = status,
            ["visual_decision"] = evaluation.VisualQaBoundaryTrace.VisualDecision.Decision,
            ["visual_decision_correction_count"] = evaluation.VisualQaBoundaryTrace.VisualDecision.CorrectionFindings.Count.ToString(CultureInfo.InvariantCulture),
            ["visual_decision_remaining_budget_usd"] = evaluation.VisualQaBoundaryTrace.VisualDecision.RemainingBudgetUsd.ToString("0.####", CultureInfo.InvariantCulture),
            ["product_not_ready"] = bool.TrueString,
            [ServerOwnedAccountingReceiptVerifiedKey] = bool.FalseString,
            [ServerOwnedAccountingReceiptStatusKey] = ServerOwnedAccountingReceiptStatusNotVerified
        };

        if (TryBuildVerifiedServerOwnedAccountingReceipt(visualJudge, out var receipt))
        {
            foreach (var pair in receipt)
                metadata[pair.Key] = pair.Value;

            metadata[ServerOwnedAccountingReceiptVerifiedKey] = bool.TrueString;
            metadata[ServerOwnedAccountingReceiptStatusKey] = ServerOwnedAccountingReceiptStatusVerifiedPersisted;
        }

        return metadata;
    }

    private static bool TryBuildVerifiedServerOwnedAccountingReceipt(
        DesignConversionVisualJudgeResult? visualJudge,
        out IReadOnlyDictionary<string, string> receipt)
    {
        receipt = new Dictionary<string, string>(StringComparer.Ordinal);
        if (visualJudge is null)
            return false;

        var resultMetadata = visualJudge.Metadata ?? new Dictionary<string, string>();
        var providerMetadata = visualJudge.Provider.Metadata ?? new Dictionary<string, string>();
        var verified = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var key in ServerOwnedAccountingReceiptKeys)
        {
            if (!resultMetadata.TryGetValue(key, out var resultValue) ||
                !providerMetadata.TryGetValue(key, out var providerValue) ||
                !string.Equals(resultValue, providerValue, StringComparison.Ordinal))
            {
                return false;
            }

            verified[key] = resultValue;
        }

        receipt = verified;
        return true;
    }

    private static DesignConversionRenderArtifactDbRef ToRenderArtifactRef(DesignConversionRenderResult render)
        => new(
            ViewportId: render.Image.Resolution.ResolutionId,
            ArtifactId: render.RenderResultId,
            Kind: render.Image.Label,
            UriRef: render.Image.Uri,
            Sha256: render.Image.Sha256,
            ByteLength: 0,
            Width: render.Image.Resolution.Width,
            Height: render.Image.Resolution.Height,
            Metadata: render.Image.Metadata);

    private static bool IsTruthy(string value)
        => string.Equals(value, bool.TrueString, StringComparison.OrdinalIgnoreCase)
           || string.Equals(value, "1", StringComparison.Ordinal)
           || string.Equals(value, "yes", StringComparison.OrdinalIgnoreCase);
}

