public sealed record DesignConversionPostEvaluationTrainingSnapshot(
    IReadOnlyList<DesignConversionLocalArtifactDbRecord> Records,
    IReadOnlyList<DesignConversionPostEvaluationTrainingEligibility>
        Eligibility);

public interface IDesignConversionLocalArtifactDb
{
    Task<OperationResult<DesignConversionLocalArtifactDbRecord>> AppendRecordAsync(
        DesignConversionLocalArtifactDbRecord record,
        CancellationToken ct = default);

    Task<OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>> ListRecordsAsync(
        DesignConversionLocalArtifactDbQuery? query = null,
        CancellationToken ct = default);

    Task<DesignConversionPostEvaluationTrainingEligibility> EvaluatePostEvaluationTrainingEligibilityAsync(
        DesignConversionLocalArtifactDbRecord record,
        CancellationToken ct = default)
        => Task.FromResult(
            DesignConversionPostEvaluationTrainingEligibility.Denied(
                DesignConversionPostEvaluationTrainingEligibilityPolicy.EvaluatorUnavailableReason,
                DesignConversionPostEvaluationTrainingEligibilityPolicy.EvaluatorUnavailableErrorCode));

    Task<IReadOnlyList<DesignConversionPostEvaluationTrainingEligibility>>
        EvaluatePostEvaluationTrainingEligibilityManyAsync(
            IReadOnlyList<DesignConversionLocalArtifactDbRecord?> records,
            CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(records);
        IReadOnlyList<DesignConversionPostEvaluationTrainingEligibility> denied =
            records
                .Select(_ =>
                    DesignConversionPostEvaluationTrainingEligibility.Denied(
                        DesignConversionPostEvaluationTrainingEligibilityPolicy
                            .EvaluatorUnavailableReason,
                        DesignConversionPostEvaluationTrainingEligibilityPolicy
                            .EvaluatorUnavailableErrorCode))
                .ToArray();
        return Task.FromResult(denied);
    }

    async Task<OperationResult<
        DesignConversionPostEvaluationTrainingSnapshot>>
        ListRecordsWithPostEvaluationTrainingEligibilityAsync(
            DesignConversionLocalArtifactDbQuery? query = null,
            CancellationToken ct = default)
    {
        var records = await ListRecordsAsync(query, ct).ConfigureAwait(false);
        if (!records.IsSuccess)
        {
            return records.MapError<
                DesignConversionPostEvaluationTrainingSnapshot>();
        }

        IReadOnlyList<DesignConversionPostEvaluationTrainingEligibility>
            eligibility;
        try
        {
            eligibility =
                await EvaluatePostEvaluationTrainingEligibilityManyAsync(
                        records.Value!,
                        ct)
                    .ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return OperationResult<
                DesignConversionPostEvaluationTrainingSnapshot>.Fail(
                "Post-evaluation training snapshot was cancelled.",
                "CANCELLED");
        }
        catch (Exception ex) when (
            ex is IOException or UnauthorizedAccessException or
                System.Security.SecurityException or
                System.Text.Json.JsonException or
                ArgumentException or InvalidOperationException)
        {
            return OperationResult<
                DesignConversionPostEvaluationTrainingSnapshot>.Fail(
                "Post-evaluation training snapshot could not be evaluated.",
                DesignConversionPostEvaluationTrainingEligibilityPolicy
                    .StateReadFailedErrorCode);
        }

        var exactEligibility = records.Value!
            .Select((_, index) =>
                index < eligibility.Count
                    ? eligibility[index]
                    : DesignConversionPostEvaluationTrainingEligibility
                        .Denied(
                            DesignConversionPostEvaluationTrainingEligibilityPolicy
                                .EvaluatorUnavailableReason,
                            DesignConversionPostEvaluationTrainingEligibilityPolicy
                                .EvaluatorUnavailableErrorCode))
            .ToArray();
        return OperationResult<
            DesignConversionPostEvaluationTrainingSnapshot>.Ok(
            new DesignConversionPostEvaluationTrainingSnapshot(
                records.Value!,
                exactEligibility));
    }

    Task<OperationResult<IReadOnlyList<DesignConversionDpoTrainingRecord>>> QueryApprovedTrainingCandidatesAsync(
        DesignConversionLocalArtifactDbQuery? query = null,
        CancellationToken ct = default);

    Task<OperationResult<DesignConversionApprovedDpoHandoffArtifact>> ExportApprovedRuntimeDpoCandidatesAsync(
        DesignConversionLocalArtifactDbQuery? query = null,
        DateTimeOffset? exportedAtUtc = null,
        CancellationToken ct = default);

    Task<OperationResult<DesignConversionTrainingIntakeRecord>> CreateTrainingIntakeAsync(
        DesignConversionApprovedDpoHandoffArtifact handoff,
        string requestedByRef,
        string reason,
        DateTimeOffset? requestedAtUtc = null,
        CancellationToken ct = default,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata = null);

    Task<OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRecord>>> ListTrainingIntakeRequestsAsync(
        CancellationToken ct = default);

    Task<OperationResult<DesignConversionTrainingIntakePreflightResult>> RunTrainingIntakePreflightAsync(
        string intakeId,
        CancellationToken ct = default);

    Task<OperationResult<DesignConversionTrainingIntakeRunResult>> RunTrainingIntakeAsync(
        string intakeId,
        DesignConversionTrainingPipelineOptions? options = null,
        CancellationToken ct = default,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata = null);

    Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>> RunTrainingIntakeAndPromoteLocalAsync(
        string intakeId,
        string promotionOutputDirectory,
        DesignConversionTrainingPipelineOptions? options = null,
        CancellationToken ct = default);

    Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>> RollbackTrainingIntakeLocalPromotionAsync(
        string promotedLocalModelRef,
        string requestedByRef,
        string reason,
        DateTimeOffset? requestedAtUtc = null,
        CancellationToken ct = default);

    Task<OperationResult<DesignConversionDpoCandidateApprovalResult>> ApproveRuntimeCreatedDpoCandidateAsync(
        string localArtifactRecordId,
        string candidateOrTrainingRecordId,
        string reviewerRef,
        string reason,
        DateTimeOffset? approvedAtUtc = null,
        CancellationToken ct = default);

    /// <summary>
    /// Утверждает несколько кандидатов обучения одной атомарной операцией: все запросы проходят проверку
    /// до первой мутации, а журнал власти переписывается один раз для всей принятой пачки.
    /// </summary>
    Task<OperationResult<DesignConversionDpoCandidateApprovalBatchResult>>
        ApproveRuntimeCreatedDpoCandidatesAsync(
            IReadOnlyList<DesignConversionDpoCandidateApprovalRequest> requests,
            CancellationToken ct = default)
        // Интерфейс не имитирует пачку циклом одиночных вызовов: такой fallback
        // мог бы утвердить половину списка. Реальное хранилище обязано переопределить
        // метод одной атомарной транзакцией либо честно отказать без мутации.
        => Task.FromResult(
            OperationResult<DesignConversionDpoCandidateApprovalBatchResult>.Fail(
                "Atomic DesignConversion DPO candidate batch approval is unavailable for this storage implementation.",
                "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_ATOMIC_UNAVAILABLE"));

    Task<OperationResult<DesignConversionDpoDisplayResult>> QueryDisplayRowsAsync(
        DesignConversionDpoDisplayQuery? query = null,
        CancellationToken ct = default);
}

public static class DesignConversionTrainingIntakeRouteAdmissionContext
{
    private static readonly System.Threading.AsyncLocal<IReadOnlyDictionary<string, string>?> CurrentMetadata = new();

    public static IReadOnlyDictionary<string, string>? Current => CurrentMetadata.Value;

    public static async Task<T> RunAsync<T>(
        IReadOnlyDictionary<string, string>? metadata,
        Func<Task<T>> action)
    {
        var previous = CurrentMetadata.Value;
        CurrentMetadata.Value = metadata is null
            ? null
            : new Dictionary<string, string>(metadata, StringComparer.Ordinal);

        try
        {
            return await action();
        }
        finally
        {
            CurrentMetadata.Value = previous;
        }
    }
}

