        IDesignConversionPostEvaluationStateStore?
            postEvaluationStateStoreForTesting = null,
        IDesignConversionDpoPolicyBaseProvider? dpoPolicyBaseProvider = null,
        Action?
            runTrainingIntakeLocalPromotionBeforePolicyBridgePathResolveObserverForTesting = null,
        Func<CancellationToken, Task>?
            runTrainingIntakeLocalPromotionBeforeIdempotencyAppendCallbackForTesting = null,
        Func<DesignConversionTrainingRunResult, DesignConversionTrainingRunResult?>?
            runTrainingIntakeLocalPromotionCompletedRunnerResultTransformerForTesting = null,
        Func<DesignConversionDpoResolvedPartition, DesignConversionDpoResolvedPartition?>?
            runTrainingIntakeLocalPromotionPostBridgePartitionTransformerForTesting = null,
        Action<DesignConversionPromotionPublicationKind>?
            promotionBeforeTerminalReturnObserverForTesting = null,
        ServerOwnedLegalTrainingTeacherAdmissionAuthority?
            legalTeacherAdmissionAuthority = null,
        IDpoPairStore? trainingIntakeDpoPairStoreForTesting = null,
        DesignConversionCandidatePayloadCustodyStore?
            candidatePayloadCustodyStoreForTesting = null,
        Action<string>? candidatePayloadCustodyFaultInjectionForTesting = null,
        long trainingIntakeLocalPromotionOperationsMaxBytes =
