            runTrainingIntakeLocalPromotionOperationPhaseObserverForTesting = null,
        Action?
            runTrainingIntakeLocalPromotionBeforePreparedAppendObserverForTesting = null,
        Action?
            runTrainingIntakeLocalPromotionAfterPairReservationObserverForTesting = null,
        Action?
            runTrainingIntakeLocalPromotionAfterOutputReservationObserverForTesting = null,
        int localPromotionMaximumSealedSegmentCount =
            DesignConversionLocalPromotionJournalSet
                .DefaultMaximumSealedSegmentCount,
        long? localPromotionMaximumAggregateSealedBytes = null,
        Action<DesignConversionLocalPromotionJournalRotationStage>?
            localPromotionJournalRotationObserverForTesting = null,
        DesignConversionLocalReceiptOnlyPromotionUploadAuthority?
            localReceiptOnlyPromotionAuthority = null,
        DesignConversionServerOwnedConfiguredRemotePromotionUploadAuthority?
            serverOwnedConfiguredRemotePromotionAuthority = null,
        Func<
            IReadOnlyList<DesignConversionDpoTrainingRecord>,
            IReadOnlyList<DesignConversionDpoTrainingRecord>>?
            runTrainingIntakeResolvedRecordsTransformerForTesting = null,
        Action? recordsAuthorityReplacedObserverForTesting = null,
        DesignConversionTrainingIntakeDpoPairStoreOptions?
            trainingIntakeDpoPairStoreOptions = null,
        Action? derivedIndexBeforeAtomicPublishCallbackForTesting = null,
        Action<DesignConversionTrainingJournalPublicationKind>?
            trainingJournalBeforeAtomicPublishCallbackForTesting = null,
        Action?
            localPromotionJournalAppendPendingPublicationStartedObserverForTesting = null)
    {
        if (string.IsNullOrWhiteSpace(rootDirectory))
            throw new ArgumentException("A local artifact DB root is required.", nameof(rootDirectory));
        if (recordsAuthorityMaxBytes <= 0)
            throw new ArgumentOutOfRangeException(
                nameof(recordsAuthorityMaxBytes),
                recordsAuthorityMaxBytes,
                "The records authority byte limit must be positive.");
        if (trainingIntakeRequestsMaxBytes <= 0)
            throw new ArgumentOutOfRangeException(
                nameof(trainingIntakeRequestsMaxBytes),
                trainingIntakeRequestsMaxBytes,
                "The training intake request journal byte limit must be positive.");
        if (trainingIntakeRunsMaxBytes <= 0)
            throw new ArgumentOutOfRangeException(
                nameof(trainingIntakeRunsMaxBytes),
                trainingIntakeRunsMaxBytes,
                "The training intake run journal byte limit must be positive.");
        if (trainingIntakeLocalPromotionsMaxBytes <= 0)
            throw new ArgumentOutOfRangeException(
                nameof(trainingIntakeLocalPromotionsMaxBytes),
                trainingIntakeLocalPromotionsMaxBytes,
                "The training intake local promotion journal byte limit must be positive.");
        if (trainingIntakeLocalPromotionOperationsMaxBytes <= 0)
            throw new ArgumentOutOfRangeException(
                nameof(trainingIntakeLocalPromotionOperationsMaxBytes),
                trainingIntakeLocalPromotionOperationsMaxBytes,
                "The training intake local promotion operation journal byte limit must be positive.");

        _rootDirectory = Path.GetFullPath(rootDirectory);
        _recordsPath = Path.Combine(_rootDirectory, RecordsFileName);
        _recordsMutationLockPath = Path.Combine(_rootDirectory, RecordsMutationLockFileName);
        _indexPath = Path.Combine(_rootDirectory, IndexFileName);
        _trainingIntakePath = Path.Combine(_rootDirectory, TrainingIntakeFileName);
        _trainingIntakeMutationLockPath = Path.Combine(_rootDirectory, TrainingIntakeMutationLockFileName);
        _trainingIntakeRunPath = Path.Combine(_rootDirectory, TrainingIntakeRunFileName);
        _trainingIntakeRunMutationLockPath = Path.Combine(_rootDirectory, TrainingIntakeRunMutationLockFileName);
        _trainingIntakeLocalPromotionMutationLockPath = Path.Combine(
            _rootDirectory,
            TrainingIntakeLocalPromotionMutationLockFileName);
        _localPromotionJournalSet = new DesignConversionLocalPromotionJournalSet(
            _rootDirectory,
            TrainingIntakeLocalPromotionOperationFileName,
            TrainingIntakeLocalPromotionFileName,
            TrainingIntakeLocalPromotionMutationLockFileName,
            trainingIntakeLocalPromotionOperationsMaxBytes,
            trainingIntakeLocalPromotionsMaxBytes,
            localPromotionMaximumSealedSegmentCount,
            localPromotionMaximumAggregateSealedBytes,
            localPromotionJournalRotationObserverForTesting,
            appendPendingPublicationStartedObserver:
                localPromotionJournalAppendPendingPublicationStartedObserverForTesting);
        var legacyPairStoreRoot = Path.Combine(
            _rootDirectory,
            TrainingIntakeDpoPairStoreDirectoryName);
        if (trainingIntakeDpoPairStoreForTesting is null)
        {
            // Production path не пишет training-intake DPO пары напрямую под
            // artifact root на WSL `/mnt/c`: resolver либо выбирает native root,
            // либо падает закрыто на migration/manifest boundary.
            var trainingIntakeDpoPairStoreRootResolution =
                DesignConversionTrainingIntakeDpoPairStoreRootResolver.Resolve(
                    _rootDirectory,
                    TrainingIntakeDpoPairStoreDirectoryName,
                    trainingIntakeDpoPairStoreOptions);
            if (!trainingIntakeDpoPairStoreRootResolution.IsSuccess ||
                trainingIntakeDpoPairStoreRootResolution.Value is null)
            {
                throw new InvalidOperationException(string.Concat(
                    trainingIntakeDpoPairStoreRootResolution.ErrorCode,
                    ": ",
                    trainingIntakeDpoPairStoreRootResolution.ErrorMessage));
            }

            _trainingIntakeDpoPairStoreRootResolution =
                trainingIntakeDpoPairStoreRootResolution.Value;
        }
        else
        {
            // Test-only injected store уже владеет своей безопасностью; root
            // resolution остаётся legacy-shaped, чтобы не подменять fixture intent.
            _trainingIntakeDpoPairStoreRootResolution =
                new DesignConversionTrainingIntakeDpoPairStoreRootResolution(
                    legacyPairStoreRoot,
                    legacyPairStoreRoot,
                    string.Empty,
                    _rootDirectory,
                    string.Empty,
                    string.Empty,
                    string.Empty,
                    legacyPairStoreRoot,
                    string.Empty,
                    UsesNativeWslStateRoot: false);
        }
        _trainingIntakeDpoPairStore =
            trainingIntakeDpoPairStoreForTesting
            ?? ContinuousLearningDpoPairStores.CreateFileStore(
                _trainingIntakeDpoPairStoreRootResolution
                    .PairStoreRootDirectory);
        _candidatePayloadCustodyStore =
            candidatePayloadCustodyStoreForTesting
            ?? new DesignConversionCandidatePayloadCustodyStore(
                _rootDirectory,
                candidatePayloadCustodyFaultInjectionForTesting);
        _postEvaluationTrainingEligibilityPolicy =
            new DesignConversionPostEvaluationTrainingEligibilityPolicy(
                postEvaluationStateStoreForTesting ??
                new JsonDesignConversionPostEvaluationStateStore(
                    Path.Combine(
                        _rootDirectory,
                        JsonDesignConversionPostEvaluationStateStore.DirectoryName)));
        _promotionUploader = promotionUploader;
        _localReceiptOnlyPromotionAuthority =
            localReceiptOnlyPromotionAuthority;
        _serverOwnedConfiguredRemotePromotionAuthority =
            serverOwnedConfiguredRemotePromotionAuthority;
        _dpoPolicyBaseProvider = dpoPolicyBaseProvider;
        _legalTeacherAdmissionAuthority = legalTeacherAdmissionAuthority;
        _createTrainingIntakeJournalWaitTaskObserverForTesting = createTrainingIntakeJournalWaitTaskObserverForTesting;
        _createTrainingIntakeJournalGateAcquiredCallbackForTesting = createTrainingIntakeJournalGateAcquiredCallbackForTesting;
        _runTrainingIntakeGateWaitTaskObserverForTesting = runTrainingIntakeGateWaitTaskObserverForTesting;
        _runTrainingIntakeGateAcquiredCallbackForTesting = runTrainingIntakeGateAcquiredCallbackForTesting;
        _runTrainingIntakeRunnerBeforeInvokeObserverForTesting = runTrainingIntakeRunnerBeforeInvokeObserverForTesting;
        _runTrainingIntakeResolvedRecordsTransformerForTesting =
            runTrainingIntakeResolvedRecordsTransformerForTesting;
        _runTrainingIntakeRunnerInvokedObserverForTesting =
            runTrainingIntakeRunnerInvokedObserverForTesting;
        _runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting =
            runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting;
        _runTrainingIntakeLocalPromotionAfterCommittedExternalIdentityValidationObserverForTesting =
            runTrainingIntakeLocalPromotionAfterCommittedExternalIdentityValidationObserverForTesting;
        _runTrainingIntakeLocalPromotionBeforePublicationObserverForTesting =
            runTrainingIntakeLocalPromotionBeforePublicationObserverForTesting;
        _runTrainingIntakeLocalPromotionBeforePolicyBridgePathResolveObserverForTesting =
            runTrainingIntakeLocalPromotionBeforePolicyBridgePathResolveObserverForTesting;
        _runTrainingIntakeLocalPromotionBeforeIdempotencyAppendCallbackForTesting =
            runTrainingIntakeLocalPromotionBeforeIdempotencyAppendCallbackForTesting;
        _runTrainingIntakeLocalPromotionCompletedRunnerResultTransformerForTesting =
            runTrainingIntakeLocalPromotionCompletedRunnerResultTransformerForTesting;
        _runTrainingIntakeLocalPromotionPostBridgePartitionTransformerForTesting =
            runTrainingIntakeLocalPromotionPostBridgePartitionTransformerForTesting;
        _promotionBeforeTerminalReturnObserverForTesting =
            promotionBeforeTerminalReturnObserverForTesting;
        _runTrainingIntakeLocalPromotionBeforeActivationObserverForTesting =
            runTrainingIntakeLocalPromotionBeforeActivationObserverForTesting;
        _runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting =
            runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting;
        _runTrainingIntakeLocalPromotionGateWaitTaskObserverForTesting =
            runTrainingIntakeLocalPromotionGateWaitTaskObserverForTesting;
        _runTrainingIntakeLocalPromotionGateAcquiredCallbackForTesting =
            runTrainingIntakeLocalPromotionGateAcquiredCallbackForTesting;
        _runTrainingIntakeLocalPromotionOperationPhaseObserverForTesting =
            runTrainingIntakeLocalPromotionOperationPhaseObserverForTesting;
        _runTrainingIntakeLocalPromotionBeforePreparedAppendObserverForTesting =
            runTrainingIntakeLocalPromotionBeforePreparedAppendObserverForTesting;
        _runTrainingIntakeLocalPromotionAfterPairReservationObserverForTesting =
            runTrainingIntakeLocalPromotionAfterPairReservationObserverForTesting;
        _runTrainingIntakeLocalPromotionAfterOutputReservationObserverForTesting =
            runTrainingIntakeLocalPromotionAfterOutputReservationObserverForTesting;
        _authorityAppendBeforeOpenCallbackForTesting = authorityAppendBeforeOpenCallbackForTesting;
        _derivedIndexWriteObserverForTesting =
            derivedIndexWriteObserverForTesting;
        _derivedIndexBeforeAtomicPublishCallbackForTesting =
            derivedIndexBeforeAtomicPublishCallbackForTesting;
        _trainingJournalBeforeAtomicPublishCallbackForTesting =
            trainingJournalBeforeAtomicPublishCallbackForTesting;
        _recordsAuthorityRewriteObserverForTesting =
            recordsAuthorityRewriteObserverForTesting;
        _recordsAuthorityReplacedObserverForTesting =
            recordsAuthorityReplacedObserverForTesting;
        _recordsAuthorityMaxBytes = recordsAuthorityMaxBytes;
        _trainingIntakeRequestsMaxBytes = trainingIntakeRequestsMaxBytes;
        _trainingIntakeRunsMaxBytes = trainingIntakeRunsMaxBytes;
        _trainingIntakeLocalPromotionsMaxBytes = trainingIntakeLocalPromotionsMaxBytes;
        _trainingIntakeLocalPromotionOperationsMaxBytes =
            trainingIntakeLocalPromotionOperationsMaxBytes;
        _recordsMutationContext = RecordsMutationContexts.GetOrAdd(
            NormalizeRecordMutationGateKey(_recordsPath),
            _ => new RecordsMutationContext());
    }

    internal static OperationResult<DesignConversionDpoResolvedPartition>
        ResolveCompletedRunnerDpoTrainPartition(
            DesignConversionTrainingRunResult? completedRunnerResult,
            IReadOnlyList<DesignConversionDpoTrainingRecord>? finalResolvedRecords,
            CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionDpoResolvedPartition>();

        if (completedRunnerResult is null || finalResolvedRecords is null)
            return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();

        var pipeline = completedRunnerResult.PipelineResult;
        var topManifest = completedRunnerResult.DatasetManifest;
        if (pipeline is null || topManifest is null || pipeline.DatasetManifest is null)
            return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();

        var pipelineManifest = pipeline.DatasetManifest;
        if (!IsSafeEvaluatedDatasetId(topManifest.DatasetId) ||
            string.IsNullOrWhiteSpace(topManifest.DomainTag) ||
            !string.Equals(
                topManifest.DatasetId,
                pipelineManifest.DatasetId,
                StringComparison.Ordinal) ||
            !string.Equals(
                topManifest.DomainTag,
                pipelineManifest.DomainTag,
                StringComparison.Ordinal) ||
            !string.Equals(
                topManifest.DomainTag,
                DesignConversionMachine.DomainTag,
                StringComparison.Ordinal) ||
            topManifest.CreatedAtUtc != pipelineManifest.CreatedAtUtc ||
            topManifest.AcceptedRecordCount != pipelineManifest.AcceptedRecordCount ||
            topManifest.QuarantinedRecordCount != pipelineManifest.QuarantinedRecordCount ||
            topManifest.ExcludedRecordCount != pipelineManifest.ExcludedRecordCount ||
            pipeline.AcceptedRecordCount != topManifest.AcceptedRecordCount ||
            pipeline.QuarantinedRecordCount != topManifest.QuarantinedRecordCount)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
        }

        var gates = new DesignConversionDpoDatasetCountGate?[]
        {
            completedRunnerResult.DatasetCountGate,
            topManifest.CountGate,
            pipeline.DatasetCountGate,
            pipelineManifest.CountGate
        };
        if (gates.Any(gate => gate is null))
            return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();

        var authoritativeGate = gates[0]!;
        if (authoritativeGate.RequiredTrainRecords <= 0 ||
            authoritativeGate.RequiredHeldOutRecords <= 0 ||
            authoritativeGate.ActualTrainRecords < authoritativeGate.RequiredTrainRecords ||
            authoritativeGate.ActualHeldOutRecords < authoritativeGate.RequiredHeldOutRecords ||
            authoritativeGate.ActualHeldOutRecords <= 0 ||
            !authoritativeGate.Passed ||
            !authoritativeGate.SourceDisjoint ||
            gates.Skip(1).Any(gate =>
                !DpoDatasetCountGateScalarsAgree(authoritativeGate, gate!)))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
        }

        if (!TryResolveManifestIdentitySets(
                topManifest,
                out var trainIdentityHashes,
                out var heldOutIdentityHashes,
                out var trainSourceIdentityHashes,
                out var heldOutSourceIdentityHashes) ||
            !TryResolveManifestIdentitySets(
                pipelineManifest,
                out var pipelineTrainIdentityHashes,
                out var pipelineHeldOutIdentityHashes,
                out var pipelineTrainSourceIdentityHashes,
                out var pipelineHeldOutSourceIdentityHashes) ||
            !trainIdentityHashes.SetEquals(pipelineTrainIdentityHashes) ||
            !heldOutIdentityHashes.SetEquals(pipelineHeldOutIdentityHashes) ||
            !trainSourceIdentityHashes.SetEquals(pipelineTrainSourceIdentityHashes) ||
            !heldOutSourceIdentityHashes.SetEquals(pipelineHeldOutSourceIdentityHashes) ||
            trainIdentityHashes.Count != authoritativeGate.ActualTrainRecords ||
            heldOutIdentityHashes.Count != authoritativeGate.ActualHeldOutRecords ||
            trainIdentityHashes.Overlaps(heldOutIdentityHashes) ||
            trainSourceIdentityHashes.Overlaps(heldOutSourceIdentityHashes) ||
            topManifest.AcceptedRecordCount !=
                trainIdentityHashes.Count + heldOutIdentityHashes.Count)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
        }

        var batches = pipeline.Batches;
        if (batches is null || batches.Count == 0)
            return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();

        var batchIds = new HashSet<string>(StringComparer.Ordinal);
        var batchCompositeKeys = new HashSet<string>(StringComparer.Ordinal);
        var batchIdentityHashes = new HashSet<string>(StringComparer.Ordinal);
        var authoritativeTrainOrder = new List<string>(trainIdentityHashes.Count);
        foreach (var batch in batches)
        {
            if (batch is null ||
                string.IsNullOrWhiteSpace(batch.BatchId) ||
                string.IsNullOrWhiteSpace(batch.UnitId) ||
                !batchIds.Add(batch.BatchId) ||
                batch.Records is null ||
                batch.Records.Count == 0)
            {
                return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
            }

            foreach (var record in batch.Records)
            {
                if (!IsDpoPartitionRecordIdentityValid(record) ||
                    !string.Equals(batch.UnitId, record.UnitId, StringComparison.Ordinal))
                {
                    return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
                }

                var compositeKey = BuildDpoPartitionCompositeKey(record);
                var identityHash = ToDpoPartitionRecordIdentityHash(record);
                if (!batchCompositeKeys.Add(compositeKey) ||
                    !batchIdentityHashes.Add(identityHash) ||
                    !trainIdentityHashes.Contains(identityHash))
                {
                    return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
                }

                authoritativeTrainOrder.Add(identityHash);
            }
        }

        if (batchIdentityHashes.Count != authoritativeGate.ActualTrainRecords ||
            !batchIdentityHashes.SetEquals(trainIdentityHashes) ||
            !DpoTrainingItemsMatchBatches(pipeline, batches))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
        }

        var expectedFinalIdentityHashes = new HashSet<string>(
            trainIdentityHashes,
            StringComparer.Ordinal);
        expectedFinalIdentityHashes.UnionWith(heldOutIdentityHashes);

        var finalCompositeKeys = new HashSet<string>(StringComparer.Ordinal);
        var finalRecordsByIdentityHash = new Dictionary<
            string,
            DesignConversionDpoTrainingRecord>(StringComparer.Ordinal);
        foreach (var record in finalResolvedRecords)
        {
            if (!IsDpoPartitionRecordIdentityValid(record) ||
                !finalCompositeKeys.Add(BuildDpoPartitionCompositeKey(record)) ||
                !finalRecordsByIdentityHash.TryAdd(
                    ToDpoPartitionRecordIdentityHash(record),
                    record))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
            }
        }

        if (finalRecordsByIdentityHash.Count != expectedFinalIdentityHashes.Count ||
            !expectedFinalIdentityHashes.SetEquals(finalRecordsByIdentityHash.Keys))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
        }

        var selected = new DesignConversionDpoTrainingRecord[authoritativeTrainOrder.Count];
        for (var index = 0; index < authoritativeTrainOrder.Count; index++)
        {
            if (!finalRecordsByIdentityHash.TryGetValue(
                    authoritativeTrainOrder[index],
                    out var record))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<DesignConversionDpoResolvedPartition>();
            }

            selected[index] = record;
        }

        var heldOut = heldOutIdentityHashes
            .Order(StringComparer.Ordinal)
            .Select(identityHash => finalRecordsByIdentityHash[identityHash])
            .ToArray();
        var trainRecordSetSha256 =
            DesignConversionDpoConsumedPartitionProjectionContract.ComputeSetHash(
            "design-conversion-dpo-train-record-set-v1",
            trainIdentityHashes);
        var heldOutRecordSetSha256 =
            DesignConversionDpoConsumedPartitionProjectionContract.ComputeSetHash(
            "design-conversion-dpo-heldout-record-set-v1",
            heldOutIdentityHashes);
        var trainSourceSetSha256 =
            DesignConversionDpoConsumedPartitionProjectionContract.ComputeSetHash(
            "design-conversion-dpo-train-source-set-v1",
            trainSourceIdentityHashes);
        var heldOutSourceSetSha256 =
            DesignConversionDpoConsumedPartitionProjectionContract.ComputeSetHash(
            "design-conversion-dpo-heldout-source-set-v1",
            heldOutSourceIdentityHashes);
        var provisionalPartition = new DesignConversionDpoResolvedPartition(
            topManifest.DatasetId,
            selected,
            heldOut,
            trainRecordSetSha256,
            heldOutRecordSetSha256,
            trainSourceSetSha256,
            heldOutSourceSetSha256,
            PartitionSnapshotSha256: string.Empty);
        if (!DesignConversionDpoConsumedPartitionProjectionContract.TryCreate(
                provisionalPartition,
                selected.Length,
                out var fullProjection) ||
            fullProjection is null ||
            !string.Equals(
                trainRecordSetSha256,
                fullProjection.TrainRecordSetSha256,
                StringComparison.Ordinal) ||
            !string.Equals(
                heldOutRecordSetSha256,
                fullProjection.HeldOutRecordSetSha256,
                StringComparison.Ordinal) ||
            !string.Equals(
                trainSourceSetSha256,
                fullProjection.TrainSourceSetSha256,
                StringComparison.Ordinal) ||
            !string.Equals(
                heldOutSourceSetSha256,
                fullProjection.HeldOutSourceSetSha256,
                StringComparison.Ordinal))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionDpoResolvedPartition>();
        }

        return OperationResult<DesignConversionDpoResolvedPartition>.Ok(
            provisionalPartition with
            {
                PartitionSnapshotSha256 = fullProjection.PartitionSnapshotSha256
            });
    }

    internal static OperationResult<DesignConversionDpoResolvedPartition>
        ResolvePreparedDpoTrainPartition(
            DesignConversionTrainingPipeline.PreparedPipelineExecution?
                prepared,
            IReadOnlyList<DesignConversionDpoTrainingRecord>?
                finalResolvedRecords,
            CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionDpoResolvedPartition>();
        if (prepared is null || finalResolvedRecords is null)
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionDpoResolvedPartition>();

        var dataset = prepared.Dataset;
        var gate = dataset.Manifest.CountGate;
        if (!IsSafeEvaluatedDatasetId(dataset.DatasetId) ||
            !gate.Passed || !gate.SourceDisjoint ||
            gate.ActualTrainRecords <= 0 || gate.ActualHeldOutRecords <= 0 ||
            prepared.Batches.Count == 0)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionDpoResolvedPartition>();
        }

        var trainHashes = dataset.TrainRows
            .Select(static row => row.RecordIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        var heldOutHashes = dataset.HeldOutRows
            .Select(static row => row.RecordIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        var trainSourceHashes = dataset.TrainRows
            .Select(static row => row.SourceIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        var heldOutSourceHashes = dataset.HeldOutRows
            .Select(static row => row.SourceIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        if (trainHashes.Count != gate.ActualTrainRecords ||
            heldOutHashes.Count != gate.ActualHeldOutRecords ||
            trainHashes.Overlaps(heldOutHashes) ||
            trainSourceHashes.Overlaps(heldOutSourceHashes))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionDpoResolvedPartition>();
        }

        var recordsByHash = new Dictionary<string,
            DesignConversionDpoTrainingRecord>(StringComparer.Ordinal);
        foreach (var record in finalResolvedRecords)
        {
            if (!IsDpoPartitionRecordIdentityValid(record) ||
                !recordsByHash.TryAdd(
                    ToDpoPartitionRecordIdentityHash(record),
                    record))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    DesignConversionDpoResolvedPartition>();
            }
        }
        if (recordsByHash.Count != trainHashes.Count + heldOutHashes.Count ||
            !recordsByHash.Keys.All(hash =>
                trainHashes.Contains(hash) || heldOutHashes.Contains(hash)))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionDpoResolvedPartition>();
        }

        var preparedTrain = prepared.Batches
            .SelectMany(static batch => batch.Records)
            .ToArray();
        var preparedTrainHashes = preparedTrain
            .Select(ToDpoPartitionRecordIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        if (preparedTrain.Length != trainHashes.Count ||
            !preparedTrainHashes.SetEquals(trainHashes))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionDpoResolvedPartition>();
        }
        var train = new DesignConversionDpoTrainingRecord[
            preparedTrain.Length];
        for (var index = 0; index < preparedTrain.Length; index++)
        {
            var preparedHash =
                ToDpoPartitionRecordIdentityHash(preparedTrain[index]);
            if (!recordsByHash.TryGetValue(preparedHash, out var resolvedTrain))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    DesignConversionDpoResolvedPartition>();
            }

            // Порядок train берём из prepared batches, а содержимое — только
            // через проверенную custody-материализацию, чтобы bridge не получил
            // public PayloadRef стороны вместо настоящих html/css.
            var materializedTrain =
                MaterializeResolvedDpoPartitionRecordForBridge(resolvedTrain);
            if (!materializedTrain.IsSuccess ||
                materializedTrain.Value is null)
            {
                return materializedTrain.MapError<
                    DesignConversionDpoResolvedPartition>();
            }

            train[index] = materializedTrain.Value;
        }
        var orderedHeldOutHashes = heldOutHashes
            .Order(StringComparer.Ordinal)
            .ToArray();
        var heldOut = new DesignConversionDpoTrainingRecord[
            orderedHeldOutHashes.Length];
        for (var index = 0; index < orderedHeldOutHashes.Length; index++)
        {
            var resolvedHeldOut = recordsByHash[orderedHeldOutHashes[index]];
            var materializedHeldOut =
                MaterializeResolvedDpoPartitionRecordForBridge(resolvedHeldOut);
            if (!materializedHeldOut.IsSuccess ||
                materializedHeldOut.Value is null)
            {
                return materializedHeldOut.MapError<
                    DesignConversionDpoResolvedPartition>();
            }

            heldOut[index] = materializedHeldOut.Value;
        }

        var trainRecordSetSha256 =
            DesignConversionDpoConsumedPartitionProjectionContract.ComputeSetHash(
                "design-conversion-dpo-train-record-set-v1",
                trainHashes);
        var heldOutRecordSetSha256 =
            DesignConversionDpoConsumedPartitionProjectionContract.ComputeSetHash(
                "design-conversion-dpo-heldout-record-set-v1",
                heldOutHashes);
        var trainSourceSetSha256 =
            DesignConversionDpoConsumedPartitionProjectionContract.ComputeSetHash(
                "design-conversion-dpo-train-source-set-v1",
                trainSourceHashes);
        var heldOutSourceSetSha256 =
            DesignConversionDpoConsumedPartitionProjectionContract.ComputeSetHash(
                "design-conversion-dpo-heldout-source-set-v1",
                heldOutSourceHashes);
        var provisional = new DesignConversionDpoResolvedPartition(
            dataset.DatasetId,
            train,
            heldOut,
            trainRecordSetSha256,
            heldOutRecordSetSha256,
            trainSourceSetSha256,
            heldOutSourceSetSha256,
            PartitionSnapshotSha256: string.Empty);
        if (!DesignConversionDpoConsumedPartitionProjectionContract.TryCreate(
                provisional,
                train.Length,
                out var fullProjection) ||
            fullProjection is null)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionDpoResolvedPartition>();
        }
        return OperationResult<DesignConversionDpoResolvedPartition>.Ok(
            provisional with
            {
                PartitionSnapshotSha256 =
                    fullProjection.PartitionSnapshotSha256
            });

        static OperationResult<DesignConversionDpoTrainingRecord>
            MaterializeResolvedDpoPartitionRecordForBridge(
                DesignConversionDpoTrainingRecord record)
        {
            if (!RequiresPayloadCustody(record))
            {
                return record.PayloadCustodySecret is null
                    ? OperationResult<DesignConversionDpoTrainingRecord>.Ok(
                        record)
                    : PayloadCustodyFailed<
                        DesignConversionDpoTrainingRecord>();
            }

            return ValidateAndMaterializePayloadCustody(record);
        }
    }

    private sealed record CommittedDualTargetTeacherPromotionMaterialization(
        DesignConversionDpoResolvedPartition Partition,
        IReadOnlyList<DesignConversionDpoTrainingRecord> TransferTrainRecords,
        DesignConversionFinalOptimizerBatch<LearningTrainingItem> FinalOptimizer,
        DpoPair[] Pairs);

    private sealed record AdmittedCorpusLocalPromotionContinuation(
        DesignConversionDpoAdmittedCorpus Corpus,
        DesignConversionPreparedTrainingRecordExecution PreparedRunner,
        ProjectedDualTargetTeacherExternalConsumption ExternalProjection,
        DesignConversionExternalConsumptionCommitEvidence
            ExternalConsumption);

    private static OperationResult<
        CommittedDualTargetTeacherPromotionMaterialization>
        MaterializeCommittedDualTargetTeacherExternalPromotionInputs(
            DesignConversionDpoResolvedPartition? partition,
            DesignConversionDpoTrainingContentAuthority
                .DualTargetTeacherAggregateCommitment? aggregateCommitment,
            DpoPairAtomicGroupEnvelope? group,
            DesignConversionExternalConsumptionCommitEvidence?
                committedExternalConsumption)
    {
        if (partition is null ||
            aggregateCommitment is null ||
            group is null ||
            committedExternalConsumption is null ||
            partition.TrainRecords.Count != 2 ||
            group.Children.Count != 2 ||
            committedExternalConsumption.OrderedPairIds.Count != 2 ||
            committedExternalConsumption.OrderedContentSha256s.Count != 2 ||
            !aggregateCommitment.MatchesExactChildren(
                aggregateCommitment.FinalOptimizer) ||
            !string.Equals(
                group.RequestId,
                committedExternalConsumption.RequestId,
                StringComparison.Ordinal) ||
            !string.Equals(
                group.GroupCommitmentSha256,
                committedExternalConsumption.GroupCommitmentSha256,
                StringComparison.Ordinal) ||
            !string.Equals(
                committedExternalConsumption.RequestId,
                aggregateCommitment.ParentProvenance.RequestId,
                StringComparison.Ordinal) ||
            !string.Equals(
                committedExternalConsumption.ParentBatchSha256,
                aggregateCommitment.ParentContent.Sha256,
                StringComparison.Ordinal) ||
            !string.Equals(
                committedExternalConsumption.ParentContentSha256,
                aggregateCommitment.ParentContent.Rows[0].Sha256,
                StringComparison.Ordinal) ||
            !committedExternalConsumption.OrderedPairIds.SequenceEqual(
                group.Children.Select(static child => child.PairId),
                StringComparer.Ordinal) ||
            !committedExternalConsumption.OrderedContentSha256s.SequenceEqual(
                group.Children.Select(static child => child.ContentSha256),
                StringComparer.Ordinal))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                CommittedDualTargetTeacherPromotionMaterialization>();
        }

        if (partition.TrainRecords.Any(static row =>
                row.TeacherProvenance is null) ||
            partition.HeldOutRecords.Any(row => string.Equals(
                row.TeacherProvenance?.RequestId,
                committedExternalConsumption.RequestId,
                StringComparison.Ordinal)))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                CommittedDualTargetTeacherPromotionMaterialization>();
        }

        var transferTrain = new DesignConversionDpoTrainingRecord[
            partition.TrainRecords.Count];
        var transferItems = new LearningTrainingItem[partition.TrainRecords.Count];
        var transferProvenance =
            new TrainingTeacherProvenance?[partition.TrainRecords.Count];
        var transferPairs = new DpoPair[partition.TrainRecords.Count];
        for (var index = 0; index < transferTrain.Length; index++)
        {
            var materialized =
                MaterializeCommittedDualTargetTeacherExternalChildForBridge(
                    partition.TrainRecords[index],
                    group.Children[index],
                    committedExternalConsumption,
                    index);
            if (!materialized.IsSuccess || materialized.Value is null)
            {
                return materialized.MapError<
                    CommittedDualTargetTeacherPromotionMaterialization>();
            }

            transferTrain[index] = materialized.Value.Record;
            transferItems[index] = materialized.Value.Item;
            transferProvenance[index] =
                materialized.Value.Record.TeacherProvenance;
            transferPairs[index] = materialized.Value.Pair;
        }

        var transferOptimizer = DesignConversionDpoTrainingContentAuthority
            .ProjectFinalOptimizerInputs(
                transferItems,
                transferProvenance,
                static item => item.Prompt,
                static item => item.ChosenResponse,
                static item => item.RejectedResponse,
                static _ => null,
                static _ => null,
                static item => string.Concat(
                    "design-conversion-learning-machine-final-v1|item=",
                    item.ItemId));
        if (!transferOptimizer.IsSuccess || transferOptimizer.Value is null)
        {
            return transferOptimizer.MapError<
                CommittedDualTargetTeacherPromotionMaterialization>();
        }

        var transfer = partition with
        {
            TrainRecords = transferTrain,
            PartitionSnapshotSha256 = string.Empty
        };
        if (!DesignConversionDpoConsumedPartitionProjectionContract.TryCreate(
                transfer,
                transferTrain.Length,
                out var projection) ||
            projection is null ||
            !transferPairs.Select(pair => pair.TeacherProvenance?.RequestId)
                .SequenceEqual(
                    transferOptimizer.Value.Provenance
                        .Select(static provenance => provenance?.RequestId),
                    StringComparer.Ordinal))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                CommittedDualTargetTeacherPromotionMaterialization>();
        }

        return OperationResult<
            CommittedDualTargetTeacherPromotionMaterialization>.Ok(
            new CommittedDualTargetTeacherPromotionMaterialization(
                transfer with
                {
                    TrainRecordSetSha256 = projection.TrainRecordSetSha256,
                    HeldOutRecordSetSha256 = projection.HeldOutRecordSetSha256,
                    TrainSourceSetSha256 = projection.TrainSourceSetSha256,
                    HeldOutSourceSetSha256 = projection.HeldOutSourceSetSha256,
                    PartitionSnapshotSha256 =
                        projection.PartitionSnapshotSha256
                },
                transferTrain,
                transferOptimizer.Value,
                transferPairs));
    }

    private static OperationResult<IReadOnlyList<DesignConversionDpoTrainingRecord>>
        ResolveAdmittedCorpusLocalPromotionRecords(
            DesignConversionDpoAdmittedCorpus? corpus,
            IReadOnlyList<DesignConversionDpoTrainingRecord>? currentRecords)
    {
        if (corpus is null ||
            currentRecords is null ||
            corpus.Records is null ||
            corpus.Records.Count != 2 ||
            corpus.Admission?.SourceProof?.TrainRows is null ||
            corpus.Admission.SourceProof.HeldOutRows is null ||
            corpus.Admission.SourceProof.HeldOutRows.Count == 0)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                IReadOnlyList<DesignConversionDpoTrainingRecord>>();
        }

        var currentByIdentity = new Dictionary<string,
            DesignConversionDpoTrainingRecord>(StringComparer.Ordinal);
        foreach (var record in currentRecords)
        {
            if (!IsDpoPartitionRecordIdentityValid(record) ||
                !currentByIdentity.TryAdd(
                    ToDpoPartitionRecordIdentityHash(record),
                    record))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    IReadOnlyList<DesignConversionDpoTrainingRecord>>();
            }
        }

        var derivativeByKey = new Dictionary<string,
            DesignConversionDpoTrainingRecord>(StringComparer.Ordinal);
        foreach (var record in corpus.Records)
        {
            if (!IsDpoPartitionRecordIdentityValid(record) ||
                !derivativeByKey.TryAdd(BuildDpoPartitionCompositeKey(record), record))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    IReadOnlyList<DesignConversionDpoTrainingRecord>>();
            }
        }

        foreach (var row in corpus.Admission.SourceProof.TrainRows)
        {
            if (string.IsNullOrWhiteSpace(row.RecordIdentityHash) ||
                !currentByIdentity.TryGetValue(
                    row.RecordIdentityHash,
                    out var currentOriginal) ||
                !derivativeByKey.ContainsKey(
                    BuildDpoPartitionCompositeKey(currentOriginal)))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    IReadOnlyList<DesignConversionDpoTrainingRecord>>();
            }
        }

        var records = new List<DesignConversionDpoTrainingRecord>(
            corpus.Records);
        foreach (var row in corpus.Admission.SourceProof.HeldOutRows)
        {
            if (string.IsNullOrWhiteSpace(row.RecordIdentityHash) ||
                !currentByIdentity.TryGetValue(
                    row.RecordIdentityHash,
                    out var heldOut))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    IReadOnlyList<DesignConversionDpoTrainingRecord>>();
            }

            var materializedHeldOut =
                MaterializeAdmittedCorpusHeldOutRecordForBridge(
                    heldOut,
                    row);
            if (!materializedHeldOut.IsSuccess ||
                materializedHeldOut.Value is null)
            {
                return materializedHeldOut.MapError<
                    IReadOnlyList<DesignConversionDpoTrainingRecord>>();
            }

            records.Add(materializedHeldOut.Value);
        }

        if (records.Select(BuildDpoPartitionCompositeKey)
                .Distinct(StringComparer.Ordinal)
                .Count() != records.Count)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                IReadOnlyList<DesignConversionDpoTrainingRecord>>();
        }

        return OperationResult<IReadOnlyList<DesignConversionDpoTrainingRecord>>
            .Ok(records);
    }

    private static OperationResult<DesignConversionDpoTrainingRecord>
        MaterializeAdmittedCorpusHeldOutRecordForBridge(
            DesignConversionDpoTrainingRecord currentHeldOut,
            DesignConversionDpoDatasetRow sourceProofRow)
    {
        if (currentHeldOut is null ||
            sourceProofRow is null ||
            string.IsNullOrWhiteSpace(sourceProofRow.RecordIdentityHash) ||
            !string.Equals(
                sourceProofRow.RecordIdentityHash,
                ToDpoPartitionRecordIdentityHash(currentHeldOut),
                StringComparison.Ordinal) ||
            !TryReadOptimizerResponsePayload(
                sourceProofRow.Chosen,
                out var chosenHtml,
                out var chosenCss) ||
            !TryReadOptimizerResponsePayload(
                sourceProofRow.Rejected,
                out var rejectedHtml,
                out var rejectedCss))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionDpoTrainingRecord>();
        }

        var sourceProofSideContract =
            DesignConversionDpoOptimizerSideContract.ValidatePair(
                sourceProofRow.Chosen,
                sourceProofRow.Rejected);
        if (!sourceProofSideContract.IsSuccess)
        {
            return sourceProofSideContract.MapError<
                DesignConversionDpoTrainingRecord>();
        }

        // Доказательство источника было создано из этой же held-out строки до
        // замены закрытого содержимого публичными хеш-ссылками. Для локальной
        // проверяемой публикации можно взять уже допущенный канонический payload
        // как свидетельство экзамена, но оставить live-идентичность записи.
        var materialized = currentHeldOut with
        {
            Chosen = currentHeldOut.Chosen with
            {
                Html = chosenHtml,
                Css = chosenCss
            },
            Rejected = currentHeldOut.Rejected with
            {
                Html = rejectedHtml,
                Css = rejectedCss
            }
        };

        if (!string.Equals(
                DesignConversionDpoDatasetBuilder
                    .BuildOptimizerResponsePayload(materialized.Chosen),
                sourceProofRow.Chosen,
                StringComparison.Ordinal) ||
            !string.Equals(
                DesignConversionDpoDatasetBuilder
                    .BuildOptimizerResponsePayload(materialized.Rejected),
                sourceProofRow.Rejected,
                StringComparison.Ordinal))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionDpoTrainingRecord>();
        }

        var bridgeSideContract =
            DesignConversionDpoOptimizerSideContract.ValidatePair(
                DesignConversionDpoPolicyCheckpointBridge
                    .SerializePolicySideText(
                        materialized.Chosen.Html,
                        materialized.Chosen.Css),
                DesignConversionDpoPolicyCheckpointBridge
                    .SerializePolicySideText(
                        materialized.Rejected.Html,
                        materialized.Rejected.Css));
        if (!bridgeSideContract.IsSuccess)
        {
            return bridgeSideContract.MapError<
                DesignConversionDpoTrainingRecord>();
        }

        return OperationResult<DesignConversionDpoTrainingRecord>.Ok(
            materialized);
    }

    private static bool TryReadOptimizerResponsePayload(
        string? payload,
        out string html,
        out string css)
    {
        html = string.Empty;
        css = string.Empty;
        if (payload is null)
            return false;

        try
        {
            using var document = JsonDocument.Parse(
                payload,
                new JsonDocumentOptions
                {
                    AllowTrailingCommas = false,
                    CommentHandling = JsonCommentHandling.Disallow,
                    MaxDepth = 16
                });
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
                return false;

            var htmlCount = 0;
            var cssCount = 0;
            var propertyCount = 0;
            foreach (var property in root.EnumerateObject())
            {
                propertyCount++;
                if (property.Value.ValueKind != JsonValueKind.String)
                    return false;

                switch (property.Name)
                {
                    case "html":
                        htmlCount++;
                        html = property.Value.GetString() ?? string.Empty;
                        break;
                    case "css":
                        cssCount++;
                        css = property.Value.GetString() ?? string.Empty;
                        break;
                    default:
                        return false;
                }
            }

            return propertyCount == 2 &&
                   htmlCount == 1 &&
                   cssCount == 1;
        }
        catch (JsonException)
        {
            return false;
        }
    }

    private static OperationResult<DesignConversionPreparedTrainingRecordExecution>
        PrepareAdmittedCorpusLocalPromotionContinuationRunner(
            DesignConversionDpoAdmittedCorpus? corpus,
            IReadOnlyList<DesignConversionDpoTrainingRecord>? localPromotionRecords,
            DesignConversionPreparedTrainingRecordExecution?
                admittedPreparedRunner)
    {
        if (corpus is null ||
            localPromotionRecords is null ||
            localPromotionRecords.Count <= corpus.Records.Count ||
            admittedPreparedRunner is null ||
            admittedPreparedRunner.Pipeline is null ||
            admittedPreparedRunner.Pipeline.FinalOptimizer is null ||
            !corpus.Admission.Authorizes(
                corpus,
                corpus.Records,
                admittedPreparedRunner.Pipeline.Dataset))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionPreparedTrainingRecordExecution>();
        }

        var datasetIdentityHashes = corpus.Dataset.TrainRows
            .Concat(corpus.Dataset.HeldOutRows)
            .Select(static row => row.RecordIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        var localIdentityHashes = localPromotionRecords
            .Select(ToDpoPartitionRecordIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        if (datasetIdentityHashes.Count != localIdentityHashes.Count ||
            !datasetIdentityHashes.SetEquals(localIdentityHashes))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionPreparedTrainingRecordExecution>();
        }

        var build = new DesignConversionDpoBuildResult(
            AcceptedRecords: localPromotionRecords,
            QuarantinedRecords: [],
            Warnings:
            [
                "DESIGN_CONVERSION_SERVER_OWNED_CORPUS_ADMISSION",
                "SOURCE_RECORDS_REMAIN_REVIEW_ONLY_NOT_TRAINING_GRADE",
                "dual_target_teacher_external_local_continuation_after_corpus_admission"
            ]);
        var preparedTrainKeys = admittedPreparedRunner.Pipeline.Batches
            .SelectMany(static batch => batch.Records)
            .Select(BuildDpoPartitionCompositeKey)
            .ToArray();
        var admittedTrainKeys = corpus.Records
            .Select(BuildDpoPartitionCompositeKey)
            .ToArray();
        if (!preparedTrainKeys.SequenceEqual(
                admittedTrainKeys,
                StringComparer.Ordinal))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionPreparedTrainingRecordExecution>();
        }

        return OperationResult<DesignConversionPreparedTrainingRecordExecution>
            .Ok(new DesignConversionPreparedTrainingRecordExecution(
                build,
                corpus.Options,
                null,
                admittedPreparedRunner.Pipeline));
    }

    private static OperationResult<DesignConversionPreparedTrainingRecordExecution>
        PrepareCommittedDualTargetTeacherLocalContinuationRunner(
            DesignConversionPreparedTrainingRecordExecution? prepared,
            CommittedDualTargetTeacherPromotionMaterialization?
                committedPromotion,
            string effectiveRunId)
    {
        if (prepared is null ||
            committedPromotion is null ||
            prepared.Pipeline is null ||
            prepared.Pipeline.Dataset is null ||
            committedPromotion.FinalOptimizer is null ||
            committedPromotion.TransferTrainRecords is null ||
            committedPromotion.TransferTrainRecords.Count == 0 ||
            committedPromotion.TransferTrainRecords.Count !=
            committedPromotion.FinalOptimizer.Inputs.Count ||
            string.IsNullOrWhiteSpace(effectiveRunId))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionPreparedTrainingRecordExecution>();
        }

        var transferTrainRecords =
            committedPromotion.TransferTrainRecords.ToArray();
        var transferItems = committedPromotion.FinalOptimizer.Inputs.ToArray();
        var transferByCompositeKey = new Dictionary<string,
            DesignConversionDpoTrainingRecord>(StringComparer.Ordinal);
        foreach (var transferRecord in transferTrainRecords)
        {
            if (!IsDpoPartitionRecordIdentityValid(transferRecord) ||
                !transferByCompositeKey.TryAdd(
                    BuildDpoPartitionCompositeKey(transferRecord),
                    transferRecord))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    DesignConversionPreparedTrainingRecordExecution>();
            }
        }

        var replacedTransferRecordCount = 0;
        var localAcceptedRecords = new List<DesignConversionDpoTrainingRecord>(
            prepared.Build.AcceptedRecords.Count);
        foreach (var acceptedRecord in prepared.Build.AcceptedRecords ?? [])
        {
            if (!IsDpoPartitionRecordIdentityValid(acceptedRecord))
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    DesignConversionPreparedTrainingRecordExecution>();
            }

            var key = BuildDpoPartitionCompositeKey(acceptedRecord);
            if (transferByCompositeKey.TryGetValue(key, out var transferRecord))
            {
                localAcceptedRecords.Add(transferRecord);
                replacedTransferRecordCount++;
            }
            else
            {
                localAcceptedRecords.Add(acceptedRecord);
            }
        }

        if (replacedTransferRecordCount != transferTrainRecords.Length)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionPreparedTrainingRecordExecution>();
        }

        var localOptions = prepared.Options with
        {
            // Durable-журнал публикации уже заморозил output path по этому run id.
            // Локальное продолжение обязано использовать тот же id, иначе защита
            // справедливо сочтёт повтор неопределённым после записи intent.
            RunId = effectiveRunId
        };
        var localBuild = new DesignConversionDpoBuildResult(
            localAcceptedRecords.ToArray(),
            prepared.Build.QuarantinedRecords,
            (prepared.Build.Warnings ?? [])
                .Append(
                    "dual_target_teacher_external_local_continuation_after_commit")
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray());
        var localPreparedPipeline = new DesignConversionTrainingPipeline()
            .PrepareExecutionWithExistingDataset(
                localBuild.AllRecords,
                localOptions,
                prepared.Pipeline.Dataset);
        if (!localPreparedPipeline.IsSuccess ||
            localPreparedPipeline.Value is null ||
            localPreparedPipeline.Value.FinalOptimizer is null ||
            !PreparedCommittedDualTargetTeacherLocalContinuationMatchesTransfer(
                localPreparedPipeline.Value,
                transferTrainRecords,
                transferItems))
        {
            return localPreparedPipeline.IsSuccess
                ? DpoPolicyBridgeTrainPartitionInvalid<
                    DesignConversionPreparedTrainingRecordExecution>()
                : localPreparedPipeline.MapError<
                DesignConversionPreparedTrainingRecordExecution>();
        }

        return OperationResult<DesignConversionPreparedTrainingRecordExecution>
            .Ok(new DesignConversionPreparedTrainingRecordExecution(
                localBuild,
                localOptions,
                prepared.CustodyCapability,
                localPreparedPipeline.Value));
    }

    private static bool
        PreparedCommittedDualTargetTeacherLocalContinuationMatchesTransfer(
            DesignConversionTrainingPipeline.PreparedPipelineExecution prepared,
            IReadOnlyList<DesignConversionDpoTrainingRecord> transferTrainRecords,
            IReadOnlyList<LearningTrainingItem> transferItems)
    {
        if (prepared is null ||
            prepared.FinalOptimizer is null ||
            transferTrainRecords is null ||
            transferItems is null ||
            transferTrainRecords.Count == 0 ||
            transferTrainRecords.Count != transferItems.Count ||
            prepared.FinalOptimizer.Inputs.Count != transferItems.Count)
        {
            return false;
        }

        var preparedTrainRecords = prepared.Batches
            .SelectMany(static batch => batch.Records)
            .ToArray();
        if (preparedTrainRecords.Length != transferTrainRecords.Count)
        {
            return false;
        }

        var transferByKey = new Dictionary<string, (
            DesignConversionDpoTrainingRecord Record,
            LearningTrainingItem Item)>(StringComparer.Ordinal);
        for (var index = 0; index < transferTrainRecords.Count; index++)
        {
            if (!transferByKey.TryAdd(
                    BuildDpoPartitionCompositeKey(transferTrainRecords[index]),
                    (transferTrainRecords[index], transferItems[index])))
            {
                return false;
            }
        }

        if (transferByKey.Count != transferTrainRecords.Count)
        {
            return false;
        }

        for (var index = 0; index < preparedTrainRecords.Length; index++)
        {
            var preparedRecord = preparedTrainRecords[index];
            if (!transferByKey.TryGetValue(
                    BuildDpoPartitionCompositeKey(preparedRecord),
                    out var transfer) ||
                !ReferenceEquals(preparedRecord, transfer.Record))
            {
                return false;
            }

            var preparedItem = prepared.FinalOptimizer.Inputs[index];
            var transferItem = transfer.Item;
            if (!string.Equals(preparedItem.Prompt, transferItem.Prompt, StringComparison.Ordinal) ||
                !string.Equals(preparedItem.ChosenResponse, transferItem.ChosenResponse, StringComparison.Ordinal) ||
                !string.Equals(preparedItem.RejectedResponse, transferItem.RejectedResponse, StringComparison.Ordinal))
            {
                return false;
            }
        }

        return true;
    }

    private static OperationResult<bool>
        ValidateCommittedExternalTransferOptimizerSidesForBridge(
            IReadOnlyList<DesignConversionDpoTrainingRecord>? records)
    {
        if (records is null || records.Count == 0)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<bool>();
        }

        foreach (var record in records)
        {
            if (record is null)
            {
                return DpoPolicyBridgeTrainPartitionInvalid<bool>();
            }

            var sideContract =
                DesignConversionDpoOptimizerSideContract.ValidatePair(
                    DesignConversionDpoPolicyCheckpointBridge
                        .SerializePolicySideText(
                            record.Chosen.Html,
                            record.Chosen.Css),
                    DesignConversionDpoPolicyCheckpointBridge
                        .SerializePolicySideText(
                            record.Rejected.Html,
                            record.Rejected.Css));
            if (!sideContract.IsSuccess)
            {
                return sideContract;
            }
        }

        return OperationResult<bool>.Ok(true);
    }

    private static IReadOnlyList<DesignConversionDpoTrainingRecord>?
        MergeCommittedDualTargetTeacherTransferTrainRecords(
            IReadOnlyList<DesignConversionDpoTrainingRecord>? sourceRecords,
            IReadOnlyList<DesignConversionDpoTrainingRecord>? transferTrainRecords)
    {
        if (sourceRecords is null ||
            transferTrainRecords is null ||
            transferTrainRecords.Count == 0)
        {
            return null;
        }

        var transferByKey = new Dictionary<string,
            DesignConversionDpoTrainingRecord>(StringComparer.Ordinal);
        foreach (var transferRecord in transferTrainRecords)
        {
            if (!IsDpoPartitionRecordIdentityValid(transferRecord) ||
                !transferByKey.TryAdd(
                    BuildDpoPartitionCompositeKey(transferRecord),
                    transferRecord))
            {
                return null;
            }
        }

        var replaced = 0;
        var merged = new DesignConversionDpoTrainingRecord[sourceRecords.Count];
        for (var index = 0; index < sourceRecords.Count; index++)
        {
            var sourceRecord = sourceRecords[index];
            if (!IsDpoPartitionRecordIdentityValid(sourceRecord))
            {
                return null;
            }

            if (transferByKey.TryGetValue(
                    BuildDpoPartitionCompositeKey(sourceRecord),
                    out var transferRecord))
            {
                // Проверочные partition-снимки должны видеть тот же train,
                // который реально мутировал локальный checkpoint. Held-out
                // строки не трогаем: экзамен остаётся исходным и независимым.
                merged[index] = transferRecord;
                replaced++;
            }
            else
            {
                merged[index] = sourceRecord;
            }
        }

        return replaced == transferByKey.Count
            ? merged
            : null;
    }

    private static OperationResult<IReadOnlyList<DesignConversionDpoTrainingRecord>>
        ResolveRunnerRecordsForCommittedDualTargetTeacherContinuation(
            IReadOnlyList<DesignConversionDpoTrainingRecord>? sourceRecords,
            CommittedDualTargetTeacherPromotionMaterialization?
                committedExternalPromotion)
    {
        if (sourceRecords is null)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                IReadOnlyList<DesignConversionDpoTrainingRecord>>();
        }

        if (committedExternalPromotion is null)
            return OperationResult<IReadOnlyList<DesignConversionDpoTrainingRecord>>
                .Ok(sourceRecords);

        var merged = MergeCommittedDualTargetTeacherTransferTrainRecords(
            sourceRecords,
            committedExternalPromotion.TransferTrainRecords);
        if (merged is null)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                IReadOnlyList<DesignConversionDpoTrainingRecord>>();
        }

        // Fresh partition-проверки должны видеть свежие held-out строки, но
        // train-строки внешнего эталона заменяются только на те child rows,
        // которые уже выведены из committed custody и реально учили checkpoint.
        return OperationResult<IReadOnlyList<DesignConversionDpoTrainingRecord>>
            .Ok(merged);
    }

    private sealed record CommittedDualTargetTeacherPromotionChild(
        DesignConversionDpoTrainingRecord Record,
        LearningTrainingItem Item,
        DpoPair Pair);

    private static OperationResult<CommittedDualTargetTeacherPromotionChild>
        MaterializeCommittedDualTargetTeacherExternalChildForBridge(
            DesignConversionDpoTrainingRecord? row,
            DpoPairAtomicGroupChild? child,
            DesignConversionExternalConsumptionCommitEvidence
                committedExternalConsumption,
            int ordinal)
    {
        if (child is null)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                CommittedDualTargetTeacherPromotionChild>();
        }

        var expectedUnit = child.Role switch
        {
            DpoPairAtomicGroupRole.CriticUnit =>
                DesignConversionDpoUnits.CriticUnit,
            DpoPairAtomicGroupRole.ImproverUnit =>
                DesignConversionDpoUnits.ImproverUnit,
            _ => string.Empty
        };
        if (row is null ||
            child.Ordinal != ordinal ||
            string.IsNullOrWhiteSpace(expectedUnit) ||
            !string.Equals(row.UnitId, expectedUnit, StringComparison.Ordinal) ||
            row.TeacherProvenance is not { } teacher ||
            !string.Equals(
                teacher.RequestId,
                committedExternalConsumption.RequestId,
                StringComparison.Ordinal) ||
            !string.Equals(
                child.PairId,
                committedExternalConsumption.OrderedPairIds[ordinal],
                StringComparison.Ordinal) ||
            !string.Equals(
                child.ContentSha256,
                committedExternalConsumption.OrderedContentSha256s[ordinal],
                StringComparison.Ordinal) ||
            row.ChosenAuthorKind is not { } chosenAuthor ||
            row.RejectedAuthorKind is not { } rejectedAuthor ||
            !TryResolveTeacherPairSourceSides(
                chosenAuthor,
                rejectedAuthor,
                out var chosenSide,
                out var rejectedSide))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                CommittedDualTargetTeacherPromotionChild>();
        }

        var materialized = ValidateAndMaterializePayloadCustody(row);
        if (!materialized.IsSuccess || materialized.Value is null)
        {
            return materialized.MapError<
                CommittedDualTargetTeacherPromotionChild>();
        }

        var originalPair = DesignConversionTrainingIntakeDpoPairAuthority
            .Project(materialized.Value);
        if (!originalPair.IsSuccess || originalPair.Value is null ||
            !PairPayloadMatches(originalPair.Value, child.Pair) ||
            !string.Equals(
                originalPair.Value.TeacherProvenance?.TrainingContentSha256,
                child.ContentSha256,
                StringComparison.Ordinal))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                CommittedDualTargetTeacherPromotionChild>();
        }

        var metadata = new Dictionary<string, string>(
            materialized.Value.Provenance.Metadata,
            StringComparer.Ordinal)
        {
            // Узкий bridge-transfer не доверяет caller metadata: реальные
            // стороны взяты из custody, а новый request id выведен только из
            // committed store transaction/group/child identities.
            ["independent_preference_proven"] = bool.TrueString,
            ["chosen_rejected_pair_proven"] = bool.TrueString,
            ["independent_preference_receipt_sha256"] =
                committedExternalConsumption.ResultSha256,
            ["independent_preference_attempt_number"] = "1",
            ["raw_independent_scorer_request_persisted"] = bool.FalseString,
            ["raw_independent_scorer_output_persisted"] = bool.FalseString,
            ["dual_target_teacher_external_bridge_authority_source"] =
                "committed_store_minted_exact_child_transfer",
            ["dual_target_teacher_external_bridge_child_ordinal"] =
                ordinal.ToString(CultureInfo.InvariantCulture),
            ["dual_target_teacher_external_bridge_child_pair_id"] =
                child.PairId,
            ["dual_target_teacher_external_bridge_child_content_sha256"] =
                child.ContentSha256,
            ["dual_target_teacher_external_bridge_group_commitment_sha256"] =
                committedExternalConsumption.GroupCommitmentSha256,
            ["dual_target_teacher_external_bridge_parent_content_sha256"] =
                committedExternalConsumption.ParentContentSha256,
            [DesignConversionDpoPolicyCheckpointBridge
                .PairChosenSourceSideMetadataKey] = chosenSide,
            [DesignConversionDpoPolicyCheckpointBridge
                .PairRejectedSourceSideMetadataKey] = rejectedSide,
            [DesignConversionDpoPolicyCheckpointBridge
                .PairAuthorshipSourceMetadataKey] =
                "committed_dual_target_teacher_external_child_transfer"
        };
        metadata.Remove("chosen_rejected_pair_not_proven");
        metadata.Remove("independent_preference_not_proven");
        metadata.Remove("teacher_candidate_only_boundary");
        metadata.Remove(DesignConversionDpoGenerator.PayloadCustodyRequiredMetadataKey);
        metadata.Remove(DesignConversionDpoGenerator.PayloadCustodyVersionMetadataKey);
        metadata.Remove(DesignConversionDpoGenerator.PayloadCustodyPromptSha256MetadataKey);
        metadata.Remove(DesignConversionDpoGenerator.PayloadCustodyChosenSha256MetadataKey);
        metadata.Remove(DesignConversionDpoGenerator.PayloadCustodyRejectedSha256MetadataKey);
        metadata.Remove(DesignConversionDpoGenerator.PayloadCustodyGovernanceSha256MetadataKey);
        metadata.Remove(DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey);

        var childProvenance = teacher with
        {
            RequestId = BuildCommittedDualTargetTeacherBridgeChildRequestId(
                committedExternalConsumption,
                child,
                ordinal),
            TrainingContentSha256 = child.ContentSha256
        };
        var transferRecord = materialized.Value with
        {
            Provenance = materialized.Value.Provenance with
            {
                Metadata = metadata
            },
            TeacherProvenance = childProvenance,
            // Старый custody-secret был честно использован выше для раскрытия
            // payload исходной строки, но он криптографически привязан к
            // прежнему request id и прежней metadata. Transfer-запись несёт уже
            // новую store-committed власть, поэтому старый secret нельзя
            // таскать дальше как будто он авторизует новую identity.
            PayloadCustodySecret = null
        };
        var transferPair = DesignConversionTrainingIntakeDpoPairAuthority
            .Project(transferRecord);
        if (!transferPair.IsSuccess || transferPair.Value is null ||
            !PairPayloadMatches(transferPair.Value, child.Pair))
        {
            return transferPair.MapError<
                CommittedDualTargetTeacherPromotionChild>();
        }

        return OperationResult<CommittedDualTargetTeacherPromotionChild>.Ok(
            new CommittedDualTargetTeacherPromotionChild(
                transferRecord,
                DesignConversionTrainingPipeline.ToCanonicalTrainingItem(
                    transferRecord),
                transferPair.Value));
    }

    private static string BuildCommittedDualTargetTeacherBridgeChildRequestId(
        DesignConversionExternalConsumptionCommitEvidence committed,
        DpoPairAtomicGroupChild child,
        int ordinal)
        => string.Concat(
            "committed-dual-target-teacher-child:",
            DesignConversionDpoGenerator.Sha256Ref(string.Join(
                "\n",
                [
                    committed.TransactionId,
                    committed.GroupCommitmentSha256,
                    child.PairId,
                    child.ContentSha256,
                    ordinal.ToString(CultureInfo.InvariantCulture)
                ])));

    private static bool PairPayloadMatches(DpoPair left, DpoPair right)
        => string.Equals(left.Prompt, right.Prompt, StringComparison.Ordinal) &&
           string.Equals(left.Chosen, right.Chosen, StringComparison.Ordinal) &&
           string.Equals(
               left.Rejected,
               right.Rejected,
               StringComparison.Ordinal) &&
           string.Equals(left.Domain, right.Domain, StringComparison.Ordinal);

    private static bool TryResolveTeacherPairSourceSides(
        DPO.Models.DpoPairSideAuthorKind chosenAuthor,
        DPO.Models.DpoPairSideAuthorKind rejectedAuthor,
        out string chosenSide,
        out string rejectedSide)
    {
        chosenSide = string.Empty;
        rejectedSide = string.Empty;
        if (chosenAuthor is DPO.Models.DpoPairSideAuthorKind.OpenTeacher &&
            rejectedAuthor is DPO.Models.DpoPairSideAuthorKind.LocalModel)
        {
            chosenSide =
                DesignConversionDpoPolicyCheckpointBridge.PairSourceSideGenerated;
            rejectedSide =
                DesignConversionDpoPolicyCheckpointBridge.PairSourceSideIncumbent;
            return true;
        }

        if (chosenAuthor is DPO.Models.DpoPairSideAuthorKind.LocalModel &&
            rejectedAuthor is DPO.Models.DpoPairSideAuthorKind.OpenTeacher)
        {
            chosenSide =
                DesignConversionDpoPolicyCheckpointBridge.PairSourceSideIncumbent;
            rejectedSide =
                DesignConversionDpoPolicyCheckpointBridge.PairSourceSideGenerated;
            return true;
        }

        return false;
    }

    private static bool DpoDatasetCountGateScalarsAgree(
        DesignConversionDpoDatasetCountGate left,
        DesignConversionDpoDatasetCountGate right)
        => left.RequiredTrainRecords == right.RequiredTrainRecords &&
           left.RequiredHeldOutRecords == right.RequiredHeldOutRecords &&
           left.ActualTrainRecords == right.ActualTrainRecords &&
           left.ActualHeldOutRecords == right.ActualHeldOutRecords &&
           left.SourceDisjoint == right.SourceDisjoint &&
           left.Passed == right.Passed;

    private static bool TryResolveManifestIdentitySets(
        DesignConversionDpoDatasetManifest manifest,
        out HashSet<string> trainIdentityHashes,
        out HashSet<string> heldOutIdentityHashes,
        out HashSet<string> trainSourceIdentityHashes,
        out HashSet<string> heldOutSourceIdentityHashes)
    {
        trainIdentityHashes = new HashSet<string>(StringComparer.Ordinal);
        heldOutIdentityHashes = new HashSet<string>(StringComparer.Ordinal);
        trainSourceIdentityHashes = new HashSet<string>(StringComparer.Ordinal);
        heldOutSourceIdentityHashes = new HashSet<string>(StringComparer.Ordinal);
        return TryCollectManifestPartitionIdentityHashes(
                manifest.TrainSources,
                trainIdentityHashes,
                trainSourceIdentityHashes) &&
            TryCollectManifestPartitionIdentityHashes(
                manifest.HeldOutSources,
                heldOutIdentityHashes,
                heldOutSourceIdentityHashes) &&
            trainIdentityHashes.Count > 0 &&
            heldOutIdentityHashes.Count > 0 &&
            !trainIdentityHashes.Overlaps(heldOutIdentityHashes) &&
            !trainSourceIdentityHashes.Overlaps(heldOutSourceIdentityHashes);
    }

    private static bool TryCollectManifestPartitionIdentityHashes(
        IReadOnlyList<DesignConversionDpoDatasetSourceGroup>? sourceGroups,
        HashSet<string> identityHashes,
        HashSet<string> sourceIdentityHashes)
    {
        if (sourceGroups is null || sourceGroups.Count == 0)
            return false;

        var sourceGroupIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var sourceGroup in sourceGroups)
        {
            if (sourceGroup is null ||
                string.IsNullOrWhiteSpace(sourceGroup.SourceGroupId) ||
                !sourceGroupIds.Add(sourceGroup.SourceGroupId) ||
                !IsCanonicalLowerSha256(sourceGroup.SourceIdentityHash) ||
                !sourceIdentityHashes.Add(sourceGroup.SourceIdentityHash) ||
                sourceGroup.RecordIdentityHashes is null ||
                sourceGroup.RecordIdentityHashes.Count == 0 ||
                sourceGroup.RecordCount != sourceGroup.RecordIdentityHashes.Count)
            {
                return false;
            }

            foreach (var identityHash in sourceGroup.RecordIdentityHashes)
            {
                if (!IsCanonicalLowerSha256(identityHash) ||
                    !identityHashes.Add(identityHash))
                {
                    return false;
                }
            }
        }

        return true;
    }

    private static bool DpoTrainingItemsMatchBatches(
        DesignConversionTrainingPipelineResult pipeline,
        IReadOnlyList<DesignConversionTrainingBatch> batches)
    {
        if (pipeline.TrainingItems is null || pipeline.TrainingItems.Count == 0)
            return false;

        var flattenedItems = new List<LearningTrainingItem>();
        foreach (var batch in batches)
        {
            if (batch.TrainingItems is null ||
                batch.TrainingItems.Count == 0 ||
                batch.TrainingItems.Count != batch.Records.Count)
            {
                return false;
            }

            for (var index = 0; index < batch.Records.Count; index++)
            {
                var item = batch.TrainingItems[index];
                if (item is null ||
                    !string.Equals(
                        item.ItemId,
                        batch.Records[index].RecordId,
                        StringComparison.Ordinal))
                {
                    return false;
                }

                flattenedItems.Add(item);
            }
        }

        return pipeline.TrainingItems.Count == flattenedItems.Count &&
            pipeline.TrainingItems
                .Zip(flattenedItems)
                .All(pair => pair.First == pair.Second);
    }

    private static bool IsDpoPartitionRecordIdentityValid(
        DesignConversionDpoTrainingRecord? record)
        => record is not null &&
           !string.IsNullOrWhiteSpace(record.RecordId) &&
           !string.IsNullOrWhiteSpace(record.UnitId);

    private static string BuildDpoPartitionCompositeKey(
        DesignConversionDpoTrainingRecord record)
        => string.Concat(record.RecordId, "\u001f", record.UnitId);

    private static string ToDpoPartitionRecordIdentityHash(
        DesignConversionDpoTrainingRecord record)
        => DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash(record);

    private static bool IsCanonicalLowerSha256(string? value)
    {
        if (value is null || value.Length != 64)
            return false;

        foreach (var character in value)
        {
            if ((character < '0' || character > '9') &&
                (character < 'a' || character > 'f'))
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsSafeEvaluatedDatasetId(string? value)
        => !string.IsNullOrWhiteSpace(value) &&
           value.Length <= 256 &&
           string.Equals(value, value.Trim(), StringComparison.Ordinal) &&
           value.All(character => char.IsAsciiLetterOrDigit(character) ||
               character is '-' or '_' or '.') &&
           !DesignConversionDpoLeakageGuard.ContainsForbiddenLeakage(value);

    private static OperationResult<T> DpoPolicyBridgeTrainPartitionInvalid<T>()
        => OperationResult<T>.Fail(
            DpoPolicyBridgeTrainPartitionInvalidSafeMessage,
            DpoPolicyBridgeTrainPartitionInvalidErrorCode);

    private static OperationResult<T> DpoCorpusAdmissionRequired<T>()
        => OperationResult<T>.Fail(
            "Independently-ranked teacher candidates require a live corpus admission.",
            DesignConversionDpoCorpusAdmissionAuthority.RequiredErrorCode);

    private static StringComparer GetPathKeyComparer()
        => OperatingSystem.IsWindows() ? StringComparer.OrdinalIgnoreCase : StringComparer.Ordinal;

    private static string NormalizeRecordMutationGateKey(string recordsPath)
        => Path.GetFullPath(recordsPath);

    private static async Task WaitForObservedGateAsync(
        SemaphoreSlim gate,
        Action<bool>? waitTaskObserver,
        Action onGateAcquired,
        CancellationToken ct)
    {
        if (waitTaskObserver is null)
        {
            await gate.WaitAsync(ct);
            onGateAcquired();
            return;
        }

        using var waitObserverFailureCancellation = CancellationTokenSource.CreateLinkedTokenSource(ct);
        var waitTask = gate.WaitAsync(waitObserverFailureCancellation.Token);
        var waitCompletedSuccessfully = waitTask.IsCompletedSuccessfully;
        try
        {
            waitTaskObserver(waitCompletedSuccessfully);
        }
        catch
        {
            waitObserverFailureCancellation.Cancel();
            try
            {
                await waitTask;
                onGateAcquired();
            }
            catch (OperationCanceledException) when (waitObserverFailureCancellation.IsCancellationRequested)
            {
            }

            throw;
        }

        await waitTask;
        onGateAcquired();
    }

    public async Task<OperationResult<DesignConversionLocalArtifactDbRecord>> AppendRecordAsync(
        DesignConversionLocalArtifactDbRecord record,
        CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionLocalArtifactDbRecord>();
        if (record is null)
            return OperationResult<DesignConversionLocalArtifactDbRecord>.Fail(
                "DesignConversion local artifact DB record is required.",
                "DESIGN_CONVERSION_LOCAL_ARTIFACT_DB_RECORD_REQUIRED");

        var originalPayloadsValid = ValidateCandidatePayloadsBeforeNormalization(record);
        if (!originalPayloadsValid.IsSuccess)
            return originalPayloadsValid.MapError<DesignConversionLocalArtifactDbRecord>();

        string? canonicalImprovementLoopAttemptHistory = null;
        if (record.Metadata is not null &&
            record.Metadata.TryGetValue(
                DesignConversionLocalArtifactDbRecord
                    .ImprovementLoopAttemptHistoryMetadataKey,
                out var serializedImprovementLoopAttemptHistory) &&
            (!record.Metadata.TryGetValue(
                 DesignConversionLocalArtifactDbRecord
                     .ImprovementLoopRefMetadataKey,
                 out var outerLoopRef) ||
             !DesignConversionLocalArtifactDbRecord
                 .TryCanonicalizeImprovementLoopAttemptHistoryMetadata(
                     serializedImprovementLoopAttemptHistory,
                     outerLoopRef,
                     out canonicalImprovementLoopAttemptHistory,
                     out _)))
        {
            return OperationResult<DesignConversionLocalArtifactDbRecord>.Fail(
                "DesignConversion improvement-loop attempt history is invalid.",
                "DESIGN_CONVERSION_IMPROVEMENT_LOOP_ATTEMPT_HISTORY_INVALID");
        }

        var normalized = NormalizeRecord(
            record,
            canonicalImprovementLoopAttemptHistory);
        if (!DesignConversionLocalArtifactDbRecord
                .HasValidImprovementLoopAttemptHistoryMetadata(normalized))
        {
            return OperationResult<DesignConversionLocalArtifactDbRecord>.Fail(
                "DesignConversion improvement-loop attempt history is invalid.",
                "DESIGN_CONVERSION_IMPROVEMENT_LOOP_ATTEMPT_HISTORY_INVALID");
        }

        var rebound = RebindNormalizedCandidatePayloadCustody(normalized);
        if (!rebound.IsSuccess)
            return rebound.MapError<DesignConversionLocalArtifactDbRecord>();
        normalized = rebound.Value!;
        var custodyPlan = BuildCandidatePayloadCustodyAppendPlan(normalized);
        if (!custodyPlan.IsSuccess)
            return custodyPlan.MapError<DesignConversionLocalArtifactDbRecord>();

        var sanitized = custodyPlan.Value!.AuthorityRecord;
        var line = JsonSerializer.Serialize(sanitized, JsonOptions);
        var projectedLineByteLength =
            Encoding.UTF8.GetByteCount(line) +
            Encoding.UTF8.GetByteCount(Environment.NewLine) +
            Encoding.UTF8.GetPreamble().Length;
        if (projectedLineByteLength > MaxIndexedRecordLineByteLength)
        {
            return OperationResult<DesignConversionLocalArtifactDbRecord>.Fail(
                "DesignConversion local artifact DB record exceeds the bounded authority-line envelope.",
                "DESIGN_CONVERSION_LOCAL_ARTIFACT_DB_RECORD_LINE_TOO_LARGE");
        }

        try
        {
            await _recordsMutationContext.Gate.WaitAsync(ct);
        }
        catch (OperationCanceledException)
        {
            return Cancelled<DesignConversionLocalArtifactDbRecord>();
        }

        try
        {
            await using var mutationLease = await AcquireRecordsAuthorityMutationLeaseAsync(ct);
            var hasCustodyPlan = custodyPlan.Value.Draft is not null &&
                                 custodyPlan.Value.Commitment is not null;
            if (hasCustodyPlan)
            {
                var reconciliation = await ReconcileCandidatePayloadCustodyUnderAuthorityLeaseAsync(
                    CancellationToken.None);
                if (!reconciliation.IsSuccess)
                    return reconciliation.MapError<DesignConversionLocalArtifactDbRecord>();
            }

            // Cancellation is honored up to the publication boundary.  Once a
            // custody stage is visible, the stage + authority append + final
            // rename is one non-cancellable critical transaction.
            if (ct.IsCancellationRequested)
                return Cancelled<DesignConversionLocalArtifactDbRecord>();

            if (!hasCustodyPlan)
                return await AppendRecordCoreAsync(sanitized, line, ct);

            DesignConversionCandidatePayloadCustodyStageReceipt? receipt = null;
            var authorityCommitted = false;
            try
            {
                var prepared = _candidatePayloadCustodyStore.Prepare(
                    custodyPlan.Value.Draft!,
                    custodyPlan.Value.Commitment!);
                if (!prepared.IsSuccess)
                    return prepared.MapError<DesignConversionLocalArtifactDbRecord>();
                receipt = prepared.Value!;

                var appended = await AppendRecordCoreAsync(
                    sanitized,
                    line,
                    CancellationToken.None);
                if (!appended.IsSuccess)
                {
                    var cleanup = await CleanupPreparedCandidatePayloadCustodyUnderAuthorityLeaseAsync(
                        receipt);
                    if (!cleanup.IsSuccess)
                        return cleanup.MapError<DesignConversionLocalArtifactDbRecord>();
                    return appended;
                }
                authorityCommitted = true;

                var committed = _candidatePayloadCustodyStore.Commit(receipt);
                if (!committed.IsSuccess)
                    return committed.MapError<DesignConversionLocalArtifactDbRecord>();
                return appended;
            }
            catch
            {
                if (!authorityCommitted && receipt is not null)
                {
                    var cleanup = await CleanupPreparedCandidatePayloadCustodyUnderAuthorityLeaseAsync(
                        receipt);
                    if (!cleanup.IsSuccess)
                        return cleanup.MapError<DesignConversionLocalArtifactDbRecord>();
                }
                throw;
            }
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<DesignConversionLocalArtifactDbRecord>();
        }
        catch (IOException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionLocalArtifactDbRecord>();
        }
        catch (UnauthorizedAccessException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionLocalArtifactDbRecord>();
        }
        finally
        {
            _recordsMutationContext.Gate.Release();
        }
    }

    private Task<DesignConversionDeterministicMutationLease> AcquireRecordsAuthorityMutationLeaseAsync(CancellationToken ct)
    {
        Directory.CreateDirectory(_rootDirectory);

        return DesignConversionDeterministicMutationLock.WaitUntilAcquiredAsync(
            _recordsMutationLockPath,
            TimeSpan.FromMilliseconds(RecordsMutationLockRetryDelayMs),
            ct);
    }

    private async Task<OperationResult<DesignConversionLocalArtifactDbRecord>> AppendRecordCoreAsync(
        DesignConversionLocalArtifactDbRecord sanitized,
        string line,
        CancellationToken ct)
    {
        var stateResult = await ResolveCurrentAuthorityStateForAppendAsync(ct);
        if (!stateResult.IsSuccess)
            return stateResult.MapError<DesignConversionLocalArtifactDbRecord>();

        var authorityState = stateResult.Value!;
        var replay = await ResolveRecordIdReplayAsync(sanitized, authorityState, ct);
        if (!replay.IsSuccess)
            return replay.MapError<DesignConversionLocalArtifactDbRecord>();
        if (replay.Value!.IsReplay)
            return OperationResult<DesignConversionLocalArtifactDbRecord>.Ok(replay.Value.Record!);

        var appendOffset = authorityState.CommittedLength;
        var appendedLineBytes = BuildAppendedAuthorityLineBytes(line, appendOffset);
        if (appendedLineBytes.LongLength > MaxIndexedRecordLineByteLength)
            return LocalArtifactDbWriteFailed<DesignConversionLocalArtifactDbRecord>();
        if (!TryProjectCommittedAuthorityLength(
                authorityState.CommittedLength,
                appendedLineBytes.LongLength,
                out var projectedCommittedAuthorityLength)
            || projectedCommittedAuthorityLength > _recordsAuthorityMaxBytes)
        {
            return LocalArtifactDbAuthorityQuotaExceeded<DesignConversionLocalArtifactDbRecord>();
        }

        Directory.CreateDirectory(_rootDirectory);
        if (_authorityAppendBeforeOpenCallbackForTesting is not null)
            await _authorityAppendBeforeOpenCallbackForTesting(ct);
        await CommitAuthorityRecordInPlaceAsync(authorityState, appendedLineBytes, ct);
        var postAppendFingerprint = GetRecordsFileFingerprint();

        var committedState = AddRecordToAuthorityState(
            authorityState,
            sanitized,
            line,
            appendOffset,
            appendedLineBytes,
            postAppendFingerprint);
        PublishCachedAuthorityStateFromCommittedAuthority(committedState);

        return await CompleteCommittedAuthorityAppendAsync(
            sanitized,
            ct,
            indexCt => TryWriteDerivedIndexAsync(committedState.Index, indexCt));
    }

    internal static async Task<OperationResult<DesignConversionLocalArtifactDbRecord>> CompleteCommittedAuthorityAppendAsync(
        DesignConversionLocalArtifactDbRecord sanitized,
        CancellationToken callerCancellationToken,
        Func<CancellationToken, Task<bool>> tryWriteDerivedIndexAsync)
    {
        if (callerCancellationToken.IsCancellationRequested)
        {
            return OperationResult<DesignConversionLocalArtifactDbRecord>.Ok(
                WithDeferredIndexEvidence(sanitized));
        }

        var derivedIndexDurable = await tryWriteDerivedIndexAsync(CancellationToken.None);
        return OperationResult<DesignConversionLocalArtifactDbRecord>.Ok(
            derivedIndexDurable ? sanitized : WithDeferredIndexEvidence(sanitized));
    }

    private async Task CommitAuthorityRecordInPlaceAsync(
        AuthorityState authorityState,
        byte[] appendedLineBytes,
        CancellationToken ct)
    {
        var expectedFingerprint = authorityState.Fingerprint;
        var expectedAppendOffset = authorityState.CommittedLength;
        var expectedSourceLength = expectedFingerprint.Length;
        ValidateAuthorityAppendBoundary(
            expectedAppendOffset,
            expectedSourceLength,
            authorityState.HasUncommittedFinalRecord,
            authorityState.UncommittedFinalByteOffset);

        var access = expectedAppendOffset < expectedSourceLength
            ? FileAccess.ReadWrite
            : FileAccess.Write;
        await using var stream = new FileStream(
            _recordsPath,
            expectedFingerprint.Exists ? FileMode.Open : FileMode.CreateNew,
            access,
            FileShare.Read,
            bufferSize: 4096,
            FileOptions.Asynchronous | FileOptions.WriteThrough | FileOptions.RandomAccess);

        ValidateOpenAuthorityForAppend(stream, expectedFingerprint, expectedSourceLength);
        var originalTailBytes = await ReadOriginalAuthorityTailAsync(
            stream,
            expectedAppendOffset,
            expectedSourceLength,
            ct);

        ct.ThrowIfCancellationRequested();
        var mutationStarted = false;
        try
        {
            mutationStarted = true;
            stream.Seek(expectedAppendOffset, SeekOrigin.Begin);
            await stream.WriteAsync(appendedLineBytes.AsMemory(0, appendedLineBytes.Length), ct);
            stream.SetLength(expectedAppendOffset + appendedLineBytes.LongLength);
            await stream.FlushAsync(ct);
            stream.Flush(flushToDisk: true);
        }
        catch (OperationCanceledException) when (mutationStarted && ct.IsCancellationRequested)
        {
            await RestoreAuthorityTailBestEffortAsync(
                stream,
                expectedAppendOffset,
                originalTailBytes,
                expectedSourceLength,
                appendedLineBytes);
            throw;
        }
        catch (IOException) when (mutationStarted)
        {
            await RestoreAuthorityTailBestEffortAsync(
                stream,
                expectedAppendOffset,
                originalTailBytes,
                expectedSourceLength,
                appendedLineBytes);
            throw;
        }
        catch (UnauthorizedAccessException) when (mutationStarted)
        {
            await RestoreAuthorityTailBestEffortAsync(
                stream,
                expectedAppendOffset,
                originalTailBytes,
                expectedSourceLength,
                appendedLineBytes);
            throw;
        }
    }

    private void ValidateOpenAuthorityForAppend(
        FileStream stream,
        RecordsFileFingerprint expectedFingerprint,
        long expectedSourceLength)
    {
        if (stream.Length != expectedSourceLength)
            throw new IOException("DesignConversion authority source length changed before commit.");

        var observedFingerprint = GetRecordsFileFingerprint();
        if (expectedFingerprint.Exists)
        {
            if (!observedFingerprint.Equals(expectedFingerprint))
                throw new IOException("DesignConversion authority source fingerprint changed before commit.");
            return;
        }

        if (!observedFingerprint.Exists || observedFingerprint.Length != 0 || expectedSourceLength != 0)
            throw new IOException("DesignConversion authority source existence changed before commit.");
    }

    private static void ValidateAuthorityAppendBoundary(
        long expectedAppendOffset,
        long expectedSourceLength,
        bool hasUncommittedFinalRecord,
        long? uncommittedFinalByteOffset)
    {
        if (expectedAppendOffset < 0
            || expectedSourceLength < 0
            || expectedAppendOffset > expectedSourceLength)
        {
            throw new IOException("DesignConversion authority append boundary is invalid.");
        }

        var tailLength = expectedSourceLength - expectedAppendOffset;
        if (tailLength > MaxIndexedRecordLineByteLength)
            throw new IOException("DesignConversion authority uncommitted tail exceeded the record line bound.");

        if (hasUncommittedFinalRecord)
        {
            if (tailLength <= 0 || uncommittedFinalByteOffset != expectedAppendOffset)
                throw new IOException("DesignConversion authority uncommitted tail boundary changed before commit.");
            return;
        }

        if (tailLength != 0)
            throw new IOException("DesignConversion authority source length changed after committed prefix scan.");
    }

    private static async Task<byte[]> ReadOriginalAuthorityTailAsync(
        FileStream stream,
        long expectedAppendOffset,
        long expectedSourceLength,
        CancellationToken ct)
    {
        var tailLength = expectedSourceLength - expectedAppendOffset;
        if (tailLength == 0)
            return [];

        var tailBytes = new byte[(int)tailLength];
        stream.Seek(expectedAppendOffset, SeekOrigin.Begin);
        await stream.ReadExactlyAsync(tailBytes.AsMemory(0, tailBytes.Length), ct);
        return tailBytes;
    }

    private static async Task RestoreAuthorityTailBestEffortAsync(
        FileStream stream,
        long expectedAppendOffset,
        byte[] originalTailBytes,
        long expectedSourceLength,
        byte[] appendedLineBytes)
    {
        if (await TryTruncateAuthorityToCommittedPrefixAsync(stream, expectedAppendOffset))
        {
            await TryRestoreOriginalAuthorityTailAsync(
                stream,
                expectedAppendOffset,
                originalTailBytes,
                expectedSourceLength);
            return;
        }

        await TryInvalidateAppendedAuthorityLineTerminatorAsync(
            stream,
            expectedAppendOffset,
            appendedLineBytes.LongLength);
    }

    private static async Task<bool> TryTruncateAuthorityToCommittedPrefixAsync(
        FileStream stream,
        long expectedAppendOffset)
    {
        try
        {
            stream.SetLength(expectedAppendOffset);
            await stream.FlushAsync(CancellationToken.None);
            stream.Flush(flushToDisk: true);
            return true;
        }
        catch (IOException)
        {
            return false;
        }
        catch (UnauthorizedAccessException)
        {
            return false;
        }
        catch (System.Security.SecurityException)
        {
            return false;
        }
    }

    private static async Task TryRestoreOriginalAuthorityTailAsync(
        FileStream stream,
        long expectedAppendOffset,
        byte[] originalTailBytes,
        long expectedSourceLength)
    {
        try
        {
            if (originalTailBytes.Length > 0)
            {
                stream.Seek(expectedAppendOffset, SeekOrigin.Begin);
                await stream.WriteAsync(originalTailBytes.AsMemory(0, originalTailBytes.Length), CancellationToken.None);
            }

            stream.SetLength(expectedSourceLength);
            await stream.FlushAsync(CancellationToken.None);
            stream.Flush(flushToDisk: true);
        }
        catch (IOException)
        {
            // The committed prefix has already been durably restored; any tail loss is recoverable by replay.
        }
        catch (UnauthorizedAccessException)
        {
            // The committed prefix has already been durably restored; any tail loss is recoverable by replay.
        }
        catch (System.Security.SecurityException)
        {
            // The committed prefix has already been durably restored; any tail loss is recoverable by replay.
        }
    }

    private static async Task TryInvalidateAppendedAuthorityLineTerminatorAsync(
        FileStream stream,
        long expectedAppendOffset,
        long appendedLineLength)
    {
        if (appendedLineLength <= 0)
            return;

        try
        {
            stream.Seek(expectedAppendOffset + appendedLineLength - 1, SeekOrigin.Begin);
            await stream.WriteAsync(new byte[] { (byte)' ' }, CancellationToken.None);
            await stream.FlushAsync(CancellationToken.None);
            stream.Flush(flushToDisk: true);
        }
        catch (IOException)
        {
            // Nothing more can be done without risking the committed prefix.
        }
        catch (UnauthorizedAccessException)
        {
            // Nothing more can be done without risking the committed prefix.
        }
        catch (System.Security.SecurityException)
        {
            // Nothing more can be done without risking the committed prefix.
        }
    }

    private async Task<OperationResult<RecordIdReplayResolution>> ResolveRecordIdReplayAsync(
        DesignConversionLocalArtifactDbRecord sanitized,
        AuthorityState authorityState,
        CancellationToken ct)
    {
        if (!authorityState.RecordsById.TryGetValue(sanitized.RecordId, out var existingState))
            return OperationResult<RecordIdReplayResolution>.Ok(new RecordIdReplayResolution(false, null));
        if (existingState.Count != 1)
            return LocalArtifactDbRecordIdConflict<RecordIdReplayResolution>();

        var replayFingerprint = GetImmutableAppendFingerprint(sanitized);
        // Legacy rows have no trustworthy original append identity, so replay fails closed.
        if (existingState.ImmutableAppendFingerprint is null
            || replayFingerprint is null
            || !string.Equals(
                existingState.ImmutableAppendFingerprint,
                replayFingerprint,
                StringComparison.Ordinal))
        {
            return LocalArtifactDbRecordIdConflict<RecordIdReplayResolution>();
        }

        var currentRecord = MaterializeDetachedAuthorityRecord(existingState.CurrentRecordJson);
        var returnedRecord = await TryWriteDerivedIndexAsync(authorityState.Index, ct)
            ? currentRecord
            : WithDeferredIndexEvidence(currentRecord);
        return OperationResult<RecordIdReplayResolution>.Ok(new RecordIdReplayResolution(true, returnedRecord));
    }

    private async Task<bool> TryWriteDerivedIndexAsync(
        DesignConversionLocalArtifactDbIndex index,
        CancellationToken ct)
    {
        _derivedIndexWriteObserverForTesting?.Invoke();
        var tempPath = Path.Combine(_rootDirectory, $"{IndexFileName}.{Guid.NewGuid():N}.write.tmp");
        try
        {
            Directory.CreateDirectory(_rootDirectory);
            await using (var temp = new FileStream(
                tempPath,
                FileMode.CreateNew,
                FileAccess.Write,
                FileShare.None,
                bufferSize: 81920,
                FileOptions.Asynchronous | FileOptions.WriteThrough))
            {
                var preamble = Encoding.UTF8.GetPreamble();
                if (preamble.Length > 0)
                    await temp.WriteAsync(preamble, ct);

                await JsonSerializer.SerializeAsync(temp, index, IndexJsonOptions, ct);
                await temp.FlushAsync(ct);
                temp.Flush(flushToDisk: true);
            }

            ct.ThrowIfCancellationRequested();
            // Удержание файла через FileShare не одинаково запрещает замену в Windows и Linux.
            // Поэтому тестовый отказ вводится в точной границе атомарной публикации, а production по умолчанию сюда не вмешивается.
            _derivedIndexBeforeAtomicPublishCallbackForTesting?.Invoke();
            File.Move(tempPath, _indexPath, overwrite: true);
            return true;
        }
        catch (IOException)
        {
            return false;
        }
        catch (UnauthorizedAccessException)
        {
            return false;
        }
        finally
        {
            DeleteIndexWriteTempBestEffort(tempPath);
        }
    }

    private static void DeleteIndexWriteTempBestEffort(string tempPath)
    {
        try
        {
            if (File.Exists(tempPath))
                File.Delete(tempPath);
        }
        catch (IOException)
        {
            // Best-effort cleanup must not replace the index write outcome.
        }
        catch (UnauthorizedAccessException)
        {
            // Best-effort cleanup must not replace the index write outcome.
        }
        catch (System.Security.SecurityException)
        {
            // Best-effort cleanup must not replace the index write outcome.
        }
    }

    private async Task<OperationResult<AuthorityState>> ResolveCurrentAuthorityStateForAppendAsync(
        CancellationToken ct)
    {
        var fingerprint = GetRecordsFileFingerprint();
        var cached = _recordsMutationContext.CachedAuthorityState;
        if (cached is not null && cached.Fingerprint.Equals(fingerprint))
            return OperationResult<AuthorityState>.Ok(cached.State);

        var scan = await ReadAuthorityRecordLinesCoreAsync(ct);
        if (!scan.IsSuccess)
            return scan.MapError<AuthorityState>();

        var postReadFingerprint = GetRecordsFileFingerprint();
        if (!postReadFingerprint.Equals(fingerprint))
        {
            _recordsMutationContext.CachedAuthorityState = null;
            return LocalArtifactDbWriteFailed<AuthorityState>();
        }

        var state = BuildAuthorityState(scan.Value!);
        PublishCachedAuthorityState(state, postReadFingerprint);
        return OperationResult<AuthorityState>.Ok(state);
    }

    private RecordsFileFingerprint GetRecordsFileFingerprint()
    {
        var info = new FileInfo(_recordsPath);
        if (!info.Exists)
            return new RecordsFileFingerprint(false, 0, DateTime.MinValue);

        info.Refresh();
        return new RecordsFileFingerprint(
            true,
            info.Length,
            info.LastWriteTimeUtc);
    }

    private void PublishCachedAuthorityState(
        AuthorityState state,
        RecordsFileFingerprint fingerprint)
        => _recordsMutationContext.CachedAuthorityState = new CachedAuthorityState(state, fingerprint);

    private void PublishCachedAuthorityStateFromCommittedAuthority(AuthorityState state)
    {
        RecordsFileFingerprint fingerprint;
        try
        {
            fingerprint = GetRecordsFileFingerprint();
        }
        catch (IOException)
        {
            _recordsMutationContext.CachedAuthorityState = null;
            return;
        }
        catch (UnauthorizedAccessException)
        {
            _recordsMutationContext.CachedAuthorityState = null;
            return;
        }
        catch (System.Security.SecurityException)
        {
            _recordsMutationContext.CachedAuthorityState = null;
            return;
        }

        PublishCachedAuthorityState(state, fingerprint);
    }

    private AuthorityState BuildAuthorityState(
        AuthorityRecordScan scan,
        IReadOnlySet<string>? eligibleRecordIds = null)
    {
        var recordsById = new Dictionary<string, AuthorityRecordIdState>(StringComparer.Ordinal);
        foreach (var recordLine in scan.Lines)
        {
            var record = recordLine.Record;
            if (string.IsNullOrEmpty(record.RecordId))
                continue;

            if (recordsById.TryGetValue(record.RecordId, out var existing))
            {
                recordsById[record.RecordId] = existing with { Count = existing.Count + 1 };
                continue;
            }

            recordsById[record.RecordId] = new AuthorityRecordIdState(
                Count: 1,
                CurrentRecordJson: recordLine.CurrentRecordJson,
                ImmutableAppendFingerprint: GetImmutableAppendFingerprint(record));
        }

        return new AuthorityState(
            BuildIndex(scan, eligibleRecordIds),
            scan.CommittedLength,
            scan.NextAppendLineNumber,
            scan.Fingerprint,
            scan.HasUncommittedFinalRecord,
            scan.UncommittedFinalLineNumber,
            scan.UncommittedFinalByteOffset,
            recordsById);
    }

    private AuthorityState AddRecordToAuthorityState(
        AuthorityState state,
        DesignConversionLocalArtifactDbRecord record,
        string authorityLine,
        long byteOffset,
        byte[] authorityLineBytes,
        RecordsFileFingerprint fingerprint)
    {
        var recordIdState = new AuthorityRecordIdState(
            Count: 1,
            CurrentRecordJson: authorityLine,
            ImmutableAppendFingerprint: GetImmutableAppendFingerprint(record));
        var authorityLineSha256 = $"sha256:{HashBytes(authorityLineBytes)}";
        var locator = BuildIndexRecordLocator(
            record,
            byteOffset,
            authorityLineBytes.Length,
            state.NextLineNumber,
            authorityLineSha256);
        // The post-evaluation state store is external to the append journal.
        // Never derive a positive training count synchronously while holding
        // the authority mutation gate. List/read paths refresh this cache from
        // one asynchronous state inventory.
        const int approvedCandidateCount = 0;
        var updatedAtUtc = DateTimeOffset.UtcNow;
        var committedLength = fingerprint.Exists ? fingerprint.Length : byteOffset + authorityLineBytes.Length;
        var rootDirectoryBindingHash = BuildRootDirectoryBindingHash(_rootDirectory);

        state.AddCommittedRecord(
            record.RecordId,
            recordIdState,
            locator,
            approvedCandidateCount,
            updatedAtUtc,
            fingerprint,
            committedLength,
            rootDirectoryBindingHash);
        return state;
    }

    private static DesignConversionLocalArtifactDbRecord MaterializeDetachedAuthorityRecord(string authorityRecordJson)
    {
        var record = JsonSerializer.Deserialize<DesignConversionLocalArtifactDbRecord>(
                         authorityRecordJson,
                         JsonOptions)
                     ?? throw new JsonException(
                         "Cached DesignConversion authority record snapshot is invalid.");
        if (!DesignConversionLocalArtifactDbRecord
                .HasValidImprovementLoopAttemptHistoryMetadata(record))
        {
            throw new JsonException(
                "Cached DesignConversion improvement-loop attempt history is invalid.");
        }

        return record;
    }

    private static DesignConversionLocalArtifactDbRecord WithDeferredIndexEvidence(
        DesignConversionLocalArtifactDbRecord record)
    {
        var metadata = new Dictionary<string, string>(record.Metadata, StringComparer.Ordinal)
        {
            ["local_artifact_db_authority_record_committed"] = bool.TrueString,
            ["local_artifact_db_derived_index_update"] = "deferred",
            ["local_artifact_db_derived_index_durable"] = bool.FalseString,
            ["local_artifact_db_cross_file_atomicity_claimed"] = bool.FalseString,
            ["product_ready"] = bool.FalseString,
            ["model_readiness_claimed"] = bool.FalseString
        };

        var evidenceRefs = record.EvidenceRefs
            .Append(AuthorityRecordCommittedMarker)
            .Append(DerivedIndexUpdateDeferredMarker)
            .Append(DerivedIndexDurableFalseMarker)
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();

        return record with
        {
            EvidenceRefs = evidenceRefs,
            Metadata = metadata
        };
    }

    private static DesignConversionDpoCandidateApprovalResult WithDeferredIndexEvidence(
        DesignConversionDpoCandidateApprovalResult result)
    {
        var boundaryMetadata = new Dictionary<string, string>(result.BoundaryMetadata, StringComparer.Ordinal)
        {
            ["local_artifact_db_authority_record_committed"] = bool.TrueString,
            ["local_artifact_db_derived_index_update"] = "deferred",
            ["local_artifact_db_derived_index_durable"] = bool.FalseString,
            ["local_artifact_db_cross_file_atomicity_claimed"] = bool.FalseString,
            ["product_ready"] = bool.FalseString,
            ["model_readiness_claimed"] = bool.FalseString
        };

        var evidenceRefs = result.EvidenceRefs
            .Append(AuthorityRecordCommittedMarker)
            .Append(DerivedIndexUpdateDeferredMarker)
            .Append(DerivedIndexDurableFalseMarker)
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();

        return result with
        {
            EvidenceRefs = evidenceRefs,
            BoundaryMetadata = boundaryMetadata
        };
    }

    public async Task<OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>> ListRecordsAsync(
        DesignConversionLocalArtifactDbQuery? query = null,
        CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>();

        var effectiveQuery = query ?? new DesignConversionLocalArtifactDbQuery();
        LastSelectiveListRecordsUsedDurableIndex = false;
        var forceDurableIndexHeal = false;
        if (IsSelectiveDurableIndexQuery(effectiveQuery))
        {
            var indexed = await TryListRecordsFromDurableIndexAsync(effectiveQuery, ct);
            if (indexed.UsedDurableIndex)
            {
                LastSelectiveListRecordsUsedDurableIndex = true;
                if (!indexed.Result.IsSuccess)
                    return indexed.Result;

                // Индекс уже доказал, где лежат нужные строки; дальше применяем
                // тот же человечески понятный фильтр, что и после полного чтения,
                // чтобы быстрый путь не менял смысл запроса.
                return await FilterListedRecordsAsync(indexed.Result.Value!, effectiveQuery, ct);
            }
            else
            {
                forceDurableIndexHeal = indexed.RequiresDurableIndexHeal;
            }
        }

        var records = await ReadRecordsAndHealDerivedIndexAsync(ct, forceDurableIndexHeal);
        if (!records.IsSuccess)
            return records.MapError<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>();

        return await FilterListedRecordsAsync(records.Value!, effectiveQuery, ct);
    }

    private async Task<OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>>
        FilterListedRecordsAsync(
            IReadOnlyList<DesignConversionLocalArtifactDbRecord> records,
            DesignConversionLocalArtifactDbQuery effectiveQuery,
            CancellationToken ct)
    {
        var eligibility = effectiveQuery.ApprovedTrainingOnly
            ? await _postEvaluationTrainingEligibilityPolicy.EvaluateManyAsync(
                records,
                ct)
            : null;
        var filtered = records
            .Where((record, index) =>
                MatchesRecord(
                    record,
                    effectiveQuery,
                    eligibility?[index].IsEligible ?? false))
            .OrderBy(record => record.CreatedAtUtc)
            .ThenBy(record => record.RecordId, StringComparer.Ordinal)
            .ToArray();

        return OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>.Ok(filtered);
    }

    private static bool IsSelectiveDurableIndexQuery(DesignConversionLocalArtifactDbQuery query)
        => !string.IsNullOrWhiteSpace(query.JobId)
           || !string.IsNullOrWhiteSpace(query.RequestId);

    private async Task<DurableIndexLookupResult> TryListRecordsFromDurableIndexAsync(
        DesignConversionLocalArtifactDbQuery query,
        CancellationToken ct)
    {
        var fingerprint = GetRecordsFileFingerprint();
        var index = await TryReadUsableDurableIndexAsync(fingerprint, ct);
        if (index is null)
            return DurableIndexFallback();

        if (!await HasCompleteDurableIndexAuthorityCoverageAsync(index, fingerprint, ct))
            return DurableIndexFallback();

        var locators = index.RecordLocators
            .Where(locator => MatchesIndexLocator(locator, query))
            .OrderBy(locator => locator.ByteOffset)
            .ThenBy(locator => locator.RecordId, StringComparer.Ordinal)
            .ToArray();
        if (locators.Length == 0)
        {
            return new DurableIndexLookupResult(
                true,
                false,
                OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>.Ok([]));
        }

        var read = await TryReadIndexedCandidateRecordsAsync(locators, ct);
        if (!read.IsTrusted)
            return DurableIndexFallback();

        if (!GetRecordsFileFingerprint().Equals(fingerprint))
            return DurableIndexFallback();

        var filtered = read.Records
            .Where(record => MatchesRecordIdentity(record, query))
            .OrderBy(record => record.CreatedAtUtc)
            .ThenBy(record => record.RecordId, StringComparer.Ordinal)
            .ToArray();

        return new DurableIndexLookupResult(
            true,
            false,
            OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>.Ok(filtered));
    }

    private static DurableIndexLookupResult DurableIndexFallback()
        => new(
            false,
            true,
            OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>.Ok([]));

    private async Task<DesignConversionLocalArtifactDbIndex?> TryReadUsableDurableIndexAsync(
        RecordsFileFingerprint fingerprint,
        CancellationToken ct)
    {
        if (!fingerprint.Exists || !File.Exists(_indexPath))
            return null;

        DesignConversionLocalArtifactDbIndex? index;
        try
        {
            await using var stream = new FileStream(
                _indexPath,
                FileMode.Open,
                FileAccess.Read,
                FileShare.Read,
                bufferSize: 4096,
                FileOptions.Asynchronous | FileOptions.SequentialScan);
            index = await JsonSerializer.DeserializeAsync<DesignConversionLocalArtifactDbIndex>(
                stream,
                IndexJsonOptions,
                ct);
        }
        catch (JsonException)
        {
            return null;
        }
        catch (IOException)
        {
            return null;
        }
        catch (UnauthorizedAccessException)
        {
            return null;
        }

        return IsUsableDurableIndex(index, fingerprint) ? index : null;
    }

    private bool IsUsableDurableIndex(
        DesignConversionLocalArtifactDbIndex? index,
        RecordsFileFingerprint fingerprint)
    {
        if (index is null
            || !string.Equals(index.DatabaseKind, LocalArtifactDbKind, StringComparison.Ordinal)
            || !string.Equals(index.SchemaVersion, SchemaVersion, StringComparison.Ordinal)
            || !string.Equals(index.RootDirectoryBindingHash, BuildRootDirectoryBindingHash(_rootDirectory), StringComparison.Ordinal)
            || !string.Equals(index.TenantBindingHash, TenantBindingNotApplicable, StringComparison.Ordinal)
            || !string.Equals(index.RecordsFileName, RecordsFileName, StringComparison.Ordinal)
            || index.RecordsFileLength != fingerprint.Length
            || index.RecordsFileLastWriteTimeUtcTicks != fingerprint.LastWriteTimeUtc.Ticks
            || index.RecordCount < 0
            || index.ApprovedTrainingCandidateCount < 0
            || index.EvidenceMarkers is null
            || index.RecordLocators is null
            || index.RecordLocators.Count != index.RecordCount
            || !index.EvidenceMarkers.Contains(StorageTrainingArtifactDbMarker, StringComparer.Ordinal)
            || !index.EvidenceMarkers.Contains(LocalArtifactDbKind, StringComparer.Ordinal))
        {
            return false;
        }

        var quarantinedLines = index.QuarantinedAuthorityLines ?? [];
        if (quarantinedLines.Count > MaxLogicallyQuarantinedAuthorityLinesPerScan)
        {
            return false;
        }

        if (quarantinedLines.Count > 0
            && (!index.EvidenceMarkers.Contains(LogicalQuarantinedAuthorityLineMarker, StringComparer.Ordinal)
                || !index.EvidenceMarkers.Contains(QuarantinedAuthorityBytesPreservedMarker, StringComparer.Ordinal)
                || !index.EvidenceMarkers.Contains(
                    $"local_artifact_db:quarantined_authority_line_count:{quarantinedLines.Count.ToString(CultureInfo.InvariantCulture)}",
                    StringComparer.Ordinal)))
        {
            return false;
        }

        foreach (var descriptor in quarantinedLines)
        {
            if (descriptor is null
                || descriptor.PhysicalLineNumber <= 0
                || descriptor.ByteOffset < 0
                || descriptor.ByteLength <= 0
                || descriptor.ByteLength > MaxIndexedRecordLineByteLength
                || descriptor.ByteOffset > fingerprint.Length - descriptor.ByteLength
                || !IsSha256Ref(descriptor.AuthorityLineSha256))
            {
                return false;
            }
        }

        var previousEnd = 0L;
        foreach (var locator in index.RecordLocators.OrderBy(locator => locator.ByteOffset))
        {
            if (string.IsNullOrWhiteSpace(locator.RecordId)
                || string.IsNullOrWhiteSpace(locator.JobId)
                || string.IsNullOrWhiteSpace(locator.RequestId)
                || string.IsNullOrWhiteSpace(locator.SourceKind)
                || locator.ByteOffset < 0
                || locator.ByteLength <= 0
                || locator.ByteLength > MaxIndexedRecordLineByteLength
                || locator.ByteOffset < previousEnd
                || locator.ByteOffset > fingerprint.Length - locator.ByteLength
                || locator.LineNumber <= 0
                || !IsSha256Ref(locator.AuthorityLineSha256)
                || !IsSha256Ref(locator.ImmutableAppendFingerprint))
            {
                return false;
            }

            previousEnd = locator.ByteOffset + locator.ByteLength;
        }

        return true;
    }

    private async Task<bool> HasCompleteDurableIndexAuthorityCoverageAsync(
        DesignConversionLocalArtifactDbIndex index,
        RecordsFileFingerprint fingerprint,
        CancellationToken ct)
    {
        var orderedLocators = index.RecordLocators
            .OrderBy(locator => locator.ByteOffset)
            .ToArray();
        var locatorIndex = 0;
        var lineStartOffset = 0L;
        var lineNumber = 0;

        try
        {
            await using var stream = new FileStream(
                _recordsPath,
                FileMode.Open,
                FileAccess.Read,
                FileShare.Read,
                bufferSize: 8192,
                FileOptions.Asynchronous | FileOptions.SequentialScan);
            var buffer = new byte[8192];
            using var currentLine = new MemoryStream();

            while (true)
            {
                var read = await stream.ReadAsync(buffer.AsMemory(0, buffer.Length), ct);
                if (read == 0)
                    break;

                for (var bufferIndex = 0; bufferIndex < read; bufferIndex++)
                {
                    if (currentLine.Length >= MaxIndexedRecordLineByteLength)
                        return false;

                    currentLine.WriteByte(buffer[bufferIndex]);
                    if (buffer[bufferIndex] != (byte)'\n')
                        continue;

                    lineNumber++;
                    if (!IsCoveredAuthorityLine(
                            currentLine.ToArray(),
                            lineStartOffset,
                            lineNumber,
                            orderedLocators,
                            ref locatorIndex))
                    {
                        return false;
                    }

                    lineStartOffset += currentLine.Length;
                    currentLine.SetLength(0);
                    currentLine.Position = 0;
                }
            }

            if (currentLine.Length > 0)
            {
                lineNumber++;
                if (!IsCoveredAuthorityLine(
                        currentLine.ToArray(),
                        lineStartOffset,
                        lineNumber,
                        orderedLocators,
                        ref locatorIndex))
                {
                    return false;
                }
            }
        }
        catch (DecoderFallbackException)
        {
            return false;
        }
        catch (IOException)
        {
            return false;
        }
        catch (UnauthorizedAccessException)
        {
            return false;
        }

        return locatorIndex == orderedLocators.Length
               && GetRecordsFileFingerprint().Equals(fingerprint);
    }

    private static bool IsCoveredAuthorityLine(
        byte[] lineBytes,
        long byteOffset,
        int lineNumber,
        IReadOnlyList<DesignConversionLocalArtifactDbIndexRecordLocator> orderedLocators,
        ref int locatorIndex)
    {
        var line = DecodeAuthorityJsonLine(lineBytes, byteOffset == 0);
        if (string.IsNullOrWhiteSpace(line))
            return true;
        if (locatorIndex >= orderedLocators.Count)
            return false;

        var locator = orderedLocators[locatorIndex];
        if (locator.ByteOffset != byteOffset
            || locator.ByteLength != lineBytes.LongLength
            || locator.LineNumber != lineNumber
            || !string.Equals(
                locator.AuthorityLineSha256,
                $"sha256:{HashBytes(lineBytes)}",
                StringComparison.Ordinal))
        {
            return false;
        }

        locatorIndex++;
        return true;
    }

    private static bool MatchesIndexLocator(
        DesignConversionLocalArtifactDbIndexRecordLocator locator,
        DesignConversionLocalArtifactDbQuery query)
    {
        if (!string.IsNullOrWhiteSpace(query.JobId)
            && !string.Equals(locator.JobId, query.JobId, StringComparison.Ordinal))
            return false;
        if (!string.IsNullOrWhiteSpace(query.RequestId)
            && !string.Equals(locator.RequestId, query.RequestId, StringComparison.Ordinal))
            return false;

        return true;
    }

    private async Task<IndexedCandidateReadResult> TryReadIndexedCandidateRecordsAsync(
        IReadOnlyList<DesignConversionLocalArtifactDbIndexRecordLocator> locators,
        CancellationToken ct)
    {
        var records = new List<DesignConversionLocalArtifactDbRecord>();
        try
        {
            await using var stream = new FileStream(
                _recordsPath,
                FileMode.Open,
                FileAccess.Read,
                FileShare.Read,
                bufferSize: 4096,
                FileOptions.Asynchronous | FileOptions.RandomAccess);

            foreach (var locator in locators)
            {
                if (locator.ByteOffset < 0
                    || locator.ByteLength <= 0
                    || locator.ByteLength > MaxIndexedRecordLineByteLength
                    || locator.ByteOffset > stream.Length - locator.ByteLength)
                {
                    return new IndexedCandidateReadResult(false, []);
                }

                var lineBytes = new byte[(int)locator.ByteLength];
                stream.Seek(locator.ByteOffset, SeekOrigin.Begin);
                await stream.ReadExactlyAsync(lineBytes.AsMemory(0, lineBytes.Length), ct);

                if (!string.Equals($"sha256:{HashBytes(lineBytes)}", locator.AuthorityLineSha256, StringComparison.Ordinal))
                    return new IndexedCandidateReadResult(false, []);

                var line = DecodeAuthorityJsonLine(lineBytes, locator.ByteOffset == 0);
                DesignConversionLocalArtifactDbRecord? record;
                try
                {
                    record = JsonSerializer.Deserialize<DesignConversionLocalArtifactDbRecord>(
                        line,
                        JsonOptions);
                }
                catch (JsonException)
                {
                    return new IndexedCandidateReadResult(false, []);
                }

                if (!DesignConversionLocalArtifactDbRecord
                        .HasValidImprovementLoopAttemptHistoryMetadata(record) ||
                    !IsIndexedRecordLocatorMatch(record, locator))
                    return new IndexedCandidateReadResult(false, []);

                records.Add(record!);
            }
        }
        catch (DecoderFallbackException)
        {
            return new IndexedCandidateReadResult(false, []);
        }
        catch (EndOfStreamException)
        {
            return new IndexedCandidateReadResult(false, []);
        }
        catch (IOException)
        {
            return new IndexedCandidateReadResult(false, []);
        }
        catch (UnauthorizedAccessException)
        {
            return new IndexedCandidateReadResult(false, []);
        }

        return new IndexedCandidateReadResult(true, records);
    }

    private static bool IsIndexedRecordLocatorMatch(
        DesignConversionLocalArtifactDbRecord? record,
        DesignConversionLocalArtifactDbIndexRecordLocator locator)
        => record is not null
           && string.Equals(record.DatabaseKind, LocalArtifactDbKind, StringComparison.Ordinal)
           && string.Equals(record.RecordId, locator.RecordId, StringComparison.Ordinal)
           && string.Equals(record.JobId, locator.JobId, StringComparison.Ordinal)
           && string.Equals(record.RequestId, locator.RequestId, StringComparison.Ordinal)
           && string.Equals(record.SourceKind, locator.SourceKind, StringComparison.Ordinal)
           && record.CreatedAtUtc.Equals(locator.CreatedAtUtc)
           && string.Equals(GetImmutableAppendFingerprint(record), locator.ImmutableAppendFingerprint, StringComparison.Ordinal);

    public async Task<OperationResult<IReadOnlyList<DesignConversionDpoTrainingRecord>>> QueryApprovedTrainingCandidatesAsync(
        DesignConversionLocalArtifactDbQuery? query = null,
        CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<IReadOnlyList<DesignConversionDpoTrainingRecord>>();

        var records = await ListRecordsAsync(query, ct);
        if (!records.IsSuccess)
            return records.MapError<IReadOnlyList<DesignConversionDpoTrainingRecord>>();

        var effectiveQuery = query ?? new DesignConversionLocalArtifactDbQuery();
        var eligibleRecords = await FilterPostEvaluationTrainingEligibleAsync(
            records.Value!,
            ct);
        var candidates = eligibleRecords
            .SelectMany(record => record.DpoCandidates)
            .Where(candidate => IsApprovedTrainingCandidate(candidate))
            .Where(candidate => MatchesCandidate(candidate, effectiveQuery))
            .Select(candidate => candidate.TrainingRecord)
            .OrderByDescending(record => record.UsefulnessScore)
            .ThenBy(record => record.RecordId, StringComparer.Ordinal)
            .ToArray();

        return OperationResult<IReadOnlyList<DesignConversionDpoTrainingRecord>>.Ok(candidates);
    }

    public async Task<OperationResult<DesignConversionApprovedDpoHandoffArtifact>> ExportApprovedRuntimeDpoCandidatesAsync(
        DesignConversionLocalArtifactDbQuery? query = null,
        DateTimeOffset? exportedAtUtc = null,
        CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionApprovedDpoHandoffArtifact>();

        var records = await ListRecordsAsync(query, ct);
        if (!records.IsSuccess)
            return records.MapError<DesignConversionApprovedDpoHandoffArtifact>();

        var effectiveQuery = query ?? new DesignConversionLocalArtifactDbQuery();
        var eligibleRecords = await FilterPostEvaluationTrainingEligibleAsync(
            records.Value!,
            ct);
        var selectedCandidates = eligibleRecords
            .SelectMany(record => record.DpoCandidates.Select(candidate => new { record, candidate }))
            .Where(item => IsApprovedRuntimeHandoffCandidate(item.record, item.candidate))
            .Where(item => MatchesCandidate(item.candidate, effectiveQuery))
            .OrderByDescending(item => item.candidate.UsefulnessScore)
            .ThenBy(item => item.candidate.RecordId, StringComparer.Ordinal)
            .ToArray();
        var handoffSchemaVersion = selectedCandidates.Any(item =>
            RequiresPayloadCustody(item.candidate.TrainingRecord))
                ? ApprovedDpoHandoffCustodySchemaVersion
                : ApprovedDpoHandoffSchemaVersion;
        var rows = selectedCandidates
            .Select(item => BuildHandoffRow(
                item.record,
                item.candidate,
                handoffSchemaVersion))
            .ToArray();
        var artifactId = BuildHandoffArtifactId(rows, handoffSchemaVersion);
        var result = new DesignConversionApprovedDpoHandoffArtifact(
            ArtifactId: artifactId,
            ArtifactRef: $"memory://design-conversion/dpo-handoff/{artifactId}",
            SchemaVersion: handoffSchemaVersion,
            ExportedAtUtc: (exportedAtUtc ?? DateTimeOffset.UtcNow).ToUniversalTime(),
            ApprovedCandidateCount: rows.Length,
            Rows: rows,
            Warnings: BuildHandoffWarnings(rows.Length),
            BoundaryMetadata: BuildHandoffBoundaryMetadata(rows, handoffSchemaVersion));

        return OperationResult<DesignConversionApprovedDpoHandoffArtifact>.Ok(result);
    }

    public async Task<OperationResult<DesignConversionTrainingIntakeRecord>> CreateTrainingIntakeAsync(
        DesignConversionApprovedDpoHandoffArtifact handoff,
        string requestedByRef,
        string reason,
        DateTimeOffset? requestedAtUtc = null,
        CancellationToken ct = default,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata = null)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeRecord>();
        if (handoff is null)
            return OperationResult<DesignConversionTrainingIntakeRecord>.Fail(
                "DesignConversion approved DPO handoff artifact is required for training intake.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_HANDOFF_REQUIRED");
        if (string.IsNullOrWhiteSpace(requestedByRef))
            return OperationResult<DesignConversionTrainingIntakeRecord>.Fail(
                "DesignConversion training intake requires a requester reference.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_REQUESTER_REQUIRED");
        if (string.IsNullOrWhiteSpace(reason))
            return OperationResult<DesignConversionTrainingIntakeRecord>.Fail(
                "DesignConversion training intake requires an evidence-bound request reason.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_REASON_REQUIRED");
        if (ContainsForbiddenTrainingIntakePayload(requestedByRef)
            || ContainsForbiddenTrainingIntakePayload(reason))
        {
            return OperationResult<DesignConversionTrainingIntakeRecord>.Fail(
                "DesignConversion training intake request metadata contains raw or private payload markers.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_REQUEST_UNSANITIZED");
        }

        var validation = ValidateTrainingIntakeHandoff(handoff);
        if (!validation.IsSuccess)
            return validation.MapError<DesignConversionTrainingIntakeRecord>();

        var requestedAt = (requestedAtUtc ?? DateTimeOffset.UtcNow).ToUniversalTime();
        var intake = BuildTrainingIntakeRecord(handoff, requestedByRef, reason, requestedAt, admissionBoundaryMetadata);

        var gateAcquired = false;
        try
        {
            await WaitForObservedGateAsync(
                _recordsMutationContext.CreateTrainingIntakeJournalGate,
                _createTrainingIntakeJournalWaitTaskObserverForTesting,
                () => gateAcquired = true,
                ct);

            if (_createTrainingIntakeJournalGateAcquiredCallbackForTesting is not null)
                await _createTrainingIntakeJournalGateAcquiredCallbackForTesting(ct);

            await using var mutationLease = await AcquireTrainingIntakeMutationLeaseAsync(ct);
            var eligibility = await ResolveTrainingIntakeRecordsAsync(intake, ct);
            if (!eligibility.IsSuccess)
                return eligibility.MapError<DesignConversionTrainingIntakeRecord>();
            if (eligibility.Value!.BlockReasons.Count > 0)
            {
                return OperationResult<DesignConversionTrainingIntakeRecord>.Fail(
                    $"DesignConversion training intake is blocked by current durable candidate eligibility: {string.Join(",", eligibility.Value.BlockReasons)}.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_POST_EVALUATION_INELIGIBLE");
            }

            return await StoreCreateTrainingIntakeWithIdempotencyReplayAsync(intake, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<DesignConversionTrainingIntakeRecord>();
        }
        catch (IOException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionTrainingIntakeRecord>();
        }
        catch (UnauthorizedAccessException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionTrainingIntakeRecord>();
        }
        finally
        {
            if (gateAcquired)
                _recordsMutationContext.CreateTrainingIntakeJournalGate.Release();
        }
    }

    private Task<DesignConversionDeterministicMutationLease> AcquireTrainingIntakeMutationLeaseAsync(CancellationToken ct)
    {
        Directory.CreateDirectory(_rootDirectory);

        return DesignConversionDeterministicMutationLock.WaitUntilAcquiredAsync(
            _trainingIntakeMutationLockPath,
            TimeSpan.FromMilliseconds(TrainingIntakeMutationLockRetryDelayMs),
            ct);
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeRecord>> StoreCreateTrainingIntakeWithIdempotencyReplayAsync(
        DesignConversionTrainingIntakeRecord intake,
        CancellationToken ct)
    {
        var replay = await ResolveCreateTrainingIntakeIdempotencyReplayAsync(intake, ct);
        if (!replay.IsSuccess)
            return replay.MapError<DesignConversionTrainingIntakeRecord>();
        if (replay.Value!.HasReplay)
            return OperationResult<DesignConversionTrainingIntakeRecord>.Ok(replay.Value.Record!);

        intake = MarkCreateTrainingIntakeIdempotencyBoundary(
            intake,
            replayHit: false,
            createdNewSideEffect: true);

        Directory.CreateDirectory(_rootDirectory);
        var line = JsonSerializer.Serialize(intake, JsonOptions);
        if (!TryProjectTrainingIntakeRequestsLength(line, out var projectedLength)
            || projectedLength > _trainingIntakeRequestsMaxBytes)
        {
            return TrainingIntakeRequestsQuotaExceeded<DesignConversionTrainingIntakeRecord>();
        }

        await DurableCopyOnWriteAppendJsonLineAsync(
            _trainingIntakePath,
            line,
            DesignConversionTrainingJournalPublicationKind.TrainingIntakeRequests,
            _trainingJournalBeforeAtomicPublishCallbackForTesting,
            ct);

        return OperationResult<DesignConversionTrainingIntakeRecord>.Ok(intake);
    }

    private bool TryProjectTrainingIntakeRequestsLength(
        string line,
        out long projectedLength)
    {
        var existingLength = File.Exists(_trainingIntakePath)
            ? new FileInfo(_trainingIntakePath).Length
            : 0;
        var appendedLineByteLength = StrictUtf8Encoding.GetByteCount(line + Environment.NewLine);

        return TryProjectCommittedAuthorityLength(
            existingLength,
            appendedLineByteLength,
            out projectedLength);
    }

    private static async Task DurableCopyOnWriteAppendJsonLineAsync(
        string destinationPath,
        string line,
        DesignConversionTrainingJournalPublicationKind publicationKind,
        Action<DesignConversionTrainingJournalPublicationKind>?
            beforeAtomicPublishCallbackForTesting,
        CancellationToken ct)
    {
        var directory = Path.GetDirectoryName(destinationPath);
        if (string.IsNullOrWhiteSpace(directory))
            directory = Directory.GetCurrentDirectory();

        Directory.CreateDirectory(directory);

        var tempPath = Path.Combine(
            directory,
            $"{Path.GetFileName(destinationPath)}.{Guid.NewGuid():N}.copyonwrite.tmp");
        var appendedBytes = StrictUtf8Encoding.GetBytes(line + Environment.NewLine);
        FileStream? source = null;
        var committed = false;

        try
        {
            var destinationExists = File.Exists(destinationPath);
            long originalSourceLength = 0;
            if (destinationExists)
            {
                source = new FileStream(
                    destinationPath,
                    FileMode.Open,
                    FileAccess.Read,
                    FileShare.Read | FileShare.Delete,
                    bufferSize: 81920,
                    FileOptions.Asynchronous | FileOptions.SequentialScan);
                originalSourceLength = source.Length;
            }

            await using (var temp = new FileStream(
                tempPath,
                FileMode.CreateNew,
                FileAccess.ReadWrite,
                FileShare.None,
                bufferSize: 81920,
                FileOptions.Asynchronous | FileOptions.WriteThrough | FileOptions.SequentialScan))
            {
                if (source is not null)
                {
                    await source.CopyToAsync(temp, 81920, ct);
                    if (source.Length != originalSourceLength
                        || temp.Position != originalSourceLength
                        || temp.Length != originalSourceLength)
                    {
                        throw new IOException("DesignConversion journal source length changed during copy-on-write append.");
                    }
                }

                await temp.WriteAsync(appendedBytes.AsMemory(0, appendedBytes.Length), ct);
                await temp.FlushAsync(ct);
                temp.Flush(flushToDisk: true);
            }

            ct.ThrowIfCancellationRequested();
            // Тестовый шов стоит после принудительной записи временного файла на диск,
            // но до единственной смены главного журнала. Он получает только вид журнала,
            // чтобы тест отказа не мог увидеть путь, JSON или ключ идемпотентности.
            beforeAtomicPublishCallbackForTesting?.Invoke(publicationKind);

            if (destinationExists)
                File.Replace(tempPath, destinationPath, null);
            else
                File.Move(tempPath, destinationPath);

            committed = true;
        }
        finally
        {
            TryDisposeCopyOnWriteSource(source);
            if (!committed || File.Exists(tempPath))
                TryDeleteCopyOnWriteTemp(tempPath);
        }
    }

    private static void TryDisposeCopyOnWriteSource(FileStream? source)
    {
        if (source is null)
            return;

        try
        {
            source.Dispose();
        }
        catch (IOException)
        {
        }
        catch (UnauthorizedAccessException)
        {
        }
        catch (SecurityException)
        {
        }
    }

    private static void TryDeleteCopyOnWriteTemp(string tempPath)
    {
        try
        {
            if (File.Exists(tempPath))
                File.Delete(tempPath);
        }
        catch (IOException)
        {
        }
        catch (UnauthorizedAccessException)
        {
        }
        catch (SecurityException)
        {
        }
    }

    public async Task<OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRecord>>> ListTrainingIntakeRequestsAsync(
        CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<IReadOnlyList<DesignConversionTrainingIntakeRecord>>();
        if (!File.Exists(_trainingIntakePath))
            return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRecord>>.Ok([]);

        var records = new List<DesignConversionTrainingIntakeRecord>();
        string[] lines;
        try
        {
            lines = await File.ReadAllLinesAsync(_trainingIntakePath, StrictUtf8Encoding, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<IReadOnlyList<DesignConversionTrainingIntakeRecord>>();
        }
        catch (DecoderFallbackException)
        {
            return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRecord>>.Fail(
                "DesignConversion training intake requests could not be read because the training intake requests file is not valid UTF-8.",
                InvalidUtf8ErrorCode);
        }
        catch (IOException)
        {
            return TrainingIntakeReadFailed<IReadOnlyList<DesignConversionTrainingIntakeRecord>>();
        }
        catch (UnauthorizedAccessException)
        {
            return TrainingIntakeReadFailed<IReadOnlyList<DesignConversionTrainingIntakeRecord>>();
        }
        catch (SecurityException)
        {
            return TrainingIntakeReadFailed<IReadOnlyList<DesignConversionTrainingIntakeRecord>>();
        }

        for (var i = 0; i < lines.Length; i++)
        {
            if (string.IsNullOrWhiteSpace(lines[i]))
                continue;

            DesignConversionTrainingIntakeRecord? record;
            try
            {
                record = JsonSerializer.Deserialize<DesignConversionTrainingIntakeRecord>(
                    lines[i],
                    JsonOptions);
            }
            catch (JsonException)
            {
                return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRecord>>.Fail(
                    $"DesignConversion training intake line {(i + 1).ToString(CultureInfo.InvariantCulture)} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_LINE_INVALID");
            }
            catch (NotSupportedException)
            {
                return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRecord>>.Fail(
                    $"DesignConversion training intake line {(i + 1).ToString(CultureInfo.InvariantCulture)} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_LINE_INVALID");
            }

            if (record is null)
            {
                return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRecord>>.Fail(
                    $"DesignConversion training intake line {(i + 1).ToString(CultureInfo.InvariantCulture)} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_LINE_INVALID");
            }

            var recordSchemaVersion = ReadMetadata(
                record.BoundaryMetadata,
                "schema_version");
            if (!string.Equals(recordSchemaVersion, TrainingIntakeSchemaVersion, StringComparison.Ordinal) &&
                !string.Equals(recordSchemaVersion, TrainingIntakeCustodySchemaVersion, StringComparison.Ordinal))
            {
                return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRecord>>.Fail(
                    $"DesignConversion training intake line {(i + 1).ToString(CultureInfo.InvariantCulture)} has an unsupported schema.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_SCHEMA_INVALID");
            }

            records.Add(record);
        }

        return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRecord>>.Ok(
            records
                .OrderBy(record => record.RequestedAtUtc)
                .ThenBy(record => record.IntakeId, StringComparer.Ordinal)
                .ToArray());
    }

    public async Task<OperationResult<DesignConversionTrainingIntakePreflightResult>> RunTrainingIntakePreflightAsync(
        string intakeId,
        CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakePreflightResult>();
        var intakeIdValidation = ValidateTrainingIntakePreflightId(intakeId);
        if (!intakeIdValidation.IsSuccess)
            return intakeIdValidation.MapError<DesignConversionTrainingIntakePreflightResult>();

        var intakes = await ListTrainingIntakeRequestsAsync(ct);
        if (!intakes.IsSuccess)
            return intakes.MapError<DesignConversionTrainingIntakePreflightResult>();

        var resolution = ResolveTrainingIntakeIdAuthority(
            intakes.Value!,
            intakeId,
            "DesignConversion training intake preflight could not find the queued intake record.",
            "DESIGN_CONVERSION_TRAINING_INTAKE_PREFLIGHT_NOT_FOUND",
            "DesignConversion training intake preflight found duplicate intake ids.",
            "DESIGN_CONVERSION_TRAINING_INTAKE_PREFLIGHT_AMBIGUOUS");
        if (!resolution.IsSuccess)
            return resolution.MapError<DesignConversionTrainingIntakePreflightResult>();

        return OperationResult<DesignConversionTrainingIntakePreflightResult>.Ok(
            BuildTrainingIntakePreflightResult(
                resolution.Value!.Record,
                resolution.Value));
    }

    public async Task<OperationResult<DesignConversionTrainingIntakeRunResult>> RunTrainingIntakeAsync(
        string intakeId,
        DesignConversionTrainingPipelineOptions? options = null,
        CancellationToken ct = default,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata = null)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeRunResult>();

        DesignConversionTrainingPipelineOptions? providedOptionsSnapshot = null;
        if (options is not null)
        {
            var capturedOptions = DesignConversionTrainingPipeline.SnapshotOptions(options);
            if (!capturedOptions.IsSuccess || capturedOptions.Value is null)
                return capturedOptions.MapError<DesignConversionTrainingIntakeRunResult>();
            providedOptionsSnapshot = capturedOptions.Value;
        }

        var preflight = await RunTrainingIntakePreflightAsync(intakeId, ct);
        if (!preflight.IsSuccess)
            return preflight.MapError<DesignConversionTrainingIntakeRunResult>();

        var intake = await FindQueuedTrainingIntakeAsync(intakeId, ct);
        if (!intake.IsSuccess)
            return intake.MapError<DesignConversionTrainingIntakeRunResult>();

        var runOptions = providedOptionsSnapshot ??
            BuildDefaultTrainingIntakeRunOptions(intake.Value!);
        var gateAcquired = false;
        try
        {
            await WaitForObservedGateAsync(
                _recordsMutationContext.RunTrainingIntakeGate,
                _runTrainingIntakeGateWaitTaskObserverForTesting,
                () => gateAcquired = true,
                ct);

            if (_runTrainingIntakeGateAcquiredCallbackForTesting is not null)
                await _runTrainingIntakeGateAcquiredCallbackForTesting(ct);

            await using var mutationLease = await AcquireTrainingIntakeRunMutationLeaseAsync(ct);
            return await RunTrainingIntakeCoreAsync(
                intake.Value!,
                preflight.Value!,
                runOptions,
                optionsProvided: options is not null,
                admissionBoundaryMetadata,
                corpusAdmissionRequest: null,
                ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<DesignConversionTrainingIntakeRunResult>();
        }
        catch (IOException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionTrainingIntakeRunResult>();
        }
        catch (UnauthorizedAccessException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionTrainingIntakeRunResult>();
        }
        finally
        {
            if (gateAcquired)
                _recordsMutationContext.RunTrainingIntakeGate.Release();
        }
    }

    internal async Task<OperationResult<DesignConversionTrainingIntakeRunResult>>
        RunTrainingIntakeWithCorpusAdmissionAsync(
            string intakeId,
            DesignConversionDpoCorpusAdmissionRequest corpusAdmissionRequest,
            DesignConversionTrainingPipelineOptions? options = null,
            CancellationToken ct = default,
            IReadOnlyDictionary<string, string>? admissionBoundaryMetadata = null)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeRunResult>();
        if (corpusAdmissionRequest is null)
        {
            return OperationResult<DesignConversionTrainingIntakeRunResult>.Fail(
                "A live corpus admission request is required.",
                DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
        }

        var preflight = await RunTrainingIntakePreflightAsync(intakeId, ct);
        if (!preflight.IsSuccess)
            return preflight.MapError<DesignConversionTrainingIntakeRunResult>();

        var intake = await FindQueuedTrainingIntakeAsync(intakeId, ct);
        if (!intake.IsSuccess)
            return intake.MapError<DesignConversionTrainingIntakeRunResult>();

        var runOptions = options ?? BuildDefaultTrainingIntakeRunOptions(intake.Value!);
        var gateAcquired = false;
        try
        {
            await WaitForObservedGateAsync(
                _recordsMutationContext.RunTrainingIntakeGate,
                _runTrainingIntakeGateWaitTaskObserverForTesting,
                () => gateAcquired = true,
                ct);

            if (_runTrainingIntakeGateAcquiredCallbackForTesting is not null)
                await _runTrainingIntakeGateAcquiredCallbackForTesting(ct);

            await using var mutationLease = await AcquireTrainingIntakeRunMutationLeaseAsync(ct);
            return await RunTrainingIntakeCoreAsync(
                intake.Value!,
                preflight.Value!,
                runOptions,
                optionsProvided: options is not null,
                admissionBoundaryMetadata,
                corpusAdmissionRequest,
                ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<DesignConversionTrainingIntakeRunResult>();
        }
        catch (IOException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionTrainingIntakeRunResult>();
        }
        catch (UnauthorizedAccessException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionTrainingIntakeRunResult>();
        }
        finally
        {
            if (gateAcquired)
                _recordsMutationContext.RunTrainingIntakeGate.Release();
        }
    }

    private Task<DesignConversionDeterministicMutationLease> AcquireTrainingIntakeRunMutationLeaseAsync(CancellationToken ct)
    {
        Directory.CreateDirectory(_rootDirectory);

        return DesignConversionDeterministicMutationLock.WaitUntilAcquiredAsync(
            _trainingIntakeRunMutationLockPath,
            TimeSpan.FromMilliseconds(TrainingIntakeRunMutationLockRetryDelayMs),
            ct);
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeRunResult>> RunTrainingIntakeCoreAsync(
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingIntakePreflightResult preflight,
        DesignConversionTrainingPipelineOptions runOptions,
        bool optionsProvided,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        DesignConversionDpoCorpusAdmissionRequest? corpusAdmissionRequest,
        CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeRunResult>();

        var replay = await ResolveRunTrainingIntakeIdempotencyReplayAsync(
            intake,
            runOptions,
            admissionBoundaryMetadata,
            ct);
        if (!replay.IsSuccess)
            return replay.MapError<DesignConversionTrainingIntakeRunResult>();
        if (replay.Value!.HasReplay)
        {
            var replayValidation =
                await ValidateRunTrainingIntakeReplayCurrentSnapshotAsync(
                    intake,
                    preflight,
                    runOptions,
                    admissionBoundaryMetadata,
                    corpusAdmissionRequest,
                    replay.Value.Result!,
                    ct);
            if (!replayValidation.IsSuccess || replayValidation.Value is null)
            {
                return replayValidation.MapError<
                    DesignConversionTrainingIntakeRunResult>();
            }

            return OperationResult<DesignConversionTrainingIntakeRunResult>.Ok(
                MarkRunTrainingIntakeIdempotencyBoundary(
                    replay.Value.Result!,
                    intake,
                    replayValidation.Value.SnapshotOptions,
                    replayValidation.Value.BoundaryMetadata,
                    replayHit: true,
                    createdNewSideEffect: false,
                    replayValidation.Value.SnapshotRecords));
        }

        DesignConversionTrainingIntakeRecordResolution? resolved = null;
        if (IsCustodyTrainingIntake(intake) || preflight.MayStartTraining)
        {
            var initialResolved = await ResolveTrainingIntakeRecordsAsync(intake, ct);
            if (!initialResolved.IsSuccess)
                return initialResolved.MapError<DesignConversionTrainingIntakeRunResult>();
            resolved = TransformRunTrainingIntakeResolvedRecordsForTesting(
                initialResolved.Value!);
        }

        if (!preflight.MayStartTraining)
        {
            var blockReasons = resolved is null
                ? preflight.BlockReasons
                : preflight.BlockReasons
                    .Concat(resolved.BlockReasons)
                    .Distinct(StringComparer.Ordinal)
                    .Order(StringComparer.Ordinal)
                    .ToArray();
            var blockedRun = BuildTrainingIntakeRunResult(
                intake,
                preflight,
                runOptions,
                optionsProvided: optionsProvided,
                resolvedTrainingRecordCount: resolved?.Records.Count ?? 0,
                runnerResult: null,
                blockReasons: blockReasons,
                trainingExecutionBoundary: resolved?.BlockReasons.Count > 0
                    ? "blocked_before_runner_by_training_intake_resolution"
                    : "blocked_before_runner_by_training_intake_preflight");
            var preflightMeasurement = RequireCallerAdmissionMeasurement(runOptions);
            if (!preflightMeasurement.IsSuccess)
            {
                return resolved?.BlockReasons.Count > 0
                    ? OperationResult<DesignConversionTrainingIntakeRunResult>.Ok(
                        blockedRun)
                    : preflightMeasurement.MapError<
                        DesignConversionTrainingIntakeRunResult>();
            }

            if (!CanReserveMaximumTrainingIntakeRunJournalRow())
                return TrainingIntakeRunsQuotaExceeded<DesignConversionTrainingIntakeRunResult>();

            return await StoreRunTrainingIntakeIdempotencyResultAsync(
                blockedRun,
                intake,
                runOptions,
                admissionBoundaryMetadata,
                ct);
        }

        if (resolved is null)
        {
            var initialResolved = await ResolveTrainingIntakeRecordsAsync(intake, ct);
            if (!initialResolved.IsSuccess)
                return initialResolved.MapError<DesignConversionTrainingIntakeRunResult>();
            resolved = TransformRunTrainingIntakeResolvedRecordsForTesting(
                initialResolved.Value!);
        }

        if (resolved.BlockReasons.Count > 0)
        {
            var blockedRun = BuildTrainingIntakeRunResult(
                intake,
                preflight,
                runOptions,
                optionsProvided: optionsProvided,
                resolvedTrainingRecordCount: resolved.Records.Count,
                runnerResult: null,
                blockReasons: resolved.BlockReasons,
                trainingExecutionBoundary: "blocked_before_runner_by_training_intake_resolution");
            var resolutionMeasurement = RequireCallerAdmissionMeasurement(runOptions);
            if (!resolutionMeasurement.IsSuccess)
            {
                return OperationResult<DesignConversionTrainingIntakeRunResult>.Ok(
                    blockedRun);
            }

            if (!CanReserveMaximumTrainingIntakeRunJournalRow())
                return TrainingIntakeRunsQuotaExceeded<DesignConversionTrainingIntakeRunResult>();

            return await StoreRunTrainingIntakeIdempotencyResultAsync(
                blockedRun,
                intake,
                runOptions,
                admissionBoundaryMetadata,
                ct);
        }

        if (corpusAdmissionRequest is null &&
            RequiresDpoCorpusAdmissionBeforeOrdinaryDuplicateAuthority(
                resolved.Records))
        {
            return DpoCorpusAdmissionRequired<DesignConversionTrainingIntakeRunResult>();
        }

        if (corpusAdmissionRequest is null &&
            !IsPotentialOrdinaryDualTargetTeacherAggregateBeforeDeepAuthority(
                resolved.Records))
        {
            var teacherRequestIds =
                RequireUniqueTeacherRequestIdsBeforeLocalMutation(resolved.Records);
            if (!teacherRequestIds.IsSuccess)
                return teacherRequestIds.MapError<DesignConversionTrainingIntakeRunResult>();
        }

        var measurementAdmission = RequireCallerAdmissionMeasurement(runOptions);
        if (!measurementAdmission.IsSuccess)
            return measurementAdmission.MapError<DesignConversionTrainingIntakeRunResult>();

        if (!CanReserveMaximumTrainingIntakeRunJournalRow())
            return TrainingIntakeRunsQuotaExceeded<DesignConversionTrainingIntakeRunResult>();

        _runTrainingIntakeRunnerBeforeInvokeObserverForTesting?.Invoke();
        var refreshedResolved = await ResolveTrainingIntakeRecordsAsync(intake, ct);
        if (!refreshedResolved.IsSuccess)
            return refreshedResolved.MapError<DesignConversionTrainingIntakeRunResult>();
        resolved = TransformRunTrainingIntakeResolvedRecordsForTesting(
            refreshedResolved.Value!);
        if (resolved.BlockReasons.Count > 0)
        {
            return await StoreRunTrainingIntakeIdempotencyResultAsync(
                BuildTrainingIntakeRunResult(
                    intake,
                    preflight,
                    runOptions,
                    optionsProvided: optionsProvided,
                    resolvedTrainingRecordCount: resolved.Records.Count,
                    runnerResult: null,
                    blockReasons: resolved.BlockReasons,
                    trainingExecutionBoundary:
                    "blocked_immediately_before_runner_by_post_evaluation_revalidation"),
                intake,
                runOptions,
                admissionBoundaryMetadata,
                ct);
        }

        if (corpusAdmissionRequest is null &&
            RequiresDpoCorpusAdmissionBeforeOrdinaryDuplicateAuthority(
                resolved.Records))
        {
            return DpoCorpusAdmissionRequired<DesignConversionTrainingIntakeRunResult>();
        }

        if (corpusAdmissionRequest is null &&
            !IsPotentialOrdinaryDualTargetTeacherAggregateBeforeDeepAuthority(
                resolved.Records))
        {
            var teacherRequestIds =
                RequireUniqueTeacherRequestIdsBeforeLocalMutation(resolved.Records);
            if (!teacherRequestIds.IsSuccess)
                return teacherRequestIds.MapError<DesignConversionTrainingIntakeRunResult>();
        }

        var recordsSnapshot = DesignConversionTrainingPipeline.SnapshotTrainingRecords(
            resolved.Records);
        if (!recordsSnapshot.IsSuccess)
            return recordsSnapshot.MapError<DesignConversionTrainingIntakeRunResult>();
        var optionsSnapshot = DesignConversionTrainingPipeline.SnapshotOptions(runOptions);
        if (!optionsSnapshot.IsSuccess)
            return optionsSnapshot.MapError<DesignConversionTrainingIntakeRunResult>();
        var snapshotRecords = recordsSnapshot.Value!;
        var snapshotOptions = optionsSnapshot.Value!;
        var metadataSnapshot = SnapshotAdmissionBoundaryMetadata(admissionBoundaryMetadata);
        var custodyEvidenceSnapshot = resolved.CustodyEvidence.ToArray();
        if (_legalTeacherAdmissionAuthority is null)
            return LegalTeacherConfigurationRequired<DesignConversionTrainingIntakeRunResult>();

        if (corpusAdmissionRequest is null &&
            DesignConversionDpoCorpusAdmissionRequirementPolicy.RequiresAdmission(
                snapshotRecords))
        {
            return DpoCorpusAdmissionRequired<DesignConversionTrainingIntakeRunResult>();
        }

        if (corpusAdmissionRequest is not null)
        {
            return await RunAdmittedCorpusTrainingIntakeAsync(
                intake,
                preflight,
                snapshotRecords,
                snapshotOptions,
                optionsProvided,
                metadataSnapshot ?? new Dictionary<string, string>(StringComparer.Ordinal),
                custodyEvidenceSnapshot,
                corpusAdmissionRequest,
                ct);
        }

        var trainingRunner = new DesignConversionTrainingRunner();
        var preparedRunner = trainingRunner.PrepareTrainingRecords(
            snapshotRecords,
            snapshotOptions,
            custodyEvidenceSnapshot);
        if (!preparedRunner.IsSuccess || preparedRunner.Value is null)
        {
            return preparedRunner.MapError<
                DesignConversionTrainingIntakeRunResult>();
        }
        var preparedPairs = PrepareFinalTrainingIntakeDpoPairs(
            preparedRunner.Value.Pipeline);
        if (!preparedPairs.IsSuccess || preparedPairs.Value is null)
            return preparedPairs.MapError<DesignConversionTrainingIntakeRunResult>();
        var pipelineFinalOptimizer =
            preparedRunner.Value.Pipeline.FinalOptimizer;

        var externalPreparation =
            PrepareDualTargetTeacherExternalConsumptionBeforeRunner(
                preparedRunner.Value,
                ct);
        if (!externalPreparation.IsSuccess)
        {
            return externalPreparation.MapError<
                DesignConversionTrainingIntakeRunResult>();
        }
        if (externalPreparation.Value is { } preparedExternal)
        {
            _runTrainingIntakeRunnerInvokedObserverForTesting?.Invoke();
            var externalRunner = await trainingRunner
                .RunPreparedDualTargetTeacherExternalConsumptionAsync(
                    _legalTeacherAdmissionAuthority,
                    new DesignConversionMachine(),
                    preparedRunner.Value,
                    preparedExternal.Transaction,
                    ct);
            if (!externalRunner.IsSuccess || externalRunner.Value is null)
            {
                return externalRunner.MapError<
                    DesignConversionTrainingIntakeRunResult>();
            }
            var committedIdentity =
                ValidateCommittedDualTargetTeacherExternalConsumption(
                    preparedExternal,
                    externalRunner.Value.ExternalConsumption);
            if (!committedIdentity.IsSuccess ||
                committedIdentity.Value is not true)
            {
                return committedIdentity.IsSuccess
                    ? OperationResult<
                        DesignConversionTrainingIntakeRunResult>.Fail(
                            "The committed external DesignConversion DPO group identity is invalid.",
                            LegalTrainingTeacherAdmissionAuthority
                                .TrainingContentInvalidErrorCode)
                    : committedIdentity.MapError<
                        DesignConversionTrainingIntakeRunResult>();
            }

            // Complete is the external transaction's irreversible boundary. A
            // caller cancellation observed after it must not erase the only
            // local terminal record for an already-committed Machine mutation.
            return await StoreRunTrainingIntakeIdempotencyResultAsync(
                BuildTrainingIntakeRunResult(
                    intake,
                    preflight,
                    snapshotOptions,
                    optionsProvided: optionsProvided,
                    resolvedTrainingRecordCount: snapshotRecords.Length,
                    runnerResult: externalRunner.Value.Run,
                    blockReasons: [],
                    trainingExecutionBoundary: BuildTrainingExecutionBoundary(
                        externalRunner.Value.Run)),
                intake,
                snapshotOptions,
                metadataSnapshot,
                CancellationToken.None,
                snapshotRecords);
        }

        DesignConversionDpoTrainingContentAuthority
            .CompositeOptimizerCommitment? compositeCommitment = null;
        OperationResult<ServerOwnedLegalTrainingTeacherAdmissionLease>
            leaseResult;
        if (pipelineFinalOptimizer is not null)
        {
            var compositeOptimizer =
                DesignConversionDpoTrainingContentAuthority
                    .ProjectCompositeOptimizerInputs(
                        pipelineFinalOptimizer,
                        preparedPairs.Value,
                        bridgeFinalOptimizer: null);
            if (!compositeOptimizer.IsSuccess ||
                compositeOptimizer.Value is null)
            {
                return compositeOptimizer.MapError<
                    DesignConversionTrainingIntakeRunResult>();
            }
            compositeCommitment = compositeOptimizer.Value;
            leaseResult = _legalTeacherAdmissionAuthority.AcquireTrainingLease(
                compositeCommitment.FinalOptimizer.Content,
                compositeCommitment.FinalOptimizer.Provenance);
        }
        else
        {
            var trainingContent =
                DesignConversionDpoTrainingContentAuthority.Project(
                    snapshotRecords);
            if (!trainingContent.IsSuccess || trainingContent.Value is null)
            {
                return trainingContent.MapError<
                    DesignConversionTrainingIntakeRunResult>();
            }
            leaseResult = _legalTeacherAdmissionAuthority.AcquireTrainingLease(
                trainingContent.Value,
                snapshotRecords
                    .Select((record, index) => record.TeacherProvenance! with
                    {
                        TrainingContentSha256 =
                            trainingContent.Value.Rows[index].Sha256
                    })
                    .ToArray());
        }
        if (!leaseResult.IsSuccess)
            return leaseResult.MapError<DesignConversionTrainingIntakeRunResult>();

        using var trainingLease = leaseResult.Value!;
        DesignConversionTrainingPipeline.NotifyTrainingLease(trainingLease);
        var admissionSnapshot = DesignConversionTrainingPipeline.SnapshotAdmission(
            trainingLease.Admission);

        DesignConversionPipelineTrainingBinding? trainingBinding = null;
        if (compositeCommitment is not null)
        {
            var bindingResult = DesignConversionPipelineTrainingBinding
                .MintComposite(
                    compositeCommitment,
                    pipelineFinalOptimizer,
                    bridgeFinalOptimizer: null,
                    trainingLease);
            if (!bindingResult.IsSuccess || bindingResult.Value is null)
            {
                return bindingResult.MapError<
                    DesignConversionTrainingIntakeRunResult>();
            }
            trainingBinding = bindingResult.Value;
        }

        var pairPermit = trainingBinding is null
            ? DesignConversionTrainingPipeline.AcquireMutationPermit(
                trainingLease,
                "run_pair_store")
            : DesignConversionTrainingPipeline.AcquireMutationPermit(
                trainingBinding,
                "run_pair_store");
        if (!pairPermit.IsSuccess)
            return pairPermit.MapError<DesignConversionTrainingIntakeRunResult>();
        OperationResult<bool> persistedPairs;
        using (pairPermit.Value!)
        {
            persistedPairs = PersistFinalTrainingIntakeDpoPairsBeforeRunner(
                preparedPairs.Value,
                ct);
        }

        var pairResultPermit = trainingBinding is null
            ? DesignConversionTrainingPipeline.AcquireMutationPermit(
                trainingLease,
                "run_pair_store_result")
            : DesignConversionTrainingPipeline.AcquireMutationPermit(
                trainingBinding,
                "run_pair_store_result");
        if (!pairResultPermit.IsSuccess)
            return pairResultPermit.MapError<DesignConversionTrainingIntakeRunResult>();
        using (pairResultPermit.Value!)
        {
            if (ct.IsCancellationRequested)
                return Cancelled<DesignConversionTrainingIntakeRunResult>();
            if (!persistedPairs.IsSuccess)
                return persistedPairs.MapError<DesignConversionTrainingIntakeRunResult>();
        }

        _runTrainingIntakeRunnerInvokedObserverForTesting?.Invoke();
        var runner = await trainingRunner.RunPreparedTrainingRecordsAsync(
            new DesignConversionMachine(),
            trainingBinding,
            preparedRunner.Value,
            ct);
        if (!runner.IsSuccess)
            return runner.MapError<DesignConversionTrainingIntakeRunResult>();

        var finalJournalPermit = trainingBinding is null
            ? DesignConversionTrainingPipeline.AcquireMutationPermit(
                trainingLease,
                "run_final_journal")
            : DesignConversionTrainingPipeline.AcquireMutationPermit(
                trainingBinding,
                "run_final_journal");
        if (!finalJournalPermit.IsSuccess)
            return finalJournalPermit.MapError<DesignConversionTrainingIntakeRunResult>();
        using (finalJournalPermit.Value!)
        {
            var stored = await StoreRunTrainingIntakeIdempotencyResultAsync(
                BuildTrainingIntakeRunResult(
                    intake,
                    preflight,
                    snapshotOptions,
                    optionsProvided: optionsProvided,
                    resolvedTrainingRecordCount: snapshotRecords.Length,
                    runnerResult: runner.Value,
                    blockReasons: [],
                    trainingExecutionBoundary: BuildTrainingExecutionBoundary(runner.Value!)),
                intake,
                snapshotOptions,
                metadataSnapshot,
                ct,
                snapshotRecords);
            GC.KeepAlive(admissionSnapshot);
            return stored;
        }
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeRunResult>>
        RunAdmittedCorpusTrainingIntakeAsync(
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingIntakePreflightResult preflight,
            IReadOnlyList<DesignConversionDpoTrainingRecord> snapshotRecords,
            DesignConversionTrainingPipelineOptions snapshotOptions,
            bool optionsProvided,
            IReadOnlyDictionary<string, string> metadataSnapshot,
            IReadOnlyList<DesignConversionCandidatePayloadCustodyStore.CommittedEvidence>
                custodyEvidenceSnapshot,
            DesignConversionDpoCorpusAdmissionRequest request,
            CancellationToken ct)
    {
        var snapshotByIdentity = snapshotRecords
            .GroupBy(
                DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash,
                StringComparer.Ordinal)
            .ToDictionary(
                static group => group.Key,
                static group => group.ToArray(),
                StringComparer.Ordinal);
        var proofRows = request.CanonicalSourceProof.TrainRows
            .Concat(request.CanonicalSourceProof.HeldOutRows)
            .ToArray();
        var proofHashes = proofRows
            .Select(static row => row.RecordIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        var snapshotHashes = snapshotRecords
            .Select(DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        if (request.CanonicalSourceProof.TrainRows.Count != 2 ||
            request.CanonicalSourceProof.HeldOutRows.Count == 0 ||
            proofRows.Length != snapshotRecords.Count ||
            !proofHashes.SetEquals(snapshotHashes) ||
            snapshotByIdentity.Any(static item => item.Value.Length != 1))
        {
            return OperationResult<DesignConversionTrainingIntakeRunResult>.Fail(
                "The live intake records do not match the canonical corpus split.",
                DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
        }

        var orderedPair = request.CanonicalSourceProof.TrainRows
            .Select(row => snapshotByIdentity[row.RecordIdentityHash][0])
            .OrderBy(static record => string.Equals(
                    record.UnitId,
                    DesignConversionDpoUnits.CriticUnit,
                    StringComparison.Ordinal)
                ? 0
                : 1)
            .ToArray();
        var custodyCapability = DesignConversionCandidatePayloadCustodyStore
            .MintTrainingCapability(custodyEvidenceSnapshot);
        if (!custodyCapability.IsSuccess || custodyCapability.Value is null)
            return custodyCapability.MapError<DesignConversionTrainingIntakeRunResult>();

        var requestBinding = await BuildCorpusAdmissionRequestBindingAsync(
            intake,
            preflight,
            snapshotOptions,
            metadataSnapshot,
            snapshotRecords,
            custodyEvidenceSnapshot,
            ct);
        if (!requestBinding.IsSuccess || requestBinding.Value is null)
            return requestBinding.MapError<DesignConversionTrainingIntakeRunResult>();

        var issued = IssueDpoCorpusAdmission(
            orderedPair,
            custodyCapability.Value,
            request.Pair,
            request.Receipt,
            request.CanonicalSourceProof,
            request.ObservedAtUtc,
            requestBinding.Value);
        if (!issued.IsSuccess || issued.Value is null)
            return issued.MapError<DesignConversionTrainingIntakeRunResult>();

        var corpus = new DesignConversionDpoDatasetBuilder()
            .BuildAdmittedCorpus(
                issued.Value,
                snapshotOptions);
        if (!corpus.IsSuccess || corpus.Value is null)
            return corpus.MapError<DesignConversionTrainingIntakeRunResult>();

        var trainingRunner = new DesignConversionTrainingRunner();
        var preparedRunner = trainingRunner.PrepareAdmittedCorpus(corpus.Value);
        if (!preparedRunner.IsSuccess || preparedRunner.Value is null)
        {
            return preparedRunner.MapError<
                DesignConversionTrainingIntakeRunResult>();
        }

        var externalPreparation =
            PrepareDualTargetTeacherExternalConsumptionBeforeRunner(
                preparedRunner.Value,
                ct);
        if (!externalPreparation.IsSuccess)
        {
            return externalPreparation.MapError<
                DesignConversionTrainingIntakeRunResult>();
        }
        if (externalPreparation.Value is not { } preparedExternal)
        {
            return OperationResult<DesignConversionTrainingIntakeRunResult>.Fail(
                "An admitted DesignConversion teacher corpus requires an atomic external transaction.",
                DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
        }

        _runTrainingIntakeRunnerInvokedObserverForTesting?.Invoke();
        var externalRunner = await trainingRunner
            .RunPreparedAdmittedCorpusExternalConsumptionAsync(
                _legalTeacherAdmissionAuthority!,
                new DesignConversionMachine(),
                corpus.Value,
                preparedRunner.Value,
                preparedExternal.Transaction,
                ct);
        if (!externalRunner.IsSuccess || externalRunner.Value is null)
        {
            return externalRunner.MapError<
                DesignConversionTrainingIntakeRunResult>();
        }

        var committedIdentity =
            ValidateCommittedDualTargetTeacherExternalConsumption(
                preparedExternal,
                externalRunner.Value.ExternalConsumption);
        if (!committedIdentity.IsSuccess || committedIdentity.Value is not true)
        {
            return committedIdentity.IsSuccess
                ? OperationResult<DesignConversionTrainingIntakeRunResult>.Fail(
                    "The committed external DesignConversion DPO group identity is invalid.",
                    LegalTrainingTeacherAdmissionAuthority
                        .TrainingContentInvalidErrorCode)
                : committedIdentity.MapError<
                    DesignConversionTrainingIntakeRunResult>();
        }

        var corpusMetadata = new Dictionary<string, string>(
            metadataSnapshot,
            StringComparer.Ordinal)
        {
            ["corpus_admission_request_binding_sha256"] = requestBinding.Value,
            ["corpus_admission_receipt_sha256"] = request.Receipt.ReceiptSha256,
            ["corpus_admission_source_proof_sha256"] = issued.Value.SourceProofSha256,
            ["corpus_admission_reservation"] = "durable_fail_closed_before_mutation"
        };
        return await StoreRunTrainingIntakeIdempotencyResultAsync(
            BuildTrainingIntakeRunResult(
                intake,
                preflight,
                snapshotOptions,
                optionsProvided,
                snapshotRecords.Count,
                externalRunner.Value.Run,
                blockReasons: [],
                trainingExecutionBoundary: BuildTrainingExecutionBoundary(
                    externalRunner.Value.Run)),
            intake,
            snapshotOptions,
            corpusMetadata,
            CancellationToken.None,
            snapshotRecords);
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>>
        RunAdmittedCorpusTrainingIntakeAndPromoteLocalAsync(
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingIntakePreflightResult preflight,
            IReadOnlyList<DesignConversionDpoTrainingRecord> snapshotRecords,
            DesignConversionTrainingPipelineOptions snapshotOptions,
            bool optionsProvided,
            string promotionOutputDirectory,
            IReadOnlyDictionary<string, string> metadataSnapshot,
            IReadOnlyList<DesignConversionCandidatePayloadCustodyStore.CommittedEvidence>
                custodyEvidenceSnapshot,
            DesignConversionDpoCorpusAdmissionRequest request,
            LocalPromotionOperationContext operationContext,
            CancellationToken ct)
    {
        var validation = await BuildLocalPromotionCorpusAdmissionValidationAsync(
            intake,
            preflight,
            snapshotRecords,
            snapshotOptions,
            metadataSnapshot,
            custodyEvidenceSnapshot,
            request,
            cachedResult: null,
            ct);
        if (!validation.IsSuccess || validation.Value is null)
        {
            return validation.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        // Неверные настройки сохранения обученной модели отклоняем до
        // расходования одноразового допуска и до изменения весов. Используем ту
        // же проверку, что и обычный путь, чтобы правила не разошлись.
        var bridgeOptions = DesignConversionDpoPolicyCheckpointBridge
            .ValidateOptions(snapshotOptions.DpoPolicyBridgeOptions);
        if (!bridgeOptions.IsSuccess)
        {
            return bridgeOptions.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var custodyCapability = DesignConversionCandidatePayloadCustodyStore
            .MintTrainingCapability(custodyEvidenceSnapshot);
        if (!custodyCapability.IsSuccess || custodyCapability.Value is null)
        {
            return custodyCapability.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var recoveredAdmittedCorpusReplay = false;
        var issued = IssueDpoCorpusAdmission(
            validation.Value.OrderedPair,
            custodyCapability.Value,
            request.Pair,
            request.Receipt,
            request.CanonicalSourceProof,
            request.ObservedAtUtc,
            validation.Value.RequestBindingSha256);
        if (!issued.IsSuccess || issued.Value is null)
        {
            if (!string.Equals(
                    issued.ErrorCode,
                    DesignConversionDpoCorpusAdmissionAuthority.ReplayErrorCode,
                    StringComparison.Ordinal))
            {
                return issued.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            var recovered = RecoverReservedDpoCorpusAdmission(
                validation.Value.OrderedPair,
                custodyCapability.Value,
                request.Pair,
                request.Receipt,
                request.CanonicalSourceProof,
                request.ObservedAtUtc,
                validation.Value.RequestBindingSha256);
            if (!recovered.IsSuccess || recovered.Value is null)
            {
                return recovered.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            issued = recovered;
            recoveredAdmittedCorpusReplay = true;
        }

        var corpus = new DesignConversionDpoDatasetBuilder()
            .BuildAdmittedCorpus(
                issued.Value,
                snapshotOptions);
        if (!corpus.IsSuccess || corpus.Value is null)
        {
            return corpus.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var trainingRunner = new DesignConversionTrainingRunner();
        var preparedRunner = trainingRunner.PrepareAdmittedCorpus(corpus.Value);
        if (!preparedRunner.IsSuccess || preparedRunner.Value is null)
        {
            return preparedRunner.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        ProjectedDualTargetTeacherExternalConsumption externalProjection;
        DesignConversionExternalConsumptionCommitEvidence
            committedExternalConsumption;
        if (recoveredAdmittedCorpusReplay)
        {
            var projectedExternal =
                ProjectDualTargetTeacherExternalConsumption(
                    preparedRunner.Value,
                    ct);
            if (!projectedExternal.IsSuccess)
            {
                return projectedExternal.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            if (projectedExternal.Value is not { } recoveredProjection)
            {
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                    .Fail(
                        "An admitted DesignConversion teacher corpus requires an atomic external transaction.",
                        DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
            }
            if (_trainingIntakeDpoPairStore is not FileDpoPairStore fileStore)
            {
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                    .Fail(
                        "External atomic DPO pair-group consumption is unavailable.",
                        "DPO_PAIR_EXTERNAL_CONSUMPTION_UNAVAILABLE");
            }

            var recoveredSnapshot =
                fileStore.ResolveCommittedExternalConsumptionSnapshot(
                    recoveredProjection.Receipt,
                    DesignConversionMachine.DomainTag,
                    recoveredProjection.Commitment.ParentContent,
                    recoveredProjection.Commitment.ParentProvenance,
                    DpoExternalConsumerKind
                        .DesignConversionDualTargetTeacherAggregate);
            if (!recoveredSnapshot.IsSuccess ||
                recoveredSnapshot.Value is null)
            {
                return recoveredSnapshot.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            var recoveredEvidence =
                MaterializeCommittedExternalConsumptionEvidence(
                    recoveredSnapshot.Value);
            if (!recoveredEvidence.IsSuccess ||
                recoveredEvidence.Value is null)
            {
                return recoveredEvidence.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            var committedIdentity =
                ValidateCommittedDualTargetTeacherExternalConsumption(
                    recoveredProjection,
                    recoveredSnapshot.Value,
                    recoveredEvidence.Value);
            if (!committedIdentity.IsSuccess ||
                committedIdentity.Value is not true)
            {
                return committedIdentity.IsSuccess
                    ? OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                        .Fail(
                            "The committed external DesignConversion DPO group identity is invalid.",
                            LegalTrainingTeacherAdmissionAuthority
                                .TrainingContentInvalidErrorCode)
                    : committedIdentity.MapError<
                        DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            externalProjection = recoveredProjection;
            committedExternalConsumption = recoveredEvidence.Value;
        }
        else
        {
            var externalPreparation =
                PrepareDualTargetTeacherExternalConsumptionBeforeRunner(
                    preparedRunner.Value,
                    ct);
            if (!externalPreparation.IsSuccess)
            {
                return externalPreparation.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            if (externalPreparation.Value is not { } preparedExternal)
            {
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                    .Fail(
                        "An admitted DesignConversion teacher corpus requires an atomic external transaction.",
                        DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
            }

            _runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting?.Invoke();
            _runTrainingIntakeRunnerInvokedObserverForTesting?.Invoke();
            var externalRunner = await trainingRunner
                .RunPreparedAdmittedCorpusExternalConsumptionAsync(
                    _legalTeacherAdmissionAuthority!,
                    new DesignConversionMachine(),
                    corpus.Value,
                    preparedRunner.Value,
                    preparedExternal.Transaction,
                    ct);
            if (!externalRunner.IsSuccess || externalRunner.Value is null)
            {
                return externalRunner.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            var committedIdentity =
                ValidateCommittedDualTargetTeacherExternalConsumption(
                    preparedExternal,
                    externalRunner.Value.ExternalConsumption);
            if (!committedIdentity.IsSuccess ||
                committedIdentity.Value is not true)
            {
                return committedIdentity.IsSuccess
                    ? OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                        .Fail(
                            "The committed external DesignConversion DPO group identity is invalid.",
                            LegalTrainingTeacherAdmissionAuthority
                                .TrainingContentInvalidErrorCode)
                    : committedIdentity.MapError<
                        DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            externalProjection = preparedExternal.Projection;
            committedExternalConsumption =
                externalRunner.Value.ExternalConsumption;
        }

        _runTrainingIntakeLocalPromotionAfterCommittedExternalIdentityValidationObserverForTesting
            ?.Invoke();
        if (ct.IsCancellationRequested)
            return DesignConversionDpoPromotedParentContinuation
                .Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>();

        var localPromotionRecords =
            ResolveAdmittedCorpusLocalPromotionRecords(
                corpus.Value,
                snapshotRecords);
        if (!localPromotionRecords.IsSuccess ||
            localPromotionRecords.Value is null)
        {
            return localPromotionRecords.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var localContinuationRunner =
            PrepareAdmittedCorpusLocalPromotionContinuationRunner(
                corpus.Value,
                localPromotionRecords.Value,
                preparedRunner.Value);
        if (!localContinuationRunner.IsSuccess ||
            localContinuationRunner.Value is null)
        {
            return localContinuationRunner.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        // Путь допущенного корпуса владеет ровно одним списанием квитанции и
        // ровно одной серверной транзакцией внешнего учителя. После её фиксации
        // локальный хвост продолжается на дочерних строках, выпущенных хранилищем
        // из долговечной группы, и не запускает допуск корпуса повторно.
        return await RunTrainingIntakeAndPromoteLocalCoreAsync(
            intake,
            preflight,
            snapshotOptions,
            optionsProvided,
            promotionOutputDirectory,
            validation.Value.BoundaryMetadata,
            request,
            ct,
            new AdmittedCorpusLocalPromotionContinuation(
                corpus.Value,
                localContinuationRunner.Value,
                externalProjection,
                committedExternalConsumption));
    }

    private static OperationResult<DesignConversionDpoCorpusAdmissionSnapshotBinding>
        ValidateCorpusAdmissionRequestMatchesSnapshot(
            IReadOnlyList<DesignConversionDpoTrainingRecord> snapshotRecords,
            DesignConversionDpoCorpusAdmissionRequest request)
    {
        var canonicalSourceProof = request?.CanonicalSourceProof;
        var trainRows = canonicalSourceProof?.TrainRows;
        var heldOutRows = canonicalSourceProof?.HeldOutRows;
        if (request?.Pair is null ||
            request.Receipt is null ||
            canonicalSourceProof is null ||
            trainRows is null ||
            heldOutRows is null ||
            trainRows.Any(static row => row is null) ||
            heldOutRows.Any(static row => row is null) ||
            trainRows.Any(static row => string.IsNullOrWhiteSpace(
                row.RecordIdentityHash)) ||
            heldOutRows.Any(static row => string.IsNullOrWhiteSpace(
                row.RecordIdentityHash)))
        {
            return OperationResult<DesignConversionDpoCorpusAdmissionSnapshotBinding>
                .Fail(
                    "A complete corpus admission request with a canonical source proof is required.",
                    DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
        }

        var snapshotByIdentity = snapshotRecords
            .GroupBy(
                DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash,
                StringComparer.Ordinal)
            .ToDictionary(
                static group => group.Key,
                static group => group.ToArray(),
                StringComparer.Ordinal);
        var proofRows = trainRows
            .Concat(heldOutRows)
            .ToArray();
        var proofHashes = proofRows
            .Select(static row => row.RecordIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        var snapshotHashes = snapshotRecords
            .Select(DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash)
            .ToHashSet(StringComparer.Ordinal);
        if (trainRows.Count != 2 ||
            heldOutRows.Count == 0 ||
            proofRows.Length != snapshotRecords.Count ||
            !proofHashes.SetEquals(snapshotHashes) ||
            snapshotByIdentity.Any(static item => item.Value.Length != 1))
        {
            return OperationResult<DesignConversionDpoCorpusAdmissionSnapshotBinding>
                .Fail(
                    "The live intake records do not match the canonical corpus split.",
                    DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
        }

        var orderedPair = trainRows
            .Select(row => snapshotByIdentity[row.RecordIdentityHash][0])
            .OrderBy(static record => string.Equals(
                    record.UnitId,
                    DesignConversionDpoUnits.CriticUnit,
                    StringComparison.Ordinal)
                ? 0
                : 1)
            .ToArray();
        if (!DesignConversionDpoDatasetBuilder.TryAuthorizeCanonicalSourceProof(
                canonicalSourceProof,
                orderedPair,
                out var sourceProofSha256))
        {
            return OperationResult<DesignConversionDpoCorpusAdmissionSnapshotBinding>
                .Fail(
                    "The exact independently-ranked aggregate and canonical source proof are required.",
                    DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
        }

        return OperationResult<DesignConversionDpoCorpusAdmissionSnapshotBinding>
            .Ok(new DesignConversionDpoCorpusAdmissionSnapshotBinding(
                orderedPair,
                sourceProofSha256));
    }

    private async Task<OperationResult<string>>
        BuildCorpusAdmissionRequestBindingAsync(
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingIntakePreflightResult preflight,
            DesignConversionTrainingPipelineOptions options,
            IReadOnlyDictionary<string, string> admissionBoundaryMetadata,
            IReadOnlyList<DesignConversionDpoTrainingRecord> records,
            IReadOnlyList<DesignConversionCandidatePayloadCustodyStore.CommittedEvidence>
                custodyEvidence,
            CancellationToken ct)
    {
        var durableRecords = await ReadRecordsCoreAsync(ct);
        if (!durableRecords.IsSuccess || durableRecords.Value is null)
            return durableRecords.MapError<string>();

        var stateStore = new JsonDesignConversionPostEvaluationStateStore(
            PostEvaluationStateRootDirectory);
        var durableBindings = new List<string>();
        foreach (var candidateRef in intake.CandidateRefs)
        {
            var matches = durableRecords.Value
                .Where(record => string.Equals(
                    record.RecordId,
                    candidateRef.LocalArtifactRecordId,
                    StringComparison.Ordinal))
                .ToArray();
            if (matches.Length != 1)
            {
                return OperationResult<string>.Fail(
                    "The live corpus intake artifact record is missing or ambiguous.",
                    DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
            }

            var stateRef = ReadMetadata(
                matches[0].Metadata,
                JsonDesignConversionPostEvaluationStateStore.StateRefMetadataKey);
            var state = await stateStore.ReadAsync(stateRef, ct);
            if (!state.IsSuccess || state.Value is null ||
                !string.Equals(
                    state.Value.PersistenceStatus,
                    JsonDesignConversionPostEvaluationStateStore.PersistenceCommitted,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    state.Value.ArtifactRecordId,
                    matches[0].RecordId,
                    StringComparison.Ordinal) ||
                state.Value.TrainingEligibilityDenied)
            {
                return OperationResult<string>.Fail(
                    "The live corpus intake eligibility state is not exactly committed.",
                    DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
            }

            durableBindings.Add(DesignConversionDpoGenerator.Sha256Ref(
                JsonSerializer.Serialize(matches[0])));
            durableBindings.Add(state.Value.StateRef);
            durableBindings.Add(state.Value.Version.ToString(CultureInfo.InvariantCulture));
            durableBindings.Add(state.Value.TrainingEligibilityDenied.ToString());
            durableBindings.Add(DesignConversionDpoGenerator.Sha256Ref(
                JsonSerializer.Serialize(candidateRef)));
        }

        var custodyBindings = custodyEvidence
            .SelectMany(static evidence => new[]
            {
                evidence.Commitment.TransactionId,
                evidence.Commitment.ManifestSha256,
                evidence.Commitment.BindingSetSha256,
                evidence.Commitment.AuthorityRecordId,
                evidence.Commitment.AuthorityFingerprintSha256,
                string.Join(",", evidence.Commitment.Bindings.Order(StringComparer.Ordinal))
            });
        return OperationResult<string>.Ok(
            DesignConversionDpoGenerator.Sha256Ref(string.Join(
                "|",
                new[]
                {
                    "design-conversion-dpo-corpus-real-intake-request-v1",
                    DesignConversionIndependentPreferenceEvidenceAssociation
                        .BuildArtifactRootBinding(this),
                    intake.IntakeId,
                    intake.IntakeRef,
                    intake.SourceHandoffArtifactId,
                    intake.SourceHandoffArtifactRef,
                    preflight.PreflightId,
                    preflight.SourceManifestStatus,
                    preflight.SourceDisjointStatus,
                    options.RunId,
                    DesignConversionDpoGenerator.Sha256Ref(
                        JsonSerializer.Serialize(options)),
                    DesignConversionDpoGenerator.Sha256Ref(JsonSerializer.Serialize(
                        admissionBoundaryMetadata.OrderBy(static item => item.Key,
                            StringComparer.Ordinal))),
                    DesignConversionDpoGenerator.Sha256Ref(string.Join(",",
                        records.Select(DesignConversionDpoDatasetBuilder
                                .ComputeRecordIdentityHash)
                            .Order(StringComparer.Ordinal)))
                }.Concat(durableBindings).Concat(custodyBindings))));
    }

    public Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>> RunTrainingIntakeAndPromoteLocalAsync(
        string intakeId,
        string promotionOutputDirectory,
        DesignConversionTrainingPipelineOptions? options = null,
        CancellationToken ct = default)
        => RunTrainingIntakeAndPromoteLocalCoreEntryAsync(
            intakeId,
            promotionOutputDirectory,
            options,
            corpusAdmissionRequest: null,
            ct);

    internal Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>>
        RunTrainingIntakeAndPromoteLocalWithCorpusAdmissionAsync(
            string intakeId,
            string promotionOutputDirectory,
            DesignConversionDpoCorpusAdmissionRequest corpusAdmissionRequest,
            DesignConversionTrainingPipelineOptions? options = null,
            CancellationToken ct = default)
    {
        if (corpusAdmissionRequest is null)
        {
            return Task.FromResult(
                OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                    .Fail(
                        "A live corpus admission request is required.",
                        DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode));
        }

        // Этот вход остаётся внутренним: он переносит запрос с подтверждением
        // допуска из процесса оценки в локальную публикацию и не расширяет
        // внешний JSON/API-контракт.
        return RunTrainingIntakeAndPromoteLocalCoreEntryAsync(
            intakeId,
            promotionOutputDirectory,
            options,
            corpusAdmissionRequest,
            ct);
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>>
        RunTrainingIntakeAndPromoteLocalCoreEntryAsync(
            string intakeId,
            string promotionOutputDirectory,
            DesignConversionTrainingPipelineOptions? options,
            DesignConversionDpoCorpusAdmissionRequest? corpusAdmissionRequest,
            CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>();
        if (string.IsNullOrWhiteSpace(promotionOutputDirectory))
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>.Fail(
                "DesignConversion local promotion requires an output directory.",
                "DESIGN_CONVERSION_LOCAL_PROMOTION_OUTPUT_DIRECTORY_REQUIRED");
        var intakeIdValidation = ValidateTrainingIntakePreflightId(intakeId);
        if (!intakeIdValidation.IsSuccess)
            return intakeIdValidation.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        DesignConversionTrainingPipelineOptions? providedOptionsSnapshot = null;
        if (options is not null)
        {
            var capturedOptions = DesignConversionTrainingPipeline.SnapshotOptions(options);
            if (!capturedOptions.IsSuccess || capturedOptions.Value is null)
            {
                return capturedOptions.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            providedOptionsSnapshot = capturedOptions.Value;
        }
        if (_legalTeacherAdmissionAuthority is null &&
            !Directory.Exists(_rootDirectory))
            return LegalTeacherConfigurationRequired<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        var admissionBoundaryMetadata =
            DesignConversionTrainingIntakeRouteAdmissionContext.Current;
        if (!HasPromoteLocalIdempotencyBoundary(admissionBoundaryMetadata))
        {
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>.Fail(
                "DesignConversion local promotion requires stable tenant and idempotency identity before mutation.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_STABLE_IDENTITY_REQUIRED");
        }
        var preflight = await RunTrainingIntakePreflightAsync(intakeId, ct);
        if (!preflight.IsSuccess)
            return preflight.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

        var intake = await FindQueuedTrainingIntakeAsync(intakeId, ct);
        if (!intake.IsSuccess)
            return intake.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

        var runOptions = providedOptionsSnapshot ??
            BuildDefaultTrainingIntakeRunOptions(intake.Value!);
        var corpusRequirement = await ValidatePromoteLocalReplayCorpusRequirementAsync(
            intake.Value!,
            preflight.Value!,
            runOptions,
            preflight.Value!.MayStartTraining,
            admissionBoundaryMetadata,
            corpusAdmissionRequest,
            cachedResult: null,
            ct);
        if (!corpusRequirement.IsSuccess)
        {
            return corpusRequirement.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var callerAdmissionMeasurementValidatedBeforeMutation = false;
        if (!File.Exists(Path.Combine(
                _rootDirectory,
                TrainingIntakeLocalPromotionFileName)))
        {
            var preMutationMeasurementAdmission =
                RequireCallerAdmissionMeasurement(runOptions);
            if (!preMutationMeasurementAdmission.IsSuccess)
            {
                return preMutationMeasurementAdmission.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            callerAdmissionMeasurementValidatedBeforeMutation = true;
        }

        var operationId = BuildPromoteLocalOperationId(admissionBoundaryMetadata!);
        var gateAcquired = false;
        DesignConversionDeterministicMutationLease? mutationLease = null;
        try
        {
            await WaitForObservedGateAsync(
                _recordsMutationContext.RunTrainingIntakeLocalPromotionGate,
                _runTrainingIntakeLocalPromotionGateWaitTaskObserverForTesting,
                () => gateAcquired = true,
                ct);

            if (_runTrainingIntakeLocalPromotionGateAcquiredCallbackForTesting is not null)
                await _runTrainingIntakeLocalPromotionGateAcquiredCallbackForTesting(ct);

            mutationLease =
                await AcquireTrainingIntakeLocalPromotionMutationLeaseAsync(ct);
            using var journalMutationLeaseBinding =
                _localPromotionJournalSet.BindMutationLease(mutationLease);
            try
            {
                var recoveredJournals =
                    await _localPromotionJournalSet.RecoverAsync(ct);
                if (!recoveredJournals.IsSuccess)
                {
                    return recoveredJournals.MapError<
                        DesignConversionTrainingIntakeLocalPromotionResult>();
                }
                var readOnlyReplay = await ResolvePromoteLocalReadOnlyReplayAsync(
                    intake.Value!,
                    preflight.Value!,
                    runOptions,
                    promotionOutputDirectory,
                    admissionBoundaryMetadata,
                    ct);
                if (!readOnlyReplay.IsSuccess)
                {
                    return readOnlyReplay.MapError<
                        DesignConversionTrainingIntakeLocalPromotionResult>();
                }
                if (readOnlyReplay.Value!.HasReplay)
                {
                    var replayCorpusRequirement =
                        await ValidatePromoteLocalReplayCorpusRequirementAsync(
                            intake.Value!,
                            preflight.Value!,
                            runOptions,
                            preflight.Value!.MayStartTraining,
                            admissionBoundaryMetadata,
                            corpusAdmissionRequest,
                            readOnlyReplay.Value.Result!,
                            ct);
                    if (!replayCorpusRequirement.IsSuccess)
                    {
                        return replayCorpusRequirement.MapError<
                            DesignConversionTrainingIntakeLocalPromotionResult>();
                    }
                    return OperationResult<
                        DesignConversionTrainingIntakeLocalPromotionResult>
                        .Ok(readOnlyReplay.Value.Result!);
                }

                if (!callerAdmissionMeasurementValidatedBeforeMutation)
                {
                    var measurementAdmission =
                        RequireCallerAdmissionMeasurement(runOptions);
                    if (!measurementAdmission.IsSuccess)
                    {
                        return measurementAdmission.MapError<
                            DesignConversionTrainingIntakeLocalPromotionResult>();
                    }
                }

                if (preflight.Value!.MayStartTraining)
                {
                    var freshOperationCapacity =
                        await RequireFreshPromoteLocalOperationCapacityBeforeEffectsAsync(
                            operationId,
                            ct);
                    if (!freshOperationCapacity.IsSuccess)
                    {
                        return freshOperationCapacity.MapError<
                            DesignConversionTrainingIntakeLocalPromotionResult>();
                    }
                }

                var result = await RunTrainingIntakeAndPromoteLocalCoreAsync(
                    intake.Value!,
                    preflight.Value!,
                    runOptions,
                    optionsProvided: options is not null,
                    promotionOutputDirectory,
                    admissionBoundaryMetadata,
                    corpusAdmissionRequest,
                    ct);
                if (result.IsSuccess ||
                    IsServerOwnedConfiguredRemotePromotionUploaderFailure(
                        result.ErrorCode) ||
                    string.Equals(
                        result.ErrorCode,
                        "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_IDEMPOTENCY_REPLAY_CONFLICT",
                        StringComparison.Ordinal))
                {
                    return result;
                }
                return await RecoverLocalPromotionAfterExceptionalExitAsync(
                    operationId,
                    result);
            }
            catch (OperationCanceledException) when (ct.IsCancellationRequested)
            {
                return await RecoverLocalPromotionAfterExceptionalExitAsync(
                    operationId,
                    Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>());
            }
            catch (Exception exception) when (exception is
                IOException or UnauthorizedAccessException or SecurityException)
            {
                return await RecoverLocalPromotionAfterExceptionalExitAsync(
                    operationId,
                    LocalArtifactDbWriteFailed<
                        DesignConversionTrainingIntakeLocalPromotionResult>());
            }
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException)
        {
            return LocalArtifactDbWriteFailed<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        finally
        {
            if (mutationLease is not null)
                await mutationLease.DisposeAsync();
            if (gateAcquired)
                _recordsMutationContext.RunTrainingIntakeLocalPromotionGate.Release();
        }
    }

    internal async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>>
        PersistServerOwnedLocalPromotionAuthorityForTestingAsync(
            DesignConversionTrainingIntakeLocalPromotionResult result,
            string idempotencyKeyRef,
            CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>();
        if (result is null ||
            !result.LocalPromotionReady ||
            result.Publication is null ||
            result.PromotedLocalModel is null ||
            result.TrainingRun is null ||
            string.IsNullOrWhiteSpace(result.TrainingRun.RunId) ||
            string.IsNullOrWhiteSpace(result.PromotionOutputDirectory) ||
            string.IsNullOrWhiteSpace(idempotencyKeyRef))
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var tenantIdRef = ReadMetadata(
            result.BoundaryMetadata,
            "training_intake_tenant_id_ref");
        if (string.IsNullOrWhiteSpace(tenantIdRef))
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var admissionBoundaryMetadata =
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["training_intake_tenant_id_ref"] = tenantIdRef,
                ["training_intake_idempotency_key_ref"] = idempotencyKeyRef
            };
        var operationId = BuildPromoteLocalOperationId(admissionBoundaryMetadata);
        var uploaderAuthority = ResolvePromotionUploaderAuthorityPreflight(
            promotionMayStart: true);
        if (!uploaderAuthority.IsSuccess)
        {
            return uploaderAuthority.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var payloadSha256 = $"sha256:{HashText(string.Join("|",
        [
            "design-conversion-model-activation-test-promotion-authority-v1",
            tenantIdRef,
            idempotencyKeyRef,
            result.TrainingRun.RunId,
            result.Publication.Manifest.PromotionUploadRef ?? string.Empty,
            result.PromotedLocalModel.ModelId,
            result.PromotedLocalModel.CheckpointSha256
        ]))}";
        var pairStoreInputSha256s = Array.Empty<string>();
        var pairStoreInputsSha256 =
            BuildPairStoreInputsSha256(pairStoreInputSha256s);
        var pairStoreReservationId = $"{operationId}:dpo-pair-batch-v1";
        var pairStoreReservationSha256 = pairStoreInputsSha256;
        var canonicalPromotionOutputDirectory =
            Path.GetFullPath(result.PromotionOutputDirectory);
        var uploaderEnvelopeReservationSha256 = $"sha256:{HashText(string.Join("|",
        [
            "design-conversion-promotion-uploader-envelope-v1",
            uploaderAuthority.Value!.UploaderAuthorityMode,
            _promotionUploader?.GetType().FullName ?? "local-only",
            uploaderAuthority.Value.UploaderConfigurationFingerprintSha256,
            uploaderAuthority.Value.MaximumSerializedReceiptUtf8Bytes.ToString(
                CultureInfo.InvariantCulture),
            MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength
                .ToString(CultureInfo.InvariantCulture)
        ]))}";
        var outputNamespaceReservationRef =
            BuildLocalPromotionOutputReservationRef(operationId);
        var outputNamespaceReservationSha256 = $"sha256:{HashText(string.Join("|",
        [
            "design-conversion-local-promotion-output-namespace-reservation-v1",
            operationId,
            canonicalPromotionOutputDirectory,
            pairStoreReservationId,
            pairStoreReservationSha256,
            uploaderEnvelopeReservationSha256,
            uploaderAuthority.Value.UploaderAuthorityMode,
            uploaderAuthority.Value.UploaderConfigurationFingerprintSha256
        ]))}";

        var gateAcquired = false;
        DesignConversionDeterministicMutationLease? mutationLease = null;
        try
        {
            await _recordsMutationContext.RunTrainingIntakeLocalPromotionGate
                .WaitAsync(ct);
            gateAcquired = true;
            mutationLease =
                await AcquireTrainingIntakeLocalPromotionMutationLeaseAsync(ct);
            using var journalMutationLeaseBinding =
                _localPromotionJournalSet.BindMutationLease(mutationLease);
            var recoveredJournals =
                await _localPromotionJournalSet.RecoverAsync(ct);
            if (!recoveredJournals.IsSuccess)
                return recoveredJournals.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var capacity =
                await RequireFreshPromoteLocalOperationCapacityBeforeEffectsAsync(
                    operationId,
                    ct);
            if (!capacity.IsSuccess)
                return capacity.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var operationJournal = await ReadLocalPromotionOperationJournalAsync(ct);
            if (!operationJournal.IsSuccess)
                return operationJournal.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var operationState = ResolveLocalPromotionOperationState(
                operationJournal.Value!,
                operationId);
            if (operationState.Phase is not null)
            {
                return LocalPromotionOperationStateInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            var context = new LocalPromotionOperationContext(
                operationId,
                tenantIdRef,
                idempotencyKeyRef,
                payloadSha256,
                canonicalPromotionOutputDirectory,
                result.TrainingRun.RunId,
                pairStoreInputSha256s,
                pairStoreInputsSha256,
                pairStoreReservationId,
                pairStoreReservationSha256,
                outputNamespaceReservationRef,
                outputNamespaceReservationSha256,
                uploaderEnvelopeReservationSha256,
                uploaderAuthority.Value.UploaderAuthorityMode,
                uploaderAuthority.Value.UploaderConfigurationFingerprintSha256,
                operationState);
            var reservation =
                await PersistLocalPromotionOutputReservationForTestingAsync(
                    context,
                    ct);
            if (!reservation.IsSuccess)
                return reservation.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var activeState = await MarkLocalPromotionActiveStateAsync(
                result,
                ct);
            if (!activeState.IsSuccess)
                return activeState;

            var storedMetadata = new Dictionary<string, string>(
                activeState.Value!.BoundaryMetadata,
                StringComparer.Ordinal)
            {
                ["training_intake_idempotency_key_ref"] = idempotencyKeyRef,
                ["training_intake_promote_local_idempotency_payload_hash"] =
                    payloadSha256,
                ["training_intake_promote_local_operation_authority"] =
                    TrainingIntakeLocalPromotionOperationFileName,
                ["training_intake_promote_local_recorded_at_utc"] =
                    DateTimeOffset.UtcNow.ToString(
                        "O",
                        CultureInfo.InvariantCulture),
                ["training_intake_idempotency_replay_hit"] = bool.FalseString,
                ["training_intake_idempotency_created_new_side_effect"] =
                    bool.TrueString,
                ["training_intake_idempotent_replay_result"] =
                    bool.FalseString,
                ["training_intake_idempotency_side_effect_boundary"] =
                    "promote_local_fenced_operation_journal_then_legacy_projection",
                ["local_promotion_operation_id"] = operationId,
                ["local_promotion_pair_reservation_id"] =
                    pairStoreReservationId,
                ["local_promotion_pair_reservation_sha256"] =
                    pairStoreReservationSha256,
                ["local_promotion_output_namespace_reservation_ref"] =
                    outputNamespaceReservationRef,
                ["local_promotion_output_namespace_reservation_sha256"] =
                    outputNamespaceReservationSha256,
                ["local_promotion_uploader_envelope_reservation_sha256"] =
                    uploaderEnvelopeReservationSha256,
                ["local_promotion_uploader_authority_mode"] =
                    uploaderAuthority.Value.UploaderAuthorityMode,
                ["local_promotion_uploader_configuration_fingerprint_sha256"] =
                    uploaderAuthority.Value.UploaderConfigurationFingerprintSha256
            };
            var stored = activeState.Value with
            {
                BoundaryMetadata = storedMetadata
            };
            var snapshotSha256 = BuildLocalPromotionFinalResultSha256(stored);
            storedMetadata["local_promotion_committed_snapshot_sha256"] =
                snapshotSha256;
            stored = stored with { BoundaryMetadata = storedMetadata };

            if (!ValidateCycleAccuracyLineageContract(stored))
                return CycleAccuracyLineageInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var artifacts = await CaptureLocalPromotionOperationArtifactsAsync(
                stored,
                context.CanonicalPromotionOutputDirectory,
                context.RunId,
                ct);
            if (!artifacts.IsSuccess)
                return artifacts.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var prepare = await AppendLocalPromotionOperationRecordAsync(
                BuildLocalPromotionOperationRecord(
                    context,
                    LocalPromotionOperationPhase.Prepare,
                    DateTimeOffset.UtcNow),
                ct);
            if (!prepare.IsSuccess)
                return prepare.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var intent = await AppendLocalPromotionOperationRecordAsync(
                BuildLocalPromotionOperationRecord(
                    context,
                    LocalPromotionOperationPhase.Intent,
                    DateTimeOffset.UtcNow),
                ct);
            if (!intent.IsSuccess)
                return intent.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var prepared = await AppendLocalPromotionOperationRecordAsync(
                BuildLocalPromotionOperationRecord(
                    context,
                    LocalPromotionOperationPhase.Prepared,
                    DateTimeOffset.UtcNow,
                    artifacts.Value,
                    stored,
                    snapshotSha256),
                ct);
            if (!prepared.IsSuccess)
                return prepared.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var validated = await ValidatePreparedLocalPromotionOperationAsync(
                prepared.Value!,
                ct);
            if (!validated.IsSuccess)
                return validated.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            var projectionPrefix =
                await ReadLocalPromotionProjectionLogicalPrefixAsync(ct);
            if (!projectionPrefix.IsSuccess)
            {
                return projectionPrefix.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            var committedRecord = BuildLocalPromotionOperationRecord(
                context,
                LocalPromotionOperationPhase.Committed,
                DateTimeOffset.UtcNow,
                finalResultSha256: snapshotSha256) with
            {
                ProjectionLogicalPrefixCount = projectionPrefix.Value!.Count,
                ProjectionLogicalPrefixSha256 = projectionPrefix.Value.Sha256
            };
            var committed = await AppendLocalPromotionOperationRecordAsync(
                committedRecord,
                ct);
            if (!committed.IsSuccess)
                return committed.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

            var projection = await RepairCommittedLocalPromotionProjectionAsync(
                prepared.Value!,
                ct);
            return projection.IsSuccess
                ? OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                    .Ok(stored)
                : projection.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException)
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        finally
        {
            if (mutationLease is not null)
                await mutationLease.DisposeAsync();
            if (gateAcquired)
                _recordsMutationContext.RunTrainingIntakeLocalPromotionGate
                    .Release();
        }
    }

    private async Task<OperationResult<bool>>
        PersistLocalPromotionOutputReservationForTestingAsync(
            LocalPromotionOperationContext context,
            CancellationToken ct)
    {
        try
        {
            var reservation = new LocalPromotionOutputNamespaceReservation(
                TrainingIntakeLocalPromotionOutputReservationSchemaVersion,
                1,
                context.OperationId,
                context.CanonicalPromotionOutputDirectory,
                context.PairStoreReservationId,
                context.PairStoreReservationSha256,
                context.UploaderEnvelopeReservationSha256,
                context.UploaderAuthorityMode,
                context.UploaderConfigurationFingerprintSha256,
                context.OutputNamespaceReservationSha256);
            var bytes = JsonSerializer.SerializeToUtf8Bytes(
                reservation,
                JsonOptions);
            if (bytes.Length > 64 * 1024)
                return LocalPromotionOperationStateInvalid<bool>();

            var parent = Path.GetDirectoryName(
                context.OutputNamespaceReservationRef);
            var leaf = Path.GetFileName(context.OutputNamespaceReservationRef);
            if (string.IsNullOrWhiteSpace(parent) ||
                string.IsNullOrWhiteSpace(leaf))
            {
                return LocalPromotionOperationStateInvalid<bool>();
            }

            using var directory =
                DesignConversionHandleBoundDirectory.AcquireOrCreate(
                    parent,
                    beforeIo: null);
            await using var existing = directory.TryOpenExistingReadOnly(leaf);
            if (existing is not null)
            {
                if (existing.Length != bytes.Length)
                    return LocalPromotionOperationStateInvalid<bool>();

                var retained = new byte[bytes.Length];
                await existing.ReadExactlyAsync(retained, ct);
                return retained.AsSpan().SequenceEqual(bytes)
                    ? OperationResult<bool>.Ok(true)
                    : LocalPromotionOperationStateInvalid<bool>();
            }

            await using (var created = directory.CreateNew(
                             leaf,
                             FileShare.Read,
                             writeThrough: true))
            {
                await created.WriteAsync(bytes, ct);
                await created.FlushAsync(ct);
                created.Flush(flushToDisk: true);
            }

            await using var readback = directory.TryOpenExistingReadOnly(leaf);
            if (readback is null || readback.Length != bytes.Length)
                return LocalPromotionOperationStateInvalid<bool>();

            var retainedReadback = new byte[bytes.Length];
            await readback.ReadExactlyAsync(retainedReadback, ct);
            return retainedReadback.AsSpan().SequenceEqual(bytes)
                ? OperationResult<bool>.Ok(true)
                : LocalPromotionOperationStateInvalid<bool>();
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException or
            PlatformNotSupportedException or JsonException or NotSupportedException)
        {
            return LocalPromotionOperationStateInvalid<bool>();
        }
    }

    private async Task<OperationResult<
        DesignConversionTrainingIntakeLocalPromotionReplayResolution>>
        ResolvePromoteLocalReadOnlyReplayAsync(
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingIntakePreflightResult preflight,
            DesignConversionTrainingPipelineOptions runOptions,
            string promotionOutputDirectory,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        CancellationToken ct)
    {
        var operationId = BuildPromoteLocalOperationId(admissionBoundaryMetadata!);
        var operationJournal = await ReadLocalPromotionOperationJournalAsync(ct);
        if (!operationJournal.IsSuccess)
        {
            return operationJournal.MapError<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
        }
        var operationState = ResolveLocalPromotionOperationState(
            operationJournal.Value!,
            operationId);

        if (!preflight.MayStartTraining &&
            operationState.Phase is null)
        {
            var operationlessLegacyReplay =
                await ResolveOperationlessPreflightBlockedLegacyPromoteLocalReplayAsync(
                    intake,
                    runOptions,
                    promotionOutputDirectory,
                    admissionBoundaryMetadata,
                    ct);
            if (!operationlessLegacyReplay.IsSuccess ||
                operationlessLegacyReplay.Value!.HasReplay)
            {
                return operationlessLegacyReplay;
            }
        }

        var uploaderAuthorityPreflight =
            ResolvePromotionUploaderAuthorityPreflight(preflight.MayStartTraining);
        if (!uploaderAuthorityPreflight.IsSuccess)
        {
            return uploaderAuthorityPreflight.MapError<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
        }
        var payloadSha256 = BuildPromoteLocalIdempotencyPayloadHash(
            intake,
            runOptions,
            promotionOutputDirectory,
            uploaderAuthorityPreflight.Value!);
        var effectiveRunId = string.IsNullOrWhiteSpace(runOptions.RunId)
            ? BuildTrainingIntakeRunId(intake)
            : runOptions.RunId;
        var firstOperationRecord = operationState.Prepare ??
                                   operationState.Intent ??
                                   operationState.Prepared ??
                                   operationState.Committed;
        if (firstOperationRecord is not null &&
            !LocalPromotionUploaderAuthorityMatches(
                firstOperationRecord.UploaderAuthorityMode,
                firstOperationRecord.UploaderConfigurationFingerprintSha256,
                uploaderAuthorityPreflight.Value!))
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
        }
        if (firstOperationRecord is not null &&
            (!string.Equals(
                 firstOperationRecord.TenantIdRef,
                 ReadMetadata(
                     admissionBoundaryMetadata,
                     "training_intake_tenant_id_ref"),
                 StringComparison.Ordinal) ||
             !string.Equals(
                 firstOperationRecord.IdempotencyKeyRef,
                 ReadMetadata(
                     admissionBoundaryMetadata,
                     "training_intake_idempotency_key_ref"),
                 StringComparison.Ordinal) ||
             !string.Equals(
                 firstOperationRecord.PayloadSha256,
                 payloadSha256,
                 StringComparison.Ordinal) ||
             !string.Equals(
                 firstOperationRecord.RunId,
                 effectiveRunId,
                 StringComparison.Ordinal)))
        {
            return OperationResult<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>
                .Fail(
                    "DesignConversion training intake promote-local idempotency key was replayed with a different intake, options, or promotion payload.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_IDEMPOTENCY_REPLAY_CONFLICT");
        }

        if (operationState.Phase == LocalPromotionOperationPhase.Prepare &&
            !preflight.MayStartTraining)
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
        }
        if (operationState.Phase == LocalPromotionOperationPhase.Intent)
        {
            return LocalPromotionOperationIndeterminate<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
        }
        if (operationState.Phase == LocalPromotionOperationPhase.Committed)
        {
            var legacy = await ReadTrainingIntakeLocalPromotionRecordsAsync(ct);
            if (!legacy.IsSuccess)
            {
                return legacy.MapError<
                    DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
            }
            if (operationState.Prepared?.FinalResult is not null &&
                HasValidCommittedLocalPromotionProjection(
                    operationState.Prepared,
                    legacy.Value!
                        .Select(entry => entry.Record)
                        .ToArray()))
            {
                var projectedAuthority =
                    await ValidateCommittedProjectedLocalPromotionOperationAsync(
                        operationState.Prepared,
                        ct);
                if (!projectedAuthority.IsSuccess)
                {
                    return projectedAuthority.MapError<
                        DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
                }
                var projectedReplay = ResolvePromoteLocalIdempotencyReplay(
                    [operationState.Prepared.FinalResult],
                    intake,
                    runOptions,
                    promotionOutputDirectory,
                    admissionBoundaryMetadata,
                    uploaderAuthorityPreflight.Value!,
                    payloadSha256);
                if (!projectedReplay.IsSuccess || projectedReplay.Value!.HasReplay)
                    return projectedReplay;
            }

            var validated = await ValidatePreparedLocalPromotionOperationAsync(
                operationState.Prepared!,
                ct);
            if (!validated.IsSuccess)
            {
                return validated.MapError<
                    DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
            }
            var repaired = await RepairCommittedLocalPromotionProjectionAsync(
                operationState.Prepared!,
                ct);
            if (!repaired.IsSuccess)
            {
                return repaired.MapError<
                    DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
            }
            return ResolvePromoteLocalIdempotencyReplay(
                [validated.Value!],
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                uploaderAuthorityPreflight.Value!,
                payloadSha256);
        }

        var journal = await ReadMergedTrainingIntakeLocalPromotionRecordsAsync(
            operationJournal.Value!,
            ct);
        if (!journal.IsSuccess)
        {
            if (operationState.Phase is null &&
                string.Equals(
                    journal.ErrorCode,
                    "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                    StringComparison.Ordinal))
            {
                return DesignConversionDpoPromotedParentContinuation
                    .StateInvalid<
                        DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
            }
            return journal.MapError<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
        }
        return ResolvePromoteLocalIdempotencyReplay(
            journal.Value!,
            intake,
            runOptions,
            promotionOutputDirectory,
            admissionBoundaryMetadata,
            uploaderAuthorityPreflight.Value!,
            payloadSha256);
    }

    private async Task<OperationResult<
        DesignConversionTrainingIntakeLocalPromotionResult>>
        RecoverLocalPromotionAfterExceptionalExitAsync(
            string operationId,
            OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                originalFailure)
    {
        var journal = await ReadLocalPromotionOperationJournalAsync(
            CancellationToken.None);
        if (!journal.IsSuccess)
        {
            return journal.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var state = ResolveLocalPromotionOperationState(
            journal.Value!,
            operationId);
        var firstRecord = state.Prepare ?? state.Intent ?? state.Prepared ??
                          state.Committed;
        if (firstRecord is not null)
        {
            var authorityPreflight =
                ResolvePromotionUploaderAuthorityPreflight(
                    promotionMayStart: true);
            if (!authorityPreflight.IsSuccess)
            {
                return authorityPreflight.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            if (!LocalPromotionUploaderAuthorityMatches(
                    firstRecord.UploaderAuthorityMode,
                    firstRecord.UploaderConfigurationFingerprintSha256,
                    authorityPreflight.Value!))
            {
                return LocalPromotionOperationStateInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
        }
        if (state.Phase is null or LocalPromotionOperationPhase.Prepare)
            return originalFailure;
        if (state.Phase == LocalPromotionOperationPhase.Intent)
        {
            return LocalPromotionOperationIndeterminate<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        if (state.Phase == LocalPromotionOperationPhase.Prepared)
        {
            var committed = await CommitPreparedLocalPromotionOperationAsync(
                state.Prepared!,
                CancellationToken.None);
            return committed.IsSuccess
                ? OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                    .Ok(MarkPromoteLocalOperationReplay(committed.Value!))
                : committed;
        }

        var validated = await ValidatePreparedLocalPromotionOperationAsync(
            state.Prepared!,
            CancellationToken.None);
        if (!validated.IsSuccess)
            return validated;
        if (string.Equals(
                originalFailure.ErrorCode,
                LocalArtifactDbWriteFailedErrorCode,
                StringComparison.Ordinal))
        {
            return originalFailure;
        }
        var repaired = await RepairCommittedLocalPromotionProjectionAsync(
            state.Prepared!,
            CancellationToken.None);
        return repaired.IsSuccess
            ? OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                .Ok(MarkPromoteLocalOperationReplay(validated.Value!))
            : repaired.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
    }

    private async Task<OperationResult<bool>>
        ValidatePromoteLocalReplayCorpusRequirementAsync(
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingIntakePreflightResult preflight,
            DesignConversionTrainingPipelineOptions runOptions,
            bool mayStartTraining,
            IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
            DesignConversionDpoCorpusAdmissionRequest? corpusAdmissionRequest,
            DesignConversionTrainingIntakeLocalPromotionResult? cachedResult,
            CancellationToken ct)
    {
        var resolved = await ResolveTrainingIntakeRecordsAsync(intake, ct);
        if (!resolved.IsSuccess)
            return resolved.MapError<bool>();

        var recordsSnapshot = DesignConversionTrainingPipeline.SnapshotTrainingRecords(
            resolved.Value!.Records);
        if (!recordsSnapshot.IsSuccess)
            return recordsSnapshot.MapError<bool>();

        var optionsSnapshot = DesignConversionTrainingPipeline.SnapshotOptions(runOptions);
        if (!optionsSnapshot.IsSuccess)
            return optionsSnapshot.MapError<bool>();

        var snapshotRecords = recordsSnapshot.Value!;
        var snapshotOptions = optionsSnapshot.Value!;
        var requiresCorpusAdmission = mayStartTraining &&
            DesignConversionDpoCorpusAdmissionRequirementPolicy.RequiresAdmission(
                snapshotRecords);
        if (requiresCorpusAdmission)
        {
            if (corpusAdmissionRequest is null)
                return DpoCorpusAdmissionRequired<bool>();

            // Повторный запрос можно вернуть только после проверки текущих
            // записей, доказательства происхождения и подтверждения
            // независимого сравнения. Один совпавший SHA в подменённом
            // внутреннем запросе не считается полномочием.
            var validation = await BuildLocalPromotionCorpusAdmissionValidationAsync(
                intake,
                preflight,
                snapshotRecords,
                snapshotOptions,
                admissionBoundaryMetadata,
                resolved.Value!.CustodyEvidence.ToArray(),
                corpusAdmissionRequest,
                cachedResult,
                ct);
            if (!validation.IsSuccess)
                return validation.MapError<bool>();
        }
        else if (mayStartTraining && corpusAdmissionRequest is not null)
        {
            return OperationResult<bool>.Fail(
                "A corpus admission request can be used only with an intake that currently requires corpus admission.",
                DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
        }

        if (mayStartTraining && _legalTeacherAdmissionAuthority is null)
            return LegalTeacherConfigurationRequired<bool>();

        return OperationResult<bool>.Ok(true);
    }

    private async Task<OperationResult<DesignConversionLocalPromotionCorpusAdmissionValidation>>
        BuildLocalPromotionCorpusAdmissionValidationAsync(
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingIntakePreflightResult preflight,
            IReadOnlyList<DesignConversionDpoTrainingRecord> snapshotRecords,
            DesignConversionTrainingPipelineOptions snapshotOptions,
            IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
            IReadOnlyList<DesignConversionCandidatePayloadCustodyStore.CommittedEvidence>
                custodyEvidenceSnapshot,
            DesignConversionDpoCorpusAdmissionRequest request,
            DesignConversionTrainingIntakeLocalPromotionResult? cachedResult,
            CancellationToken ct)
    {
        var boundaryMetadata = admissionBoundaryMetadata is null
            ? new Dictionary<string, string>(StringComparer.Ordinal)
            : new Dictionary<string, string>(
                admissionBoundaryMetadata,
                StringComparer.Ordinal);
        AddCurrentPromoteLocalReplaySnapshotMetadata(
            boundaryMetadata,
            snapshotRecords,
            snapshotOptions);

        var requestSnapshot = ValidateCorpusAdmissionRequestMatchesSnapshot(
            snapshotRecords,
            request);
        if (!requestSnapshot.IsSuccess || requestSnapshot.Value is null)
        {
            return requestSnapshot.MapError<
                DesignConversionLocalPromotionCorpusAdmissionValidation>();
        }

        var runtimeEvidence = ValidateCorpusAdmissionRequestRuntimeEvidence(
            requestSnapshot.Value,
            request);
        if (!runtimeEvidence.IsSuccess)
        {
            return runtimeEvidence.MapError<
                DesignConversionLocalPromotionCorpusAdmissionValidation>();
        }

        var requestBinding = await BuildCorpusAdmissionRequestBindingAsync(
            intake,
            preflight,
            snapshotOptions,
            boundaryMetadata,
            snapshotRecords,
            custodyEvidenceSnapshot,
            ct);
        if (!requestBinding.IsSuccess || requestBinding.Value is null)
        {
            return requestBinding.MapError<
                DesignConversionLocalPromotionCorpusAdmissionValidation>();
        }

        boundaryMetadata["corpus_admission_request_binding_sha256"] =
            requestBinding.Value;
        boundaryMetadata["corpus_admission_receipt_sha256"] =
            request.Receipt.ReceiptSha256;
        boundaryMetadata["corpus_admission_source_proof_sha256"] =
            requestSnapshot.Value.SourceProofSha256;
        boundaryMetadata["corpus_admission_reservation"] =
            "durable_fail_closed_before_mutation";

        if (cachedResult is not null &&
            (!CachedRunReplayMetadataExactlyMatches(
                    cachedResult.BoundaryMetadata,
                    "training_intake_promote_local_current_records_snapshot_sha256",
                    boundaryMetadata[
                        "training_intake_promote_local_current_records_snapshot_sha256"]) ||
             !CachedRunReplayMetadataExactlyMatches(
                    cachedResult.BoundaryMetadata,
                    "training_intake_promote_local_current_options_snapshot_sha256",
                    boundaryMetadata[
                        "training_intake_promote_local_current_options_snapshot_sha256"]) ||
             !CachedRunReplayMetadataExactlyMatches(
                    cachedResult.BoundaryMetadata,
                    "corpus_admission_request_binding_sha256",
                    requestBinding.Value) ||
             !CachedRunReplayMetadataExactlyMatches(
                    cachedResult.BoundaryMetadata,
                    "corpus_admission_receipt_sha256",
                    request.Receipt.ReceiptSha256) ||
             !CachedRunReplayMetadataExactlyMatches(
                    cachedResult.BoundaryMetadata,
                    "corpus_admission_source_proof_sha256",
                    requestSnapshot.Value.SourceProofSha256)))
        {
            return OperationResult<DesignConversionLocalPromotionCorpusAdmissionValidation>
                .Fail(
                    "DesignConversion local promotion replay does not match the current corpus admission authority.",
                    DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
        }

        return OperationResult<DesignConversionLocalPromotionCorpusAdmissionValidation>
            .Ok(new DesignConversionLocalPromotionCorpusAdmissionValidation(
                requestSnapshot.Value.OrderedPair,
                requestBinding.Value,
                requestSnapshot.Value.SourceProofSha256,
                boundaryMetadata));
    }

    private OperationResult<bool> ValidateCorpusAdmissionRequestRuntimeEvidence(
        DesignConversionDpoCorpusAdmissionSnapshotBinding snapshot,
        DesignConversionDpoCorpusAdmissionRequest request)
    {
        var artifactRootBinding = DesignConversionIndependentPreferenceEvidenceAssociation
            .BuildArtifactRootBinding(this);
        if (!DesignConversionDpoGenerator
                .TryValidateIndependentPreferenceEvidenceForRuntime(
                    request.Pair,
                    request.Receipt,
                    artifactRootBinding,
                    request.ObservedAtUtc,
                    out _) ||
            !HasExactCorpusAdmissionPairBinding(
                snapshot.OrderedPair[0],
                snapshot.OrderedPair[1],
                request.Pair,
                request.Receipt))
        {
            return OperationResult<bool>.Fail(
                "The exact independently-ranked aggregate and preference receipt are required.",
                DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
        }

        return OperationResult<bool>.Ok(true);
    }

    private static bool HasExactCorpusAdmissionPairBinding(
        DesignConversionDpoTrainingRecord critic,
        DesignConversionDpoTrainingRecord improver,
        DesignConversionTeacherAuthoredEvaluationPair pair,
        DesignConversionIndependentPreferenceEvidence receipt)
    {
        var criticItem = DesignConversionTrainingPipeline.ToCanonicalTrainingItem(critic);
        var improverItem = DesignConversionTrainingPipeline.ToCanonicalTrainingItem(improver);
        if (!string.Equals(criticItem.ChosenResponse, improverItem.ChosenResponse, StringComparison.Ordinal) ||
            !string.Equals(criticItem.RejectedResponse, improverItem.RejectedResponse, StringComparison.Ordinal))
            return false;

        foreach (var record in new[] { critic, improver })
        {
            var metadata = record.Provenance.Metadata;
            if (!string.Equals(ReadMetadata(metadata, "teacher_authoring_output_hash"),
                    pair.AuthoringEvidence.OutputHash, StringComparison.Ordinal) ||
                !string.Equals(ReadMetadata(metadata, "teacher_authoring_incumbent_ref"),
                    pair.AuthoringEvidence.IncumbentRef, StringComparison.Ordinal) ||
                !string.Equals(ReadMetadata(metadata, "teacher_authoring_generated_ref"),
                    pair.AuthoringEvidence.GeneratedRef, StringComparison.Ordinal) ||
                !string.Equals(ReadMetadata(metadata, "independent_preference_generated_evaluation_identity"),
                    receipt.GeneratedEvaluationIdentity, StringComparison.Ordinal) ||
                !string.Equals(ReadMetadata(metadata, "independent_preference_incumbent_evaluation_identity"),
                    receipt.IncumbentEvaluationIdentity, StringComparison.Ordinal) ||
                !string.Equals(ReadMetadata(metadata, "independent_preference_artifact_root_binding"),
                    receipt.ArtifactRootBinding, StringComparison.Ordinal))
            {
                return false;
            }
        }

        return true;
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>> RunTrainingIntakeAndPromoteLocalCoreAsync(
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingIntakePreflightResult preflight,
        DesignConversionTrainingPipelineOptions runOptions,
        bool optionsProvided,
        string promotionOutputDirectory,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        DesignConversionDpoCorpusAdmissionRequest? corpusAdmissionRequest,
        CancellationToken ct,
        AdmittedCorpusLocalPromotionContinuation?
            admittedCorpusContinuation = null)
    {
        var stableAdmissionMetadata = admissionBoundaryMetadata!;
        var operationId = BuildPromoteLocalOperationId(stableAdmissionMetadata);
        var canonicalRequestedOutputDirectory =
            NormalizePromotionOutputDirectoryForIdempotency(
                promotionOutputDirectory);
        var effectiveRunId = string.IsNullOrWhiteSpace(runOptions.RunId)
            ? BuildTrainingIntakeRunId(intake)
            : runOptions.RunId;
        var operationJournal = await ReadLocalPromotionOperationJournalAsync(ct);
        if (!operationJournal.IsSuccess)
            return operationJournal.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        var operationState = ResolveLocalPromotionOperationState(
            operationJournal.Value!,
            operationId);
        var firstOperationRecord = operationState.Prepare ?? operationState.Intent ??
                                   operationState.Prepared ?? operationState.Committed;
        var uploaderAuthorityPreflight =
            ResolvePromotionUploaderAuthorityPreflight(preflight.MayStartTraining);
        if (!uploaderAuthorityPreflight.IsSuccess)
        {
            return uploaderAuthorityPreflight.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var payloadSha256 = BuildPromoteLocalIdempotencyPayloadHash(
            intake,
            runOptions,
            promotionOutputDirectory,
            uploaderAuthorityPreflight.Value!);
        if (firstOperationRecord is not null &&
            !LocalPromotionUploaderAuthorityMatches(
                firstOperationRecord.UploaderAuthorityMode,
                firstOperationRecord.UploaderConfigurationFingerprintSha256,
                uploaderAuthorityPreflight.Value!))
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        if (firstOperationRecord is not null &&
            (!string.Equals(
                 firstOperationRecord.TenantIdRef,
                 ReadMetadata(stableAdmissionMetadata, "training_intake_tenant_id_ref"),
                 StringComparison.Ordinal) ||
             !string.Equals(
                 firstOperationRecord.IdempotencyKeyRef,
                 ReadMetadata(stableAdmissionMetadata, "training_intake_idempotency_key_ref"),
                 StringComparison.Ordinal) ||
             !string.Equals(
                 firstOperationRecord.PayloadSha256,
                 payloadSha256,
                 StringComparison.Ordinal) ||
             !string.Equals(firstOperationRecord.RunId, effectiveRunId, StringComparison.Ordinal)))
        {
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>.Fail(
                "DesignConversion training intake promote-local idempotency key was replayed with a different intake, options, or promotion payload.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_IDEMPOTENCY_REPLAY_CONFLICT");
        }
        if (operationState.Phase == LocalPromotionOperationPhase.Intent)
        {
            return LocalPromotionOperationIndeterminate<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        if (operationState.Phase == LocalPromotionOperationPhase.Prepared)
        {
            var committed = await CommitPreparedLocalPromotionOperationAsync(
                operationState.Prepared!,
                ct);
            if (!committed.IsSuccess)
                return committed;
            var replayCorpusRequirement =
                await ValidatePromoteLocalReplayCorpusRequirementAsync(
                    intake,
                    preflight,
                    runOptions,
                    preflight.MayStartTraining,
                    admissionBoundaryMetadata,
                    corpusAdmissionRequest,
                    committed.Value!,
                    ct);
            if (!replayCorpusRequirement.IsSuccess)
            {
                return replayCorpusRequirement.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                .Ok(MarkPromoteLocalOperationReplay(committed.Value!));
        }
        if (operationState.Phase == LocalPromotionOperationPhase.Committed)
        {
            var validated = await ValidatePreparedLocalPromotionOperationAsync(
                operationState.Prepared!,
                ct);
            if (!validated.IsSuccess)
                return validated;
            var repaired = await RepairCommittedLocalPromotionProjectionAsync(
                operationState.Prepared!,
                ct);
            if (!repaired.IsSuccess)
            {
                return repaired.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            var replayCorpusRequirement =
                await ValidatePromoteLocalReplayCorpusRequirementAsync(
                    intake,
                    preflight,
                    runOptions,
                    preflight.MayStartTraining,
                    admissionBoundaryMetadata,
                    corpusAdmissionRequest,
                    validated.Value!,
                    ct);
            if (!replayCorpusRequirement.IsSuccess)
            {
                return replayCorpusRequirement.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
                .Ok(MarkPromoteLocalOperationReplay(validated.Value!));
        }

        var journal = await ReadMergedTrainingIntakeLocalPromotionRecordsAsync(
            operationJournal.Value!,
            ct);
        if (!journal.IsSuccess)
        {
            if (string.Equals(journal.ErrorCode, "CANCELLED", StringComparison.Ordinal))
            {
                return DesignConversionDpoPromotedParentContinuation
                    .Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            return DesignConversionDpoPromotedParentContinuation
                .StateInvalid<DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var replay = ResolvePromoteLocalIdempotencyReplay(
            journal.Value!,
            intake,
            runOptions,
            promotionOutputDirectory,
            admissionBoundaryMetadata,
            uploaderAuthorityPreflight.Value!,
            payloadSha256);
        if (!replay.IsSuccess)
            return replay.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        if (replay.Value!.HasReplay)
        {
            var replayCorpusRequirement =
                await ValidatePromoteLocalReplayCorpusRequirementAsync(
                    intake,
                    preflight,
                    runOptions,
                    preflight.MayStartTraining,
                    admissionBoundaryMetadata,
                    corpusAdmissionRequest,
                    replay.Value.Result!,
                    ct);
            if (!replayCorpusRequirement.IsSuccess)
            {
                return replayCorpusRequirement.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>.Ok(
                replay.Value.Result!);
        }

        var measurementAdmission = RequireCallerAdmissionMeasurement(runOptions);
        if (!measurementAdmission.IsSuccess)
            return measurementAdmission.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();

        var reconciled = await ReconcileCommittedLocalPromotionProjectionsAsync(
            operationJournal.Value!,
            ct);
        if (!reconciled.IsSuccess)
            return reconciled.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();

        var operationContext = new LocalPromotionOperationContext(
            operationId,
            ReadMetadata(stableAdmissionMetadata, "training_intake_tenant_id_ref"),
            ReadMetadata(stableAdmissionMetadata, "training_intake_idempotency_key_ref"),
            payloadSha256,
            canonicalRequestedOutputDirectory,
            effectiveRunId,
            [],
            BuildPairStoreInputsSha256([]),
            string.Empty,
            string.Empty,
            string.Empty,
            string.Empty,
            string.Empty,
            uploaderAuthorityPreflight.Value!.UploaderAuthorityMode,
            uploaderAuthorityPreflight.Value!
                .UploaderConfigurationFingerprintSha256,
            operationState);

        var parentState = ResolveCurrentLocalPromotionActiveState(journal.Value!);
        if (parentState.Kind == DesignConversionLocalPromotionActiveStateKind.Invalid)
        {
            return DesignConversionDpoPromotedParentContinuation
                .StateInvalid<DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        DesignConversionDpoPromotedParentContinuationLease? retainedParent = null;
        if (parentState.Kind == DesignConversionLocalPromotionActiveStateKind.Active &&
            parentState.Active!.Anchors is not null)
        {
            var resolvedParent = await DesignConversionDpoPromotedParentContinuation
                .ResolveAsync(parentState.Active!, _rootDirectory, ct);
            if (!resolvedParent.IsSuccess)
            {
                return resolvedParent.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            retainedParent = resolvedParent.Value!;
        }
        using var retainedParentScope = retainedParent;

        if (!preflight.MayStartTraining)
        {
            var blockedRun = BuildTrainingIntakeRunResult(
                intake,
                preflight,
                runOptions,
                optionsProvided: optionsProvided,
                resolvedTrainingRecordCount: 0,
                runnerResult: null,
                blockReasons: preflight.BlockReasons,
                trainingExecutionBoundary: "blocked_before_runner_by_training_intake_preflight");

            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    blockedRun,
                    promotionOutputDirectory,
                    promotedCheckpointPath: string.Empty,
                    publication: null,
                    promotedLocalModel: null,
                    additionalBlockReasons: ["local_promotion_blocked_training_intake_preflight"],
                    additionalWarnings: ["local_promotion_not_attempted"],
                    additionalEvidenceRefs: ["DESIGN_CONVERSION_LOCAL_PROMOTION_BLOCKED_BEFORE_TRAINING_RUNNER"]),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        var resolved = await ResolveTrainingIntakeRecordsForFreshRunBoundaryAsync(
            intake,
            ct);
        if (!resolved.IsSuccess)
            return resolved.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

        if (resolved.Value!.BlockReasons.Count > 0)
        {
            var blockedRun = BuildTrainingIntakeRunResult(
                intake,
                preflight,
                runOptions,
                optionsProvided: optionsProvided,
                resolvedTrainingRecordCount: resolved.Value.Records.Count,
                runnerResult: null,
                blockReasons: resolved.Value.BlockReasons,
                trainingExecutionBoundary: "blocked_before_runner_by_training_intake_resolution");

            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    blockedRun,
                    promotionOutputDirectory,
                    promotedCheckpointPath: string.Empty,
                    publication: null,
                    promotedLocalModel: null,
                    additionalBlockReasons: ["local_promotion_blocked_training_intake_resolution"],
                    additionalWarnings: ["local_promotion_not_attempted"],
                    additionalEvidenceRefs: ["DESIGN_CONVERSION_LOCAL_PROMOTION_BLOCKED_BY_TRAINING_INTAKE_RESOLUTION"]),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        resolved = await ResolveTrainingIntakeRecordsForFreshRunBoundaryAsync(
            intake,
            ct);
        if (!resolved.IsSuccess)
            return resolved.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        if (resolved.Value!.BlockReasons.Count > 0)
        {
            var blockedRun = BuildTrainingIntakeRunResult(
                intake,
                preflight,
                runOptions,
                optionsProvided: optionsProvided,
                resolvedTrainingRecordCount: resolved.Value.Records.Count,
                runnerResult: null,
                blockReasons: resolved.Value.BlockReasons,
                trainingExecutionBoundary:
                "blocked_immediately_before_runner_by_post_evaluation_revalidation");
            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    blockedRun,
                    promotionOutputDirectory,
                    promotedCheckpointPath: string.Empty,
                    publication: null,
                    promotedLocalModel: null,
                    additionalBlockReasons:
                    ["local_promotion_blocked_post_evaluation_revalidation"],
                    additionalWarnings: ["local_promotion_not_attempted"],
                    additionalEvidenceRefs:
                    ["DESIGN_CONVERSION_LOCAL_PROMOTION_POST_EVALUATION_REVALIDATION_BLOCKED"]),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        var remainingOperationPhaseCount =
            operationState.Phase == LocalPromotionOperationPhase.Prepare ? 3 : 4;
        var aggregateQuota = await CanReserveAggregateLocalPromotionRecoveryAsync(
            operationJournal.Value!,
            operationId,
            remainingOperationPhaseCount,
            ct);
        if (!aggregateQuota.IsSuccess)
        {
            return aggregateQuota.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        if (!aggregateQuota.Value)
        {
            return LocalPromotionOperationQuotaExceeded<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var projectionQuota = await EnsureLocalPromotionProjectionCapacityAsync(
            MaxTrainingIntakeLocalPromotionJournalRowByteLength,
            ct);
        if (!projectionQuota.IsSuccess)
        {
            return projectionQuota.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        if (!projectionQuota.Value)
        {
            return TrainingIntakeLocalPromotionsQuotaExceeded<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var recordsSnapshot = DesignConversionTrainingPipeline.SnapshotTrainingRecords(
            resolved.Value.Records);
        if (!recordsSnapshot.IsSuccess)
            return recordsSnapshot.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        var optionsSnapshot = DesignConversionTrainingPipeline.SnapshotOptions(runOptions);
        if (!optionsSnapshot.IsSuccess)
            return optionsSnapshot.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        var metadataSnapshot = SnapshotAdmissionBoundaryMetadata(admissionBoundaryMetadata);
        var custodyEvidenceSnapshot = resolved.Value.CustodyEvidence.ToArray();
        if (_legalTeacherAdmissionAuthority is null)
            return LegalTeacherConfigurationRequired<DesignConversionTrainingIntakeLocalPromotionResult>();
        var snapshotRecords = recordsSnapshot.Value!;
        var snapshotOptions = optionsSnapshot.Value!;
        runOptions = snapshotOptions;
        admissionBoundaryMetadata = metadataSnapshot;
        OperationResult<IReadOnlyList<DesignConversionDpoTrainingRecord>>
            ResolveLocalPromotionRecordsForCurrentSnapshot(
                IReadOnlyList<DesignConversionDpoTrainingRecord>? records)
        {
            if (admittedCorpusContinuation is not { } continuation)
            {
                return records is null
                    ? DpoPolicyBridgeTrainPartitionInvalid<
                        IReadOnlyList<DesignConversionDpoTrainingRecord>>()
                    : OperationResult<
                        IReadOnlyList<DesignConversionDpoTrainingRecord>>.Ok(
                        records);
            }

            // Продолжение допущенного корпуса после фиксации внешней транзакции
            // заново проверяет live-снимок вызывающей стороны, затем собирает
            // точный вид для локальной публикации: допущенные производные
            // обучающие строки плюс текущие исходные строки экзамена.
            return ResolveAdmittedCorpusLocalPromotionRecords(
                continuation.Corpus,
                records);
        }

        if (DesignConversionDpoCorpusAdmissionRequirementPolicy.RequiresAdmission(
                snapshotRecords) &&
            admittedCorpusContinuation is null)
        {
            if (corpusAdmissionRequest is null)
            {
                return DpoCorpusAdmissionRequired<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            return await RunAdmittedCorpusTrainingIntakeAndPromoteLocalAsync(
                intake,
                preflight,
                snapshotRecords,
                snapshotOptions,
                optionsProvided,
                promotionOutputDirectory,
                metadataSnapshot ?? new Dictionary<string, string>(
                    StringComparer.Ordinal),
                custodyEvidenceSnapshot,
                corpusAdmissionRequest,
                operationContext,
                ct);
        }

        if (_dpoPolicyBaseProvider is null)
        {
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>.Fail(
                "DesignConversion DPO policy base provider is required.",
                "DESIGN_CONVERSION_DPO_POLICY_BASE_PROVIDER_REQUIRED");
        }

        var machine = new DesignConversionMachine();
        var trainingRunner = new DesignConversionTrainingRunner();
        var localPromotionRecords =
            ResolveLocalPromotionRecordsForCurrentSnapshot(snapshotRecords);
        if (!localPromotionRecords.IsSuccess ||
            localPromotionRecords.Value is null)
        {
            return localPromotionRecords.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var localPromotionResolvedRecords = localPromotionRecords.Value;
        OperationResult<DesignConversionPreparedTrainingRecordExecution>
            preparedRunner;
        if (admittedCorpusContinuation is { } admittedContinuation)
        {
            preparedRunner = OperationResult<
                DesignConversionPreparedTrainingRecordExecution>.Ok(
                    admittedContinuation.PreparedRunner);
        }
        else
        {
            preparedRunner = trainingRunner.PrepareTrainingRecords(
                snapshotRecords,
                runOptions,
                custodyEvidenceSnapshot);
        }
        if (!preparedRunner.IsSuccess || preparedRunner.Value is null)
        {
            return preparedRunner.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var pipelineFinalOptimizer =
            preparedRunner.Value.Pipeline.FinalOptimizer;
        if (pipelineFinalOptimizer is null)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var preparedPairs = PrepareFinalTrainingIntakeDpoPairs(
            preparedRunner.Value.Pipeline);
        if (!preparedPairs.IsSuccess || preparedPairs.Value is null)
        {
            return preparedPairs.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        DesignConversionExternalConsumptionCommitEvidence?
            committedExternalConsumption = null;
        DesignConversionDpoTrainingContentAuthority
            .DualTargetTeacherAggregateCommitment? committedExternalCommitment =
                null;
        ProjectedDualTargetTeacherExternalConsumption?
            committedExternalProjection = null;

        if (admittedCorpusContinuation is { } committedAdmitted)
        {
            committedExternalConsumption =
                committedAdmitted.ExternalConsumption;
            committedExternalCommitment =
                committedAdmitted.ExternalProjection.Commitment;
            committedExternalProjection =
                committedAdmitted.ExternalProjection;
        }
        else
        {
            var externalPreparation =
                PrepareDualTargetTeacherExternalConsumptionBeforeRunner(
                    preparedRunner.Value,
                    ct);
            if (!externalPreparation.IsSuccess)
            {
                return externalPreparation.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }
            if (externalPreparation.Value is { } preparedExternal)
            {
                _runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting?.Invoke();
                _runTrainingIntakeRunnerInvokedObserverForTesting?.Invoke();
                var externalRunner = await trainingRunner
                    .RunPreparedDualTargetTeacherExternalConsumptionAsync(
                        _legalTeacherAdmissionAuthority,
                        machine,
                        preparedRunner.Value,
                        preparedExternal.Transaction,
                        ct);
                if (!externalRunner.IsSuccess || externalRunner.Value is null)
                {
                    return externalRunner.MapError<
                        DesignConversionTrainingIntakeLocalPromotionResult>();
                }

                var committedIdentity =
                    ValidateCommittedDualTargetTeacherExternalConsumption(
                        preparedExternal,
                        externalRunner.Value.ExternalConsumption);
                if (!committedIdentity.IsSuccess ||
                    committedIdentity.Value is not true)
                {
                    return committedIdentity.IsSuccess
                        ? OperationResult<
                            DesignConversionTrainingIntakeLocalPromotionResult>.Fail(
                                "The committed external DesignConversion DPO group identity is invalid.",
                                LegalTrainingTeacherAdmissionAuthority
                                    .TrainingContentInvalidErrorCode)
                        : committedIdentity.MapError<
                            DesignConversionTrainingIntakeLocalPromotionResult>();
                }

                // После фиксации внешней транзакции нельзя повторно списывать
                // исходный запрос к учителю. Ниже мост получает новые дочерние
                // идентичности из долговечного доказательства и настоящий
                // закрытый payload из хранилища, а локальный запуск идёт уже на
                // этих дочерних записях.
                committedExternalConsumption =
                    externalRunner.Value.ExternalConsumption;
                committedExternalCommitment = preparedExternal.Commitment;
                committedExternalProjection = preparedExternal.Projection;
            }
        }

        var preparedPartition = ResolvePreparedDpoTrainPartition(
            preparedRunner.Value.Pipeline,
            localPromotionResolvedRecords,
            ct);
        if (!preparedPartition.IsSuccess || preparedPartition.Value is null)
        {
            return preparedPartition.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var bridgePreparationPartition = preparedPartition.Value;
        var promotionPipelineFinalOptimizer = pipelineFinalOptimizer;
        var promotionPairs = preparedPairs.Value;
        CommittedDualTargetTeacherPromotionMaterialization?
            committedExternalPromotion = null;
        if (committedExternalConsumption is not null)
        {
            var materializedPromotion =
                MaterializeCommittedDualTargetTeacherExternalPromotionInputs(
                    bridgePreparationPartition,
                    committedExternalCommitment,
                    committedExternalProjection?.Group,
                    committedExternalConsumption);
            if (!materializedPromotion.IsSuccess ||
                materializedPromotion.Value is null)
            {
                return OperationResult<
                    DesignConversionTrainingIntakeLocalPromotionResult>.Fail(
                    "materialize_committed_external_promotion_inputs: " +
                    materializedPromotion.ErrorMessage,
                    materializedPromotion.ErrorCode);
            }

            committedExternalPromotion = materializedPromotion.Value;
            var localContinuationRunner =
                PrepareCommittedDualTargetTeacherLocalContinuationRunner(
                    preparedRunner.Value,
                    committedExternalPromotion,
                    effectiveRunId);
            if (!localContinuationRunner.IsSuccess ||
                localContinuationRunner.Value is null ||
                localContinuationRunner.Value.Pipeline.FinalOptimizer is null)
            {
                return localContinuationRunner.IsSuccess
                    ? DpoPolicyBridgeTrainPartitionInvalid<
                        DesignConversionTrainingIntakeLocalPromotionResult>()
                    : OperationResult<
                        DesignConversionTrainingIntakeLocalPromotionResult>
                        .Fail(
                            "prepare_committed_external_local_continuation_runner: " +
                            localContinuationRunner.ErrorMessage,
                            localContinuationRunner.ErrorCode);
            }

            // Для локального продолжения после внешнего эталона runner получает
            // отдельную подготовку: train-пары уже store-minted child rows, а
            // held-out остаётся прежним, чтобы качество мерилось тем же экзаменом.
            var committedExternalLocalContinuationRunner =
                localContinuationRunner.Value;
            bridgePreparationPartition = committedExternalPromotion.Partition
                with
                {
                    // Упаковка моста получает те же материализованные строки
                    // передачи, которые были выведены из зафиксированного
                    // закрытого содержимого, а не строки из входного снимка
                    // вызывающей стороны.
                    TrainRecords =
                        committedExternalPromotion.TransferTrainRecords
                };
            promotionPipelineFinalOptimizer =
                committedExternalLocalContinuationRunner
                    .Pipeline.FinalOptimizer;
            promotionPairs = committedExternalPromotion.Pairs;
            preparedRunner = OperationResult<
                DesignConversionPreparedTrainingRecordExecution>.Ok(
                    committedExternalLocalContinuationRunner);
        }
        if (committedExternalPromotion is not null)
        {
            var transferSideContract =
                ValidateCommittedExternalTransferOptimizerSidesForBridge(
                    bridgePreparationPartition.TrainRecords);
            if (!transferSideContract.IsSuccess)
            {
                return OperationResult<
                    DesignConversionTrainingIntakeLocalPromotionResult>.Fail(
                    "pre_bridge_committed_transfer_side_contract: " +
                    transferSideContract.ErrorMessage,
                    transferSideContract.ErrorCode);
            }

            var heldOutSideContract =
                ValidateCommittedExternalTransferOptimizerSidesForBridge(
                    bridgePreparationPartition.HeldOutRecords);
            if (!heldOutSideContract.IsSuccess)
            {
                return OperationResult<
                    DesignConversionTrainingIntakeLocalPromotionResult>.Fail(
                    "pre_bridge_held_out_side_contract: " +
                    heldOutSideContract.ErrorMessage,
                    heldOutSideContract.ErrorCode);
            }
        }

        var preparedBridge = await DesignConversionDpoPolicyCheckpointBridge
            .PrepareEvaluatedCompositeExecutionAsync(
                _legalTeacherAdmissionAuthority,
                bridgePreparationPartition,
                _dpoPolicyBaseProvider,
                runOptions.DpoPolicyBridgeOptions,
                retainedParent?.Request,
                useContinuation: retainedParent is not null,
                ct,
                committedExternalTransferTrainRecords:
                    committedExternalPromotion?.TransferTrainRecords);
        if (!preparedBridge.IsSuccess || preparedBridge.Value is null)
        {
            return OperationResult<
                DesignConversionTrainingIntakeLocalPromotionResult>.Fail(
                "prepare_evaluated_composite_execution: " +
                preparedBridge.ErrorMessage,
                preparedBridge.ErrorCode);
        }
        var frozenPaths = ResolveTrainingIntakeLocalPromotionArtifactPaths(
            promotionOutputDirectory,
            effectiveRunId);
        if (!frozenPaths.IsSuccess)
            return frozenPaths.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        var pairStoreInputSha256s = promotionPairs
            .Select(BuildPairStoreInputSha256)
            .ToArray();
        operationContext = operationContext with
        {
            CanonicalPromotionOutputDirectory = frozenPaths.Value!.OutputDirectory,
            PairStoreInputSha256s = pairStoreInputSha256s,
            PairStoreInputsSha256 = BuildPairStoreInputsSha256(pairStoreInputSha256s)
        };
        var reservedReceiptBytes =
            uploaderAuthorityPreflight.Value!
                .MaximumSerializedReceiptUtf8Bytes;
        var reservedMutationEnvelope =
            await ReserveLocalPromotionMutationEnvelopeAsync(
                operationContext,
                promotionPairs,
                reservedReceiptBytes,
                uploaderAuthorityPreflight.Value.UploaderAuthorityMode,
                uploaderAuthorityPreflight.Value
                    .UploaderConfigurationFingerprintSha256,
                ct);
        if (!reservedMutationEnvelope.IsSuccess)
        {
            return reservedMutationEnvelope.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        operationContext = reservedMutationEnvelope.Value!;
        if (operationState.Prepare is { } existingPrepare &&
            (!PathsEqualForPlatform(
                 existingPrepare.CanonicalPromotionOutputDirectory,
                 operationContext.CanonicalPromotionOutputDirectory) ||
             !existingPrepare.PairStoreInputSha256s.SequenceEqual(
                 operationContext.PairStoreInputSha256s,
                 StringComparer.Ordinal) ||
             !string.Equals(
                 existingPrepare.PairStoreInputsSha256,
                 operationContext.PairStoreInputsSha256,
                 StringComparison.Ordinal) ||
             !string.Equals(
                 existingPrepare.PairStoreReservationId,
                 operationContext.PairStoreReservationId,
                 StringComparison.Ordinal) ||
             !string.Equals(
                 existingPrepare.PairStoreReservationSha256,
                 operationContext.PairStoreReservationSha256,
                 StringComparison.Ordinal) ||
             !string.Equals(
                 existingPrepare.OutputNamespaceReservationRef,
                 operationContext.OutputNamespaceReservationRef,
                 StringComparison.Ordinal) ||
             !string.Equals(
                 existingPrepare.OutputNamespaceReservationSha256,
                 operationContext.OutputNamespaceReservationSha256,
                 StringComparison.Ordinal) ||
             !string.Equals(
                 existingPrepare.UploaderEnvelopeReservationSha256,
                 operationContext.UploaderEnvelopeReservationSha256,
                 StringComparison.Ordinal) ||
             !string.Equals(
                 existingPrepare.UploaderAuthorityMode,
                 operationContext.UploaderAuthorityMode,
                 StringComparison.Ordinal) ||
             !string.Equals(
                 existingPrepare.UploaderConfigurationFingerprintSha256,
                 operationContext.UploaderConfigurationFingerprintSha256,
                 StringComparison.Ordinal)))
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var compositeOptimizer = DesignConversionDpoTrainingContentAuthority
            .ProjectCompositeOptimizerInputs(
                promotionPipelineFinalOptimizer,
                promotionPairs,
                preparedBridge.Value.FinalOptimizer);
        if (!compositeOptimizer.IsSuccess ||
            compositeOptimizer.Value is null)
        {
            var failure = compositeOptimizer.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
            return operationState.Phase is null
                ? ReleaseLocalPromotionMutationEnvelope(
                    operationContext,
                    failure)
                : failure;
        }
        var leaseResult = _legalTeacherAdmissionAuthority.AcquireTrainingLease(
            compositeOptimizer.Value.FinalOptimizer.Content,
            compositeOptimizer.Value.FinalOptimizer.Provenance);
        if (!leaseResult.IsSuccess)
        {
            var failure = leaseResult.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
            return operationState.Phase is null
                ? ReleaseLocalPromotionMutationEnvelope(
                    operationContext,
                    failure)
                : failure;
        }

        var trainingLease = leaseResult.Value!;
        var bindingResult = DesignConversionPipelineTrainingBinding
            .MintComposite(
                compositeOptimizer.Value,
                promotionPipelineFinalOptimizer,
                preparedBridge.Value.FinalOptimizer,
                trainingLease);
        using var trainingLeaseTransfer =
            new LocalTrainingLeaseTransferGuard(trainingLease);
        DesignConversionTrainingPipeline.NotifyTrainingLease(trainingLease);
        var admissionSnapshot = DesignConversionTrainingPipeline.SnapshotAdmission(
            trainingLease.Admission);

        if (!bindingResult.IsSuccess || bindingResult.Value is null)
        {
            var failure = bindingResult.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
            return operationState.Phase is null
                ? ReleaseLocalPromotionMutationEnvelope(
                    operationContext,
                    failure)
                : failure;
        }
        var trainingBinding = bindingResult.Value;

        var currentOperationState = operationState;
        if (currentOperationState.Phase is null)
        {
            var prepareRecord = await AppendLocalPromotionOperationRecordAsync(
                BuildLocalPromotionOperationRecord(
                    operationContext,
                    LocalPromotionOperationPhase.Prepare,
                    DateTimeOffset.UtcNow),
                ct);
            if (!prepareRecord.IsSuccess)
            {
                return ReleaseLocalPromotionMutationEnvelope(
                    operationContext,
                    prepareRecord.MapError<
                        DesignConversionTrainingIntakeLocalPromotionResult>());
            }
            currentOperationState = currentOperationState with
            {
                Prepare = prepareRecord.Value
            };
        }
        if (currentOperationState.Phase == LocalPromotionOperationPhase.Prepare)
        {
            var intentRecord = await AppendLocalPromotionOperationRecordAsync(
                BuildLocalPromotionOperationRecord(
                    operationContext,
                    LocalPromotionOperationPhase.Intent,
                    DateTimeOffset.UtcNow),
                ct);
            if (!intentRecord.IsSuccess)
                return intentRecord.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            // Idempotent replay может уже держать Intent, но committed
            // external path всё равно валидирует state перед pair-store/result
            // gates; Prepared/Committed остаются только за StorePromoteLocal.
            currentOperationState = currentOperationState with
            {
                Intent = intentRecord.Value
            };
        }
        if (currentOperationState.Phase != LocalPromotionOperationPhase.Intent)
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var pairPermit = DesignConversionTrainingPipeline.AcquireMutationPermit(
            trainingBinding,
            "run_pair_store");
        if (!pairPermit.IsSuccess)
            return pairPermit.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        OperationResult<bool> persistedPairs;
        using (pairPermit.Value!)
        {
            // Journal Prepared hashes должны ссылаться на реальные pair-store
            // rows. В committed external path это store-minted transfer pairs,
            // а не caller/prepared originals.
            persistedPairs = PersistFinalTrainingIntakeDpoPairsBeforeRunner(
                promotionPairs,
                ct);
        }

        var pairResultPermit = DesignConversionTrainingPipeline.AcquireMutationPermit(
            trainingBinding,
            "run_pair_store_result");
        if (!pairResultPermit.IsSuccess)
            return pairResultPermit.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        using (pairResultPermit.Value!)
        {
            if (ct.IsCancellationRequested)
                return Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>();
            if (!persistedPairs.IsSuccess)
                return persistedPairs.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var preparedRunnerExecution = preparedRunner.Value;
        if (preparedRunnerExecution is null)
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        DesignConversionTrainingRunResult completedRunnerResult;
        if (committedExternalConsumption is { } retainedExternalForRunner)
        {
            if (committedExternalPromotion is null ||
                preparedRunnerExecution.Pipeline.FinalOptimizer is null)
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            // Внешний эталон уже списан и зафиксирован ровно один раз; теперь
            // ordinary local runner обязан сам продолжить локальную модель на
            // store-minted transfer-парах, чтобы checkpoint mutation была
            // доказана реальной записью, а не внешним паспортом.
            _runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting?.Invoke();
            _runTrainingIntakeRunnerInvokedObserverForTesting?.Invoke();
            var runner = await trainingRunner
                .RunPreparedCommittedDualTargetTeacherLocalContinuationAsync(
                    machine,
                    trainingBinding,
                    preparedRunnerExecution,
                    retainedExternalForRunner,
                    ct);
            if (!runner.IsSuccess)
            {
                return runner.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            completedRunnerResult = runner.Value!;
        }
        else
        {
            _runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting?.Invoke();
            _runTrainingIntakeRunnerInvokedObserverForTesting?.Invoke();
            var runner = await trainingRunner.RunPreparedTrainingRecordsAsync(
                machine,
                trainingBinding,
                preparedRunnerExecution,
                ct);
            if (!runner.IsSuccess)
                return runner.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

            completedRunnerResult = runner.Value!;
        }

        if (_runTrainingIntakeLocalPromotionCompletedRunnerResultTransformerForTesting is not null)
        {
            var transformedRunnerResult =
                _runTrainingIntakeLocalPromotionCompletedRunnerResultTransformerForTesting(
                    completedRunnerResult);
            if (transformedRunnerResult is null)
                return DpoPolicyBridgeTrainPartitionInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();

            completedRunnerResult = transformedRunnerResult;
        }

        var trainingRun = BuildTrainingIntakeRunResult(
            intake,
            preflight,
            runOptions,
            optionsProvided: optionsProvided,
            resolvedTrainingRecordCount: resolved.Value.Records.Count,
            runnerResult: completedRunnerResult,
            blockReasons: [],
            trainingExecutionBoundary: BuildTrainingExecutionBoundary(
                completedRunnerResult));
        if (committedExternalConsumption is not null)
        {
            if (committedExternalProjection is null)
            {
                return DpoPolicyBridgeTrainPartitionInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
            }

            trainingRun = MarkCommittedDualTargetTeacherExternalConsumption(
                trainingRun,
                committedExternalProjection,
                committedExternalConsumption);
        }

        resolved = await ResolveTrainingIntakeRecordsForFreshRunBoundaryAsync(
            intake,
            ct);
        if (!resolved.IsSuccess)
            return resolved.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        if (resolved.Value!.BlockReasons.Count > 0)
        {
            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    trainingRun,
                    promotionOutputDirectory,
                    promotedCheckpointPath: string.Empty,
                    publication: null,
                    promotedLocalModel: null,
                    additionalBlockReasons: resolved.Value.BlockReasons
                        .Append("local_promotion_blocked_post_training_eligibility_change")
                        .ToArray(),
                    additionalWarnings: ["local_promotion_not_attempted"],
                    additionalEvidenceRefs:
                    ["DESIGN_CONVERSION_LOCAL_PROMOTION_BLOCKED_BEFORE_CHECKPOINT_PROMOTION"]),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        var resolvedPaths = ResolveTrainingIntakeLocalPromotionArtifactPaths(
            promotionOutputDirectory,
            trainingRun.RunId);
        if (!resolvedPaths.IsSuccess ||
            !LocalPromotionArtifactPathsMatch(frozenPaths.Value!, resolvedPaths.Value!))
        {
            return LocalPromotionOperationIndeterminate<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var outputDirectory = resolvedPaths.Value!.OutputDirectory;
        var checkpointPath = resolvedPaths.Value.RuntimeCheckpointPath;

        _runTrainingIntakeLocalPromotionBeforePolicyBridgePathResolveObserverForTesting?.Invoke();
        // Re-resolve for the existing path-security checks, but the durable
        // Intent freezes authority to the pre-mutation path set. Any mismatch is
        // indeterminate-after-intent and must never be retrained on retry.
        var immediatelyResolvedPaths =
            ResolveTrainingIntakeLocalPromotionArtifactPaths(
                promotionOutputDirectory,
                trainingRun.RunId);
        if (!immediatelyResolvedPaths.IsSuccess ||
            !LocalPromotionArtifactPathsMatch(
                frozenPaths.Value!,
                immediatelyResolvedPaths.Value!))
        {
            return LocalPromotionOperationIndeterminate<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        resolvedPaths = immediatelyResolvedPaths;
        outputDirectory = resolvedPaths.Value!.OutputDirectory;
        checkpointPath = resolvedPaths.Value.RuntimeCheckpointPath;

        resolved = await ResolveTrainingIntakeRecordsForFreshRunBoundaryAsync(
            intake,
            ct);
        if (!resolved.IsSuccess)
            return resolved.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        if (resolved.Value!.BlockReasons.Count > 0)
        {
            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    trainingRun,
                    operationContext.CanonicalPromotionOutputDirectory,
                    promotedCheckpointPath: string.Empty,
                    publication: null,
                    promotedLocalModel: null,
                    additionalBlockReasons: resolved.Value.BlockReasons
                        .Append("local_promotion_blocked_immediately_before_policy_bridge")
                        .ToArray(),
                    additionalWarnings: ["local_promotion_not_attempted"],
                    additionalEvidenceRefs:
                    ["DESIGN_CONVERSION_LOCAL_PROMOTION_ELIGIBILITY_REVALIDATED_BEFORE_POLICY_BRIDGE"]),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        var finalResolvedPaths =
            ResolveTrainingIntakeLocalPromotionArtifactPaths(
                promotionOutputDirectory,
                trainingRun.RunId);
        if (!finalResolvedPaths.IsSuccess ||
            !LocalPromotionArtifactPathsMatch(
                frozenPaths.Value!,
                finalResolvedPaths.Value!))
        {
            return LocalPromotionOperationIndeterminate<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        resolvedPaths = finalResolvedPaths;
        outputDirectory = resolvedPaths.Value!.OutputDirectory;
        checkpointPath = resolvedPaths.Value.RuntimeCheckpointPath;
        var bridgeOutputDirectory = outputDirectory;
        var bridgeCheckpointPath = checkpointPath;
        var bridgeRunId = trainingRun.RunId;
        var bridgeBaseProvider = _dpoPolicyBaseProvider;
        var bridgeParent = retainedParent;

        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>();

        var runnerAdmittedRecords =
            ResolveRunnerRecordsForCommittedDualTargetTeacherContinuation(
                localPromotionResolvedRecords,
                committedExternalPromotion);
        if (!runnerAdmittedRecords.IsSuccess)
        {
            return runnerAdmittedRecords.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var currentPromotionRecords =
            ResolveLocalPromotionRecordsForCurrentSnapshot(
                resolved.Value.Records);
        if (!currentPromotionRecords.IsSuccess ||
            currentPromotionRecords.Value is null)
        {
            return currentPromotionRecords.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var runnerCurrentRecords =
            ResolveRunnerRecordsForCommittedDualTargetTeacherContinuation(
                currentPromotionRecords.Value,
                committedExternalPromotion);
        if (!runnerCurrentRecords.IsSuccess)
        {
            return runnerCurrentRecords.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var admittedPartitionResult = ResolveCompletedRunnerDpoTrainPartition(
            completedRunnerResult,
            runnerAdmittedRecords.Value,
            ct);
        if (!admittedPartitionResult.IsSuccess)
        {
            return admittedPartitionResult.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var currentPartitionResult = ResolveCompletedRunnerDpoTrainPartition(
            completedRunnerResult,
            runnerCurrentRecords.Value,
            ct);
        if (!currentPartitionResult.IsSuccess)
        {
            return currentPartitionResult.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var bridgePartition = admittedPartitionResult.Value!;
        if (!FullEvaluatedPartitionMatches(
                committedExternalPromotion is null
                    ? preparedPartition.Value
                    : bridgePreparationPartition,
                bridgePartition) ||
            !FullEvaluatedPartitionMatches(
                bridgePartition,
                currentPartitionResult.Value!))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        OperationResult<DesignConversionDpoEvaluatedBridgeLease> bridgeLeaseResult;
        if (bridgeParent is null)
        {
            var bridgeTask = DesignConversionDpoPolicyCheckpointBridge
                .ExecutePreparedEvaluatedCompositeWithTransferredLeaseAsync(
                    trainingLease,
                    trainingBinding,
                    preparedBridge.Value,
                    bridgeOutputDirectory,
                    bridgeRunId,
                    bridgeCheckpointPath,
                    ct: ct);
            trainingLeaseTransfer.TransferOwnership();
            bridgeLeaseResult = await bridgeTask;
        }
        else
        {
            OperationResult<DesignConversionDpoEvaluatedBridgeLease>?
                continuationBridgeResult = null;
            DesignConversionDpoEvaluatedBridgeLease?
                callbackProducedBridgeLease = null;
            ExceptionDispatchInfo? continuationInvocationException = null;
            try
            {
                continuationBridgeResult = await bridgeParent.InvokeAndDisposeAsync(
                    async (_, continuationCt) =>
                    {
                        var callbackTask = DesignConversionDpoPolicyCheckpointBridge
                            .ExecutePreparedEvaluatedCompositeWithTransferredLeaseAsync(
                                trainingLease,
                                trainingBinding,
                                preparedBridge.Value,
                                bridgeOutputDirectory,
                                bridgeRunId,
                                bridgeCheckpointPath,
                                ct: continuationCt);
                        trainingLeaseTransfer.TransferOwnership();
                        var callbackResult = await callbackTask;
                        if (callbackResult.IsSuccess && callbackResult.Value is not null)
                            callbackProducedBridgeLease = callbackResult.Value;
                        return callbackResult;
                    },
                    ct);
            }
            catch (Exception exception)
            {
                continuationInvocationException =
                    ExceptionDispatchInfo.Capture(exception);
            }
            CompleteContinuationOwnedResult(
                callbackProducedBridgeLease,
                continuationBridgeResult,
                continuationInvocationException);
            bridgeLeaseResult = continuationBridgeResult!;
        }
        GC.KeepAlive(admissionSnapshot);
        if (!bridgeLeaseResult.IsSuccess)
            return bridgeLeaseResult.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        using var bridgeLease = bridgeLeaseResult.Value!;
        var bridge = bridgeLease.Result;

        var postBridgePermit = DesignConversionTrainingPipeline.AcquireMutationPermit(
            bridgeLease,
            "local_promotion:bridge_result");
        if (!postBridgePermit.IsSuccess || postBridgePermit.Value is null)
        {
            return postBridgePermit.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        using var postBridgeMutationPermit = postBridgePermit.Value;

        trainingRun = MarkDpoContinuationBoundary(
            trainingRun,
            retainedParent);

        _runTrainingIntakeLocalPromotionBeforePublicationObserverForTesting?.Invoke();
        resolved = await ResolveTrainingIntakeRecordsForFreshRunBoundaryAsync(
            intake,
            ct);
        if (!resolved.IsSuccess)
            return resolved.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        if (resolved.Value!.BlockReasons.Count > 0)
        {
            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    trainingRun,
                    outputDirectory,
                    checkpointPath,
                    publication: null,
                    promotedLocalModel: null,
                    additionalBlockReasons: resolved.Value.BlockReasons
                        .Append("local_promotion_blocked_immediately_before_publication")
                        .ToArray(),
                    additionalWarnings: ["local_promotion_publication_not_attempted"],
                    additionalEvidenceRefs:
                    ["DESIGN_CONVERSION_LOCAL_PROMOTION_POST_EVALUATION_REVALIDATION_BEFORE_PUBLICATION"]),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        var finalPromotionRecords =
            ResolveLocalPromotionRecordsForCurrentSnapshot(
                resolved.Value.Records);
        if (!finalPromotionRecords.IsSuccess ||
            finalPromotionRecords.Value is null)
        {
            return finalPromotionRecords.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var runnerFinalRecords =
            ResolveRunnerRecordsForCommittedDualTargetTeacherContinuation(
                finalPromotionRecords.Value,
                committedExternalPromotion);
        if (!runnerFinalRecords.IsSuccess)
        {
            return runnerFinalRecords.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var finalPartition = ResolveCompletedRunnerDpoTrainPartition(
            completedRunnerResult,
            runnerFinalRecords.Value,
            ct);
        if (!finalPartition.IsSuccess)
            return finalPartition.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        var postBridgePartition = finalPartition.Value!;
        if (_runTrainingIntakeLocalPromotionPostBridgePartitionTransformerForTesting is not null)
        {
            postBridgePartition =
                _runTrainingIntakeLocalPromotionPostBridgePartitionTransformerForTesting(
                    postBridgePartition);
            if (postBridgePartition is null)
                return DpoPolicyBridgeTrainPartitionInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var postBridgePartitionForBridge = postBridgePartition;
        if (!FullEvaluatedPartitionMatches(
                bridgePreparationPartition,
                postBridgePartitionForBridge) ||
            !EvaluatedPartitionMatchesBridge(
                postBridgePartitionForBridge,
                bridge,
                bridgeLease.Evaluation,
                runOptions.DpoPolicyBridgeOptions))
        {
            return DpoPolicyBridgeTrainPartitionInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var requiredEvaluatedAccuracy = ResolveRequiredEvaluatedAccuracy(
            runOptions,
            bridgeLease.Evaluation);
        if (!requiredEvaluatedAccuracy.IsSuccess)
        {
            return requiredEvaluatedAccuracy.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var preservedAuthoritativeBlockers = BuildPreservedAuthoritativeBlockers(trainingRun);
        trainingRun = ApplyEvaluatedTrainingRun(
            trainingRun,
            bridgeLease.Evaluation,
            requiredEvaluatedAccuracy.Value!);
        if (preservedAuthoritativeBlockers.Count > 0)
        {
            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    trainingRun,
                    outputDirectory,
                    checkpointPath,
                    publication: null,
                    promotedLocalModel: null,
                    additionalBlockReasons: preservedAuthoritativeBlockers,
                    additionalWarnings: ["local_promotion_publication_not_attempted_authoritative_blocker"],
                    additionalEvidenceRefs:
                    ["DESIGN_CONVERSION_LOCAL_PROMOTION_BLOCKED_BY_PRESERVED_AUTHORITATIVE_FAILURE"]),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        var contractPublication = await DesignConversionDpoPromotionArtifactContractCodec
            .PublishEvaluatedAsync(
                resolvedPaths.Value,
                bridge,
                bridgeLease.Evaluation,
                ct);
        if (!contractPublication.IsSuccess)
        {
            return contractPublication.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        bridgeLease.CommitPublishedArtifacts();

        trainingRun = trainingRun with
        {
            BoundaryMetadata = DesignConversionDpoPromotionArtifactContractCodec
                .AddTrustedAnchorMetadata(
                    trainingRun.BoundaryMetadata,
                    contractPublication.Value!.Anchors)
        };

        var artifacts = contractPublication.Value!.ManifestArtifacts;
        // With no configured uploader, publishing remains a local bookkeeping step and gains no network authority.
        var publicationUploader =
            _promotionUploader ?? new LocalOnlyTrainingIntakePromotionUploader();
        var gateReport = BuildEvaluatedLocalPromotionGateReport(
            completedRunnerResult.PipelineResult,
            artifacts,
            bridgeLease.Evaluation,
            requiredEvaluatedAccuracy.Value!,
            uploaderAuthorityPreflight.Value!);
        var publisher = new DesignConversionPromotionPublisher(publicationUploader)
        {
            BeforeTerminalReturnForTesting = _promotionBeforeTerminalReturnObserverForTesting
        };
        var publication = await publisher.PublishEvaluatedDpoAsync(
            bridge.RuntimeMachine,
            completedRunnerResult,
            $"{ToSafeLocalPromotionFileName(trainingRun.RunId)}-local-promotion-manifest",
            contractPublication.Value,
            gateReport,
            uploaderAuthorityPreflight.Value.PublicationUploadAuthorityMode,
            ct);
        if (!publication.IsSuccess)
            return publication.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        var receiptLimit =
            uploaderAuthorityPreflight.Value.MaximumSerializedReceiptUtf8Bytes;
        if (publication.Value!.UploadReceipt is { } actualReceipt &&
            (StrictUtf8Encoding.GetByteCount(
                 JsonSerializer.Serialize(actualReceipt, JsonOptions)) > receiptLimit ||
             StrictUtf8Encoding.GetByteCount(
                 JsonSerializer.Serialize(actualReceipt, JsonOptions)) >
             MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength))
        {
            return LocalPromotionOperationIndeterminate<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        if (IsLocalReceiptPublicationOrRejectedLocalReceipt(publication.Value) &&
            uploaderAuthorityPreflight.Value.PublicationUploadAuthorityMode !=
                DesignConversionPromotionUploadAuthorityMode.LocalReceiptOnly)
        {
            return LocalPromotionOperationIndeterminate<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        trainingRun = ApplyEvaluatedPromotionDecision(
            trainingRun,
            publication.Value!.Decision);

        if (!publication.Value!.Decision.AllowsUpload || !trainingRun.ModelUploadReady)
        {
            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    trainingRun,
                    outputDirectory,
                    checkpointPath,
                    publication.Value,
                    promotedLocalModel: null,
                    additionalBlockReasons: publication.Value.Decision.Reasons,
                    additionalWarnings: ["local_promotion_rejected_by_promotion_gate"],
                    additionalEvidenceRefs: publication.Value.Decision.EvidenceRefs),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        if (publication.Value.Manifest.ModelServerUploadAttempted)
        {
            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    trainingRun,
                    outputDirectory,
                    checkpointPath,
                    publication.Value,
                    promotedLocalModel: null,
                    additionalBlockReasons: ["local_promotion_not_loaded_after_verified_model_server_upload"],
                    additionalWarnings: ["model_server_upload_verified_local_activation_not_attempted"],
                    additionalEvidenceRefs:
                    [
                        "DESIGN_CONVERSION_MODEL_SERVER_UPLOAD_VERIFIED_BY_CONFIGURED_UPLOADER",
                        "DESIGN_CONVERSION_LOCAL_MODEL_LOAD_NOT_ATTEMPTED_FOR_REMOTE_PROMOTION_RECEIPT"
                    ]),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        _runTrainingIntakeLocalPromotionBeforeActivationObserverForTesting?.Invoke();
        resolved = await ResolveTrainingIntakeRecordsForFreshRunBoundaryAsync(
            intake,
            ct);
        if (!resolved.IsSuccess)
            return resolved.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        if (resolved.Value!.BlockReasons.Count > 0)
        {
            return await StorePromoteLocalIdempotencyResultAsync(
                BuildTrainingIntakeLocalPromotionResult(
                    trainingRun,
                    outputDirectory,
                    checkpointPath,
                    publication.Value,
                    promotedLocalModel: null,
                    additionalBlockReasons: resolved.Value.BlockReasons
                        .Append("local_activation_blocked_post_evaluation_eligibility_change")
                        .ToArray(),
                    additionalWarnings: ["local_model_activation_not_attempted"],
                    additionalEvidenceRefs:
                    ["DESIGN_CONVERSION_LOCAL_ACTIVATION_POST_EVALUATION_REVALIDATION_BLOCKED"]),
                intake,
                runOptions,
                promotionOutputDirectory,
                admissionBoundaryMetadata,
                operationContext,
                ct);
        }

        _runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting?.Invoke();
        var promoted = await DesignConversionPromotedLocalModelLoader.LoadAsync(
            publication.Value,
            checkpointPath,
            ct);
        if (!promoted.IsSuccess)
            return promoted.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

        return await StorePromoteLocalIdempotencyResultAsync(
            BuildTrainingIntakeLocalPromotionResult(
                trainingRun,
                outputDirectory,
                checkpointPath,
                publication.Value,
                promoted.Value!.Model,
                additionalBlockReasons: [],
                 additionalWarnings: ["local_promotion_ready_no_external_cloud_upload"],
                 additionalEvidenceRefs: promoted.Value.Model.EvidenceRefs
                     .Concat(bridge.EvidenceRefs)
                     .Distinct(StringComparer.Ordinal)
                     .ToArray(),
                 cycleAccuracyEvaluation: bridgeLease.Evaluation),
            intake,
            runOptions,
            promotionOutputDirectory,
            admissionBoundaryMetadata,
            operationContext,
            ct);
    }

    public async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>> RollbackTrainingIntakeLocalPromotionAsync(
        string promotedLocalModelRef,
        string requestedByRef,
        string reason,
        DateTimeOffset? requestedAtUtc = null,
        CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
        if (string.IsNullOrWhiteSpace(promotedLocalModelRef))
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Fail(
                "DesignConversion local promotion rollback requires a promoted local model reference.",
                "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_REF_REQUIRED");
        if (string.IsNullOrWhiteSpace(requestedByRef))
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Fail(
                "DesignConversion local promotion rollback requires requestedByRef.",
                "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_REQUESTED_BY_REQUIRED");
        if (string.IsNullOrWhiteSpace(reason))
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Fail(
                "DesignConversion local promotion rollback requires an evidence-bound reason.",
                "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_REASON_REQUIRED");

        var admissionBoundaryMetadata = DesignConversionTrainingIntakeRouteAdmissionContext.Current;
        var gateAcquired = false;
        try
        {
            await WaitForObservedGateAsync(
                _recordsMutationContext.RunTrainingIntakeLocalPromotionGate,
                _runTrainingIntakeLocalPromotionGateWaitTaskObserverForTesting,
                () => gateAcquired = true,
                ct);

            if (_runTrainingIntakeLocalPromotionGateAcquiredCallbackForTesting is not null)
                await _runTrainingIntakeLocalPromotionGateAcquiredCallbackForTesting(ct);

            await using var mutationLease = await AcquireTrainingIntakeLocalPromotionMutationLeaseAsync(ct);
            using var journalMutationLeaseBinding =
                _localPromotionJournalSet.BindMutationLease(mutationLease);
            var recoveredJournals =
                await _localPromotionJournalSet.RecoverAsync(ct);
            if (!recoveredJournals.IsSuccess)
            {
                return string.Equals(
                    recoveredJournals.ErrorCode,
                    InvalidUtf8ErrorCode,
                    StringComparison.Ordinal)
                    ? TrainingIntakeLocalPromotionsInvalidUtf8<
                        DesignConversionTrainingIntakeLocalPromotionRollbackResult>()
                    : recoveredJournals.MapError<
                        DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
            }
            var operationRecords = await ReadLocalPromotionOperationJournalAsync(ct);
            if (!operationRecords.IsSuccess)
                return operationRecords.MapError<
                    DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
            var reconciled = await ReconcileCommittedLocalPromotionProjectionsAsync(
                operationRecords.Value!,
                ct);
            if (!reconciled.IsSuccess)
                return reconciled.MapError<
                    DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
            var records = await ReadMergedTrainingIntakeLocalPromotionRecordsAsync(
                operationRecords.Value!,
                ct);
            if (!records.IsSuccess)
                return records.MapError<DesignConversionTrainingIntakeLocalPromotionRollbackResult>();

            var target = records.Value!
                .LastOrDefault(record => MatchesLocalPromotionRef(record, promotedLocalModelRef));
            if (target is null)
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Fail(
                    "DesignConversion local promotion rollback could not find the promoted local model reference.",
                    "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_TARGET_NOT_FOUND");
            if (!target.LocalPromotionReady)
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Fail(
                    "DesignConversion local promotion rollback target is not an active-ready local promotion.",
                    "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_TARGET_NOT_READY");

            var targetRef = BuildLocalPromotionActiveRef(target);
            var replay = ResolveRollbackLocalPromotionIdempotencyReplay(
                records.Value!,
                targetRef,
                requestedByRef,
                reason,
                requestedAtUtc,
                admissionBoundaryMetadata);
            if (!replay.IsSuccess)
                return replay.MapError<DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
            if (replay.Value!.HasReplay)
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Ok(replay.Value.Result!);

            var current = ResolveCurrentLocalPromotionActiveState(records.Value!);
            if (current.Kind == DesignConversionLocalPromotionActiveStateKind.Invalid)
            {
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Fail(
                    "DesignConversion local promotion rollback state is invalid.",
                    "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_STATE_INVALID");
            }
            if (current.Kind != DesignConversionLocalPromotionActiveStateKind.Active ||
                current.Active is null ||
                !string.Equals(
                    current.Active.ActiveLocalModelRef,
                    targetRef,
                    StringComparison.Ordinal))
            {
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Fail(
                    "DesignConversion local promotion rollback target is not the current active local promotion.",
                    "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_TARGET_NOT_ACTIVE");
            }

            var priorRef = ReadMetadata(target.BoundaryMetadata, "local_promotion_prior_active_local_model_ref");
            var priorModelId = ReadMetadata(target.BoundaryMetadata, "local_promotion_prior_active_model_id");
            var priorCheckpoint = ReadMetadata(target.BoundaryMetadata, "local_promotion_prior_active_checkpoint_sha256");
            var noPrior = string.Equals(
                ReadMetadata(target.BoundaryMetadata, "local_promotion_prior_state_kind"),
                "none",
                StringComparison.Ordinal);
            if (noPrior)
            {
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Fail(
                    "DesignConversion local promotion rollback target has no prior active local promotion to restore.",
                    "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_PRIOR_STATE_NOT_RECORDED");
            }

            if (string.IsNullOrWhiteSpace(priorRef) && !noPrior)
            {
                return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Fail(
                    "DesignConversion local promotion rollback target has no recorded prior active local state.",
                    "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_PRIOR_STATE_MISSING");
            }

            var rollbackCapacity =
                await CanReserveLocalPromotionProjectionRowWithoutRotationAsync(
                    MaxTrainingIntakeLocalPromotionJournalRowByteLength,
                    ct);
            if (!rollbackCapacity.IsSuccess)
                return rollbackCapacity.MapError<
                    DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
            if (!rollbackCapacity.Value)
            {
                return TrainingIntakeLocalPromotionsQuotaExceeded<
                    DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
            }

            var rollbackAt = requestedAtUtc ?? DateTimeOffset.UtcNow;
            var rollbackId = BuildLocalPromotionRollbackId(
                targetRef,
                priorRef,
                requestedByRef,
                reason,
                rollbackAt);
            var rollbackRecord = BuildLocalPromotionRollbackRecord(
                target,
                rollbackId,
                targetRef,
                current.Active.ActiveLocalModelRef,
                priorRef,
                priorModelId,
                priorCheckpoint,
                requestedByRef,
                reason,
                rollbackAt);
            rollbackRecord = MarkRollbackLocalPromotionIdempotencyBoundary(
                rollbackRecord,
                targetRef,
                requestedByRef,
                reason,
                requestedAtUtc,
                admissionBoundaryMetadata,
                replayHit: false,
                createdNewSideEffect: true);
            if (!ValidateCycleAccuracyLineageContract(rollbackRecord))
                return CycleAccuracyLineageInvalid<DesignConversionTrainingIntakeLocalPromotionRollbackResult>();

            var line = JsonSerializer.Serialize(rollbackRecord, JsonOptions);
            var framedLineByteLength = StrictUtf8Encoding.GetByteCount(line + Environment.NewLine);
            if (framedLineByteLength > MaxTrainingIntakeLocalPromotionJournalRowByteLength ||
                framedLineByteLength > _trainingIntakeLocalPromotionsMaxBytes)
            {
                return TrainingIntakeLocalPromotionsQuotaExceeded<DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
            }
            var exactRollbackCapacity =
                await EnsureLocalPromotionProjectionCapacityAsync(
                    framedLineByteLength,
                    ct);
            if (!exactRollbackCapacity.IsSuccess)
                return exactRollbackCapacity.MapError<
                    DesignConversionTrainingIntakeLocalPromotionRollbackResult>();

            var appended = await _localPromotionJournalSet.AppendLineAsync(
                DesignConversionLocalPromotionJournalKind.Projection,
                line,
                ct);
            if (!appended.IsSuccess)
                return appended.MapError<
                    DesignConversionTrainingIntakeLocalPromotionRollbackResult>();

            return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackResult>.Ok(
                BuildLocalPromotionRollbackResult(rollbackRecord));
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
        }
        catch (IOException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
        }
        catch (UnauthorizedAccessException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionTrainingIntakeLocalPromotionRollbackResult>();
        }
        finally
        {
            if (gateAcquired)
                _recordsMutationContext.RunTrainingIntakeLocalPromotionGate.Release();
        }
    }

    private Task<DesignConversionDeterministicMutationLease> AcquireTrainingIntakeLocalPromotionMutationLeaseAsync(CancellationToken ct)
    {
        Directory.CreateDirectory(_rootDirectory);

        return DesignConversionDeterministicMutationLock.WaitUntilAcquiredAsync(
            _trainingIntakeLocalPromotionMutationLockPath,
            TimeSpan.FromMilliseconds(TrainingIntakeLocalPromotionMutationLockRetryDelayMs),
            ct);
    }

    public async Task<OperationResult<DesignConversionDpoCandidateApprovalResult>> ApproveRuntimeCreatedDpoCandidateAsync(
        string localArtifactRecordId,
        string candidateOrTrainingRecordId,
        string reviewerRef,
        string reason,
        DateTimeOffset? approvedAtUtc = null,
        CancellationToken ct = default)
    {
        // Одиночный совместимый вход сохраняет прежний публичный договор: уже
        // отменённый вызов возвращает обычный результат CANCELLED до проверки
        // аргументов, а не выбрасывает исключение из нового пачечного адаптера.
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionDpoCandidateApprovalResult>();
        var batch = await ApproveRuntimeCreatedDpoCandidatesAsync(
            [
                new DesignConversionDpoCandidateApprovalRequest(
                    localArtifactRecordId,
                    candidateOrTrainingRecordId,
                    reviewerRef,
                    reason,
                    approvedAtUtc)
            ],
            ct);
        if (!batch.IsSuccess)
            return batch.MapError<DesignConversionDpoCandidateApprovalResult>();

        return OperationResult<DesignConversionDpoCandidateApprovalResult>.Ok(
            batch.Value!.Approvals[0]);
    }

    public async Task<OperationResult<DesignConversionDpoCandidateApprovalBatchResult>>
        ApproveRuntimeCreatedDpoCandidatesAsync(
            IReadOnlyList<DesignConversionDpoCandidateApprovalRequest> requests,
            CancellationToken ct = default)
    {
        var batchShapeValidation = ValidateApprovalBatchShape(requests);
        if (!batchShapeValidation.IsSuccess)
            return batchShapeValidation.MapError<DesignConversionDpoCandidateApprovalBatchResult>();

        try
        {
            await _recordsMutationContext.Gate.WaitAsync(ct);
        }
        catch (OperationCanceledException)
        {
            return Cancelled<DesignConversionDpoCandidateApprovalBatchResult>();
        }

        try
        {
            return await ApproveRuntimeCreatedDpoCandidatesCoreAsync(
                requests,
                ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<DesignConversionDpoCandidateApprovalBatchResult>();
        }
        catch (IOException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionDpoCandidateApprovalBatchResult>();
        }
        catch (UnauthorizedAccessException)
        {
            return LocalArtifactDbWriteFailed<DesignConversionDpoCandidateApprovalBatchResult>();
        }
        finally
        {
            _recordsMutationContext.Gate.Release();
        }
    }

    private async Task<OperationResult<DesignConversionDpoCandidateApprovalBatchResult>>
        ApproveRuntimeCreatedDpoCandidatesCoreAsync(
            IReadOnlyList<DesignConversionDpoCandidateApprovalRequest> requests,
            CancellationToken ct)
    {
        var recordsResult = await ReadRecordsCoreAsync(ct);
        if (!recordsResult.IsSuccess)
            return recordsResult.MapError<DesignConversionDpoCandidateApprovalBatchResult>();

        var records = recordsResult.Value!.ToArray();
        var plans = new List<DpoCandidateApprovalApplicationPlan>(requests.Count);
        var materializedRecordIndexes = new HashSet<int>();
        var resolvedApprovalKeys = new HashSet<string>(StringComparer.Ordinal);
        // Один снимок внешнего состояния покрывает всю текущую authority-версию.
        // По нему проверяются затронутые записи и строится точный индекс после commit;
        // повторного внешнего чтения состояния по одному кандидату или после замены
        // журнала нет. Сам authority-журнал читается отдельно: один начальный scan
        // здесь и не более одного согласующего scan после состоявшейся замены.
        var eligibilitySnapshot =
            await EvaluatePostEvaluationTrainingEligibilityManyAsync(
                records
                    .Select(record => (DesignConversionLocalArtifactDbRecord?)record)
                    .ToArray(),
                ct);
        var eligibilityByRecordIndex = eligibilitySnapshot
            .Select((eligibility, index) => new { index, eligibility })
            .ToDictionary(item => item.index, item => item.eligibility);
        var eligibleRecordIds = records
            .Where((_, index) => eligibilitySnapshot[index].IsEligible)
            .Select(record => record.RecordId)
            .ToHashSet(StringComparer.Ordinal);

        // Сначала строим весь план и проверяем каждый кандидат. Если один запрос плохой,
        // файл власти еще не тронут, поэтому остальные кандидаты не получают полумутацию.
        for (var requestIndex = 0; requestIndex < requests.Count; requestIndex++)
        {
            var request = requests[requestIndex];
            var plan = await BuildApprovalApplicationPlanAsync(
                records,
                request,
                requestIndex,
                materializedRecordIndexes,
                resolvedApprovalKeys,
                eligibilityByRecordIndex);
            if (!plan.IsSuccess)
                return plan.MapError<DesignConversionDpoCandidateApprovalBatchResult>();

            plans.Add(plan.Value!);
        }

        var rewrittenRecordIndexes = plans
            .Select(plan => plan.RecordIndex)
            .Distinct()
            .Order()
            .ToArray();
        // После полной проверки можно менять память: порядок запросов сохраняется,
        // но каждая запись журнала собирается только один раз.
        foreach (var recordGroup in plans.GroupBy(plan => plan.RecordIndex).OrderBy(group => group.Key))
        {
            var candidates = records[recordGroup.Key].DpoCandidates.ToArray();
            var record = records[recordGroup.Key];
            foreach (var plan in recordGroup.OrderBy(item => item.RequestIndex))
            {
                candidates[plan.CandidateIndex] = plan.ApprovedCandidate;
                record = ApplyApprovalToRecordMetadata(record, candidates, plan.Result);
            }

            records[recordGroup.Key] = record;
        }

        // На диск уходит одна crash-safe замена журнала для всей пачки, а не
        // отдельная полная перепись на каждый утвержденный кандидат.
        var write = await WriteRecordsCoreWithCandidatePayloadCustodyAsync(
            records,
            rewrittenRecordIndexes,
            ct,
            eligibleRecordIds);
        if (!write.IsSuccess)
            return write.MapError<DesignConversionDpoCandidateApprovalBatchResult>();

        var approvals = plans
            .OrderBy(plan => plan.RequestIndex)
            .Select(plan => write.Value ? plan.Result : WithDeferredIndexEvidence(plan.Result))
            .ToArray();

        return OperationResult<DesignConversionDpoCandidateApprovalBatchResult>.Ok(
            new DesignConversionDpoCandidateApprovalBatchResult(
                approvals,
                BuildDpoCandidateApprovalBatchMetadata(approvals, rewrittenRecordIndexes.Length, write.Value)));
    }

    private async Task<OperationResult<DpoCandidateApprovalApplicationPlan>>
        BuildApprovalApplicationPlanAsync(
            DesignConversionLocalArtifactDbRecord[] records,
            DesignConversionDpoCandidateApprovalRequest request,
            int requestIndex,
            HashSet<int> materializedRecordIndexes,
            HashSet<string> resolvedApprovalKeys,
            IReadOnlyDictionary<int, DesignConversionPostEvaluationTrainingEligibility>
                eligibilityByRecordIndex)
    {
        var matchingRecordIndexes = records
            .Select((record, index) => new { record, index })
            .Where(item => string.Equals(item.record.RecordId, request.LocalArtifactRecordId, StringComparison.Ordinal))
            .ToArray();
        if (matchingRecordIndexes.Length == 0)
            return OperationResult<DpoCandidateApprovalApplicationPlan>.Fail(
                "DesignConversion local artifact record was not found for DPO candidate approval.",
                "DESIGN_CONVERSION_LOCAL_ARTIFACT_RECORD_NOT_FOUND");
        if (matchingRecordIndexes.Length > 1)
            return OperationResult<DpoCandidateApprovalApplicationPlan>.Fail(
                "DesignConversion local artifact record id is ambiguous for DPO candidate approval.",
                "DESIGN_CONVERSION_LOCAL_ARTIFACT_RECORD_AMBIGUOUS");

        var recordIndex = matchingRecordIndexes[0].index;
        var record = records[recordIndex];
        if (!string.Equals(record.DatabaseKind, LocalArtifactDbKind, StringComparison.Ordinal))
            return OperationResult<DpoCandidateApprovalApplicationPlan>.Fail(
                "DesignConversion DPO candidate approval is only allowed for local artifact DB records.",
                "DESIGN_CONVERSION_DPO_APPROVAL_NON_LOCAL_RECORD");

        var postEvaluationEligibility = eligibilityByRecordIndex[recordIndex];
        if (!postEvaluationEligibility.IsEligible)
        {
            return OperationResult<DpoCandidateApprovalApplicationPlan>.Fail(
                $"DesignConversion DPO candidate is blocked by durable post-evaluation eligibility: {postEvaluationEligibility.Reason}.",
                postEvaluationEligibility.ErrorCode);
        }

        if (materializedRecordIndexes.Add(recordIndex))
        {
            var materializedRecord =
                await MaterializeCandidatePayloadCustodyForAuthorityRewriteAsync(
                    record);
            if (!materializedRecord.IsSuccess)
                return materializedRecord.MapError<DpoCandidateApprovalApplicationPlan>();

            records[recordIndex] = materializedRecord.Value!;
        }

        record = records[recordIndex];
        var candidates = record.DpoCandidates.ToArray();
        var matchingCandidateIndexes = candidates
            .Select((candidate, index) => new { candidate, index })
            .Where(item => MatchesCandidateApprovalIdentity(item.candidate, request.CandidateOrTrainingRecordId))
            .ToArray();
        if (matchingCandidateIndexes.Length == 0)
            return OperationResult<DpoCandidateApprovalApplicationPlan>.Fail(
                "DesignConversion runtime-created DPO candidate was not found for approval.",
                "DESIGN_CONVERSION_DPO_CANDIDATE_NOT_FOUND");
        if (matchingCandidateIndexes.Length > 1)
            return OperationResult<DpoCandidateApprovalApplicationPlan>.Fail(
                "DesignConversion runtime-created DPO candidate id is ambiguous for approval.",
                "DESIGN_CONVERSION_DPO_CANDIDATE_AMBIGUOUS");

        var candidateIndex = matchingCandidateIndexes[0].index;
        var candidate = candidates[candidateIndex];
        var resolvedApprovalKey = $"{record.RecordId}\u001F{candidate.CandidateId}";
        if (!resolvedApprovalKeys.Add(resolvedApprovalKey))
        {
            return OperationResult<DpoCandidateApprovalApplicationPlan>.Fail(
                "DesignConversion DPO candidate approval batch contains the same runtime candidate more than once.",
                "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_DUPLICATE_CANDIDATE");
        }

        var validation = ValidateApprovalCandidate(record, candidate);
        if (!validation.IsSuccess)
            return validation.MapError<DpoCandidateApprovalApplicationPlan>();

        var approval = BuildApprovedCandidate(
            record,
            candidate,
            request.ReviewerRef,
            request.Reason,
            request.ApprovedAtUtc ?? DateTimeOffset.UtcNow);

        return OperationResult<DpoCandidateApprovalApplicationPlan>.Ok(
            new DpoCandidateApprovalApplicationPlan(
                requestIndex,
                recordIndex,
                candidateIndex,
                approval.Candidate,
                approval.Result));
    }

    private static OperationResult<bool> ValidateApprovalBatchShape(
        IReadOnlyList<DesignConversionDpoCandidateApprovalRequest>? requests)
    {
        if (requests is null || requests.Count == 0)
            return OperationResult<bool>.Fail(
                "DesignConversion DPO candidate approval batch requires at least one request.",
                "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_REQUIRED");
        if (requests.Count > MaxRuntimeDpoCandidateApprovalBatchSize)
            return OperationResult<bool>.Fail(
                "DesignConversion DPO candidate approval batch exceeds the bounded local approval limit.",
                "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_TOO_LARGE");

        var submittedKeys = new HashSet<string>(StringComparer.Ordinal);
        long serializedMetadataUtf8Bytes = 0;
        for (var index = 0; index < requests.Count; index++)
        {
            var request = requests[index];
            // Быстрая проверка формы стоит до lock-а: пустые поля и повтор одной ссылки
            // не должны занимать общий журнал власти.
            if (request is null)
                return OperationResult<bool>.Fail(
                    "DesignConversion DPO candidate approval batch contains a null request.",
                    "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_REQUEST_NULL");
            if (string.IsNullOrWhiteSpace(request.LocalArtifactRecordId))
                return OperationResult<bool>.Fail(
                    "DesignConversion local artifact record id is required for DPO candidate approval.",
                    "DESIGN_CONVERSION_LOCAL_ARTIFACT_RECORD_ID_REQUIRED");
            if (string.IsNullOrWhiteSpace(request.CandidateOrTrainingRecordId))
                return OperationResult<bool>.Fail(
                    "DesignConversion DPO candidate or training record id is required for approval.",
                    "DESIGN_CONVERSION_DPO_CANDIDATE_ID_REQUIRED");
            if (string.IsNullOrWhiteSpace(request.ReviewerRef))
                return OperationResult<bool>.Fail(
                    "DesignConversion DPO candidate approval requires a local reviewer reference.",
                    "DESIGN_CONVERSION_DPO_APPROVAL_REVIEWER_REQUIRED");
            if (string.IsNullOrWhiteSpace(request.Reason))
                return OperationResult<bool>.Fail(
                    "DesignConversion DPO candidate approval requires an evidence-bound reason.",
                    "DESIGN_CONVERSION_DPO_APPROVAL_REASON_REQUIRED");

            try
            {
                // Сначала считаем сами значения без выделения большого JSON-буфера,
                // затем учитываем точный сериализованный вид с именами полей и escaping.
                var rawMetadataUtf8Bytes = checked(
                    StrictUtf8Encoding.GetByteCount(request.LocalArtifactRecordId) +
                    StrictUtf8Encoding.GetByteCount(request.CandidateOrTrainingRecordId) +
                    StrictUtf8Encoding.GetByteCount(request.ReviewerRef) +
                    StrictUtf8Encoding.GetByteCount(request.Reason) +
                    (request.ApprovedAtUtc.HasValue
                        ? StrictUtf8Encoding.GetByteCount(
                            request.ApprovedAtUtc.Value.ToString(
                                "O",
                                CultureInfo.InvariantCulture))
                        : 0));
                if (rawMetadataUtf8Bytes >
                    MaxRuntimeDpoCandidateApprovalBatchMetadataUtf8Bytes)
                {
                    return ApprovalBatchMetadataTooLarge();
                }

                var serializedRequestUtf8Bytes =
                    JsonSerializer.SerializeToUtf8Bytes(request, JsonOptions)
                        .LongLength;
                serializedMetadataUtf8Bytes = checked(
                    serializedMetadataUtf8Bytes + serializedRequestUtf8Bytes);
                if (serializedMetadataUtf8Bytes >
                    MaxRuntimeDpoCandidateApprovalBatchMetadataUtf8Bytes)
                {
                    return ApprovalBatchMetadataTooLarge();
                }
            }
            catch (EncoderFallbackException)
            {
                return OperationResult<bool>.Fail(
                    "DesignConversion DPO candidate approval metadata is not valid UTF-8 text.",
                    InvalidUtf8ErrorCode);
            }
            catch (OverflowException)
            {
                return ApprovalBatchMetadataTooLarge();
            }

            var submittedKey = $"{request.LocalArtifactRecordId}\u001F{request.CandidateOrTrainingRecordId}";
            if (!submittedKeys.Add(submittedKey))
                return OperationResult<bool>.Fail(
                    "DesignConversion DPO candidate approval batch contains the same submitted candidate reference more than once.",
                    "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_DUPLICATE_CANDIDATE");
        }

        return OperationResult<bool>.Ok(true);
    }

    private static OperationResult<bool> ApprovalBatchMetadataTooLarge()
        => OperationResult<bool>.Fail(
            "DesignConversion DPO candidate approval batch metadata exceeds the bounded UTF-8 limit.",
            "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_METADATA_TOO_LARGE");

    private static IReadOnlyDictionary<string, string> BuildDpoCandidateApprovalBatchMetadata(
        IReadOnlyList<DesignConversionDpoCandidateApprovalResult> approvals,
        int rewrittenRecordCount,
        bool derivedIndexDurable)
        => new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["approval_batch_count"] = approvals.Count.ToString(CultureInfo.InvariantCulture),
            ["approval_batch_rewritten_record_count"] = rewrittenRecordCount.ToString(CultureInfo.InvariantCulture),
            ["approval_batch_atomic"] = bool.TrueString,
            ["approval_batch_storage"] = "single_authority_rewrite",
            ["approval_batch_derived_index_durable"] = derivedIndexDurable.ToString()
        };

    public Task<DesignConversionPostEvaluationTrainingEligibility> EvaluatePostEvaluationTrainingEligibilityAsync(
        DesignConversionLocalArtifactDbRecord record,
        CancellationToken ct = default)
        => _postEvaluationTrainingEligibilityPolicy.EvaluateAsync(record, ct);

    public Task<IReadOnlyList<
        DesignConversionPostEvaluationTrainingEligibility>>
        EvaluatePostEvaluationTrainingEligibilityManyAsync(
            IReadOnlyList<DesignConversionLocalArtifactDbRecord?> records,
            CancellationToken ct = default)
        => _postEvaluationTrainingEligibilityPolicy.EvaluateManyAsync(
            records,
            ct);

    public async Task<OperationResult<
        DesignConversionPostEvaluationTrainingSnapshot>>
        ListRecordsWithPostEvaluationTrainingEligibilityAsync(
            DesignConversionLocalArtifactDbQuery? query = null,
            CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
        {
            return Cancelled<
                DesignConversionPostEvaluationTrainingSnapshot>();
        }

        var scan = await ReadAuthorityRecordLinesCoreAsync(ct);
        if (!scan.IsSuccess)
        {
            return scan.MapError<
                DesignConversionPostEvaluationTrainingSnapshot>();
        }

        var authorityScan = scan.Value!;
        var authorityRecords =
            authorityScan.Lines.Select(line => line.Record).ToArray();
        var eligibility =
            await _postEvaluationTrainingEligibilityPolicy.EvaluateManyAsync(
                authorityRecords,
                ct);
        var exactEligibility = authorityRecords
            .Select((_, index) =>
                index < eligibility.Count
                    ? eligibility[index]
                    : DesignConversionPostEvaluationTrainingEligibility
                        .Denied(
                            DesignConversionPostEvaluationTrainingEligibilityPolicy
                                .EvaluatorUnavailableReason,
                            DesignConversionPostEvaluationTrainingEligibilityPolicy
                                .EvaluatorUnavailableErrorCode))
            .ToArray();

        var eligibleRecordIds = authorityRecords
            .Where((_, index) => exactEligibility[index].IsEligible)
            .Select(record => record.RecordId)
            .ToHashSet(StringComparer.Ordinal);
        var refreshedIndex = BuildIndex(
            authorityScan,
            eligibleRecordIds);
        var currentIndex = await TryReadUsableDurableIndexAsync(
            authorityScan.Fingerprint,
            ct);
        if (currentIndex is null ||
            currentIndex.ApprovedTrainingCandidateCount !=
            refreshedIndex.ApprovedTrainingCandidateCount)
        {
            await TryWriteDerivedIndexAsync(refreshedIndex, ct);
        }

        var effectiveQuery =
            query ?? new DesignConversionLocalArtifactDbQuery();
        var materializedRecords =
            MaterializeRecoveredAuthorityRecords(authorityScan);
        var paired = materializedRecords
            .Select((record, index) => new
            {
                Record = record,
                Eligibility = exactEligibility[index]
            })
            .Where(item =>
                MatchesRecord(
                    item.Record,
                    effectiveQuery,
                    item.Eligibility.IsEligible))
            .OrderBy(item => item.Record.CreatedAtUtc)
            .ThenBy(item => item.Record.RecordId, StringComparer.Ordinal)
            .ToArray();

        return OperationResult<
            DesignConversionPostEvaluationTrainingSnapshot>.Ok(
            new DesignConversionPostEvaluationTrainingSnapshot(
                paired.Select(item => item.Record).ToArray(),
                paired.Select(item => item.Eligibility).ToArray()));
    }

    private async Task<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>
        FilterPostEvaluationTrainingEligibleAsync(
            IReadOnlyList<DesignConversionLocalArtifactDbRecord> records,
            CancellationToken ct)
    {
        var eligibility =
            await _postEvaluationTrainingEligibilityPolicy.EvaluateManyAsync(
                records,
                ct);
        return records
            .Where((_, index) => eligibility[index].IsEligible)
            .ToArray();
    }

    public async Task<OperationResult<DesignConversionDpoDisplayResult>> QueryDisplayRowsAsync(
        DesignConversionDpoDisplayQuery? query = null,
        CancellationToken ct = default)
    {
        if (ct.IsCancellationRequested)
            return OperationResult<DesignConversionDpoDisplayResult>.Fail(
                "DesignConversion local artifact DB query cancelled.",
                "CANCELLED");

        var records = await ListRecordsAsync(null, ct);
        if (!records.IsSuccess)
            return records.MapError<DesignConversionDpoDisplayResult>();

        var eligibleRecords =
            await FilterPostEvaluationTrainingEligibleAsync(
                records.Value!,
                ct);
        var trainingRecords = eligibleRecords
            .SelectMany(record => record.DpoCandidates)
            .Select(candidate => candidate.TrainingRecord)
            .ToArray();
        var candidateMetadataByDisplayId =
            BuildCandidateMetadataByDisplayId(eligibleRecords);

        var display = new DesignConversionDpoDisplayBuilder().BuildDisplay(trainingRecords, query);
        if (!display.IsSuccess)
            return display;

        return OperationResult<DesignConversionDpoDisplayResult>.Ok(
            ApplyRuntimeReviewBoundary(display.Value!, candidateMetadataByDisplayId));
    }

    private static DesignConversionDpoDisplayResult ApplyRuntimeReviewBoundary(
        DesignConversionDpoDisplayResult display,
        IReadOnlyDictionary<string, IReadOnlyDictionary<string, string>> candidateMetadataByDisplayId)
    {
        var rows = display.Rows
            .Select(row => ApplyRuntimeReviewBoundary(row, candidateMetadataByDisplayId))
            .ToArray();
        var hasRuntimeReviewPending = rows.Any(row =>
            string.Equals(
                ReadMetadata(row.BoundaryMetadata, "review_status"),
                RuntimeCandidateReviewPendingStatus,
                StringComparison.Ordinal));
        var hasRuntimeReviewApproved = rows.Any(row =>
            string.Equals(
                ReadMetadata(row.BoundaryMetadata, "review_status"),
                RuntimeCandidateReviewApprovedStatus,
                StringComparison.Ordinal));

        return display with
        {
            Rows = rows,
            Warnings = display.Warnings
                .Concat(hasRuntimeReviewPending
                    ?
                    [
                        "runtime_created_dpo_candidate_review_pending",
                        "runtime_created_dpo_candidate_approval_required",
                        "approved_for_training=false",
                        "production_dpo=false",
                        "model_readiness_claimed=false"
                    ]
                    : [])
                .Concat(hasRuntimeReviewApproved
                    ?
                    [
                        "runtime_created_dpo_candidate_approved_for_training",
                        "approval_status=approved",
                        "approved_for_training=true",
                        "production_dpo=false",
                        "model_readiness_claimed=false"
                    ]
                    : [])
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray()
        };
    }

    private static DesignConversionDpoDisplayRow ApplyRuntimeReviewBoundary(
        DesignConversionDpoDisplayRow row,
        IReadOnlyDictionary<string, IReadOnlyDictionary<string, string>> candidateMetadataByDisplayId)
    {
        var approvalMetadata = candidateMetadataByDisplayId.TryGetValue(row.DisplayId, out var candidateMetadata)
            ? candidateMetadata
            : row.BoundaryMetadata;
        if (!IsRuntimeCreatedReviewRow(row.BoundaryMetadata) &&
            !IsRuntimeCreatedReviewRow(approvalMetadata))
        {
            return row;
        }

        var approved = IsApprovedReviewMetadata(approvalMetadata);
        var approvalStatus = approved ? "approved" : "pending";
        var reviewStatus = approved ? RuntimeCandidateReviewApprovedStatus : RuntimeCandidateReviewPendingStatus;
        var readinessBoundary = approved ? row.ReadinessBoundary : RuntimeCandidateReviewPendingStatus;
        var metadata = new Dictionary<string, string>(row.BoundaryMetadata, StringComparer.Ordinal)
        {
            ["runtime_created_dpo_candidate"] = bool.TrueString,
            ["review_required"] = bool.TrueString,
            ["approval_required"] = bool.TrueString,
            ["approval_status"] = approvalStatus,
            ["review_status"] = reviewStatus,
            ["approved_for_training"] = approved.ToString(),
            ["training_candidate_only"] = row.TrainingCandidateOnly.ToString(),
            ["production_dpo"] = bool.FalseString,
            ["product_not_ready"] = bool.TrueString,
            ["model_readiness_claimed"] = bool.FalseString,
            ["heldout"] = bool.FalseString,
            ["held_out_not_proven"] = bool.TrueString,
            ["source_disjoint_not_proven"] = bool.TrueString,
            ["api_train_ready"] = approved.ToString()
        };
        CopyApprovalMetadata(approvalMetadata, metadata, "approved_by_ref");
        CopyApprovalMetadata(approvalMetadata, metadata, "approval_reason");
        CopyApprovalMetadata(approvalMetadata, metadata, "approved_at_utc");
        CopyApprovalMetadata(approvalMetadata, metadata, "local_reviewer_approval_evidence");

        return row with
        {
            ReadinessBoundary = readinessBoundary,
            UsefulnessFactors = row.UsefulnessFactors
                .Concat(
                [
                    reviewStatus,
                    "review_required=true",
                    $"approval_status={approvalStatus}",
                    $"approved_for_training={approved.ToString().ToLowerInvariant()}",
                    "training_candidate_only=true",
                    "production_dpo=false",
                    "model_readiness_claimed=false",
                    "held_out_not_proven=true",
                    "source_disjoint_not_proven=true"
                ])
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray(),
            EvidenceRefs = row.EvidenceRefs
                .Append($"design-conversion-dpo-display:{reviewStatus}")
                .Append("design-conversion-dpo-display:approval_required")
                .Append("design-conversion-dpo-display:not_production_dpo")
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray(),
            BoundaryMetadata = metadata
        };
    }

    private static IReadOnlyDictionary<string, IReadOnlyDictionary<string, string>> BuildCandidateMetadataByDisplayId(
        IReadOnlyList<DesignConversionLocalArtifactDbRecord> records)
    {
        var builder = new DesignConversionDpoDisplayBuilder();
        var map = new Dictionary<string, IReadOnlyDictionary<string, string>>(StringComparer.Ordinal);
        foreach (var candidate in records.SelectMany(record => record.DpoCandidates))
        {
            var display = builder.BuildDisplay(
                [candidate.TrainingRecord],
                new DesignConversionDpoDisplayQuery(IncludeBlocked: true));
            if (!display.IsSuccess || display.Value!.Rows.Count != 1)
                continue;

            var row = display.Value.Rows[0];
            map[row.DisplayId] = candidate.TrainingRecord.Provenance.Metadata;
        }

        return map;
    }

    private static void CopyApprovalMetadata(
        IReadOnlyDictionary<string, string> source,
        IDictionary<string, string> target,
        string key)
    {
        if (source.TryGetValue(key, out var value) && !string.IsNullOrWhiteSpace(value))
            target[key] = value;
    }

    private async Task<OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>> ReadRecordsCoreAsync(
        CancellationToken ct)
    {
        var scan = await ReadAuthorityRecordLinesCoreAsync(ct);
        if (!scan.IsSuccess)
            return scan.MapError<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>();

        return OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>.Ok(
            MaterializeRecoveredAuthorityRecords(scan.Value!));
    }

    private async Task<OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>> ReadRecordsAndHealDerivedIndexAsync(
        CancellationToken ct,
        bool forceDurableIndexHeal = false)
    {
        var scan = await ReadAuthorityRecordLinesCoreAsync(ct);
        if (!scan.IsSuccess)
            return scan.MapError<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>();

        var authorityScan = scan.Value!;
        var authorityRecords =
            authorityScan.Lines.Select(line => line.Record).ToArray();
        var eligibility =
            await _postEvaluationTrainingEligibilityPolicy.EvaluateManyAsync(
                authorityRecords,
                ct);
        var eligibleRecordIds = authorityRecords
            .Where((_, index) => eligibility[index].IsEligible)
            .Select(record => record.RecordId)
            .ToHashSet(StringComparer.Ordinal);
        // The authority file fingerprint cannot reveal a state-store-only
        // eligibility transition. Recompute it on every authority read, but
        // avoid rewriting an otherwise-current index when the derived count
        // did not change.
        var refreshedIndex = BuildIndex(
            authorityScan,
            eligibleRecordIds);
        var currentIndex = await TryReadUsableDurableIndexAsync(
            authorityScan.Fingerprint,
            ct);
        if (forceDurableIndexHeal ||
            currentIndex is null ||
            currentIndex.ApprovedTrainingCandidateCount !=
            refreshedIndex.ApprovedTrainingCandidateCount)
        {
            await TryWriteDerivedIndexAsync(refreshedIndex, ct);
        }

        return OperationResult<IReadOnlyList<DesignConversionLocalArtifactDbRecord>>.Ok(
            MaterializeRecoveredAuthorityRecords(authorityScan));
    }

    private static IReadOnlyList<DesignConversionLocalArtifactDbRecord> MaterializeRecoveredAuthorityRecords(
        AuthorityRecordScan scan)
    {
        var quarantineEvidenceValue = scan.QuarantinedLines.Count == 0
            ? string.Empty
            : BuildQuarantinedAuthorityLineEvidenceValue(scan.QuarantinedLines);
        var records = scan.Lines
            .Select(line => line.Record)
            .Select(record => WithLogicalQuarantineRecoveryEvidence(
                record,
                scan.QuarantinedLines.Count,
                quarantineEvidenceValue))
            .ToArray();
        if (!scan.HasUncommittedFinalRecord)
            return records;

        return records
            .Select(record => WithUncommittedFinalRecordRecoveryEvidence(record, scan))
            .ToArray();
    }

    private static DesignConversionLocalArtifactDbRecord WithLogicalQuarantineRecoveryEvidence(
        DesignConversionLocalArtifactDbRecord record,
        int quarantinedLineCount,
        string quarantineEvidenceValue)
    {
        if (quarantinedLineCount == 0)
            return record;

        var metadata = record.Metadata is null
            ? new Dictionary<string, string>(StringComparer.Ordinal)
            : new Dictionary<string, string>(record.Metadata, StringComparer.Ordinal);
        metadata["local_artifact_db_logical_quarantine_recovered"] = bool.TrueString;
        metadata["local_artifact_db_quarantined_authority_line_count"] =
            quarantinedLineCount.ToString(CultureInfo.InvariantCulture);
        metadata["local_artifact_db_quarantined_authority_bytes_preserved"] = bool.TrueString;
        metadata["local_artifact_db_quarantined_authority_lines"] = quarantineEvidenceValue;

        var evidenceRefs = (record.EvidenceRefs ?? Array.Empty<string>())
            .Append(LogicalQuarantinedAuthorityLineMarker)
            .Append(QuarantinedAuthorityBytesPreservedMarker)
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();

        return record with
        {
            EvidenceRefs = evidenceRefs,
            Metadata = metadata
        };
    }

    private static DesignConversionLocalArtifactDbRecord WithUncommittedFinalRecordRecoveryEvidence(
        DesignConversionLocalArtifactDbRecord record,
        AuthorityRecordScan scan)
    {
        var metadata = record.Metadata is null
            ? new Dictionary<string, string>(StringComparer.Ordinal)
            : new Dictionary<string, string>(record.Metadata, StringComparer.Ordinal);
        metadata["local_artifact_db_uncommitted_final_record_recovered"] = bool.TrueString;
        metadata["local_artifact_db_uncommitted_final_record_committed"] = bool.FalseString;
        metadata["local_artifact_db_uncommitted_final_record_line"] =
            (scan.UncommittedFinalLineNumber ?? 0).ToString(CultureInfo.InvariantCulture);
        metadata["local_artifact_db_uncommitted_final_record_byte_offset"] =
            (scan.UncommittedFinalByteOffset ?? 0).ToString(CultureInfo.InvariantCulture);
        metadata["local_artifact_db_committed_length_bytes"] = scan.CommittedLength.ToString(CultureInfo.InvariantCulture);
        metadata["local_artifact_db_records_file_length_bytes"] = scan.Fingerprint.Length.ToString(CultureInfo.InvariantCulture);

        var evidenceRefs = (record.EvidenceRefs ?? Array.Empty<string>())
            .Append(UncommittedFinalRecordRecoveredMarker)
            .Append(UncommittedFinalRecordNotCommittedMarker)
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();

        return record with
        {
            EvidenceRefs = evidenceRefs,
            Metadata = metadata
        };
    }

    private async Task<OperationResult<AuthorityRecordScan>> ReadAuthorityRecordLinesCoreAsync(
        CancellationToken ct)
    {
        var startFingerprint = GetRecordsFileFingerprint();
        if (!startFingerprint.Exists)
            return OperationResult<AuthorityRecordScan>.Ok(
                new AuthorityRecordScan(
                    [],
                    [],
                    startFingerprint,
                    CommittedLength: 0,
                    NextAppendLineNumber: 1,
                    HasUncommittedFinalRecord: false,
                    UncommittedFinalLineNumber: null,
                    UncommittedFinalByteOffset: null));

        var lines = new List<AuthorityRecordLine>();
        var quarantinedLines = new List<DesignConversionLocalArtifactDbQuarantinedAuthorityLine>();
        try
        {
            await using var stream = new FileStream(
                _recordsPath,
                FileMode.Open,
                FileAccess.Read,
                FileShare.Read,
                bufferSize: 8192,
                FileOptions.Asynchronous | FileOptions.SequentialScan);
            var buffer = new byte[8192];
            using var currentLine = new MemoryStream();
            var lineStartOffset = 0L;
            var lineNumber = 0;
            var committedLength = 0L;
            var hasUncommittedFinalRecord = false;
            int? uncommittedFinalLineNumber = null;
            long? uncommittedFinalByteOffset = null;

            while (true)
            {
                var read = await stream.ReadAsync(buffer.AsMemory(0, buffer.Length), ct);
                if (read == 0)
                    break;

                for (var index = 0; index < read; index++)
                {
                    if (currentLine.Length >= MaxIndexedRecordLineByteLength)
                        return InvalidAuthorityRecordLine(lineNumber + 1).MapError<AuthorityRecordScan>();

                    currentLine.WriteByte(buffer[index]);
                    if (buffer[index] != (byte)'\n')
                        continue;

                    lineNumber++;
                    var parsed = ParseAuthorityRecordLineBytes(
                        currentLine.ToArray(),
                        lineStartOffset,
                        lineNumber,
                        quarantinedLines.Count < MaxLogicallyQuarantinedAuthorityLinesPerScan);
                    if (!parsed.IsSuccess)
                        return parsed.MapError<AuthorityRecordScan>();
                    if (parsed.Value?.RecordLine is not null)
                        lines.Add(parsed.Value.RecordLine);
                    if (parsed.Value?.QuarantinedLine is not null)
                        quarantinedLines.Add(parsed.Value.QuarantinedLine);

                    lineStartOffset += currentLine.Length;
                    committedLength = lineStartOffset;
                    currentLine.SetLength(0);
                    currentLine.Position = 0;
                }
            }

            if (currentLine.Length > 0)
            {
                hasUncommittedFinalRecord = true;
                uncommittedFinalLineNumber = lineNumber + 1;
                uncommittedFinalByteOffset = lineStartOffset;
            }

            var endFingerprint = GetRecordsFileFingerprint();
            if (!endFingerprint.Equals(startFingerprint))
                return LocalArtifactDbWriteFailed<AuthorityRecordScan>();

            return OperationResult<AuthorityRecordScan>.Ok(new AuthorityRecordScan(
                lines,
                quarantinedLines,
                endFingerprint,
                committedLength,
                NextAppendLineNumber: lineNumber + 1,
                hasUncommittedFinalRecord,
                uncommittedFinalLineNumber,
                uncommittedFinalByteOffset));
        }
        catch (DecoderFallbackException)
        {
            return OperationResult<AuthorityRecordScan>.Fail(
                "DesignConversion local artifact DB records could not be read because the records file is not valid UTF-8.",
                InvalidUtf8ErrorCode);
        }
    }

    private static OperationResult<AuthorityLineParseResult?> ParseAuthorityRecordLineBytes(
        byte[] lineBytes,
        long byteOffset,
        int lineNumber,
        bool canQuarantineLine)
    {
        var line = DecodeAuthorityJsonLine(lineBytes, byteOffset == 0);
        if (string.IsNullOrWhiteSpace(line))
            return OperationResult<AuthorityLineParseResult?>.Ok(null);

        DesignConversionLocalArtifactDbRecord? record;
        try
        {
            record = JsonSerializer.Deserialize<DesignConversionLocalArtifactDbRecord>(
                line,
                JsonOptions);
        }
        catch (JsonException)
        {
            return BuildQuarantinedAuthorityLineParseResult(
                lineBytes,
                byteOffset,
                lineNumber,
                canQuarantineLine);
        }

        if (record is null ||
            !DesignConversionLocalArtifactDbRecord
                .HasValidImprovementLoopAttemptHistoryMetadata(record))
        {
            return BuildQuarantinedAuthorityLineParseResult(
                lineBytes,
                byteOffset,
                lineNumber,
                canQuarantineLine);
        }

        return OperationResult<AuthorityLineParseResult?>.Ok(
            new AuthorityLineParseResult(
                RecordLine: new AuthorityRecordLine(
                    Record: record,
                    CurrentRecordJson: line,
                    ByteOffset: byteOffset,
                    ByteLength: lineBytes.LongLength,
                    LineNumber: lineNumber,
                    AuthorityLineSha256: $"sha256:{HashBytes(lineBytes)}"),
                QuarantinedLine: null));
    }

    private static OperationResult<AuthorityLineParseResult?> BuildQuarantinedAuthorityLineParseResult(
        byte[] lineBytes,
        long byteOffset,
        int lineNumber,
        bool canQuarantineLine)
    {
        if (!canQuarantineLine)
            return LogicalAuthorityQuarantineLimitExceeded(lineNumber);

        return OperationResult<AuthorityLineParseResult?>.Ok(
            new AuthorityLineParseResult(
                RecordLine: null,
                QuarantinedLine: BuildQuarantinedAuthorityLine(lineBytes, byteOffset, lineNumber)));
    }

    private static DesignConversionLocalArtifactDbQuarantinedAuthorityLine BuildQuarantinedAuthorityLine(
        byte[] lineBytes,
        long byteOffset,
        int lineNumber)
        => new(
            PhysicalLineNumber: lineNumber,
            ByteOffset: byteOffset,
            ByteLength: lineBytes.LongLength,
            AuthorityLineSha256: $"sha256:{HashBytes(lineBytes)}");

    private static string BuildQuarantinedAuthorityLineEvidenceValue(
        IReadOnlyList<DesignConversionLocalArtifactDbQuarantinedAuthorityLine> quarantinedLines)
        => string.Join(
            "|",
            quarantinedLines
                .OrderBy(line => line.ByteOffset)
                .ThenBy(line => line.PhysicalLineNumber)
                .Select(line =>
                    $"line={line.PhysicalLineNumber.ToString(CultureInfo.InvariantCulture)};" +
                    $"byte_offset={line.ByteOffset.ToString(CultureInfo.InvariantCulture)};" +
                    $"byte_length={line.ByteLength.ToString(CultureInfo.InvariantCulture)};" +
                    $"sha256_ref={line.AuthorityLineSha256}"));

    private static OperationResult<IReadOnlyList<TRecord>> InvalidRecordLine<TRecord>(int lineNumber)
        => OperationResult<IReadOnlyList<TRecord>>.Fail(
            $"DesignConversion local artifact DB line {lineNumber.ToString(CultureInfo.InvariantCulture)} could not be read.",
            "DESIGN_CONVERSION_LOCAL_ARTIFACT_DB_LINE_INVALID");

    private static OperationResult<AuthorityRecordLine?> InvalidAuthorityRecordLine(int lineNumber)
        => OperationResult<AuthorityRecordLine?>.Fail(
            $"DesignConversion local artifact DB line {lineNumber.ToString(CultureInfo.InvariantCulture)} could not be read.",
            "DESIGN_CONVERSION_LOCAL_ARTIFACT_DB_LINE_INVALID");

    private static OperationResult<AuthorityLineParseResult?> LogicalAuthorityQuarantineLimitExceeded(int lineNumber)
        => OperationResult<AuthorityLineParseResult?>.Fail(
            $"DesignConversion local artifact DB logical quarantine limit was exceeded at line {lineNumber.ToString(CultureInfo.InvariantCulture)}.",
            LocalArtifactDbAuthorityLogicalQuarantineLimitExceededErrorCode);

    private async Task<OperationResult<bool>> WriteRecordsCoreAsync(
        IReadOnlyList<DesignConversionLocalArtifactDbRecord> records,
        CancellationToken ct,
        IReadOnlySet<string>? knownEligibleRecordIds = null)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<bool>();

        Directory.CreateDirectory(_rootDirectory);
        var rewrite = await RewriteRecordsAuthorityThroughTempAsync(records, ct);
        if (!rewrite.IsSuccess)
            return rewrite;

        // File.Move уже сделал новый журнал властью. С этого места отмена вызывающей
        // стороны не может превратить совершённый commit в ложный ответ «не записано».
        _recordsMutationContext.CachedAuthorityState = null;
        if (!rewrite.Value)
            return OperationResult<bool>.Ok(false);

        try
        {
            // Это второй и последний scan authority-журнала в успешной пачке:
            // первый дал проверяемый снимок до мутации, а этот перечитывает уже
            // зафиксированные байты для точного кеша и производного индекса.
            var scan = await ReadAuthorityRecordLinesCoreAsync(CancellationToken.None);
            if (!scan.IsSuccess)
                return OperationResult<bool>.Ok(false);

            var authorityRecords =
                scan.Value!.Lines.Select(line => line.Record).ToArray();
            var eligibleRecordIds = knownEligibleRecordIds;
            if (eligibleRecordIds is null)
            {
                var eligibility =
                    await _postEvaluationTrainingEligibilityPolicy.EvaluateManyAsync(
                        authorityRecords,
                        CancellationToken.None);
                eligibleRecordIds = authorityRecords
                    .Where((_, index) => eligibility[index].IsEligible)
                    .Select(record => record.RecordId)
                    .ToHashSet(StringComparer.Ordinal);
            }

            var authorityState = BuildAuthorityState(
                scan.Value!,
                eligibleRecordIds);
            PublishCachedAuthorityStateFromCommittedAuthority(authorityState);

            var derivedIndexDurable = await TryWriteDerivedIndexAsync(
                authorityState.Index,
                CancellationToken.None);
            return OperationResult<bool>.Ok(derivedIndexDurable);
        }
        catch (Exception)
        {
            // Журнал уже заменён атомарно. Любой сбой вторичного чтения или индекса
            // становится отложенным ремонтом, а не ложным отказом всей операции.
            _recordsMutationContext.CachedAuthorityState = null;
            return OperationResult<bool>.Ok(false);
        }
    }

    private async Task<OperationResult<bool>> RewriteRecordsAuthorityThroughTempAsync(
        IReadOnlyList<DesignConversionLocalArtifactDbRecord> records,
        CancellationToken ct)
    {
        var tempPath = BuildRecordsRewriteTempPath();
        try
        {
            await using (var stream = new FileStream(
                tempPath,
                FileMode.CreateNew,
                FileAccess.Write,
                FileShare.None,
                bufferSize: 4096,
                FileOptions.Asynchronous | FileOptions.WriteThrough))
            await using (var writer = new StreamWriter(
                stream,
                StrictUtf8Encoding,
                bufferSize: 4096,
                leaveOpen: true))
            {
                long projectedAuthorityLength = 0;
                foreach (var record in records)
                {
                    ct.ThrowIfCancellationRequested();
                    var line = JsonSerializer.Serialize(record, JsonOptions);
                    var committedLineBytes = BuildAppendedAuthorityLineBytes(
                        line,
                        projectedAuthorityLength);
                    // Перепись держит тот же лимит строки, что и обычное добавление:
                    // безопасная замена журнала не должна протащить запись, которую
                    // обычный append справедливо отклонил бы.
                    if (committedLineBytes.LongLength > MaxIndexedRecordLineByteLength)
                        return LocalArtifactDbWriteFailed<bool>();
                    if (!TryProjectCommittedAuthorityLength(
                            projectedAuthorityLength,
                            committedLineBytes.LongLength,
                            out projectedAuthorityLength) ||
                        projectedAuthorityLength > _recordsAuthorityMaxBytes)
                    {
                        return LocalArtifactDbAuthorityQuotaExceeded<bool>();
                    }

                    await writer.WriteLineAsync(line.AsMemory(), ct);
                }

                ct.ThrowIfCancellationRequested();
                await writer.FlushAsync(ct);
                await stream.FlushAsync(ct);
            }

            ct.ThrowIfCancellationRequested();
            _recordsAuthorityRewriteObserverForTesting?.Invoke();
            // Наблюдатель в тесте стоит ровно перед заменой файла. Если отмена пришла
            // в этот момент, временный файл удаляется, а старый журнал остается главным.
            ct.ThrowIfCancellationRequested();
            File.Move(tempPath, _recordsPath, overwrite: true);

            try
            {
                _recordsAuthorityReplacedObserverForTesting?.Invoke();
            }
            catch (Exception)
            {
                // Тестовый шов моделирует сбой сразу после commit. Сам журнал уже
                // главный; вызывающая сторона получает успех с отложенным индексом.
                return OperationResult<bool>.Ok(false);
            }

            return OperationResult<bool>.Ok(true);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            DeleteRecordsRewriteTempBestEffort(tempPath);
            return Cancelled<bool>();
        }
        catch (IOException)
        {
            DeleteRecordsRewriteTempBestEffort(tempPath);
            return LocalArtifactDbWriteFailed<bool>();
        }
        catch (UnauthorizedAccessException)
        {
            DeleteRecordsRewriteTempBestEffort(tempPath);
            return LocalArtifactDbWriteFailed<bool>();
        }
        finally
        {
            DeleteRecordsRewriteTempBestEffort(tempPath);
        }
    }

    private string BuildRecordsRewriteTempPath()
        => Path.Combine(_rootDirectory, $"{RecordsFileName}.{Guid.NewGuid():N}.rewrite.tmp");

    private static void DeleteRecordsRewriteTempBestEffort(string tempPath)
    {
        try
        {
            if (File.Exists(tempPath))
                File.Delete(tempPath);
        }
        catch (IOException)
        {
            // Best-effort cleanup must not replace the write/cancellation outcome.
        }
        catch (UnauthorizedAccessException)
        {
            // Best-effort cleanup must not replace the write/cancellation outcome.
        }
        catch (System.Security.SecurityException)
        {
            // Best-effort cleanup must not replace the write/cancellation outcome.
        }
    }

    private DesignConversionLocalArtifactDbIndex BuildIndex(
        AuthorityRecordScan scan,
        IReadOnlySet<string>? eligibleRecordIds = null)
    {
        var index = BuildIndex(
            scan.Lines,
            scan.QuarantinedLines,
            scan.Fingerprint,
            eligibleRecordIds);
        if (!scan.HasUncommittedFinalRecord)
            return WithoutUncommittedFinalRecordIndexEvidence(index);

        return index with
        {
            EvidenceMarkers = (index.EvidenceMarkers ?? [])
                .Concat(
                [
                    UncommittedFinalRecordRecoveredMarker,
                    UncommittedFinalRecordNotCommittedMarker
                ])
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray()
        };
    }

    private static DesignConversionLocalArtifactDbIndex WithoutUncommittedFinalRecordIndexEvidence(
        DesignConversionLocalArtifactDbIndex index)
        => index with
        {
            EvidenceMarkers = (index.EvidenceMarkers ?? [])
                .Where(marker => !string.Equals(marker, UncommittedFinalRecordRecoveredMarker, StringComparison.Ordinal)
                                 && !string.Equals(marker, UncommittedFinalRecordNotCommittedMarker, StringComparison.Ordinal))
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray()
        };

    private DesignConversionLocalArtifactDbIndex BuildIndex(
        IReadOnlyList<AuthorityRecordLine> recordLines,
        IReadOnlyList<DesignConversionLocalArtifactDbQuarantinedAuthorityLine> quarantinedLines,
        RecordsFileFingerprint fingerprint,
        IReadOnlySet<string>? eligibleRecordIds = null)
    {
        var records = recordLines.Select(line => line.Record).ToArray();
        eligibleRecordIds ??= new HashSet<string>(StringComparer.Ordinal);
        var evidenceMarkers = new List<string>
        {
            StorageTrainingArtifactDbMarker,
            LocalArtifactDbKind,
            ConversionResultMarker,
            RenderArtifactRefsMarker,
            VisualJudgeStatusMarker,
            DpoCandidateMarker,
            UsefulnessScoreMarker,
            QuarantineMarker,
            TrainingCandidateOnlyMarker,
            ProductNotReadyMarker,
            "approved_training_candidate_count_post_evaluation_state_cache",
            "production_db_ready:false"
        };
        if (quarantinedLines.Count > 0)
        {
            evidenceMarkers.Add(LogicalQuarantinedAuthorityLineMarker);
            evidenceMarkers.Add(QuarantinedAuthorityBytesPreservedMarker);
            evidenceMarkers.Add($"local_artifact_db:quarantined_authority_line_count:{quarantinedLines.Count.ToString(CultureInfo.InvariantCulture)}");
        }

        return new DesignConversionLocalArtifactDbIndex(
            DatabaseKind: LocalArtifactDbKind,
            SchemaVersion: SchemaVersion,
            RecordCount: records.Length,
            ApprovedTrainingCandidateCount: records
                .Where(record =>
                    eligibleRecordIds.Contains(record.RecordId))
                .SelectMany(record => record.DpoCandidates)
                .Count(IsApprovedTrainingCandidate),
            UpdatedAtUtc: DateTimeOffset.UtcNow,
            EvidenceMarkers: evidenceMarkers
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray())
        {
            RootDirectoryBindingHash = BuildRootDirectoryBindingHash(_rootDirectory),
            TenantBindingHash = TenantBindingNotApplicable,
            RecordsFileName = RecordsFileName,
            RecordsFileLength = fingerprint.Exists ? fingerprint.Length : 0,
            RecordsFileLastWriteTimeUtcTicks = fingerprint.Exists ? fingerprint.LastWriteTimeUtc.Ticks : DateTime.MinValue.Ticks,
            RecordLocators = recordLines
                .Select(line => BuildIndexRecordLocator(
                    line.Record,
                    line.ByteOffset,
                    line.ByteLength,
                    line.LineNumber,
                    line.AuthorityLineSha256))
                .ToArray(),
            QuarantinedAuthorityLines = quarantinedLines
                .OrderBy(line => line.ByteOffset)
                .ThenBy(line => line.PhysicalLineNumber)
                .ToArray()
        };
    }

    private static DesignConversionLocalArtifactDbRecord NormalizeRecord(
        DesignConversionLocalArtifactDbRecord record,
        string? canonicalImprovementLoopAttemptHistory)
    {
        var redactions = new SortedSet<string>(StringComparer.Ordinal);
        var visualStatus = NormalizeVisualJudgeStatus(record.VisualJudgeStatus, redactions);
        var candidates = (record.DpoCandidates ?? [])
            .Select(candidate => NormalizeCandidate(candidate, visualStatus, redactions))
            .ToArray();
        var hasRuntimeCandidate = candidates.Any(IsRuntimeCreatedCandidate);
        var hasApprovedRuntimeCandidate = candidates.Any(candidate =>
            IsRuntimeCreatedCandidate(candidate) && IsReviewApprovedForTraining(candidate));
        var hasPendingRuntimeCandidate = candidates.Any(candidate =>
            IsRuntimeCreatedCandidate(candidate) && !IsReviewApprovedForTraining(candidate));
        var sanitizedSourceRefs =
            DesignConversionDpoLeakageGuard.SanitizeMetadata(
                record.SanitizedSourceRefs,
                "source_refs",
                redactions);

        var callerMetadata = (record.Metadata ?? new Dictionary<string, string>())
            .Where(pair =>
                !string.Equals(
                    pair.Key,
                    ImmutableAppendFingerprintMetadataKey,
                    StringComparison.Ordinal) &&
                !string.Equals(
                    pair.Key,
                    DesignConversionLocalArtifactDbRecord
                        .ImprovementLoopAttemptHistoryMetadataKey,
                    StringComparison.Ordinal))
            .ToDictionary(pair => pair.Key, pair => pair.Value, StringComparer.Ordinal);
        var metadata = new Dictionary<string, string>(
            DesignConversionDpoLeakageGuard.SanitizeMetadata(callerMetadata, "local_artifact_db_metadata", redactions),
            StringComparer.Ordinal)
        {
            ["storage_training_artifact_db"] = bool.TrueString,
            ["local_artifact_db"] = bool.TrueString,
            ["production_db_ready"] = bool.FalseString,
            ["product_ready"] = bool.FalseString,
            ["product_not_ready"] = bool.TrueString,
            ["training_candidate_only"] = candidates.Any(candidate => candidate.TrainingCandidateOnly).ToString(),
            ["training_grade"] = bool.FalseString,
            ["not_training_grade"] = bool.TrueString,
            ["training_grade_boundary"] = "local_artifact_db_training_candidate_not_training_grade",
            ["runtime_created_dpo_candidate"] = hasRuntimeCandidate.ToString(),
            ["review_required"] = hasRuntimeCandidate.ToString(),
            ["approval_status"] = hasRuntimeCandidate
                ? hasPendingRuntimeCandidate ? "pending" : "approved"
                : "not-required",
            ["approved_for_training"] = hasRuntimeCandidate
                ? hasApprovedRuntimeCandidate.ToString()
                : candidates.Any(IsApprovedTrainingCandidate).ToString(),
            ["production_dpo"] = bool.FalseString,
            ["model_readiness_claimed"] = bool.FalseString
        };
        AddTrainingDatabaseDurabilityMetadata(
            metadata,
            SchemaVersion,
            "conversion-results",
            Math.Max(1, candidates.Length),
            sanitizedSourceRefs
                .Values
                .Concat(candidates.Select(candidate => candidate.TrainingRecord.Provenance.SourceManifestRef)),
            [
                record.RecordId,
                record.JobId,
                record.RequestId,
                record.SourceKind,
                candidates.Length.ToString(CultureInfo.InvariantCulture),
                string.Join(",", candidates.Select(candidate => candidate.TrainingRecord.RecordId).Order(StringComparer.Ordinal))
            ]);
        if (redactions.Count > 0)
            metadata["redaction_codes"] = string.Join(",", redactions);
        if (canonicalImprovementLoopAttemptHistory is not null)
        {
            metadata[
                DesignConversionLocalArtifactDbRecord
                    .ImprovementLoopAttemptHistoryMetadataKey] =
                canonicalImprovementLoopAttemptHistory;
        }

        var normalized = record with
        {
            RecordId = SafeScalar(record.RecordId, "record_id", redactions, "artifact-db-record"),
            DatabaseKind = LocalArtifactDbKind,
            JobId = SafeScalar(record.JobId, "job_id", redactions, "job"),
            RequestId = SafeScalar(record.RequestId, "request_id", redactions, "request"),
            SourceKind = SafeScalar(record.SourceKind, "source_kind", redactions, "unknown"),
            Tier = SafeScalar(record.Tier, "tier", redactions, "unspecified"),
            SanitizedSourceRefs = sanitizedSourceRefs,
            ConversionResult = NormalizeConversionResult(record.ConversionResult, redactions),
            RenderArtifactRefs = (record.RenderArtifactRefs ?? [])
                .Select(render => NormalizeRenderArtifactRef(render, redactions))
                .ToArray(),
            VisualJudgeStatus = visualStatus,
            DpoCandidates = candidates,
            CreatedAtUtc = record.CreatedAtUtc == default ? DateTimeOffset.UtcNow : record.CreatedAtUtc,
            EvidenceRefs = (record.EvidenceRefs ?? [])
                .Select(reference => SafeArtifactRef(reference, "evidence_ref", redactions))
                .Append(StorageTrainingArtifactDbMarker)
                .Append(LocalArtifactDbKind)
                .Append(ConversionResultMarker)
                .Append(RenderArtifactRefsMarker)
                .Append(VisualJudgeStatusMarker)
                .Append(DpoCandidateMarker)
                .Append(UsefulnessScoreMarker)
                .Append(QuarantineMarker)
                .Append(TrainingCandidateOnlyMarker)
                .Append(ProductNotReadyMarker)
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray(),
            Metadata = metadata
        };

        var persistedMetadata = new Dictionary<string, string>(normalized.Metadata, StringComparer.Ordinal)
        {
            [ImmutableAppendFingerprintMetadataKey] = BuildImmutableAppendFingerprint(normalized)
        };
        return normalized with { Metadata = persistedMetadata };
    }

    private static DesignConversionConversionResultArtifact NormalizeConversionResult(
        DesignConversionConversionResultArtifact? result,
        SortedSet<string> redactions)
    {
        result ??= new DesignConversionConversionResultArtifact(
            ResultId: "conversion-result-missing",
            HtmlRef: string.Empty,
            HtmlSha256: string.Empty,
            CssRef: string.Empty,
            CssSha256: string.Empty,
            Metadata: new Dictionary<string, string>());

        var htmlHash = NormalizeSha256(result.HtmlSha256, result.HtmlRef);
        var cssHash = NormalizeSha256(result.CssSha256, result.CssRef);
        var metadata = new Dictionary<string, string>(
            DesignConversionDpoLeakageGuard.SanitizeMetadata(result.Metadata, "conversion_result_metadata", redactions),
            StringComparer.Ordinal)
        {
            ["conversion_result"] = "html_css_refs_or_hashes_only",
            ["raw_html_included"] = bool.FalseString,
            ["raw_css_included"] = bool.FalseString
        };

        return new DesignConversionConversionResultArtifact(
            ResultId: SafeScalar(result.ResultId, "conversion_result_id", redactions, "conversion-result"),
            HtmlRef: PayloadRef("html_result", result.HtmlRef, redactions),
            HtmlSha256: htmlHash,
            CssRef: PayloadRef("css_result", result.CssRef, redactions),
            CssSha256: cssHash,
            Metadata: metadata);
    }

    private static DesignConversionRenderArtifactDbRef NormalizeRenderArtifactRef(
        DesignConversionRenderArtifactDbRef render,
        SortedSet<string> redactions)
        => new(
            ViewportId: SafeScalar(render.ViewportId, "render_viewport_id", redactions, "viewport"),
            ArtifactId: SafeScalar(render.ArtifactId, "render_artifact_id", redactions, "render-artifact"),
            Kind: SafeScalar(render.Kind, "render_artifact_kind", redactions, "render_artifact"),
            UriRef: SafeArtifactRef(render.UriRef, "render_artifact_uri", redactions),
            Sha256: NormalizeSha256(render.Sha256, render.UriRef),
            ByteLength: Math.Max(0, render.ByteLength),
            Width: Math.Max(0, render.Width),
            Height: Math.Max(0, render.Height),
            Metadata: DesignConversionDpoLeakageGuard.SanitizeMetadata(
                render.Metadata,
                "render_artifact_metadata",
                redactions));

    private static DesignConversionVisualJudgeArtifactDbStatus NormalizeVisualJudgeStatus(
        DesignConversionVisualJudgeArtifactDbStatus? status,
        SortedSet<string> redactions)
    {
        status ??= new DesignConversionVisualJudgeArtifactDbStatus(
            Status: DesignConversionVisualQaBoundaryPolicy.ProviderRequired,
            ProviderBoundary: DesignConversionVisualQaBoundaryPolicy.ProviderRequired,
            ExternalCallExecuted: false,
            EstimatedCostUsd: null,
            TierDecision: DesignConversionVisualQaBoundaryPolicy.ProviderRequired,
            EvidenceRefs: [DesignConversionVisualQaBoundaryPolicy.VisualJudgeProviderRequiredMarker],
            Metadata: new Dictionary<string, string>());

        var rawMetadata = status.Metadata ?? new Dictionary<string, string>();
        rawMetadata.TryGetValue(
            DesignConversionLocalArtifactDbRecord.CompletedStatusSnapshotMetadataKey,
            out var serializedSnapshot);
        var metadataWithoutSnapshot = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var pair in rawMetadata)
        {
            if (!string.Equals(
                    pair.Key,
                    DesignConversionLocalArtifactDbRecord.CompletedStatusSnapshotMetadataKey,
                    StringComparison.Ordinal))
            {
                metadataWithoutSnapshot[pair.Key] = pair.Value;
            }
        }

        var metadata = new Dictionary<string, string>(
            DesignConversionDpoLeakageGuard.SanitizeMetadata(
                metadataWithoutSnapshot,
                "visual_judge_metadata",
                redactions),
            StringComparer.Ordinal)
        {
            ["visual_judge_status"] = SafeScalar(status.Status, "visual_judge_status", redactions, "unknown"),
            ["product_not_ready"] = bool.TrueString
        };
        if (serializedSnapshot is not null &&
            DesignConversionLocalArtifactDbRecord.TryCanonicalizeCompletedStatusSnapshotMetadata(
                serializedSnapshot,
                out var canonicalSnapshotJson) &&
            canonicalSnapshotJson is not null)
        {
            metadata[DesignConversionLocalArtifactDbRecord.CompletedStatusSnapshotMetadataKey] =
                canonicalSnapshotJson;
        }

        return status with
        {
            Status = SafeScalar(status.Status, "visual_judge_status", redactions, "unknown"),
            ProviderBoundary = SafeScalar(status.ProviderBoundary, "visual_judge_provider_boundary", redactions, "unknown"),
            TierDecision = SafeScalar(status.TierDecision, "visual_judge_tier_decision", redactions, "unknown"),
            EvidenceRefs = (status.EvidenceRefs ?? [])
                .Select(reference => SafeArtifactRef(reference, "visual_judge_evidence_ref", redactions))
                .Append(VisualJudgeStatusMarker)
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray(),
            Metadata = metadata
        };
    }

    private static DesignConversionLocalArtifactDbDpoCandidate NormalizeCandidate(
        DesignConversionLocalArtifactDbDpoCandidate candidate,
        DesignConversionVisualJudgeArtifactDbStatus visualStatus,
        SortedSet<string> redactions)
    {
        var record = AttachVisualJudgeMetadata(
            SanitizeTrainingRecord(candidate.TrainingRecord, redactions),
            visualStatus);
        var blockReasons = BuildBlockReasons(candidate, record, visualStatus)
            .Select(reason => SafeScalar(reason, "dpo_candidate_block_reason", redactions, "blocked"))
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();
        var trainingCandidateOnly = candidate.TrainingCandidateOnly
            && candidate.ProductNotReady
            && record.License.AllowsTraining
            && !record.License.ContainsUserPrivateData
            && !record.Quarantine.IsQuarantined;

        return candidate with
        {
            CandidateId = SafeScalar(candidate.CandidateId, "dpo_candidate_id", redactions, $"{record.RecordId}:dpo-candidate"),
            RecordId = record.RecordId,
            UnitId = record.UnitId,
            UsefulnessScore = Math.Round(record.UsefulnessScore, 6),
            TrainingCandidateOnly = trainingCandidateOnly,
            ProductNotReady = true,
            AllowsTraining = record.License.AllowsTraining,
            ContainsUserPrivateData = record.License.ContainsUserPrivateData,
            IsQuarantined = record.Quarantine.IsQuarantined,
            QuarantineReason = SafeScalar(record.Quarantine.Reason, "quarantine_reason", redactions, "unknown"),
            BlockReasons = blockReasons,
            TrainingRecord = record
        };
    }

    private static DesignConversionDpoTrainingRecord SanitizeTrainingRecord(
        DesignConversionDpoTrainingRecord record,
        SortedSet<string> redactions)
    {
        var metadata = new Dictionary<string, string>(
            DesignConversionDpoLeakageGuard.SanitizeMetadata(record.Provenance.Metadata, "dpo_provenance_metadata", redactions),
            StringComparer.Ordinal)
        {
            ["storage_training_artifact_db"] = bool.TrueString,
            ["local_artifact_db"] = bool.TrueString,
            ["training_candidate_only"] = bool.TrueString,
            ["training_grade"] = bool.FalseString,
            ["not_training_grade"] = bool.TrueString,
            ["training_grade_boundary"] = "local_artifact_db_training_candidate_not_training_grade",
            ["product_not_ready"] = bool.TrueString
        };

        if (redactions.Count > 0)
            metadata["source_encoder_redaction_codes"] = string.Join(",", redactions);

        return record with
        {
            RecordId = SafeScalar(record.RecordId, "dpo_record_id", redactions, "dpo-record"),
            UnitId = SafeScalar(record.UnitId, "dpo_unit_id", redactions, "unknown"),
            InternalUnitStatePayload = DesignConversionDpoLeakageGuard.SanitizeJsonPayload(
                record.InternalUnitStatePayload,
                "dpo_internal_unit_state",
                redactions),
            InternalVectorPayload = (record.InternalVectorPayload ?? [])
                .Where(double.IsFinite)
                .Select(value => Math.Round(value, 6))
                .ToArray(),
            SourceStructurePayload = DesignConversionDpoLeakageGuard.SanitizeJsonPayload(
                record.SourceStructurePayload,
                "dpo_source_structure",
                redactions),
            Chosen = SanitizeTrainingOutput(record.Chosen, "chosen", redactions),
            Rejected = SanitizeTrainingOutput(record.Rejected, "rejected", redactions),
            TieBreakerPayload = DesignConversionDpoLeakageGuard.SanitizeJsonPayload(
                record.TieBreakerPayload,
                "dpo_tie_breaker",
                redactions),
            UsefulnessScore = Math.Round(record.UsefulnessScore, 6),
            NegativeQualityReason = SafeScalar(record.NegativeQualityReason, "negative_quality_reason", redactions, "unknown"),
            NegativeReasonTaxonomy = SafeScalar(record.NegativeReasonTaxonomy, "negative_reason_taxonomy", redactions, "unknown"),
            Provenance = record.Provenance with
            {
                SourceRequestId = SafeArtifactRef(record.Provenance.SourceRequestId, "source_request_ref", redactions),
                SourceKind = SafeScalar(record.Provenance.SourceKind, "source_kind", redactions, "unknown"),
                SourceManifestRef = SafeArtifactRef(record.Provenance.SourceManifestRef, "source_manifest_ref", redactions),
                ReviewerRef = SafeArtifactRef(record.Provenance.ReviewerRef, "reviewer_ref", redactions),
                Metadata = metadata
            },
            License = record.License with
            {
                LicenseId = SafeScalar(record.License.LicenseId, "license_id", redactions, "license"),
                RightsScope = SafeScalar(record.License.RightsScope, "rights_scope", redactions, "unknown"),
                Metadata = DesignConversionDpoLeakageGuard.SanitizeMetadata(
                    record.License.Metadata,
                    "license_metadata",
                    redactions)
            },
            Quarantine = record.Quarantine with
            {
                Reason = SafeScalar(record.Quarantine.Reason, "quarantine_reason", redactions, "unknown"),
                EvidenceRefs = (record.Quarantine.EvidenceRefs ?? [])
                    .Select(reference => SafeArtifactRef(reference, "quarantine_evidence_ref", redactions))
                    .ToArray()
            }
        };
    }

    private static DesignConversionDpoTrainingRecord AttachVisualJudgeMetadata(
        DesignConversionDpoTrainingRecord record,
        DesignConversionVisualJudgeArtifactDbStatus visualStatus)
    {
        var metadata = new Dictionary<string, string>(record.Provenance.Metadata, StringComparer.Ordinal)
        {
            ["visual_judge_status"] = visualStatus.Status,
            ["visual_judge_provider_boundary"] = visualStatus.ProviderBoundary,
            ["visual_judge_tier_decision"] = visualStatus.TierDecision,
            ["external_ai_visual_judge_executed"] = visualStatus.ExternalCallExecuted.ToString(),
            ["storage_visual_judge_boundary"] = "persisted_for_training_candidate_filter"
        };

        return record with
        {
            Provenance = record.Provenance with
            {
                Metadata = metadata
            }
        };
    }

    private static DesignConversionImprovementOutput SanitizeTrainingOutput(
        DesignConversionImprovementOutput output,
        string label,
        SortedSet<string> redactions)
        => output with
        {
            OutputId = SafeScalar(output.OutputId, $"{label}_output_id", redactions, $"{label}-output"),
            CandidateId = SafeScalar(output.CandidateId, $"{label}_candidate_id", redactions, $"{label}-candidate"),
            Html = PayloadRef($"{label}_html", output.Html, redactions),
            Css = PayloadRef($"{label}_css", output.Css, redactions),
            Verdict = SanitizeVerdict(output.Verdict, label, redactions),
            QaResults = (output.QaResults ?? [])
                .Select(result => SanitizeQaResult(result, label, redactions))
                .ToArray(),
            EvidenceRefs = (output.EvidenceRefs ?? [])
                .Select(reference => SafeArtifactRef(reference, $"{label}_evidence_ref", redactions))
                .ToArray()
        };

    private static RenderQaResultRecord SanitizeQaResult(
        RenderQaResultRecord result,
        string label,
        SortedSet<string> redactions)
        => result with
        {
            ResultId = SafeScalar(result.ResultId, $"{label}_qa_result_id", redactions, "qa-result"),
            RequestId = SafeArtifactRef(result.RequestId, $"{label}_qa_request_id", redactions),
            Expected = SanitizeImage(result.Expected, $"{label}_expected", redactions),
            Actual = SanitizeImage(result.Actual, $"{label}_actual", redactions),
            Verdict = SanitizeVerdict(result.Verdict, $"{label}_qa", redactions),
            Warnings = (result.Warnings ?? [])
                .Select(warning => SafeScalar(warning, $"{label}_qa_warning", redactions, "warning"))
                .ToArray()
        };

    private static RenderQaImageRecord SanitizeImage(
        RenderQaImageRecord image,
        string label,
        SortedSet<string> redactions)
        => image with
        {
            ImageId = SafeScalar(image.ImageId, $"{label}_image_id", redactions, "image"),
            Uri = SafeArtifactRef(image.Uri, $"{label}_image_uri", redactions),
