            "source_encoder_feature_names",
            "source_structure_signal_summary",
            "result_signal_summary",
            "source_encoder_shortcut_guard",
            "source_kind_in_vector",
            "source_id_in_vector",
            DesignConversionDpoGenerator.PayloadCustodyRequiredMetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyVersionMetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyPromptSha256MetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyChosenSha256MetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyRejectedSha256MetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyGovernanceSha256MetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey,
            "payload_custody_raw_in_public_record"
        ]);
    }

    private static void CopyBoundaryMetadata(
        IReadOnlyDictionary<string, string> source,
        IDictionary<string, string> target,
        SortedSet<string> redactions,
        IReadOnlyList<string> keys)
    {
        foreach (var key in keys)
        {
            if (source.TryGetValue(key, out var value))
                target[key] = SafeScalar(value, $"source_encoding_metadata_{key}", redactions, "missing");
        }
    }

    private static OperationResult<bool> ValidateTrainingIntakeHandoff(
        DesignConversionApprovedDpoHandoffArtifact handoff)
    {
        var rows = handoff.Rows ?? [];
        if (!string.Equals(handoff.SchemaVersion, ApprovedDpoHandoffSchemaVersion, StringComparison.Ordinal) &&
            !string.Equals(handoff.SchemaVersion, ApprovedDpoHandoffCustodySchemaVersion, StringComparison.Ordinal))
            return OperationResult<bool>.Fail(
                "DesignConversion training intake only accepts approved DPO handoff schema v1 or v2 artifacts.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_HANDOFF_SCHEMA_INVALID");
        var custodyRowCount = rows.Count(row => IsTruthy(ReadMetadata(
            row?.BoundaryMetadata,
            DesignConversionDpoGenerator.PayloadCustodyRequiredMetadataKey)));
        if (!string.Equals(
                ReadMetadata(handoff.BoundaryMetadata, "schema_version"),
                handoff.SchemaVersion,
                StringComparison.Ordinal) ||
            (custodyRowCount > 0 &&
             !string.Equals(
                 handoff.SchemaVersion,
                 ApprovedDpoHandoffCustodySchemaVersion,
                 StringComparison.Ordinal)) ||
            (custodyRowCount == 0 &&
             string.Equals(
                 handoff.SchemaVersion,
                 ApprovedDpoHandoffCustodySchemaVersion,
                 StringComparison.Ordinal)))
        {
            return OperationResult<bool>.Fail(
                "DesignConversion approved DPO handoff schema does not match its custody boundary.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_HANDOFF_SCHEMA_INVALID");
        }

        if (string.Equals(
                handoff.SchemaVersion,
                ApprovedDpoHandoffCustodySchemaVersion,
                StringComparison.Ordinal))
        {
            var custodyRows = rows.Where(row => row is not null && IsTruthy(ReadMetadata(
                    row.BoundaryMetadata,
                    DesignConversionDpoGenerator.PayloadCustodyRequiredMetadataKey)))
                .ToArray();
            var bindings = custodyRows.Select(row => ReadMetadata(
                    row.BoundaryMetadata,
                    DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey))
                .Order(StringComparer.Ordinal)
                .ToArray();
            var expectedVersions = string.Join(",", custodyRows.Select(row => ReadMetadata(
                    row.BoundaryMetadata,
                    DesignConversionDpoGenerator.PayloadCustodyVersionMetadataKey))
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal));
            if (!int.TryParse(
                    ReadMetadata(handoff.BoundaryMetadata, "payload_custody_required_count"),
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out var declaredCustodyCount) ||
                declaredCustodyCount != custodyRows.Length ||
                !string.Equals(
                    ReadMetadata(handoff.BoundaryMetadata, "payload_custody_versions"),
                    expectedVersions,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    ReadMetadata(handoff.BoundaryMetadata, "payload_custody_commitment_set_sha256"),
                    DesignConversionDpoGenerator.Sha256Ref(string.Join("|", bindings)),
                    StringComparison.Ordinal) ||
                custodyRows.Any(row =>
                    !string.Equals(
                        ReadMetadata(row.BoundaryMetadata,
                            DesignConversionDpoGenerator.PayloadCustodyVersionMetadataKey),
                        DesignConversionDpoGenerator.PayloadCustodyVersion,
                        StringComparison.Ordinal) ||
                    !IsSha256Ref(ReadMetadata(row.BoundaryMetadata,
                        DesignConversionDpoGenerator.PayloadCustodyPromptSha256MetadataKey)) ||
                    !IsSha256Ref(ReadMetadata(row.BoundaryMetadata,
                        DesignConversionDpoGenerator.PayloadCustodyChosenSha256MetadataKey)) ||
                    !IsSha256Ref(ReadMetadata(row.BoundaryMetadata,
                        DesignConversionDpoGenerator.PayloadCustodyRejectedSha256MetadataKey)) ||
                    !IsSha256Ref(ReadMetadata(row.BoundaryMetadata,
                        DesignConversionDpoGenerator.PayloadCustodyGovernanceSha256MetadataKey)) ||
                    !IsSha256Ref(ReadMetadata(row.BoundaryMetadata,
                        DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey)) ||
                    !string.Equals(
                        ReadMetadata(row.BoundaryMetadata,
                            "payload_custody_raw_in_public_record"),
                        bool.FalseString,
                        StringComparison.OrdinalIgnoreCase)))
            {
                return OperationResult<bool>.Fail(
                    "DesignConversion approved DPO handoff custody commitment is invalid.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_HANDOFF_CUSTODY_INVALID");
            }
        }

        var topLevelBoundary = ValidateTrainingIntakeBoundaryMetadata(
            handoff.BoundaryMetadata,
            "approved_dpo_handoff");
        if (!topLevelBoundary.IsSuccess)
            return topLevelBoundary;

        if (ContainsForbiddenTrainingIntakePayload(handoff))
            return OperationResult<bool>.Fail(
                "DesignConversion training intake handoff contains raw or private payload markers.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_HANDOFF_UNSANITIZED");

        if (handoff.ApprovedCandidateCount == 0 && rows.Count == 0)
            return OperationResult<bool>.Ok(true);

        if (handoff.ApprovedCandidateCount <= 0
            || rows.Count == 0
            || handoff.ApprovedCandidateCount != rows.Count)
        {
            return OperationResult<bool>.Fail(
                "DesignConversion training intake handoff approved candidate count does not match approved rows.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_HANDOFF_COUNT_MISMATCH");
        }

        foreach (var row in rows)
        {
            if (row is null)
            {
                return OperationResult<bool>.Fail(
                    "DesignConversion training intake handoff contains a missing row.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_ROW_REQUIRED");
            }

            var rowBoundary = ValidateTrainingIntakeBoundaryMetadata(
                row.BoundaryMetadata,
                "approved_dpo_handoff_row");
            if (!rowBoundary.IsSuccess)
                return rowBoundary;

            if (!row.TrainingHandoffOnly
                || !row.ApprovedForTraining
                || !string.Equals(row.ApprovalStatus, "approved", StringComparison.OrdinalIgnoreCase)
                || !string.Equals(row.ReviewStatus, RuntimeCandidateReviewApprovedStatus, StringComparison.Ordinal))
            {
                return OperationResult<bool>.Fail(
                    "DesignConversion training intake requires approved handoff-only rows.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_ROW_NOT_APPROVED");
            }

            if (string.IsNullOrWhiteSpace(row.ApprovedByRef)
                || string.IsNullOrWhiteSpace(row.ApprovalReason)
                || string.IsNullOrWhiteSpace(row.ApprovedAtUtc))
            {
                return OperationResult<bool>.Fail(
                    "DesignConversion training intake requires approved reviewer, reason, and timestamp metadata.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_APPROVAL_METADATA_REQUIRED");
            }

            if (string.IsNullOrWhiteSpace(row.CandidateId)
                || string.IsNullOrWhiteSpace(row.TrainingRecordId)
                || string.IsNullOrWhiteSpace(row.RecordHash)
                || string.IsNullOrWhiteSpace(row.InternalUnitStateHash)
                || string.IsNullOrWhiteSpace(row.SourceStructureHash)
                || string.IsNullOrWhiteSpace(row.ChosenPayloadHash)
                || string.IsNullOrWhiteSpace(row.RejectedPayloadHash)
                || string.IsNullOrWhiteSpace(row.TieBreakerHash))
            {
                return OperationResult<bool>.Fail(
                    "DesignConversion training intake requires candidate ids and handoff hashes.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_CANDIDATE_HASH_REQUIRED");
            }

            if (string.IsNullOrWhiteSpace(row.ChosenHtmlRef)
                || string.IsNullOrWhiteSpace(row.ChosenCssRef)
                || string.IsNullOrWhiteSpace(row.RejectedHtmlRef)
                || string.IsNullOrWhiteSpace(row.RejectedCssRef)
                || string.IsNullOrWhiteSpace(row.DesignTreeRef)
                || string.IsNullOrWhiteSpace(row.OriginalTreeRef)
                || (row.SourceArtifactRefs?.Count ?? 0) == 0
                || (row.RenderArtifactRefs?.Count ?? 0) == 0
                || (row.ComparisonArtifactRefs?.Count ?? 0) == 0)
            {
                return OperationResult<bool>.Fail(
                    "DesignConversion training intake requires persisted html/css/source/render/comparison refs.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_RUNTIME_ARTIFACT_REFS_REQUIRED");
            }
        }

        return OperationResult<bool>.Ok(true);
    }

    private static OperationResult<bool> ValidateTrainingIntakeBoundaryMetadata(
        IReadOnlyDictionary<string, string>? metadata,
        string scope)
    {
        if (metadata is null || metadata.Count == 0)
            return OperationResult<bool>.Fail(
                $"DesignConversion training intake requires {scope} boundary metadata.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_BOUNDARY_METADATA_REQUIRED");

        foreach (var key in RequiredTrainingIntakeTrueBoundaryKeys)
        {
            if (!IsTruthy(ReadMetadata(metadata, key)))
            {
                return OperationResult<bool>.Fail(
                    $"DesignConversion training intake requires {scope} boundary '{key}=true'.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_BOUNDARY_METADATA_REQUIRED");
            }
        }

        foreach (var key in RequiredTrainingIntakeFalseBoundaryKeys)
        {
            if (!string.Equals(ReadMetadata(metadata, key), bool.FalseString, StringComparison.OrdinalIgnoreCase))
            {
                return OperationResult<bool>.Fail(
                    $"DesignConversion training intake requires {scope} boundary '{key}=false'.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_BOUNDARY_METADATA_REQUIRED");
            }
        }

        return OperationResult<bool>.Ok(true);
    }

    private static DesignConversionTrainingIntakeRecord BuildTrainingIntakeRecord(
        DesignConversionApprovedDpoHandoffArtifact handoff,
        string requestedByRef,
        string reason,
        DateTimeOffset requestedAtUtc,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata)
    {
        var trainingIntakeSchemaVersion = string.Equals(
            handoff.SchemaVersion,
            ApprovedDpoHandoffCustodySchemaVersion,
            StringComparison.Ordinal)
                ? TrainingIntakeCustodySchemaVersion
                : TrainingIntakeSchemaVersion;
        var redactions = new SortedSet<string>(StringComparer.Ordinal);
        var requestedBy = SafeScalar(
            requestedByRef,
            "training_intake_requested_by_ref",
            redactions,
            "local-requester");
        var requestReason = SafeScalar(
            reason,
            "training_intake_reason",
            redactions,
            "future-training-intake-request");
        var candidates = (handoff.Rows ?? [])
            .OrderBy(row => row.TrainingRecordId, StringComparer.Ordinal)
            .ThenBy(row => row.CandidateId, StringComparer.Ordinal)
            .Select(row => BuildTrainingIntakeCandidateRef(
                row,
                redactions,
                trainingIntakeSchemaVersion))
            .ToArray();
        var intakeId = BuildTrainingIntakeId(
            handoff,
            requestedBy,
            requestReason,
            requestedAtUtc,
            admissionBoundaryMetadata,
            trainingIntakeSchemaVersion);
        var sourceProof = BuildTrainingIntakeSourceProof(candidates);
        var warnings = BuildTrainingIntakeWarnings(candidates.Length, sourceProof);

        return new DesignConversionTrainingIntakeRecord(
            IntakeId: intakeId,
            IntakeRef: candidates.Length == 0
                ? string.Empty
                : $"memory://design-conversion/training-intake/{intakeId}",
            SourceHandoffArtifactId: SafeScalar(
                handoff.ArtifactId,
                "training_intake_source_handoff_artifact_id",
                redactions,
                "approved-dpo-handoff"),
            SourceHandoffArtifactRef: SafeArtifactRef(
                handoff.ArtifactRef,
                "training_intake_source_handoff_artifact_ref",
                redactions),
            ApprovedCandidateCount: handoff.ApprovedCandidateCount,
            AcceptedCandidateCount: candidates.Length,
            CandidateRefs: candidates,
            RequestedAtUtc: requestedAtUtc,
            RequestedByRef: requestedBy,
            RequestReason: requestReason,
            TrainingIntakeOnly: true,
            TrainingNotStarted: true,
            NotTrained: true,
            WeightsNotProduced: true,
            CheckpointNotMutated: true,
            ModelUploadNotReady: true,
            ProductNotReady: true,
            HeldOutNotProven: true,
            SourceDisjointNotProven: true,
            Warnings: warnings,
            BoundaryMetadata: BuildTrainingIntakeBoundaryMetadata(
                handoff,
                candidates.Length,
                requestedBy,
                requestReason,
                sourceProof,
                redactions,
                admissionBoundaryMetadata,
                trainingIntakeSchemaVersion));
    }

    private static DesignConversionTrainingIntakeCandidateRef BuildTrainingIntakeCandidateRef(
        DesignConversionApprovedDpoHandoffRow row,
        SortedSet<string> redactions,
        string trainingIntakeSchemaVersion)
    {
        var sourceManifestRef = SafeArtifactRef(
            row.SourceManifestRef,
            "training_intake_source_manifest_ref",
            redactions);
        var sourceManifestHash = BuildTrainingIntakeSourceManifestHash(sourceManifestRef);
        var sourceIdentityHash = BuildTrainingIntakeSourceIdentityHash(
            sourceManifestRef,
            row.SourceStructureHash,
            row.TrainingRecordId);
        var chosenHtmlRef = SafeArtifactRef(row.ChosenHtmlRef, "training_intake_chosen_html_ref", redactions);
        var chosenCssRef = SafeArtifactRef(row.ChosenCssRef, "training_intake_chosen_css_ref", redactions);
        var rejectedHtmlRef = SafeArtifactRef(row.RejectedHtmlRef, "training_intake_rejected_html_ref", redactions);
        var rejectedCssRef = SafeArtifactRef(row.RejectedCssRef, "training_intake_rejected_css_ref", redactions);
        var designTreeRef = SafeArtifactRef(row.DesignTreeRef, "training_intake_design_tree_ref", redactions);
        var originalTreeRef = SafeArtifactRef(row.OriginalTreeRef, "training_intake_original_tree_ref", redactions);
        var sourceArtifactRefs = SanitizeTrainingIntakeRefList(
            row.SourceArtifactRefs,
            "training_intake_source_artifact_ref",
            redactions);
        var renderArtifactRefs = SanitizeTrainingIntakeRefList(
            row.RenderArtifactRefs,
            "training_intake_render_artifact_ref",
            redactions);
        var comparisonArtifactRefs = SanitizeTrainingIntakeRefList(
            row.ComparisonArtifactRefs,
            "training_intake_comparison_artifact_ref",
            redactions);
        var metadata = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["candidate_id"] = row.CandidateId,
            ["training_record_id"] = row.TrainingRecordId,
            ["handoff_record_hash"] = row.RecordHash,
            ["source_manifest_ref"] = sourceManifestRef,
            ["source_manifest_hash"] = sourceManifestHash,
            ["source_identity_hash"] = sourceIdentityHash,
            ["approved_by_ref"] = row.ApprovedByRef,
            ["approval_reason"] = row.ApprovalReason,
            ["approved_at_utc"] = row.ApprovedAtUtc,
            ["training_intake_only"] = bool.TrueString,
            ["training_grade"] = bool.FalseString,
            ["not_training_grade"] = bool.TrueString,
            ["training_grade_boundary"] = "training_intake_preflight_not_training_grade",
            ["training_not_started"] = bool.TrueString,
            ["not_trained"] = bool.TrueString,
            ["weights_not_produced"] = bool.TrueString,
            ["checkpoint_not_mutated"] = bool.TrueString,
            ["model_upload_not_ready"] = bool.TrueString,
            ["product_ready"] = bool.FalseString,
            ["product_not_ready"] = bool.TrueString,
            ["held_out_not_proven"] = bool.TrueString,
            ["source_disjoint_not_proven"] = bool.TrueString,
            ["design_conversion_runtime_artifacts_persisted"] = bool.TrueString,
            ["chosen_html_ref"] = chosenHtmlRef,
            ["chosen_css_ref"] = chosenCssRef,
            ["rejected_html_ref"] = rejectedHtmlRef,
            ["rejected_css_ref"] = rejectedCssRef,
            ["design_tree_ref"] = designTreeRef,
            ["original_tree_ref"] = originalTreeRef,
            ["source_artifact_ref_count"] = sourceArtifactRefs.Count.ToString(CultureInfo.InvariantCulture),
            ["render_artifact_ref_count"] = renderArtifactRefs.Count.ToString(CultureInfo.InvariantCulture),
            ["comparison_artifact_ref_count"] = comparisonArtifactRefs.Count.ToString(CultureInfo.InvariantCulture)
        };
        CopyBoundaryMetadata(row.BoundaryMetadata, metadata, redactions,
        [
            "internal_vector_hash",
            "internal_vector_dimensions",
            "source_encoder_vector_hash",
            "source_encoder_feature_map_hash",
            "source_encoder_feature_names",
            "source_structure_signal_summary",
            "result_signal_summary",
            "source_encoder_shortcut_guard",
            "source_kind_in_vector",
            "source_id_in_vector",
            "attempt_count",
            "stop_reason",
            "quality_reached",
            "final_candidate_from_loop",
            "comparison_diff_metadata_ref",
            "runtime_created_dpo_candidate_count",
            "runtime_created_dpo_candidate",
            "improvement_loop_to_local_training_store",
            "local_training_store_dpo_source",
            "refs_or_hashes_only",
            DesignConversionDpoGenerator.PayloadCustodyRequiredMetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyVersionMetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyPromptSha256MetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyChosenSha256MetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyRejectedSha256MetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyGovernanceSha256MetadataKey,
            DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey,
            "payload_custody_raw_in_public_record"
        ]);
        AddTrainingDatabaseDurabilityMetadata(
            metadata,
            trainingIntakeSchemaVersion,
            "training-intake-candidate",
            1,
            new[]
            {
                sourceManifestRef,
                chosenHtmlRef,
                chosenCssRef,
                rejectedHtmlRef,
                rejectedCssRef,
                designTreeRef,
                originalTreeRef
            }
                .Concat(sourceArtifactRefs)
                .Concat(renderArtifactRefs)
                .Concat(comparisonArtifactRefs),
            new List<string>
            {
                row.LocalArtifactRecordId,
                row.CandidateId,
                row.TrainingRecordId,
                row.RecordHash,
                row.InternalUnitStateHash,
                row.SourceStructureHash,
                row.ChosenPayloadHash,
                row.RejectedPayloadHash,
                row.TieBreakerHash
            }.Concat(string.Equals(
                trainingIntakeSchemaVersion,
                TrainingIntakeCustodySchemaVersion,
                StringComparison.Ordinal)
                    ?
                    [
                        ReadMetadata(row.BoundaryMetadata, DesignConversionDpoGenerator.PayloadCustodyVersionMetadataKey),
                        ReadMetadata(row.BoundaryMetadata, DesignConversionDpoGenerator.PayloadCustodyPromptSha256MetadataKey),
                        ReadMetadata(row.BoundaryMetadata, DesignConversionDpoGenerator.PayloadCustodyChosenSha256MetadataKey),
                        ReadMetadata(row.BoundaryMetadata, DesignConversionDpoGenerator.PayloadCustodyRejectedSha256MetadataKey),
                        ReadMetadata(row.BoundaryMetadata, DesignConversionDpoGenerator.PayloadCustodyGovernanceSha256MetadataKey),
                        ReadMetadata(row.BoundaryMetadata, DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey)
                    ]
                    : []));

        return new DesignConversionTrainingIntakeCandidateRef(
            LocalArtifactRecordId: row.LocalArtifactRecordId,
            CandidateId: row.CandidateId,
            TrainingRecordId: row.TrainingRecordId,
            UnitId: row.UnitId,
            UsefulnessScore: row.UsefulnessScore,
            HandoffRecordHash: row.RecordHash,
            SourceManifestRef: sourceManifestRef,
            SourceManifestHash: sourceManifestHash,
            SourceIdentityHash: sourceIdentityHash,
            InternalUnitStateHash: row.InternalUnitStateHash,
            SourceStructureHash: row.SourceStructureHash,
            ChosenPayloadHash: row.ChosenPayloadHash,
            RejectedPayloadHash: row.RejectedPayloadHash,
            TieBreakerHash: row.TieBreakerHash,
            ChosenHtmlRef: chosenHtmlRef,
            ChosenCssRef: chosenCssRef,
            RejectedHtmlRef: rejectedHtmlRef,
            RejectedCssRef: rejectedCssRef,
            DesignTreeRef: designTreeRef,
            OriginalTreeRef: originalTreeRef,
            SourceArtifactRefs: sourceArtifactRefs,
            RenderArtifactRefs: renderArtifactRefs,
            ComparisonArtifactRefs: comparisonArtifactRefs,
            BoundaryMetadata: metadata);
    }

    private static IReadOnlyList<string> SanitizeTrainingIntakeRefList(
        IReadOnlyList<string>? refs,
        string scope,
        SortedSet<string> redactions)
        => (refs ?? [])
            .Select(reference => SafeArtifactRef(reference, scope, redactions))
            .Where(reference => !string.IsNullOrWhiteSpace(reference))
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();

    private static IReadOnlyList<string> BuildTrainingIntakeWarnings(
        int acceptedCandidateCount,
        DesignConversionTrainingIntakeSourceProof sourceProof)
    {
        var warnings = new List<string>
        {
            "training_intake_only",
            "future_ilearningmachine_training_intake_request",
            "training_not_started",
            "not_trained",
            "weights_not_produced",
            "checkpoint_not_mutated",
            "model_upload_not_ready",
            "product_not_ready",
            "held_out_not_proven",
            "source_disjoint_not_proven",
            $"source_manifest_status:{sourceProof.SourceManifestStatus}",
            $"source_disjoint_status:{sourceProof.SourceDisjointStatus}",
            "raw_html_css_tree_private_provider_payloads_not_emitted"
        };
        if (acceptedCandidateCount == 0)
        {
            warnings.Add("no_approved_candidates");
            warnings.Add("training_intake_not_enqueued");
        }

        return warnings
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();
    }

    private static IReadOnlyDictionary<string, string> BuildTrainingIntakeBoundaryMetadata(
        DesignConversionApprovedDpoHandoffArtifact handoff,
        int acceptedCandidateCount,
        string requestedBy,
        string reason,
        DesignConversionTrainingIntakeSourceProof sourceProof,
        SortedSet<string> redactions,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        string trainingIntakeSchemaVersion)
    {
        var metadata = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["schema_version"] = trainingIntakeSchemaVersion,
            ["source_handoff_schema_version"] = handoff.SchemaVersion,
            ["source_handoff_artifact_id"] = handoff.ArtifactId,
            ["source_handoff_artifact_ref"] = handoff.ArtifactRef,
            ["approved_candidate_count"] = handoff.ApprovedCandidateCount.ToString(CultureInfo.InvariantCulture),
            ["accepted_candidate_count"] = acceptedCandidateCount.ToString(CultureInfo.InvariantCulture),
            ["requested_by_ref"] = requestedBy,
            ["request_reason"] = reason,
            ["training_intake_only"] = bool.TrueString,
            ["training_not_started"] = bool.TrueString,
            ["training_started"] = bool.FalseString,
            ["not_trained"] = bool.TrueString,
            ["weights_not_produced"] = bool.TrueString,
            ["checkpoint_not_mutated"] = bool.TrueString,
            ["model_upload_not_ready"] = bool.TrueString,
            ["model_ready"] = bool.FalseString,
            ["product_ready"] = bool.FalseString,
            ["product_not_ready"] = bool.TrueString,
            ["held_out_not_proven"] = bool.TrueString,
            ["source_disjoint_not_proven"] = bool.TrueString,
            ["source_manifest_status"] = sourceProof.SourceManifestStatus,
            ["source_disjoint_status"] = sourceProof.SourceDisjointStatus,
            ["source_manifest_proven"] = sourceProof.SourceManifestProven.ToString(),
            ["source_disjoint_proven"] = sourceProof.SourceDisjointProven.ToString(),
            ["source_manifest_candidate_count"] = sourceProof.CandidateCount.ToString(CultureInfo.InvariantCulture),
            ["source_manifest_hash_count"] = sourceProof.SourceManifestHashCount.ToString(CultureInfo.InvariantCulture),
            ["source_disjoint_train_source_count"] = sourceProof.TrainSourceIdentityHashes.Count.ToString(CultureInfo.InvariantCulture),
            ["source_disjoint_heldout_source_count"] = sourceProof.HeldOutSourceIdentityHashes.Count.ToString(CultureInfo.InvariantCulture),
            ["source_disjoint_overlap_count"] = sourceProof.OverlapSourceIdentityHashes.Count.ToString(CultureInfo.InvariantCulture),
            ["public_api_verified"] = bool.FalseString,
            ["production_db_ready"] = bool.FalseString,
            ["trained_model_ready"] = bool.FalseString,
            ["model_readiness_claimed"] = bool.FalseString,
            ["raw_html_included"] = bool.FalseString,
            ["raw_css_included"] = bool.FalseString,
            ["raw_design_tree_included"] = bool.FalseString,
            ["raw_user_private_data_included"] = bool.FalseString,
            ["provider_payload_included"] = bool.FalseString,
            ["target_training_system"] = "future_ILearningMachine",
            ["training_execution_boundary"] = acceptedCandidateCount == 0
                ? "zero_intake_not_enqueued"
                : "local_intake_record_only"
        };
        foreach (var pair in admissionBoundaryMetadata ?? new Dictionary<string, string>(StringComparer.Ordinal))
            metadata[SafeScalar(pair.Key, "training_intake_admission_metadata_key", redactions, "admission_metadata_key")] =
                SafeScalar(pair.Value, $"training_intake_admission_metadata_{pair.Key}", redactions, "admission_metadata_value");

        if (string.Equals(
                trainingIntakeSchemaVersion,
                TrainingIntakeCustodySchemaVersion,
                StringComparison.Ordinal))
        {
            metadata["payload_custody_required_count"] = ReadMetadata(
                handoff.BoundaryMetadata,
                "payload_custody_required_count");
            metadata["payload_custody_versions"] = ReadMetadata(
                handoff.BoundaryMetadata,
                "payload_custody_versions");
            metadata["payload_custody_commitment_set_sha256"] = ReadMetadata(
                handoff.BoundaryMetadata,
                "payload_custody_commitment_set_sha256");
        }

        AddTrainingDatabaseDurabilityMetadata(
            metadata,
            trainingIntakeSchemaVersion,
            "training-intake",
            acceptedCandidateCount,
            [
                handoff.ArtifactRef,
                handoff.ArtifactId,
                sourceProof.SourceManifestStatus,
                sourceProof.SourceDisjointStatus
            ],
            new List<string>
            {
                handoff.ArtifactId,
                handoff.SchemaVersion,
                acceptedCandidateCount.ToString(CultureInfo.InvariantCulture),
                sourceProof.SourceManifestHashCount.ToString(CultureInfo.InvariantCulture),
                sourceProof.SourceManifestStatus,
                sourceProof.SourceDisjointStatus
            }.Concat(string.Equals(
                trainingIntakeSchemaVersion,
                TrainingIntakeCustodySchemaVersion,
                StringComparison.Ordinal)
                    ?
                    [
                        ReadMetadata(handoff.BoundaryMetadata, "payload_custody_required_count"),
                        ReadMetadata(handoff.BoundaryMetadata, "payload_custody_versions"),
                        ReadMetadata(handoff.BoundaryMetadata, "payload_custody_commitment_set_sha256")
                    ]
                    : []));

        if (redactions.Count > 0)
            metadata["training_intake_redaction_codes"] = string.Join(",", redactions);

        return metadata;
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeReplayResolution>> ResolveCreateTrainingIntakeIdempotencyReplayAsync(
        DesignConversionTrainingIntakeRecord intake,
        CancellationToken ct)
    {
        if (!HasCreateTrainingIntakeIdempotencyBoundary(intake.BoundaryMetadata))
            return OperationResult<DesignConversionTrainingIntakeReplayResolution>.Ok(
                new DesignConversionTrainingIntakeReplayResolution(false, null));

        var existing = await ListTrainingIntakeRequestsAsync(ct);
        if (!existing.IsSuccess)
        {
            if (string.Equals(existing.ErrorCode, TrainingIntakeReadFailedErrorCode, StringComparison.Ordinal))
                return LocalArtifactDbWriteFailed<DesignConversionTrainingIntakeReplayResolution>();

            return existing.MapError<DesignConversionTrainingIntakeReplayResolution>();
        }

        var matches = existing.Value!
            .Where(record => HasSameCreateTrainingIntakeIdempotencyBoundary(record, intake))
            .OrderBy(record => record.RequestedAtUtc)
            .ThenBy(record => record.IntakeId, StringComparer.Ordinal)
            .ToArray();
        if (matches.Length == 0)
            return OperationResult<DesignConversionTrainingIntakeReplayResolution>.Ok(
                new DesignConversionTrainingIntakeReplayResolution(false, null));

        var incomingFingerprint = BuildNormalizedTrainingIntakeRecordFingerprint(intake);
        if (matches.Any(record =>
                !string.Equals(record.IntakeId, intake.IntakeId, StringComparison.Ordinal)
                || !string.Equals(
                    BuildNormalizedTrainingIntakeRecordFingerprint(record),
                    incomingFingerprint,
                    StringComparison.Ordinal)))
        {
            return OperationResult<DesignConversionTrainingIntakeReplayResolution>.Fail(
                "DesignConversion training intake create idempotency key was replayed with a different payload.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_IDEMPOTENCY_REPLAY_CONFLICT");
        }

        var samePayload = matches[0];

        return OperationResult<DesignConversionTrainingIntakeReplayResolution>.Ok(
            new DesignConversionTrainingIntakeReplayResolution(
                true,
                MarkCreateTrainingIntakeIdempotencyBoundary(
                    samePayload,
                    replayHit: true,
                    createdNewSideEffect: false)));
    }

    private static bool HasSameCreateTrainingIntakeIdempotencyBoundary(
        DesignConversionTrainingIntakeRecord existing,
        DesignConversionTrainingIntakeRecord candidate)
        => string.Equals(
               ReadMetadata(existing.BoundaryMetadata, "training_intake_tenant_id_ref"),
               ReadMetadata(candidate.BoundaryMetadata, "training_intake_tenant_id_ref"),
               StringComparison.Ordinal)
           && string.Equals(
               ReadMetadata(existing.BoundaryMetadata, "training_intake_idempotency_key_ref"),
               ReadMetadata(candidate.BoundaryMetadata, "training_intake_idempotency_key_ref"),
               StringComparison.Ordinal);

    private static bool HasCreateTrainingIntakeIdempotencyBoundary(
        IReadOnlyDictionary<string, string>? metadata)
        => !string.IsNullOrWhiteSpace(ReadMetadata(metadata, "training_intake_tenant_id_ref"))
           && !string.IsNullOrWhiteSpace(ReadMetadata(metadata, "training_intake_idempotency_key_ref"));

    private static string BuildNormalizedTrainingIntakeRecordFingerprint(
        DesignConversionTrainingIntakeRecord record)
    {
        var normalizedRecord = record;
        if (record.BoundaryMetadata is not null)
        {
            var normalizedMetadata = new Dictionary<string, string>(
                record.BoundaryMetadata,
                StringComparer.Ordinal);
            normalizedMetadata.Remove("training_intake_admission_boundary_scope");
            normalizedMetadata.Remove("training_intake_create_replay_cache_boundary");
            normalizedMetadata.Remove("training_intake_replay_cache_checked");
            normalizedMetadata.Remove("training_intake_idempotency_replay_hit");
            normalizedMetadata.Remove("training_intake_idempotency_created_new_side_effect");
            normalizedMetadata.Remove("training_intake_idempotent_replay_result");
            normalizedMetadata.Remove("training_intake_idempotency_side_effect_boundary");
            normalizedRecord = record with { BoundaryMetadata = normalizedMetadata };
        }

        using var document = JsonDocument.Parse(
            JsonSerializer.Serialize(normalizedRecord, JsonOptions));
        var canonical = new StringBuilder();
        canonical.Append(TrainingIntakeSemanticFingerprintPolicyVersion);
        canonical.Append('|');
        AppendCanonicalJson(document.RootElement, canonical);
        return $"sha256:{HashText(canonical.ToString())}";
    }

    private static DesignConversionTrainingIntakeRecord MarkCreateTrainingIntakeIdempotencyBoundary(
        DesignConversionTrainingIntakeRecord record,
        bool replayHit,
        bool createdNewSideEffect)
    {
        if (!HasCreateTrainingIntakeIdempotencyBoundary(record.BoundaryMetadata))
            return record;

        var metadata = new Dictionary<string, string>(record.BoundaryMetadata, StringComparer.Ordinal)
        {
            ["training_intake_admission_boundary_scope"] =
                "route_admission_plus_local_create_replay_cache_no_auth_token_no_full_tenant_isolation",
            ["training_intake_create_replay_cache_boundary"] =
                "tenant_id_idempotency_key_same_payload_create_replay_cache_v1",
            ["training_intake_replay_cache_checked"] = bool.TrueString,
            ["training_intake_idempotency_replay_hit"] = replayHit.ToString(),
            ["training_intake_idempotency_created_new_side_effect"] = createdNewSideEffect.ToString(),
            ["training_intake_idempotent_replay_result"] = replayHit.ToString(),
            ["training_intake_idempotency_side_effect_boundary"] = "create_training_intake_append_only_once"
        };

        return record with { BoundaryMetadata = metadata };
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeRunReplayResolution>> ResolveRunTrainingIntakeIdempotencyReplayAsync(
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        CancellationToken ct)
    {
        if (!HasRunTrainingIntakeIdempotencyBoundary(admissionBoundaryMetadata))
            return OperationResult<DesignConversionTrainingIntakeRunReplayResolution>.Ok(
                new DesignConversionTrainingIntakeRunReplayResolution(false, null));

        var existing = await ReadTrainingIntakeRunRecordsAsync(ct);
        if (!existing.IsSuccess)
            return existing.MapError<DesignConversionTrainingIntakeRunReplayResolution>();

        var matches = existing.Value!
            .Where(result => HasSameRunTrainingIntakeIdempotencyBoundary(result.BoundaryMetadata, admissionBoundaryMetadata))
            .OrderBy(result => ReadMetadata(result.BoundaryMetadata, "training_intake_run_recorded_at_utc"), StringComparer.Ordinal)
            .ThenBy(result => result.RunId, StringComparer.Ordinal)
            .ToArray();
        if (matches.Length == 0)
            return OperationResult<DesignConversionTrainingIntakeRunReplayResolution>.Ok(
                new DesignConversionTrainingIntakeRunReplayResolution(false, null));

        var payloadHash = BuildRunTrainingIntakeIdempotencyPayloadHash(intake, options);
        var samePayload = matches.FirstOrDefault(result =>
            string.Equals(
                ReadMetadata(result.BoundaryMetadata, "training_intake_run_idempotency_payload_hash"),
                payloadHash,
                StringComparison.Ordinal));
        if (samePayload is null)
        {
            return OperationResult<DesignConversionTrainingIntakeRunReplayResolution>.Fail(
                "DesignConversion training intake run idempotency key was replayed with a different intake or options payload.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_RUN_IDEMPOTENCY_REPLAY_CONFLICT");
        }

        return OperationResult<DesignConversionTrainingIntakeRunReplayResolution>.Ok(
            new DesignConversionTrainingIntakeRunReplayResolution(
                true,
                samePayload));
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeRunReplayValidation>>
        ValidateRunTrainingIntakeReplayCurrentSnapshotAsync(
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingIntakePreflightResult preflight,
            DesignConversionTrainingPipelineOptions runOptions,
            IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
            DesignConversionDpoCorpusAdmissionRequest? corpusAdmissionRequest,
            DesignConversionTrainingIntakeRunResult cachedResult,
            CancellationToken ct)
    {
        var resolved = await ResolveTrainingIntakeRecordsAsync(intake, ct);
        if (!resolved.IsSuccess || resolved.Value is null)
            return resolved.MapError<DesignConversionTrainingIntakeRunReplayValidation>();
        if (resolved.Value.BlockReasons.Count > 0)
        {
            return OperationResult<DesignConversionTrainingIntakeRunReplayValidation>
                .Fail(
                    "DesignConversion training intake run idempotency replay cannot be returned because current intake records no longer resolve.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_RUN_IDEMPOTENCY_REPLAY_CONFLICT");
        }

        var recordsSnapshot = DesignConversionTrainingPipeline.SnapshotTrainingRecords(
            resolved.Value.Records);
        if (!recordsSnapshot.IsSuccess || recordsSnapshot.Value is null)
        {
            return recordsSnapshot.MapError<
                DesignConversionTrainingIntakeRunReplayValidation>();
        }
        var optionsSnapshot =
            DesignConversionTrainingPipeline.SnapshotOptions(runOptions);
        if (!optionsSnapshot.IsSuccess || optionsSnapshot.Value is null)
        {
            return optionsSnapshot.MapError<
                DesignConversionTrainingIntakeRunReplayValidation>();
        }

        var snapshotRecords = recordsSnapshot.Value;
        var snapshotOptions = optionsSnapshot.Value;
        var boundaryMetadata = admissionBoundaryMetadata is null
            ? new Dictionary<string, string>(StringComparer.Ordinal)
            : new Dictionary<string, string>(
                admissionBoundaryMetadata,
                StringComparer.Ordinal);
        AddCurrentRunReplaySnapshotMetadata(
            boundaryMetadata,
            snapshotRecords,
            snapshotOptions);
        var cachedMetadata = cachedResult.BoundaryMetadata;
        if (!CachedRunReplayMetadataMatches(
                cachedMetadata,
                "training_intake_run_current_records_snapshot_sha256",
                boundaryMetadata["training_intake_run_current_records_snapshot_sha256"]) ||
            !CachedRunReplayMetadataMatches(
                cachedMetadata,
                "training_intake_run_current_options_snapshot_sha256",
                boundaryMetadata["training_intake_run_current_options_snapshot_sha256"]))
        {
            return InvalidCorpusRunReplayBinding();
        }

        if (!DesignConversionDpoCorpusAdmissionRequirementPolicy
                .RequiresAdmission(snapshotRecords))
        {
            return OperationResult<DesignConversionTrainingIntakeRunReplayValidation>
                .Ok(new DesignConversionTrainingIntakeRunReplayValidation(
                    snapshotRecords,
                    snapshotOptions,
                    boundaryMetadata));
        }

        if (corpusAdmissionRequest is null)
            return DpoCorpusAdmissionRequired<DesignConversionTrainingIntakeRunReplayValidation>();

        var requestSnapshot = ValidateCorpusAdmissionRequestMatchesSnapshot(
            snapshotRecords,
            corpusAdmissionRequest);
        if (!requestSnapshot.IsSuccess || requestSnapshot.Value is null)
            return requestSnapshot.MapError<DesignConversionTrainingIntakeRunReplayValidation>();

        var requestBinding = await BuildCorpusAdmissionRequestBindingAsync(
            intake,
            preflight,
            snapshotOptions,
            boundaryMetadata,
            snapshotRecords,
            resolved.Value.CustodyEvidence.ToArray(),
            ct);
        if (!requestBinding.IsSuccess || requestBinding.Value is null)
            return requestBinding.MapError<DesignConversionTrainingIntakeRunReplayValidation>();

        boundaryMetadata["corpus_admission_request_binding_sha256"] =
            requestBinding.Value;
        boundaryMetadata["corpus_admission_receipt_sha256"] =
            corpusAdmissionRequest.Receipt.ReceiptSha256;
        boundaryMetadata["corpus_admission_source_proof_sha256"] =
            requestSnapshot.Value.SourceProofSha256;
        boundaryMetadata["corpus_admission_reservation"] =
            "durable_fail_closed_before_mutation";

        if (!CachedRunReplayMetadataExactlyMatches(
                cachedMetadata,
                "training_intake_run_current_records_snapshot_sha256",
                boundaryMetadata["training_intake_run_current_records_snapshot_sha256"]) ||
            !CachedRunReplayMetadataExactlyMatches(
                cachedMetadata,
                "training_intake_run_current_options_snapshot_sha256",
                boundaryMetadata["training_intake_run_current_options_snapshot_sha256"]) ||
            !CachedRunReplayMetadataExactlyMatches(
                cachedMetadata,
                "corpus_admission_request_binding_sha256",
                requestBinding.Value) ||
            !CachedRunReplayMetadataExactlyMatches(
                cachedMetadata,
                "corpus_admission_receipt_sha256",
                corpusAdmissionRequest.Receipt.ReceiptSha256) ||
            !CachedRunReplayMetadataExactlyMatches(
                cachedMetadata,
                "corpus_admission_source_proof_sha256",
                requestSnapshot.Value.SourceProofSha256))
        {
            return InvalidCorpusRunReplayBinding();
        }

        return OperationResult<DesignConversionTrainingIntakeRunReplayValidation>
            .Ok(new DesignConversionTrainingIntakeRunReplayValidation(
                snapshotRecords,
                snapshotOptions,
                boundaryMetadata));

        static OperationResult<DesignConversionTrainingIntakeRunReplayValidation>
            InvalidCorpusRunReplayBinding()
            => OperationResult<DesignConversionTrainingIntakeRunReplayValidation>
                .Fail(
                    "DesignConversion training intake run idempotency replay does not match the current corpus admission authority.",
                    DesignConversionDpoCorpusAdmissionAuthority.InvalidErrorCode);
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeRunResult>> StoreRunTrainingIntakeIdempotencyResultAsync(
        DesignConversionTrainingIntakeRunResult result,
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        CancellationToken ct,
        IReadOnlyList<DesignConversionDpoTrainingRecord>? snapshotRecords = null)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeRunResult>();

        var stored = MarkRunTrainingIntakeIdempotencyBoundary(
            result,
            intake,
            options,
            admissionBoundaryMetadata,
            replayHit: false,
            createdNewSideEffect: true,
            snapshotRecords);
        var line = JsonSerializer.Serialize(stored, JsonOptions);
        var framedLineByteLength = StrictUtf8Encoding.GetByteCount(line + Environment.NewLine);
        if (framedLineByteLength > MaxTrainingIntakeRunJournalRowByteLength
            || !TryProjectTrainingIntakeRunsLength(framedLineByteLength, out var projectedLength)
            || projectedLength > _trainingIntakeRunsMaxBytes)
        {
            return TrainingIntakeRunsQuotaExceeded<DesignConversionTrainingIntakeRunResult>();
        }

        Directory.CreateDirectory(_rootDirectory);
        await DurableCopyOnWriteAppendJsonLineAsync(
            _trainingIntakeRunPath,
            line,
            DesignConversionTrainingJournalPublicationKind.TrainingIntakeRuns,
            _trainingJournalBeforeAtomicPublishCallbackForTesting,
            ct);

        return OperationResult<DesignConversionTrainingIntakeRunResult>.Ok(stored);
    }

    private bool CanReserveMaximumTrainingIntakeRunJournalRow()
        => TryProjectTrainingIntakeRunsLength(
                MaxTrainingIntakeRunJournalRowByteLength,
                out var projectedLength)
           && projectedLength <= _trainingIntakeRunsMaxBytes;

    private bool TryProjectTrainingIntakeRunsLength(
        long appendedLineByteLength,
        out long projectedLength)
    {
        var existingLength = File.Exists(_trainingIntakeRunPath)
            ? new FileInfo(_trainingIntakeRunPath).Length
            : 0;

        return TryProjectCommittedAuthorityLength(
            existingLength,
            appendedLineByteLength,
            out projectedLength);
    }

    private async Task<OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>> ReadTrainingIntakeRunRecordsAsync(
        CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>();
        if (!File.Exists(_trainingIntakeRunPath))
            return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>.Ok([]);

        var records = new List<DesignConversionTrainingIntakeRunResult>();
        string[] lines;
        try
        {
            lines = await File.ReadAllLinesAsync(_trainingIntakeRunPath, StrictUtf8Encoding, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>();
        }
        catch (DecoderFallbackException)
        {
            return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>.Fail(
                "DesignConversion training intake runs could not be read because the training intake runs file is not valid UTF-8.",
                InvalidUtf8ErrorCode);
        }
        catch (IOException)
        {
            return TrainingIntakeRunReadFailed<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>();
        }
        catch (UnauthorizedAccessException)
        {
            return TrainingIntakeRunReadFailed<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>();
        }
        catch (SecurityException)
        {
            return TrainingIntakeRunReadFailed<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>();
        }

        for (var i = 0; i < lines.Length; i++)
        {
            if (string.IsNullOrWhiteSpace(lines[i]))
                continue;

            DesignConversionTrainingIntakeRunResult? record;
            try
            {
                record = JsonSerializer.Deserialize<DesignConversionTrainingIntakeRunResult>(
                    lines[i],
                    JsonOptions);
            }
            catch (JsonException)
            {
                return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>.Fail(
                    $"DesignConversion training intake run line {(i + 1).ToString(CultureInfo.InvariantCulture)} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_RUN_LINE_INVALID");
            }
            catch (NotSupportedException)
            {
                return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>.Fail(
                    $"DesignConversion training intake run line {(i + 1).ToString(CultureInfo.InvariantCulture)} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_RUN_LINE_INVALID");
            }

            if (record is null)
            {
                return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>.Fail(
                    $"DesignConversion training intake run line {(i + 1).ToString(CultureInfo.InvariantCulture)} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_RUN_LINE_INVALID");
            }

            records.Add(record);
        }

        return OperationResult<IReadOnlyList<DesignConversionTrainingIntakeRunResult>>.Ok(records.ToArray());
    }

    private static DesignConversionTrainingIntakeRunResult MarkRunTrainingIntakeIdempotencyBoundary(
        DesignConversionTrainingIntakeRunResult result,
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        bool replayHit,
        bool createdNewSideEffect,
        IReadOnlyList<DesignConversionDpoTrainingRecord>? snapshotRecords = null)
    {
        var metadata = new Dictionary<string, string>(result.BoundaryMetadata, StringComparer.Ordinal);
        foreach (var pair in admissionBoundaryMetadata ?? new Dictionary<string, string>(StringComparer.Ordinal))
            metadata[pair.Key] = pair.Value;

        if (!HasRunTrainingIntakeIdempotencyBoundary(metadata))
            return result with { BoundaryMetadata = metadata };

        metadata["training_intake_admission_boundary_scope"] =
            "route_admission_plus_local_run_replay_cache_no_auth_token_no_full_tenant_isolation";
        metadata["training_intake_run_replay_cache_boundary"] =
            "tenant_id_idempotency_key_same_intake_options_run_replay_cache_v1";
        metadata["training_intake_replay_cache_checked"] = bool.TrueString;
        metadata["training_intake_idempotency_replay_hit"] = replayHit.ToString();
        metadata["training_intake_idempotency_created_new_side_effect"] = createdNewSideEffect.ToString();
        metadata["training_intake_idempotent_replay_result"] = replayHit.ToString();
        metadata["training_intake_idempotency_side_effect_boundary"] = "run_training_intake_append_only_once";
        metadata["training_intake_run_idempotency_payload_hash"] =
            BuildRunTrainingIntakeIdempotencyPayloadHash(intake, options);
        if (snapshotRecords is not null)
            AddCurrentRunReplaySnapshotMetadata(metadata, snapshotRecords, options);
        metadata["training_intake_run_recorded_at_utc"] = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);

        return result with { BoundaryMetadata = metadata };
    }

    private static bool HasSameRunTrainingIntakeIdempotencyBoundary(
        IReadOnlyDictionary<string, string>? existing,
        IReadOnlyDictionary<string, string>? candidate)
        => string.Equals(
               ReadMetadata(existing, "training_intake_tenant_id_ref"),
               ReadMetadata(candidate, "training_intake_tenant_id_ref"),
               StringComparison.Ordinal)
           && string.Equals(
               ReadMetadata(existing, "training_intake_idempotency_key_ref"),
               ReadMetadata(candidate, "training_intake_idempotency_key_ref"),
               StringComparison.Ordinal);

    private static bool HasRunTrainingIntakeIdempotencyBoundary(
        IReadOnlyDictionary<string, string>? metadata)
        => !string.IsNullOrWhiteSpace(ReadMetadata(metadata, "training_intake_tenant_id_ref"))
           && !string.IsNullOrWhiteSpace(ReadMetadata(metadata, "training_intake_idempotency_key_ref"));

    private static string BuildRunTrainingIntakeIdempotencyPayloadHash(
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options)
        => $"sha256:{HashText(string.Join("|",
        [
            TrainingIntakeRunSchemaVersion,
            intake.IntakeId,
            JsonSerializer.Serialize(options, JsonOptions)
        ]))}";

    private static OperationResult<bool> RequireCallerAdmissionMeasurement(
        DesignConversionTrainingPipelineOptions options)
    {
        var measurement = new DesignConversionMeasurementGateEvaluator().Evaluate(
            options.MeasurementGateRequest);
        if (measurement.Passed)
            return OperationResult<bool>.Ok(true);

        return OperationResult<bool>.Fail(
            "Caller admission/advisory measurement did not pass; no local training mutation was started.",
            "DESIGN_CONVERSION_CALLER_ADMISSION_MEASUREMENT_NOT_PASSED");
    }

    private static OperationResult<bool> RequireUniqueTeacherRequestIdsBeforeLocalMutation(
        IReadOnlyList<DesignConversionDpoTrainingRecord> records)
    {
        var duplicate = records
            .Select(static record => record.TeacherProvenance?.RequestId)
            .Where(static requestId => !string.IsNullOrWhiteSpace(requestId))
            .GroupBy(static requestId => requestId, StringComparer.Ordinal)
            .FirstOrDefault(static request => request.Count() > 1);
        if (duplicate is null)
            return OperationResult<bool>.Ok(true);

        return OperationResult<bool>.Fail(
            "A teacher request id may authorize exactly one training row.",
            LegalTrainingTeacherAdmissionAuthority.DuplicateRequestIdErrorCode);
    }

    private static bool RequiresDpoCorpusAdmissionBeforeOrdinaryDuplicateAuthority(
        IReadOnlyList<DesignConversionDpoTrainingRecord> records)
        => DesignConversionDpoCorpusAdmissionRequirementPolicy
            .RequiresAdmission(records);

    private static bool IsPotentialOrdinaryDualTargetTeacherAggregateBeforeDeepAuthority(
        IReadOnlyList<DesignConversionDpoTrainingRecord> records)
    {
        var duplicateGroups = records
            .Where(static record => !string.IsNullOrWhiteSpace(
                record.TeacherProvenance?.RequestId))
            .GroupBy(
                static record => record.TeacherProvenance!.RequestId!,
                StringComparer.Ordinal)
            .Where(static group => group.Count() > 1)
            .ToArray();
        if (duplicateGroups.Length != 1)
            return false;

        var duplicateRecords = duplicateGroups[0].ToArray();
        if (duplicateRecords.Length != 2)
            return false;

        var distinctRecordIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var record in duplicateRecords)
        {
            if (string.IsNullOrWhiteSpace(record.RecordId) ||
                !distinctRecordIds.Add(record.RecordId))
            {
                return false;
            }
        }

        return duplicateRecords.Count(static record => string.Equals(
                   record.UnitId,
                   DesignConversionDpoUnits.CriticUnit,
                   StringComparison.Ordinal)) == 1 &&
               duplicateRecords.Count(static record => string.Equals(
                   record.UnitId,
                   DesignConversionDpoUnits.ImproverUnit,
                   StringComparison.Ordinal)) == 1;
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeRecordResolution>>
        ResolveTrainingIntakeRecordsForFreshRunBoundaryAsync(
            DesignConversionTrainingIntakeRecord intake,
            CancellationToken ct)
    {
        var resolved = await ResolveTrainingIntakeRecordsAsync(intake, ct);
        if (!resolved.IsSuccess || resolved.Value is null)
            return resolved;

        // Локальная публикация проверяет данные несколько раз: перед runner,
        // перед мостом политики и перед публикацией результата. Тестовый
        // переключатель должен проходить через те же границы, иначе регрессия
        // не докажет, что поздняя замена held-out записи реально останавливает
        // публикацию. Когда hook не задан, метод возвращает обычное свежее
        // чтение без изменений.
        return OperationResult<DesignConversionTrainingIntakeRecordResolution>.Ok(
            TransformRunTrainingIntakeResolvedRecordsForTesting(resolved.Value));
    }

    private DesignConversionTrainingIntakeRecordResolution
        TransformRunTrainingIntakeResolvedRecordsForTesting(
            DesignConversionTrainingIntakeRecordResolution resolution)
        => _runTrainingIntakeResolvedRecordsTransformerForTesting is null
            ? resolution
            : resolution with
            {
                Records = _runTrainingIntakeResolvedRecordsTransformerForTesting(
                    resolution.Records)
            };

    private static string BuildPromoteLocalOperationId(
        IReadOnlyDictionary<string, string> admissionBoundaryMetadata)
        => $"local-promotion-operation-{HashText(string.Join("|",
        [
            TrainingIntakeLocalPromotionOperationSchemaVersion,
            ReadMetadata(admissionBoundaryMetadata, "training_intake_tenant_id_ref"),
            ReadMetadata(admissionBoundaryMetadata, "training_intake_idempotency_key_ref")
        ]))}";

    private static string BuildPairStoreInputSha256(DpoPair pair)
        => $"sha256:{HashText(JsonSerializer.Serialize(pair, JsonOptions))}";

    private static string BuildPairStoreInputsSha256(IReadOnlyList<string> pairHashes)
        => $"sha256:{HashText(string.Join("\n", pairHashes))}";

    private OperationResult<LocalPromotionUploaderAuthorityPreflight>
        ResolvePromotionUploaderAuthorityPreflight(
            bool promotionMayStart)
    {
        if (_promotionUploader is null)
        {
            if (_localReceiptOnlyPromotionAuthority is not null ||
                _serverOwnedConfiguredRemotePromotionAuthority is not null)
            {
                return OperationResult<LocalPromotionUploaderAuthorityPreflight>
                    .Fail(
                        "DesignConversion promotion upload authority cannot be bound without a configured uploader.",
                        "DESIGN_CONVERSION_PROMOTION_UPLOAD_AUTHORITY_INVALID");
            }

            // The built-in authority may issue a local receipt, but it cannot authorize a server upload.
            return OperationResult<LocalPromotionUploaderAuthorityPreflight>.Ok(
                BuildBuiltInLocalReceiptOnlyPromotionUploaderAuthorityPreflight());
        }

        if (!promotionMayStart)
        {
            var blockedFingerprint =
                BuildLocalPromotionUploaderAuthorityFingerprint(
                "BlockedBeforePromotion",
                _promotionUploader.GetType().FullName ?? "configured-uploader",
                64 * 1024,
                "sha256:" + HashText(
                    "design-conversion-local-promotion-blocked-before-uploader-v1"));
            return OperationResult<LocalPromotionUploaderAuthorityPreflight>.Ok(
                new LocalPromotionUploaderAuthorityPreflight(
                    "BlockedBeforePromotion",
                    blockedFingerprint,
                    BudgetTierPolicyPassed: false,
                    BudgetTier: "promotion-blocked-before-uploader-authority",
                    DesignConversionPromotionUploadAuthorityMode.Unrestricted,
                    64 * 1024,
                    [
                        "DESIGN_CONVERSION_LOCAL_PROMOTION_BLOCKED_BEFORE_UPLOADER_AUTHORITY"
                    ]));
        }

        if (_promotionUploader is not
                IDesignConversionBoundedPromotionUploader boundedUploader ||
            boundedUploader.MaximumSerializedReceiptUtf8Bytes <= 0 ||
            boundedUploader.MaximumSerializedReceiptUtf8Bytes > 64 * 1024 ||
            _promotionUploader is not
                IDesignConversionPromotionUploaderPreflight uploaderPreflight)
        {
            return OperationResult<LocalPromotionUploaderAuthorityPreflight>.Fail(
                "DesignConversion crash-safe local promotion requires bounded receipt and mutation-free uploader configuration fingerprint contracts.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_UPLOADER_BOUND_REQUIRED");
        }
        var fingerprint = uploaderPreflight
            .PreflightConfigurationFingerprintSha256();
        if (!fingerprint.IsSuccess)
        {
            return fingerprint.MapError<
                LocalPromotionUploaderAuthorityPreflight>();
        }
        if (!IsSha256Ref(fingerprint.Value))
        {
            return OperationResult<LocalPromotionUploaderAuthorityPreflight>.Fail(
                "DesignConversion promotion uploader configuration fingerprint is invalid.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_UPLOADER_FINGERPRINT_INVALID");
        }

        var uploaderTypeIdentity = _promotionUploader.GetType().FullName ??
                                   _promotionUploader.GetType().Name;
        if (_localReceiptOnlyPromotionAuthority is not null &&
            _serverOwnedConfiguredRemotePromotionAuthority is not null)
        {
            return OperationResult<LocalPromotionUploaderAuthorityPreflight>.Fail(
                "DesignConversion promotion uploader authority modes are mutually exclusive.",
                "DESIGN_CONVERSION_PROMOTION_UPLOAD_AUTHORITY_MODE_EXCLUSIVE_REQUIRED");
        }

        if (_serverOwnedConfiguredRemotePromotionAuthority is not null)
        {
            var remoteAuthorityValidation =
                _serverOwnedConfiguredRemotePromotionAuthority.Validate(
                    _promotionUploader,
                    _legalTeacherAdmissionAuthority,
                    fingerprint.Value!,
                    boundedUploader.MaximumSerializedReceiptUtf8Bytes);
            if (!remoteAuthorityValidation.IsSuccess)
            {
                return remoteAuthorityValidation.MapError<
                    LocalPromotionUploaderAuthorityPreflight>();
            }

            return OperationResult<LocalPromotionUploaderAuthorityPreflight>.Ok(
                new LocalPromotionUploaderAuthorityPreflight(
                    "ServerOwnedConfiguredRemote",
                    remoteAuthorityValidation.Value!.StableAuthorityFingerprintSha256,
                    BudgetTierPolicyPassed: true,
                    BudgetTier: "server-owned-configured-remote-authorized",
                    DesignConversionPromotionUploadAuthorityMode
                        .ServerOwnedConfiguredRemote,
                    remoteAuthorityValidation.Value.MaximumSerializedReceiptUtf8Bytes,
                    [
                        "DESIGN_CONVERSION_SERVER_OWNED_CONFIGURED_REMOTE_UPLOAD_AUTHORITY_VALIDATED",
                        "DESIGN_CONVERSION_SERVER_OWNED_CONFIGURED_REMOTE_PROMOTION_BUDGET_POLICY_PASSED",
                        "DESIGN_CONVERSION_SERVER_OWNED_CONFIGURED_REMOTE_PROMOTION_INTEGRITY_POLICY_PASSED",
                        "DESIGN_CONVERSION_MODEL_SERVER_ROUTE_ADMISSION_TENANT_BOUND_FOR_REMOTE_PROMOTION",
                        remoteAuthorityValidation.Value.RouteBindingFingerprintSha256,
                        remoteAuthorityValidation.Value.IssuerEvidenceRef
                    ]));
        }

        if (_localReceiptOnlyPromotionAuthority is null)
        {
            var untrustedFingerprint =
                BuildLocalPromotionUploaderAuthorityFingerprint(
                    "ConfiguredUploaderUntrusted",
                    uploaderTypeIdentity,
                    boundedUploader.MaximumSerializedReceiptUtf8Bytes,
                    fingerprint.Value!);
            return OperationResult<LocalPromotionUploaderAuthorityPreflight>.Ok(
                new LocalPromotionUploaderAuthorityPreflight(
                    "ConfiguredUploaderUntrusted",
                    untrustedFingerprint,
                    BudgetTierPolicyPassed: false,
                    BudgetTier:
                    "server-owned-promotion-budget-policy-not-configured",
                    DesignConversionPromotionUploadAuthorityMode
                        .Unrestricted,
                    boundedUploader.MaximumSerializedReceiptUtf8Bytes,
                    [
                        "DESIGN_CONVERSION_SERVER_OWNED_PROMOTION_BUDGET_AUTHORITY_NOT_CONFIGURED",
                        "DESIGN_CONVERSION_SERVER_OWNED_PROMOTION_INTEGRITY_AUTHORITY_NOT_CONFIGURED",
                        "DESIGN_CONVERSION_CONFIGURED_PROMOTION_UPLOADER_UNTRUSTED_BY_DEFAULT"
                    ]));
        }

        var authorityValidation = _localReceiptOnlyPromotionAuthority.Validate(
            _promotionUploader,
            fingerprint.Value!,
            boundedUploader.MaximumSerializedReceiptUtf8Bytes);
        if (!authorityValidation.IsSuccess)
        {
            return authorityValidation.MapError<
                LocalPromotionUploaderAuthorityPreflight>();
        }

        return OperationResult<LocalPromotionUploaderAuthorityPreflight>.Ok(
            new LocalPromotionUploaderAuthorityPreflight(
                "LocalReceiptOnly",
                authorityValidation.Value!.StableAuthorityFingerprintSha256,
                BudgetTierPolicyPassed: true,
                BudgetTier: "local-receipt-only-authorized-no-remote",
                DesignConversionPromotionUploadAuthorityMode.LocalReceiptOnly,
                authorityValidation.Value.MaximumSerializedReceiptUtf8Bytes,
                [
                    "DESIGN_CONVERSION_LOCAL_RECEIPT_ONLY_UPLOAD_AUTHORITY_VALIDATED",
                    "DESIGN_CONVERSION_LOCAL_RECEIPT_ONLY_PROMOTION_BUDGET_POLICY_PASSED",
                    "DESIGN_CONVERSION_LOCAL_RECEIPT_ONLY_PROMOTION_INTEGRITY_POLICY_PASSED",
                    authorityValidation.Value.IssuerEvidenceRef
                ]));
    }

    private static LocalPromotionUploaderAuthorityPreflight
        BuildBuiltInLocalReceiptOnlyPromotionUploaderAuthorityPreflight()
    {
        var builtInFingerprint =
            BuildLocalPromotionUploaderAuthorityFingerprint(
                "BuiltInLocalReceiptOnly",
                "design-conversion-local-only-promotion-uploader",
                64 * 1024,
                "sha256:" + HashText(
                    "design-conversion-local-only-promotion-uploader-v1"));
        return new LocalPromotionUploaderAuthorityPreflight(
            "BuiltInLocalReceiptOnly",
            builtInFingerprint,
            BudgetTierPolicyPassed: true,
            BudgetTier: "built-in-local-only-no-remote",
            DesignConversionPromotionUploadAuthorityMode.LocalReceiptOnly,
            64 * 1024,
            [
                "DESIGN_CONVERSION_BUILT_IN_LOCAL_ONLY_PROMOTION_BUDGET_POLICY_PASSED",
                "DESIGN_CONVERSION_BUILT_IN_LOCAL_ONLY_PROMOTION_INTEGRITY_POLICY_PASSED"
            ]);
    }

    private static string BuildLocalPromotionUploaderAuthorityFingerprint(
        string authorityMode,
        string uploaderTypeIdentity,
        int maximumSerializedReceiptUtf8Bytes,
        string preflightFingerprintSha256)
        => $"sha256:{HashText(string.Join("|",
        [
            "design-conversion-local-promotion-uploader-authority-fingerprint-v1",
            authorityMode,
            uploaderTypeIdentity,
            maximumSerializedReceiptUtf8Bytes.ToString(CultureInfo.InvariantCulture),
            preflightFingerprintSha256,
            MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength
                .ToString(CultureInfo.InvariantCulture)
        ]))}";

    internal static string BuildLocalPromotionOperationRecordSha256(
        LocalPromotionOperationJournalRecord record)
        => $"sha256:{HashText(JsonSerializer.Serialize(
            record with { RecordSha256 = string.Empty },
            JsonOptions))}";

    internal static string BuildLocalPromotionFinalResultSha256(
        DesignConversionTrainingIntakeLocalPromotionResult result)
    {
        var metadata = new Dictionary<string, string>(
            result.BoundaryMetadata,
            StringComparer.Ordinal);
        metadata.Remove("local_promotion_committed_snapshot_sha256");
        return $"sha256:{HashText(JsonSerializer.Serialize(
            result with { BoundaryMetadata = metadata },
            JsonOptions))}";
    }

    private async Task<OperationResult<IReadOnlyList<LocalPromotionOperationJournalRecord>>>
        ReadLocalPromotionOperationJournalAsync(CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<IReadOnlyList<LocalPromotionOperationJournalRecord>>();
        var journalSet = await _localPromotionJournalSet.ReadAsync(ct);
        if (!journalSet.IsSuccess)
        {
            return string.Equals(
                journalSet.ErrorCode,
                InvalidUtf8ErrorCode,
                StringComparison.Ordinal)
                ? TrainingIntakeLocalPromotionsInvalidUtf8<IReadOnlyList<
                    LocalPromotionOperationJournalRecord>>()
                : journalSet.MapError<IReadOnlyList<
                    LocalPromotionOperationJournalRecord>>();
        }
        var lines = journalSet.Value!.OperationLines;

        var records = new List<LocalPromotionOperationJournalRecord>();
        var states = new Dictionary<string, LocalPromotionOperationState>(
            StringComparer.Ordinal);
        var previousHash = string.Empty;
        foreach (var physicalLine in lines)
        {
            var line = physicalLine.Text;
            if (string.IsNullOrWhiteSpace(line) ||
                StrictUtf8Encoding.GetByteCount(line + "\r\n") >
                    MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength)
                return LocalPromotionOperationStateInvalid<
                    IReadOnlyList<LocalPromotionOperationJournalRecord>>();

            LocalPromotionOperationJournalRecord? record;
            try
            {
                record = JsonSerializer.Deserialize<
                    LocalPromotionOperationJournalRecord>(line, JsonOptions);
            }
            catch (Exception exception) when (exception is JsonException or NotSupportedException)
            {
                return LocalPromotionOperationStateInvalid<
                    IReadOnlyList<LocalPromotionOperationJournalRecord>>();
            }

            if (record is null ||
                !string.Equals(
                    record.SchemaVersion,
                    TrainingIntakeLocalPromotionOperationSchemaVersion,
                    StringComparison.Ordinal) ||
                record.Version != 1 ||
                string.IsNullOrWhiteSpace(record.OperationId) ||
                string.IsNullOrWhiteSpace(record.TenantIdRef) ||
                string.IsNullOrWhiteSpace(record.IdempotencyKeyRef) ||
                !IsSha256Ref(record.PayloadSha256) ||
                string.IsNullOrWhiteSpace(record.CanonicalPromotionOutputDirectory) ||
                string.IsNullOrWhiteSpace(record.RunId) ||
                record.RecordedAtUtc == default ||
                record.PairStoreInputCount < 0 ||
                record.PairStoreInputSha256s is null ||
                record.PairStoreInputCount != record.PairStoreInputSha256s.Count ||
                record.PairStoreInputSha256s.Any(hash => !IsSha256Ref(hash)) ||
                !IsSha256Ref(record.PairStoreInputsSha256) ||
                !string.Equals(
                    record.PairStoreInputsSha256,
                    BuildPairStoreInputsSha256(record.PairStoreInputSha256s),
                    StringComparison.Ordinal) ||
                !string.Equals(
                    record.PairStoreReservationId,
                    $"{record.OperationId}:dpo-pair-batch-v1",
                    StringComparison.Ordinal) ||
                !IsSha256Ref(record.PairStoreReservationSha256) ||
                string.IsNullOrWhiteSpace(
                    record.OutputNamespaceReservationRef) ||
                !Path.IsPathFullyQualified(
                    record.OutputNamespaceReservationRef) ||
                !string.Equals(
                    record.OutputNamespaceReservationRef,
                    BuildLocalPromotionOutputReservationRef(
                        record.OperationId),
                    StringComparison.Ordinal) ||
                !IsSha256Ref(record.OutputNamespaceReservationSha256) ||
                !IsSha256Ref(record.UploaderEnvelopeReservationSha256) ||
                string.IsNullOrWhiteSpace(record.UploaderAuthorityMode) ||
                !IsSha256Ref(
                    record.UploaderConfigurationFingerprintSha256) ||
                record.ArtifactDescriptors is null ||
                !HasValidLocalPromotionProjectionPrefixDeclaration(record) ||
                !string.Equals(record.PreviousRecordSha256, previousHash, StringComparison.Ordinal) ||
                !IsSha256Ref(record.RecordSha256) ||
                !string.Equals(
                    record.RecordSha256,
                    BuildLocalPromotionOperationRecordSha256(record),
                    StringComparison.Ordinal))
            {
                return LocalPromotionOperationStateInvalid<
                    IReadOnlyList<LocalPromotionOperationJournalRecord>>();
            }

            record = record with
            {
                JournalGeneration = physicalLine.Generation,
                JournalOrdinal = physicalLine.Ordinal,
                JournalIsActive = physicalLine.IsActive
            };

            states.TryGetValue(
                record.OperationId,
                out var state);
            state ??= new LocalPromotionOperationState(null, null, null, null);
            if (!LocalPromotionOperationIdentityMatches(state, record) ||
                !TryAdvanceLocalPromotionOperationState(state, record, out var advanced))
            {
                return LocalPromotionOperationStateInvalid<
                    IReadOnlyList<LocalPromotionOperationJournalRecord>>();
            }

            states[record.OperationId] = advanced!;
            records.Add(record);
            previousHash = record.RecordSha256;
        }

        return OperationResult<IReadOnlyList<LocalPromotionOperationJournalRecord>>
            .Ok(records.ToArray());
    }

    private static bool LocalPromotionOperationIdentityMatches(
        LocalPromotionOperationState state,
        LocalPromotionOperationJournalRecord candidate)
    {
        var first = state.Prepare ?? state.Intent ?? state.Prepared ?? state.Committed;
        return first is null ||
               string.Equals(first.TenantIdRef, candidate.TenantIdRef, StringComparison.Ordinal) &&
               string.Equals(first.IdempotencyKeyRef, candidate.IdempotencyKeyRef, StringComparison.Ordinal) &&
               string.Equals(first.PayloadSha256, candidate.PayloadSha256, StringComparison.Ordinal) &&
               PathsEqualForPlatform(
                   first.CanonicalPromotionOutputDirectory,
                   candidate.CanonicalPromotionOutputDirectory) &&
               string.Equals(first.RunId, candidate.RunId, StringComparison.Ordinal) &&
               first.PairStoreInputSha256s.SequenceEqual(
                   candidate.PairStoreInputSha256s,
                   StringComparer.Ordinal) &&
               string.Equals(
                   first.PairStoreInputsSha256,
                   candidate.PairStoreInputsSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   first.PairStoreReservationId,
                   candidate.PairStoreReservationId,
                   StringComparison.Ordinal) &&
               string.Equals(
                   first.PairStoreReservationSha256,
                   candidate.PairStoreReservationSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   first.OutputNamespaceReservationRef,
                   candidate.OutputNamespaceReservationRef,
                   StringComparison.Ordinal) &&
               string.Equals(
                   first.OutputNamespaceReservationSha256,
                   candidate.OutputNamespaceReservationSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   first.UploaderEnvelopeReservationSha256,
                   candidate.UploaderEnvelopeReservationSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   first.UploaderAuthorityMode,
                   candidate.UploaderAuthorityMode,
                   StringComparison.Ordinal) &&
               string.Equals(
                   first.UploaderConfigurationFingerprintSha256,
                   candidate.UploaderConfigurationFingerprintSha256,
                   StringComparison.Ordinal);
    }

    private static bool TryAdvanceLocalPromotionOperationState(
        LocalPromotionOperationState state,
        LocalPromotionOperationJournalRecord record,
        out LocalPromotionOperationState? advanced)
    {
        advanced = null;
        switch (record.Phase)
        {
            case LocalPromotionOperationPhase.Prepare when
                state.Phase is null &&
                record.FinalResult is null &&
                string.IsNullOrEmpty(record.FinalResultSha256) &&
                record.ArtifactDescriptors.Count == 0:
                advanced = state with { Prepare = record };
                return true;
            case LocalPromotionOperationPhase.Intent when
                state.Phase == LocalPromotionOperationPhase.Prepare &&
                record.FinalResult is null &&
                string.IsNullOrEmpty(record.FinalResultSha256) &&
                record.ArtifactDescriptors.Count == 0:
                advanced = state with { Intent = record };
                return true;
            case LocalPromotionOperationPhase.Prepared when
                state.Phase == LocalPromotionOperationPhase.Intent &&
                record.FinalResult is not null &&
                PreparedFinalResultCrossBindingMatches(record) &&
                IsSha256Ref(record.FinalResultSha256) &&
                string.Equals(
                    record.FinalResultSha256,
                    BuildLocalPromotionFinalResultSha256(record.FinalResult),
                    StringComparison.Ordinal) &&
                string.Equals(
                    ReadMetadata(
                        record.FinalResult.BoundaryMetadata,
                        "local_promotion_operation_id"),
                    record.OperationId,
                    StringComparison.Ordinal) &&
                string.Equals(
                    ReadMetadata(
                        record.FinalResult.BoundaryMetadata,
                        "local_promotion_committed_snapshot_sha256"),
                    record.FinalResultSha256,
                    StringComparison.Ordinal):
                advanced = state with { Prepared = record };
                return true;
            case LocalPromotionOperationPhase.Committed when
                state.Phase == LocalPromotionOperationPhase.Prepared &&
                record.FinalResult is null &&
                record.ArtifactDescriptors.Count == 0 &&
                string.Equals(
                    record.FinalResultSha256,
                    state.Prepared!.FinalResultSha256,
                    StringComparison.Ordinal):
                advanced = state with { Committed = record };
                return true;
            default:
                return false;
        }
    }

    private static bool PreparedFinalResultCrossBindingMatches(
        LocalPromotionOperationJournalRecord prepared)
    {
        var result = prepared.FinalResult;
        if (result is null)
            return false;
        var metadata = result.BoundaryMetadata;
        return string.Equals(
                   ReadMetadata(metadata, "training_intake_tenant_id_ref"),
                   prepared.TenantIdRef,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(metadata, "training_intake_idempotency_key_ref"),
                   prepared.IdempotencyKeyRef,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(
                       metadata,
                       "training_intake_promote_local_idempotency_payload_hash"),
                   prepared.PayloadSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   result.TrainingRun.RunId,
                   prepared.RunId,
                   StringComparison.Ordinal) &&
               PathsEqualForPlatform(
                   result.PromotionOutputDirectory,
                   prepared.CanonicalPromotionOutputDirectory) &&
               string.Equals(
                   ReadMetadata(metadata, "local_promotion_operation_id"),
                   prepared.OperationId,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(
                       metadata,
                       "local_promotion_committed_snapshot_sha256"),
                   prepared.FinalResultSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(
                       metadata,
                       "training_intake_promote_local_operation_authority"),
                   TrainingIntakeLocalPromotionOperationFileName,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(metadata, "local_promotion_pair_reservation_id"),
                   prepared.PairStoreReservationId,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(
                       metadata,
                       "local_promotion_pair_reservation_sha256"),
                   prepared.PairStoreReservationSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(
                       metadata,
                       "local_promotion_output_namespace_reservation_ref"),
                   prepared.OutputNamespaceReservationRef,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(
                       metadata,
                       "local_promotion_output_namespace_reservation_sha256"),
                   prepared.OutputNamespaceReservationSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(
                       metadata,
                       "local_promotion_uploader_envelope_reservation_sha256"),
                   prepared.UploaderEnvelopeReservationSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(
                       metadata,
                       "local_promotion_uploader_authority_mode"),
                   prepared.UploaderAuthorityMode,
                   StringComparison.Ordinal) &&
               string.Equals(
                   ReadMetadata(
                       metadata,
                       "local_promotion_uploader_configuration_fingerprint_sha256"),
                   prepared.UploaderConfigurationFingerprintSha256,
                   StringComparison.Ordinal);
    }

    private static LocalPromotionOperationState ResolveLocalPromotionOperationState(
        IReadOnlyList<LocalPromotionOperationJournalRecord> records,
        string operationId)
    {
        var state = new LocalPromotionOperationState(null, null, null, null);
        foreach (var record in records.Where(record =>
                     string.Equals(record.OperationId, operationId, StringComparison.Ordinal)))
        {
            if (!TryAdvanceLocalPromotionOperationState(state, record, out var advanced))
                return new LocalPromotionOperationState(null, null, null, null);
            state = advanced!;
        }
        return state;
    }

    private async Task<OperationResult<LocalPromotionOperationJournalRecord>>
        AppendLocalPromotionOperationRecordAsync(
            LocalPromotionOperationJournalRecord record,
            CancellationToken ct)
    {
        var existing = await ReadLocalPromotionOperationJournalAsync(ct);
        if (!existing.IsSuccess)
            return existing.MapError<LocalPromotionOperationJournalRecord>();
        var operationState = ResolveLocalPromotionOperationState(
            existing.Value!,
            record.OperationId);
        if (!LocalPromotionOperationIdentityMatches(operationState, record) ||
            !TryAdvanceLocalPromotionOperationState(
                operationState,
                record,
                out _))
        {
            return LocalPromotionOperationStateInvalid<
                LocalPromotionOperationJournalRecord>();
        }
        var previousHash = existing.Value!.LastOrDefault()?.RecordSha256 ?? string.Empty;
        record = record with
        {
            PreviousRecordSha256 = previousHash,
            RecordSha256 = string.Empty
        };
        record = record with
        {
            RecordSha256 = BuildLocalPromotionOperationRecordSha256(record)
        };
        var line = JsonSerializer.Serialize(record, JsonOptions);
        var bytes = StrictUtf8Encoding.GetByteCount(line + Environment.NewLine);
        if (bytes > MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength)
        {
            return LocalPromotionOperationQuotaExceeded<
                LocalPromotionOperationJournalRecord>();
        }
        var capacity = await _localPromotionJournalSet.EnsureCapacityAsync(
            bytes,
            0L,
            "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_QUOTA_EXCEEDED",
            "DesignConversion local promotion operation journal quota is exhausted.",
            ct);
        if (!capacity.IsSuccess)
            return capacity.MapError<LocalPromotionOperationJournalRecord>();

        var appended = await _localPromotionJournalSet.AppendLineAsync(
            DesignConversionLocalPromotionJournalKind.Operation,
            line,
            ct);
        if (!appended.IsSuccess)
            return appended.MapError<LocalPromotionOperationJournalRecord>();
        _runTrainingIntakeLocalPromotionOperationPhaseObserverForTesting?
            .Invoke(record.Phase);
        return OperationResult<LocalPromotionOperationJournalRecord>.Ok(record);
    }

    private async Task<OperationResult<bool>>
        CanReserveAggregateLocalPromotionRecoveryAsync(
            IReadOnlyList<LocalPromotionOperationJournalRecord> records,
            string currentOperationId,
            int currentRemainingPhaseCount,
            CancellationToken ct)
    {
        if (currentRemainingPhaseCount is < 0 or > 4)
            return LocalPromotionOperationStateInvalid<bool>();
        var legacy = await ReadTrainingIntakeLocalPromotionRecordsAsync(ct);
        if (!legacy.IsSuccess)
            return legacy.MapError<bool>();

        long owedPhaseRows = 0;
        long owedProjectionRows = 0;
        var operationIds = records
            .Select(record => record.OperationId)
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        foreach (var operationId in operationIds)
        {
            var state = ResolveLocalPromotionOperationState(records, operationId);
            if (state.Phase is null)
                return LocalPromotionOperationStateInvalid<bool>();
            owedPhaseRows += state.Phase switch
            {
                LocalPromotionOperationPhase.Prepare => 3,
                LocalPromotionOperationPhase.Intent => 2,
                LocalPromotionOperationPhase.Prepared => 1,
                LocalPromotionOperationPhase.Committed => 0,
                _ => 0
            };
            if (state.Phase != LocalPromotionOperationPhase.Committed ||
                !HasValidCommittedLocalPromotionProjection(
                    state.Prepared!,
                    legacy.Value!.Select(entry => entry.Record).ToArray()))
            {
                owedProjectionRows++;
            }
        }
        if (!operationIds.Contains(currentOperationId, StringComparer.Ordinal))
        {
            owedPhaseRows += currentRemainingPhaseCount;
            owedProjectionRows++;
        }

        long operationReservation;
        long projectionReservation;
        try
        {
            operationReservation = checked(owedPhaseRows *
                MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength);
            projectionReservation = checked(owedProjectionRows *
                MaxTrainingIntakeLocalPromotionJournalRowByteLength);
        }
        catch (OverflowException)
        {
            return LocalPromotionOperationQuotaExceeded<bool>();
        }

        var ensured = await _localPromotionJournalSet.EnsureCapacityAsync(
            operationReservation,
            projectionReservation,
            "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_QUOTA_EXCEEDED",
            "DesignConversion local promotion operation journal quota is exhausted.",
            ct);
        return ensured.IsSuccess
            ? OperationResult<bool>.Ok(true)
            : ensured.MapError<bool>();
    }

    private static bool HasValidCommittedLocalPromotionProjection(
        LocalPromotionOperationJournalRecord prepared,
        IReadOnlyList<DesignConversionTrainingIntakeLocalPromotionResult>
            legacy)
    {
        var marked = legacy.Where(record => string.Equals(
                ReadMetadata(
                    record.BoundaryMetadata,
                    "local_promotion_operation_id"),
                prepared.OperationId,
                StringComparison.Ordinal))
            .ToArray();
        return marked.Length == 1 &&
               string.Equals(
                   ReadMetadata(
                       marked[0].BoundaryMetadata,
                       "local_promotion_committed_snapshot_sha256"),
                   prepared.FinalResultSha256,
                   StringComparison.Ordinal) &&
               string.Equals(
                   BuildLocalPromotionFinalResultSha256(marked[0]),
                   prepared.FinalResultSha256,
                   StringComparison.Ordinal);
    }

    private async Task<OperationResult<LocalPromotionOperationContext>>
        ReserveLocalPromotionMutationEnvelopeAsync(
            LocalPromotionOperationContext context,
            IReadOnlyList<DpoPair> pairs,
            int maximumSerializedReceiptUtf8Bytes,
            string uploaderAuthorityMode,
            string uploaderConfigurationFingerprintSha256,
            CancellationToken ct)
    {
        if (_trainingIntakeDpoPairStore is not
            IDpoPairBatchReservationStore reservationStore)
        {
            return OperationResult<LocalPromotionOperationContext>.Fail(
                "DesignConversion local promotion requires a durable DPO pair batch reservation store.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_PAIR_RESERVATION_REQUIRED");
        }
        var pairReservation = reservationStore.ReserveBatch(
            $"{context.OperationId}:dpo-pair-batch-v1",
            pairs);
        if (!pairReservation.IsSuccess)
            return pairReservation.MapError<LocalPromotionOperationContext>();
        _runTrainingIntakeLocalPromotionAfterPairReservationObserverForTesting?
            .Invoke();

        var uploaderEnvelopeSha256 = $"sha256:{HashText(string.Join("|",
        [
            "design-conversion-promotion-uploader-envelope-v1",
            uploaderAuthorityMode,
            _promotionUploader?.GetType().FullName ?? "local-only",
            uploaderConfigurationFingerprintSha256,
            maximumSerializedReceiptUtf8Bytes.ToString(
                CultureInfo.InvariantCulture),
            MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength
                .ToString(CultureInfo.InvariantCulture)
        ]))}";
        var outputReservationSha256 = $"sha256:{HashText(string.Join("|",
        [
            "design-conversion-local-promotion-output-namespace-reservation-v1",
            context.OperationId,
            context.CanonicalPromotionOutputDirectory,
            pairReservation.Value!.ReservationId,
            pairReservation.Value.BatchSha256,
            uploaderEnvelopeSha256,
            uploaderAuthorityMode,
            uploaderConfigurationFingerprintSha256
        ]))}";
        var reservationRef = BuildLocalPromotionOutputReservationRef(
            context.OperationId);
        var reservationRoot = Path.GetDirectoryName(reservationRef)!;
        var leaf = Path.GetFileName(reservationRef);
        var reservation = new LocalPromotionOutputNamespaceReservation(
            TrainingIntakeLocalPromotionOutputReservationSchemaVersion,
            1,
            context.OperationId,
            context.CanonicalPromotionOutputDirectory,
            pairReservation.Value.ReservationId,
            pairReservation.Value.BatchSha256,
            uploaderEnvelopeSha256,
            uploaderAuthorityMode,
            uploaderConfigurationFingerprintSha256,
            outputReservationSha256);
        var bytes = JsonSerializer.SerializeToUtf8Bytes(reservation, JsonOptions);
        if (bytes.Length > 64 * 1024 ||
            Directory.Exists(context.CanonicalPromotionOutputDirectory) ||
            File.Exists(context.CanonicalPromotionOutputDirectory))
        {
            return ReleasePairReservationAfterPreIntentFailure(
                reservationStore,
                pairReservation.Value,
                OperationResult<LocalPromotionOperationContext>.Fail(
                    "DesignConversion local promotion output namespace is already occupied.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OUTPUT_NAMESPACE_COLLISION"));
        }
        try
        {
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireOrCreate(
                    reservationRoot,
                    beforeIo: null);
            await using var existing = directory.TryOpenExistingReadOnly(leaf);
            if (existing is not null)
            {
                if (existing.Length != bytes.Length)
                {
                    return ReleasePairReservationAfterPreIntentFailure(
                        reservationStore,
                        pairReservation.Value,
                        LocalPromotionOperationStateInvalid<
                            LocalPromotionOperationContext>());
                }
                var retained = new byte[bytes.Length];
                await existing.ReadExactlyAsync(retained, ct);
                if (!retained.AsSpan().SequenceEqual(bytes))
                {
                    return ReleasePairReservationAfterPreIntentFailure(
                        reservationStore,
                        pairReservation.Value,
                        LocalPromotionOperationStateInvalid<
                            LocalPromotionOperationContext>());
                }
            }
            else
            {
                await using (var created = directory.CreateNew(
                                 leaf,
                                 FileShare.Read,
                                 writeThrough: true))
                {
                    await created.WriteAsync(bytes, ct);
                    await created.FlushAsync(ct);
                    created.Flush(flushToDisk: true);
                }
                await using var readback =
                    directory.TryOpenExistingReadOnly(leaf);
                if (readback is null || readback.Length != bytes.Length)
                {
                    return ReleasePairReservationAfterPreIntentFailure(
                        reservationStore,
                        pairReservation.Value,
                        LocalPromotionOperationStateInvalid<
                            LocalPromotionOperationContext>());
                }
                var retained = new byte[bytes.Length];
                await readback.ReadExactlyAsync(retained, ct);
                if (!retained.AsSpan().SequenceEqual(bytes))
                {
                    return ReleasePairReservationAfterPreIntentFailure(
                        reservationStore,
                        pairReservation.Value,
                        LocalPromotionOperationStateInvalid<
                            LocalPromotionOperationContext>());
                }
            }
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            var released = reservationStore.ReleaseBatch(pairReservation.Value);
            if (!released.IsSuccess)
            {
                return OperationResult<LocalPromotionOperationContext>.Fail(
                    "DesignConversion local promotion pre-intent reservation cancellation cleanup failed.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_RESERVATION_ROLLBACK_FAILED");
            }
            throw;
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException or
            PlatformNotSupportedException)
        {
            return ReleasePairReservationAfterPreIntentFailure(
                reservationStore,
                pairReservation.Value,
                LocalPromotionOperationStateInvalid<
                    LocalPromotionOperationContext>());
        }

        _runTrainingIntakeLocalPromotionAfterOutputReservationObserverForTesting?
            .Invoke();

        return OperationResult<LocalPromotionOperationContext>.Ok(context with
        {
            PairStoreReservationId = pairReservation.Value.ReservationId,
            PairStoreReservationSha256 = pairReservation.Value.BatchSha256,
            OutputNamespaceReservationRef = reservationRef,
            OutputNamespaceReservationSha256 = outputReservationSha256,
            UploaderEnvelopeReservationSha256 = uploaderEnvelopeSha256,
            UploaderAuthorityMode = uploaderAuthorityMode,
            UploaderConfigurationFingerprintSha256 =
                uploaderConfigurationFingerprintSha256
        });
    }

    private static OperationResult<T>
        ReleasePairReservationAfterPreIntentFailure<T>(
            IDpoPairBatchReservationStore store,
            DpoPairBatchReservation reservation,
            OperationResult<T> originalFailure)
    {
        var released = store.ReleaseBatch(reservation);
        return released.IsSuccess
            ? originalFailure
            : OperationResult<T>.Fail(
                "DesignConversion local promotion pre-intent reservation rollback failed.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_RESERVATION_ROLLBACK_FAILED");
    }

    private OperationResult<T> ReleaseLocalPromotionMutationEnvelope<T>(
        LocalPromotionOperationContext context,
        OperationResult<T> originalFailure)
    {
        if (!HasDurableLocalPromotionMutationEnvelope(context))
            return originalFailure;

        try
        {
            var parent = Path.GetDirectoryName(
                context.OutputNamespaceReservationRef);
            var leaf = Path.GetFileName(context.OutputNamespaceReservationRef);
            if (string.IsNullOrWhiteSpace(parent) ||
                string.IsNullOrWhiteSpace(leaf))
            {
                return OperationResult<T>.Fail(
                    "DesignConversion local promotion pre-intent reservation rollback failed.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_RESERVATION_ROLLBACK_FAILED");
            }
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    parent,
                    beforeIo: null);
            directory.DeleteIfRegular(leaf);
        }
        catch (DesignConversionHandleBoundDeleteDispositionException ex) when (
            ex.Disposition ==
            DesignConversionHandleBoundDeleteDisposition
                .NamespaceEntryRemovedDirectoryFlushNotConfirmed)
        {
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException or
            PlatformNotSupportedException)
        {
            return OperationResult<T>.Fail(
                "DesignConversion local promotion pre-intent reservation rollback failed.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_RESERVATION_ROLLBACK_FAILED");
        }
        if (_trainingIntakeDpoPairStore is not
            IDpoPairBatchReservationStore reservationStore)
        {
            return OperationResult<T>.Fail(
                "DesignConversion local promotion pre-intent reservation rollback failed.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_RESERVATION_ROLLBACK_FAILED");
        }
        return ReleasePairReservationAfterPreIntentFailure(
            reservationStore,
            new DpoPairBatchReservation(
                context.PairStoreReservationId,
                context.PairStoreReservationSha256,
                context.PairStoreInputSha256s.Count),
            originalFailure);
    }

    private async Task<OperationResult<bool>>
        RequireFreshPromoteLocalOperationCapacityBeforeEffectsAsync(
            string operationId,
            CancellationToken ct)
    {
        var operationJournal = await ReadLocalPromotionOperationJournalAsync(ct);
        if (!operationJournal.IsSuccess)
            return operationJournal.MapError<bool>();

        var operationState = ResolveLocalPromotionOperationState(
            operationJournal.Value!,
            operationId);
        if (operationState.Phase is not null)
            return OperationResult<bool>.Ok(true);

        var projectionQuota =
            await EnsureLocalPromotionProjectionCapacityAsync(
                MaxTrainingIntakeLocalPromotionJournalRowByteLength,
                ct);
        if (!projectionQuota.IsSuccess)
            return projectionQuota;

        var aggregateQuota = await CanReserveAggregateLocalPromotionRecoveryAsync(
            operationJournal.Value!,
            operationId,
            currentRemainingPhaseCount: 4,
            ct);
        if (!aggregateQuota.IsSuccess)
            return aggregateQuota;
        return aggregateQuota.Value
            ? OperationResult<bool>.Ok(true)
            : LocalPromotionOperationQuotaExceeded<bool>();
    }

    private static LocalPromotionOperationJournalRecord BuildLocalPromotionOperationRecord(
        LocalPromotionOperationContext context,
        LocalPromotionOperationPhase phase,
        DateTimeOffset recordedAtUtc,
        IReadOnlyList<LocalPromotionOperationArtifactDescriptor>? artifacts = null,
        DesignConversionTrainingIntakeLocalPromotionResult? finalResult = null,
        string finalResultSha256 = "")
        => new(
            SchemaVersion: TrainingIntakeLocalPromotionOperationSchemaVersion,
            Version: 1,
            OperationId: context.OperationId,
            Phase: phase,
            TenantIdRef: context.TenantIdRef,
            IdempotencyKeyRef: context.IdempotencyKeyRef,
            PayloadSha256: context.PayloadSha256,
            CanonicalPromotionOutputDirectory:
                context.CanonicalPromotionOutputDirectory,
            RunId: context.RunId,
            RecordedAtUtc: recordedAtUtc,
            PairStoreInputCount: context.PairStoreInputSha256s.Count,
            PairStoreInputSha256s: context.PairStoreInputSha256s,
            PairStoreInputsSha256: context.PairStoreInputsSha256,
            PairStoreReservationId: context.PairStoreReservationId,
            PairStoreReservationSha256: context.PairStoreReservationSha256,
            OutputNamespaceReservationRef:
                context.OutputNamespaceReservationRef,
            OutputNamespaceReservationSha256:
                context.OutputNamespaceReservationSha256,
            UploaderEnvelopeReservationSha256:
                context.UploaderEnvelopeReservationSha256,
            UploaderAuthorityMode:
                context.UploaderAuthorityMode,
            UploaderConfigurationFingerprintSha256:
                context.UploaderConfigurationFingerprintSha256,
            ArtifactDescriptors: artifacts ?? [],
            FinalResult: finalResult,
            FinalResultSha256: finalResultSha256,
            PreviousRecordSha256: string.Empty,
            RecordSha256: string.Empty);

    private static OperationResult<T> LocalPromotionOperationStateInvalid<T>()
        => OperationResult<T>.Fail(
            "DesignConversion local promotion operation journal state is invalid.",
            "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID");

    private static OperationResult<T> LocalPromotionOperationQuotaExceeded<T>()
        => OperationResult<T>.Fail(
            "DesignConversion local promotion operation journal quota is exhausted.",
            "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_QUOTA_EXCEEDED");

    private static OperationResult<T> LocalPromotionOperationIndeterminate<T>()
        => OperationResult<T>.Fail(
            "DesignConversion local promotion stopped after durable mutation intent; retry is indeterminate and will not repeat training.",
            "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_INDETERMINATE_AFTER_INTENT");

    private bool IsServerOwnedConfiguredRemotePromotionUploaderFailure(
        string? errorCode)
        => _serverOwnedConfiguredRemotePromotionAuthority is not null &&
           !string.IsNullOrWhiteSpace(errorCode) &&
           errorCode.StartsWith(
               "DESIGN_CONVERSION_PROMOTION_UPLOAD_",
               StringComparison.Ordinal);

    private static OperationResult<T> TrainingIntakeLocalPromotionsInvalidUtf8<T>()
        => OperationResult<T>.Fail(
            "DesignConversion training intake local promotions could not be read because the training intake local promotions file is not valid UTF-8.",
            InvalidUtf8ErrorCode);

    private async Task<OperationResult<IReadOnlyList<
        LocalPromotionOperationArtifactDescriptor>>>
        CaptureLocalPromotionOperationArtifactsAsync(
            DesignConversionTrainingIntakeLocalPromotionResult result,
            string canonicalPromotionOutputDirectory,
            string runId,
            CancellationToken ct)
    {
        var resolved = ResolveExpectedLocalPromotionArtifactPaths(
            result,
            canonicalPromotionOutputDirectory,
            runId);
        if (!resolved.IsSuccess)
            return resolved.MapError<IReadOnlyList<
                LocalPromotionOperationArtifactDescriptor>>();

        var descriptors = new List<LocalPromotionOperationArtifactDescriptor>();
        foreach (var path in resolved.Value!)
        {
            ct.ThrowIfCancellationRequested();
            var hashed = await HashLocalPromotionArtifactNoFollowAsync(path, ct);
            if (!hashed.IsSuccess)
                return LocalPromotionOperationStateInvalid<IReadOnlyList<
                    LocalPromotionOperationArtifactDescriptor>>();
            descriptors.Add(new LocalPromotionOperationArtifactDescriptor(
                path,
                hashed.Value.ByteLength,
                hashed.Value.Sha256));
        }

        return OperationResult<IReadOnlyList<LocalPromotionOperationArtifactDescriptor>>
            .Ok(descriptors.ToArray());
    }

    private OperationResult<IReadOnlyList<string>>
        ResolveExpectedLocalPromotionArtifactPaths(
            DesignConversionTrainingIntakeLocalPromotionResult result,
            string canonicalPromotionOutputDirectory,
            string runId)
    {
        if (result.Publication is null)
        {
            return string.IsNullOrWhiteSpace(result.PromotedCheckpointPath) &&
                   result.PromotedLocalModel is null
                ? OperationResult<IReadOnlyList<string>>.Ok([])
                : LocalPromotionOperationStateInvalid<IReadOnlyList<string>>();
        }

        var canonical = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            _rootDirectory,
            canonicalPromotionOutputDirectory,
            runId);
        var artifacts = result.Publication.Manifest.PromotionArtifacts;
        if (!canonical.IsSuccess || artifacts is null)
            return LocalPromotionOperationStateInvalid<IReadOnlyList<string>>();
        var expected = canonical.Value!;
        var policyArtifact = artifacts.PolicyCheckpointArtifact;
        if (policyArtifact is null ||
            string.IsNullOrWhiteSpace(policyArtifact.FileName) ||
            Path.IsPathFullyQualified(policyArtifact.FileName) ||
            !string.Equals(
                Path.GetFileName(policyArtifact.FileName),
                policyArtifact.FileName,
                StringComparison.Ordinal))
        {
            return LocalPromotionOperationStateInvalid<IReadOnlyList<string>>();
        }

        string expectedPolicyCheckpointPath;
        try
        {
            expectedPolicyCheckpointPath = Path.GetFullPath(Path.Combine(
                expected.OutputDirectory,
                policyArtifact.FileName));
        }
        catch (Exception exception) when (exception is
            ArgumentException or NotSupportedException or PathTooLongException)
        {
            return LocalPromotionOperationStateInvalid<IReadOnlyList<string>>();
        }

        bool Matches(string? actual, string? expectedPath)
        {
            if (string.IsNullOrWhiteSpace(actual) ||
                string.IsNullOrWhiteSpace(expectedPath))
            {
                return false;
            }
            try
            {
                return PathsEqualForPlatform(
                    Path.GetFullPath(actual),
                    Path.GetFullPath(expectedPath));
            }
            catch (Exception exception) when (exception is
                ArgumentException or NotSupportedException or PathTooLongException)
            {
                return false;
            }
        }

        bool DescriptorMatches(
            DesignConversionTrainingManifestArtifactDescriptor? descriptor,
            string expectedPath)
            => descriptor is not null &&
               Matches(descriptor.CanonicalPath, expectedPath) &&
               string.Equals(
                   descriptor.FileName,
                   Path.GetFileName(expectedPath),
                   StringComparison.Ordinal);

        var hasCanonicalBpe =
            artifacts.CanonicalBpeTokenizerPath is not null ||
            artifacts.CanonicalBpeTokenizerArtifact is not null;
        if (!Matches(
                result.PromotionOutputDirectory,
                expected.OutputDirectory) ||
            !Matches(result.PromotedCheckpointPath, expected.RuntimeCheckpointPath) ||
            result.PromotedLocalModel is not null &&
            !Matches(
                result.PromotedLocalModel.CheckpointPath,
                expected.RuntimeCheckpointPath) ||
            !Matches(artifacts.CheckpointPath, expected.RuntimeCheckpointPath) ||
            !Matches(artifacts.TokenizerPath, expected.TokenizerArtifactPath) ||
            !Matches(artifacts.SourceEncoderPath, expected.SourceEncoderContractPath) ||
            !Matches(artifacts.PolicyPath, expected.PolicyCheckpointContractPath) ||
            !DescriptorMatches(
                artifacts.RuntimeCheckpointArtifact,
                expected.RuntimeCheckpointPath) ||
            !DescriptorMatches(
                artifacts.TokenizerArtifact,
                expected.TokenizerArtifactPath) ||
            !DescriptorMatches(
                artifacts.SourceEncoderContractArtifact,
                expected.SourceEncoderContractPath) ||
            !DescriptorMatches(
                artifacts.PolicyCheckpointContractArtifact,
                expected.PolicyCheckpointContractPath) ||
            !DescriptorMatches(policyArtifact, expectedPolicyCheckpointPath) ||
            hasCanonicalBpe &&
            (!Matches(
                 artifacts.CanonicalBpeTokenizerPath,
                 expected.CanonicalBpeTokenizerPath) ||
             !DescriptorMatches(
                 artifacts.CanonicalBpeTokenizerArtifact,
                 expected.CanonicalBpeTokenizerPath!)) ||
            !hasCanonicalBpe &&
            (artifacts.CanonicalBpeTokenizerPath is not null ||
             artifacts.CanonicalBpeTokenizerArtifact is not null))
        {
            return LocalPromotionOperationStateInvalid<IReadOnlyList<string>>();
        }

        var paths = new SortedSet<string>(GetPathKeyComparer())
        {
            expected.RuntimeCheckpointPath,
            expected.TokenizerArtifactPath,
            expected.SourceEncoderContractPath,
            expected.PolicyCheckpointContractPath,
            expectedPolicyCheckpointPath
        };
        if (hasCanonicalBpe)
            paths.Add(expected.CanonicalBpeTokenizerPath!);
        var expectedCount = hasCanonicalBpe ? 6 : 5;
        if (paths.Count != expectedCount)
            return LocalPromotionOperationStateInvalid<IReadOnlyList<string>>();

        foreach (var path in paths)
        {
            var relative = Path.GetRelativePath(_rootDirectory, path);
            if (Path.IsPathFullyQualified(relative) ||
                relative.Equals("..", StringComparison.Ordinal) ||
                relative.StartsWith(
                    $"..{Path.DirectorySeparatorChar}",
                    StringComparison.Ordinal) ||
                relative.StartsWith(
                    $"..{Path.AltDirectorySeparatorChar}",
                    StringComparison.Ordinal))
            {
                return LocalPromotionOperationStateInvalid<IReadOnlyList<string>>();
            }
        }
        return OperationResult<IReadOnlyList<string>>.Ok(paths.ToArray());
    }

    private static async Task<OperationResult<(long ByteLength, string Sha256)>>
        HashLocalPromotionArtifactNoFollowAsync(
            string canonicalPath,
            CancellationToken ct)
    {
        try
        {
            var parent = Path.GetDirectoryName(canonicalPath);
            var leaf = Path.GetFileName(canonicalPath);
            if (string.IsNullOrWhiteSpace(parent) ||
                string.IsNullOrWhiteSpace(leaf))
            {
                return LocalPromotionOperationStateInvalid<
                    (long ByteLength, string Sha256)>();
            }
            using var directory = DesignConversionHandleBoundDirectory.AcquireExisting(
                parent,
                beforeIo: null);
            await using var stream = directory.TryOpenExistingReadOnly(leaf);
            if (stream is null)
            {
                return LocalPromotionOperationStateInvalid<
                    (long ByteLength, string Sha256)>();
            }
            var length = stream.Length;
            var sha = await SHA256.HashDataAsync(stream, ct);
            if (stream.Length != length)
            {
                return LocalPromotionOperationStateInvalid<
                    (long ByteLength, string Sha256)>();
            }
            return OperationResult<(long ByteLength, string Sha256)>.Ok((
                length,
                $"sha256:{Convert.ToHexString(sha).ToLowerInvariant()}"));
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException or
            PlatformNotSupportedException or ArgumentException or NotSupportedException)
        {
            return LocalPromotionOperationStateInvalid<
                (long ByteLength, string Sha256)>();
        }
    }

    private bool ValidateLocalPromotionOperationArtifactAuthority(
        DesignConversionTrainingIntakeLocalPromotionResult result,
        string canonicalPromotionOutputDirectory,
        string runId,
        IReadOnlyList<LocalPromotionOperationArtifactDescriptor> descriptors)
    {
        var expected = ResolveExpectedLocalPromotionArtifactPaths(
            result,
            canonicalPromotionOutputDirectory,
            runId);
        if (!expected.IsSuccess ||
            descriptors is null ||
            descriptors.Count != expected.Value!.Count)
        {
            return false;
        }

        for (var index = 0; index < descriptors.Count; index++)
        {
            var descriptor = descriptors[index];
            var expectedPath = expected.Value[index];
            if (descriptor is null ||
                string.IsNullOrWhiteSpace(descriptor.CanonicalPath) ||
                descriptor.ByteLength < 0 ||
                !IsSha256Ref(descriptor.Sha256) ||
                !string.Equals(
                    descriptor.CanonicalPath,
                    expectedPath,
                    StringComparison.Ordinal))
            {
                return false;
            }
        }
        return true;
    }

    private static async Task<bool>
        ValidateLocalPromotionOperationArtifactBytesAsync(
            IReadOnlyList<LocalPromotionOperationArtifactDescriptor> descriptors,
            CancellationToken ct)
    {
        foreach (var descriptor in descriptors)
        {
            var hashed = await HashLocalPromotionArtifactNoFollowAsync(
                descriptor.CanonicalPath,
                ct);
            if (!hashed.IsSuccess ||
                hashed.Value.ByteLength != descriptor.ByteLength ||
                !string.Equals(
                    hashed.Value.Sha256,
                    descriptor.Sha256,
                    StringComparison.Ordinal))
            {
                return false;
            }
        }
        return true;
    }

    private static async Task<bool>
        ValidateLocalPromotionOperationArtifactBytesAsync(
            IReadOnlyList<LocalPromotionOperationArtifactDescriptor> descriptors,
            string canonicalPromotionOutputDirectory,
            DesignConversionHandleBoundDirectory outputDirectory,
            CancellationToken ct)
    {
        try
        {
            foreach (var descriptor in descriptors)
            {
                var parent = Path.GetDirectoryName(descriptor.CanonicalPath);
                var leaf = Path.GetFileName(descriptor.CanonicalPath);
                if (string.IsNullOrWhiteSpace(parent) ||
                    string.IsNullOrWhiteSpace(leaf) ||
                    !string.Equals(
                        parent,
                        canonicalPromotionOutputDirectory,
                        StringComparison.Ordinal))
                {
                    return false;
                }

                await using var stream = outputDirectory.TryOpenExistingReadOnly(leaf);
                if (stream is null)
                    return false;
                var length = stream.Length;
                var sha = await SHA256.HashDataAsync(stream, ct);
                if (stream.Length != length ||
                    length != descriptor.ByteLength ||
                    !string.Equals(
                        $"sha256:{Convert.ToHexString(sha).ToLowerInvariant()}",
                        descriptor.Sha256,
                        StringComparison.Ordinal))
                {
                    return false;
                }
            }
            return true;
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException or
            PlatformNotSupportedException or ArgumentException or NotSupportedException)
        {
            return false;
        }
    }

    private static bool IsLocalPromotionOutputNamespaceAbsentNoFollow(
        string canonicalPath)
    {
        var parent = Path.GetDirectoryName(canonicalPath);
        var leaf = Path.GetFileName(canonicalPath);
        if (string.IsNullOrWhiteSpace(parent) ||
            string.IsNullOrWhiteSpace(leaf))
        {
            return false;
        }

        try
        {
            using var parentDirectory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    parent,
                    beforeIo: null);
            return !parentDirectory.ContainsNameNoFollow(
                MaxLocalPromotionOutputNamespaceParentEntryCount,
                leaf);
        }
        catch (DesignConversionHandleBoundNotFoundException)
        {
            return IsLocalPromotionOutputNamespaceAbsentNoFollow(parent);
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException or
            PlatformNotSupportedException or ArgumentException or NotSupportedException)
        {
            return false;
        }
    }

    private bool ValidateLocalPromotionOperationPairStoreInputs(
        LocalPromotionOperationJournalRecord prepared)
    {
        var all = _trainingIntakeDpoPairStore.GetAll();
        if (!all.IsSuccess || all.Value is null)
            return false;
        var retained = all.Value
            .Select(BuildPairStoreInputSha256)
            .GroupBy(hash => hash, StringComparer.Ordinal)
            .ToDictionary(group => group.Key, group => group.Count(), StringComparer.Ordinal);
        foreach (var required in prepared.PairStoreInputSha256s
                     .GroupBy(hash => hash, StringComparer.Ordinal))
        {
            if (!retained.TryGetValue(required.Key, out var retainedCount) ||
                retainedCount < required.Count())
            {
                return false;
            }
        }
        return true;
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>>
        ValidatePreparedLocalPromotionDurableAuthorityAsync(
            LocalPromotionOperationJournalRecord prepared,
            CancellationToken ct)
    {
        var result = prepared.FinalResult;
        if (result is null ||
            !PreparedFinalResultCrossBindingMatches(prepared) ||
            !ValidateCycleAccuracyLineageContract(result) ||
            !string.Equals(
                prepared.FinalResultSha256,
                BuildLocalPromotionFinalResultSha256(result),
                StringComparison.Ordinal) ||
            !ValidateLocalPromotionOperationPairStoreInputs(prepared) ||
            !await ValidateLocalPromotionOutputReservationAsync(prepared, ct) ||
            !ValidateLocalPromotionOperationArtifactAuthority(
                 result,
                 prepared.CanonicalPromotionOutputDirectory,
                 prepared.RunId,
                 prepared.ArtifactDescriptors))
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>
            .Ok(result);
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>>
        ValidatePreparedLocalPromotionOperationAsync(
            LocalPromotionOperationJournalRecord prepared,
            CancellationToken ct)
    {
        var durable = await ValidatePreparedLocalPromotionDurableAuthorityAsync(
            prepared,
            ct);
        if (!durable.IsSuccess ||
            !await ValidateLocalPromotionOperationArtifactBytesAsync(
                prepared.ArtifactDescriptors,
                ct))
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        return durable;
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>>
        ValidateCommittedProjectedLocalPromotionOperationAsync(
            LocalPromotionOperationJournalRecord prepared,
            CancellationToken ct)
    {
        var durable = await ValidatePreparedLocalPromotionDurableAuthorityAsync(
            prepared,
            ct);
        if (!durable.IsSuccess)
            return durable;

        try
        {
            using var outputDirectory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    prepared.CanonicalPromotionOutputDirectory,
                    beforeIo: null);
            return await ValidateLocalPromotionOperationArtifactBytesAsync(
                prepared.ArtifactDescriptors,
                prepared.CanonicalPromotionOutputDirectory,
                outputDirectory,
                ct)
                ? durable
                : LocalPromotionOperationStateInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        catch (DesignConversionHandleBoundNotFoundException)
        {
            return IsLocalPromotionOutputNamespaceAbsentNoFollow(
                prepared.CanonicalPromotionOutputDirectory)
                ? durable
                : LocalPromotionOperationStateInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException or
            PlatformNotSupportedException or ArgumentException or NotSupportedException)
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
    }

    private string BuildLocalPromotionOutputReservationRef(string operationId)
        => Path.Combine(
            _rootDirectory,
            TrainingIntakeLocalPromotionOutputReservationDirectoryName,
            $"{HashText(operationId)}.json");

    private async Task<bool> ValidateLocalPromotionOutputReservationAsync(
        LocalPromotionOperationJournalRecord prepared,
        CancellationToken ct)
    {
        var expectedRef = BuildLocalPromotionOutputReservationRef(
            prepared.OperationId);
        if (!string.Equals(
                prepared.OutputNamespaceReservationRef,
                expectedRef,
                StringComparison.Ordinal))
        {
            return false;
        }
        var expectedSha256 = $"sha256:{HashText(string.Join("|",
        [
            "design-conversion-local-promotion-output-namespace-reservation-v1",
            prepared.OperationId,
            prepared.CanonicalPromotionOutputDirectory,
            prepared.PairStoreReservationId,
            prepared.PairStoreReservationSha256,
            prepared.UploaderEnvelopeReservationSha256,
            prepared.UploaderAuthorityMode,
            prepared.UploaderConfigurationFingerprintSha256
        ]))}";
        if (!string.Equals(
                prepared.OutputNamespaceReservationSha256,
                expectedSha256,
                StringComparison.Ordinal))
        {
            return false;
        }
        try
        {
            var parent = Path.GetDirectoryName(expectedRef);
            var leaf = Path.GetFileName(expectedRef);
            if (string.IsNullOrWhiteSpace(parent) ||
                string.IsNullOrWhiteSpace(leaf))
            {
                return false;
            }
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    parent,
                    beforeIo: null);
            await using var stream = directory.TryOpenExistingReadOnly(leaf);
            if (stream is null || stream.Length <= 0 || stream.Length > 64 * 1024)
                return false;
            var bytes = new byte[checked((int)stream.Length)];
            await stream.ReadExactlyAsync(bytes, ct);
            var expected = new LocalPromotionOutputNamespaceReservation(
                TrainingIntakeLocalPromotionOutputReservationSchemaVersion,
                1,
                prepared.OperationId,
                prepared.CanonicalPromotionOutputDirectory,
                prepared.PairStoreReservationId,
                prepared.PairStoreReservationSha256,
                prepared.UploaderEnvelopeReservationSha256,
                prepared.UploaderAuthorityMode,
                prepared.UploaderConfigurationFingerprintSha256,
                expectedSha256);
            var expectedBytes = JsonSerializer.SerializeToUtf8Bytes(
                expected,
                JsonOptions);
            return bytes.AsSpan().SequenceEqual(expectedBytes);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException or
            PlatformNotSupportedException or JsonException or NotSupportedException)
        {
            return false;
        }
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>>
        CommitPreparedLocalPromotionOperationAsync(
            LocalPromotionOperationJournalRecord prepared,
            CancellationToken ct)
    {
        var validated = await ValidatePreparedLocalPromotionOperationAsync(prepared, ct);
        if (!validated.IsSuccess)
            return validated;
        var operationJournal = await ReadLocalPromotionOperationJournalAsync(ct);
        if (!operationJournal.IsSuccess)
        {
            return operationJournal.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var capacity = await CanReserveAggregateLocalPromotionRecoveryAsync(
            operationJournal.Value!,
            prepared.OperationId,
            currentRemainingPhaseCount: 0,
            ct);
        if (!capacity.IsSuccess)
        {
            return capacity.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var projectionPrefix =
            await ReadLocalPromotionProjectionLogicalPrefixAsync(ct);
        if (!projectionPrefix.IsSuccess)
        {
            return projectionPrefix.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var context = new LocalPromotionOperationContext(
            prepared.OperationId,
            prepared.TenantIdRef,
            prepared.IdempotencyKeyRef,
            prepared.PayloadSha256,
            prepared.CanonicalPromotionOutputDirectory,
            prepared.RunId,
            prepared.PairStoreInputSha256s,
            prepared.PairStoreInputsSha256,
            prepared.PairStoreReservationId,
            prepared.PairStoreReservationSha256,
            prepared.OutputNamespaceReservationRef,
            prepared.OutputNamespaceReservationSha256,
            prepared.UploaderEnvelopeReservationSha256,
            prepared.UploaderAuthorityMode,
            prepared.UploaderConfigurationFingerprintSha256,
            new LocalPromotionOperationState(null, null, prepared, null));
        var committedRecord = BuildLocalPromotionOperationRecord(
                context,
                LocalPromotionOperationPhase.Committed,
                DateTimeOffset.UtcNow,
                finalResultSha256: prepared.FinalResultSha256) with
        {
            ProjectionLogicalPrefixCount = projectionPrefix.Value!.Count,
            ProjectionLogicalPrefixSha256 = projectionPrefix.Value.Sha256
        };
        var committed = await AppendLocalPromotionOperationRecordAsync(
            committedRecord,
            ct);
        if (!committed.IsSuccess)
            return committed.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        var projection = await RepairCommittedLocalPromotionProjectionAsync(
            prepared,
            ct);
        return projection.IsSuccess
            ? OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>.Ok(
                validated.Value!)
            : projection.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
    }

    private async Task<OperationResult<bool>> RepairCommittedLocalPromotionProjectionAsync(
        LocalPromotionOperationJournalRecord prepared,
        CancellationToken ct)
    {
        var legacy = await ReadTrainingIntakeLocalPromotionRecordsAsync(ct);
        if (!legacy.IsSuccess)
            return legacy.MapError<bool>();
        var marked = legacy.Value!
            .Where(entry => string.Equals(
                ReadMetadata(entry.Record.BoundaryMetadata, "local_promotion_operation_id"),
                prepared.OperationId,
                StringComparison.Ordinal))
            .ToArray();
        if (marked.Length > 1)
            return LocalPromotionOperationStateInvalid<bool>();
        if (marked.Length == 1)
        {
            return string.Equals(
                       ReadMetadata(
                           marked[0].Record.BoundaryMetadata,
                           "local_promotion_committed_snapshot_sha256"),
                       prepared.FinalResultSha256,
                       StringComparison.Ordinal) &&
                   string.Equals(
                       BuildLocalPromotionFinalResultSha256(marked[0].Record),
                       prepared.FinalResultSha256,
                       StringComparison.Ordinal)
                ? OperationResult<bool>.Ok(true)
                : LocalPromotionOperationStateInvalid<bool>();
        }

        var operationJournal = await ReadLocalPromotionOperationJournalAsync(ct);
        if (!operationJournal.IsSuccess ||
            !IsUniqueSafeLocalPromotionProjectionRepairTail(
                prepared,
                operationJournal.Value!,
                legacy.Value!))
        {
            return LocalPromotionOperationStateInvalid<bool>();
        }

        var line = JsonSerializer.Serialize(prepared.FinalResult, JsonOptions);
        var lineBytes = StrictUtf8Encoding.GetByteCount(line + Environment.NewLine);
        if (lineBytes > MaxTrainingIntakeLocalPromotionJournalRowByteLength)
        {
            return TrainingIntakeLocalPromotionsQuotaExceeded<bool>();
        }
        var capacity = await EnsureLocalPromotionProjectionCapacityAsync(
            MaxTrainingIntakeLocalPromotionJournalRowByteLength,
            ct);
        if (!capacity.IsSuccess)
            return capacity;
        var appended = await _localPromotionJournalSet.AppendLineAsync(
            DesignConversionLocalPromotionJournalKind.Projection,
            line,
            ct);
        return appended.IsSuccess
            ? OperationResult<bool>.Ok(true)
            : appended.MapError<bool>();
    }

    private async Task<OperationResult<LocalPromotionProjectionLogicalPrefix>>
        ReadLocalPromotionProjectionLogicalPrefixAsync(CancellationToken ct)
    {
        var projection = await ReadTrainingIntakeLocalPromotionRecordsAsync(ct);
        return projection.IsSuccess
            ? OperationResult<LocalPromotionProjectionLogicalPrefix>.Ok(
                BuildLocalPromotionProjectionLogicalPrefix(projection.Value!))
            : projection.MapError<LocalPromotionProjectionLogicalPrefix>();
    }

    private static LocalPromotionProjectionLogicalPrefix
        BuildLocalPromotionProjectionLogicalPrefix(
            IReadOnlyList<LocalPromotionProjectionJournalEntry> records)
    {
        var logicalRows = records
            .Select(entry => JsonSerializer.Serialize(entry.Record, JsonOptions))
            .ToArray();
        var bytes = JsonSerializer.SerializeToUtf8Bytes(logicalRows, JsonOptions);
        return new LocalPromotionProjectionLogicalPrefix(
            logicalRows.LongLength,
            $"sha256:{Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant()}");
    }

    private static bool IsUniqueSafeLocalPromotionProjectionRepairTail(
        LocalPromotionOperationJournalRecord prepared,
        IReadOnlyList<LocalPromotionOperationJournalRecord> operationRecords,
        IReadOnlyList<LocalPromotionProjectionJournalEntry> projectionRecords)
    {
        var preparedByOperation = operationRecords
            .Where(record => record.Phase == LocalPromotionOperationPhase.Prepared)
            .ToDictionary(record => record.OperationId, StringComparer.Ordinal);
        var commits = operationRecords
            .Where(record => record.Phase == LocalPromotionOperationPhase.Committed)
            .ToArray();
        var projectedIds = projectionRecords
            .Select(entry => ReadMetadata(
                entry.Record.BoundaryMetadata,
                "local_promotion_operation_id"))
            .Where(operationId => !string.IsNullOrWhiteSpace(operationId))
            .ToHashSet(StringComparer.Ordinal);
        var missing = commits
            .Where(commit => !projectedIds.Contains(commit.OperationId))
            .ToArray();
        if (missing.Length != 1 ||
            !string.Equals(
                missing[0].OperationId,
                prepared.OperationId,
                StringComparison.Ordinal) ||
            !preparedByOperation.ContainsKey(prepared.OperationId) ||
            !ReferenceEquals(operationRecords.LastOrDefault(), missing[0]))
        {
            return false;
        }

        if (missing[0].ProjectionLogicalPrefixSha256 is not null)
        {
            var currentPrefix =
                BuildLocalPromotionProjectionLogicalPrefix(projectionRecords);
            return currentPrefix.Count ==
                       missing[0].ProjectionLogicalPrefixCount &&
                   string.Equals(
                       currentPrefix.Sha256,
                       missing[0].ProjectionLogicalPrefixSha256,
                       StringComparison.Ordinal);
        }

        return projectionRecords.Count == 0;
    }

    private async Task<OperationResult<bool>> ReconcileCommittedLocalPromotionProjectionsAsync(
        IReadOnlyList<LocalPromotionOperationJournalRecord> operationRecords,
        CancellationToken ct)
    {
        var legacy = await ReadTrainingIntakeLocalPromotionRecordsAsync(ct);
        if (!legacy.IsSuccess)
            return legacy.MapError<bool>();
        var projected = legacy.Value!
            .Select(entry => entry.Record)
            .ToArray();
        var preparedByOperation = operationRecords
            .Where(record => record.Phase == LocalPromotionOperationPhase.Prepared)
            .ToDictionary(record => record.OperationId, StringComparer.Ordinal);
        foreach (var committed in operationRecords
                     .Where(record => record.Phase == LocalPromotionOperationPhase.Committed))
        {
            if (!preparedByOperation.TryGetValue(committed.OperationId, out var prepared) ||
                !string.Equals(
                    committed.FinalResultSha256,
                    prepared.FinalResultSha256,
                    StringComparison.Ordinal))
            {
                return LocalPromotionOperationStateInvalid<bool>();
            }
            if (HasValidCommittedLocalPromotionProjection(prepared, projected))
            {
                var projectedAuthority =
                    await ValidateCommittedProjectedLocalPromotionOperationAsync(
                        prepared,
                        ct);
                if (!projectedAuthority.IsSuccess)
                    return projectedAuthority.MapError<bool>();
                continue;
            }

            var validated = await ValidatePreparedLocalPromotionOperationAsync(prepared, ct);
            if (!validated.IsSuccess)
                return validated.MapError<bool>();
            var repaired = await RepairCommittedLocalPromotionProjectionAsync(prepared, ct);
            if (!repaired.IsSuccess)
                return repaired;
        }
        return OperationResult<bool>.Ok(true);
    }

    private async Task<OperationResult<IReadOnlyList<
        DesignConversionTrainingIntakeLocalPromotionResult>>>
        ReadMergedTrainingIntakeLocalPromotionRecordsAsync(
            IReadOnlyList<LocalPromotionOperationJournalRecord> operationRecords,
            CancellationToken ct)
    {
        var legacy = await ReadTrainingIntakeLocalPromotionRecordsAsync(ct);
        if (!legacy.IsSuccess)
            return legacy.MapError<IReadOnlyList<
                DesignConversionTrainingIntakeLocalPromotionResult>>();

        var committedIds = operationRecords
            .Where(record => record.Phase == LocalPromotionOperationPhase.Committed)
            .Select(record => record.OperationId)
            .ToHashSet(StringComparer.Ordinal);
        var prepared = operationRecords
            .Where(record => record.Phase == LocalPromotionOperationPhase.Prepared &&
                             committedIds.Contains(record.OperationId))
            .ToDictionary(record => record.OperationId, StringComparer.Ordinal);
        var merged = new List<DesignConversionTrainingIntakeLocalPromotionResult>(
            legacy.Value!.Count);
        var projectedOperationIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var entry in legacy.Value)
        {
            var record = entry.Record;
            var operationId = ReadMetadata(
                record.BoundaryMetadata,
                "local_promotion_operation_id");
            if (string.IsNullOrWhiteSpace(operationId))
            {
                merged.Add(record);
                continue;
            }

            if (!projectedOperationIds.Add(operationId) ||
                !prepared.TryGetValue(operationId, out var authoritative) ||
                !string.Equals(
                    ReadMetadata(
                        record.BoundaryMetadata,
                        "local_promotion_committed_snapshot_sha256"),
                    authoritative.FinalResultSha256,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    BuildLocalPromotionFinalResultSha256(record),
                    authoritative.FinalResultSha256,
                    StringComparison.Ordinal))
            {
                return LocalPromotionOperationStateInvalid<IReadOnlyList<
                    DesignConversionTrainingIntakeLocalPromotionResult>>();
            }
            // The legacy row is a repairable projection, but its physical ordinal
            // remains the cross-authority ordering fence. Substitute the exact
            // Prepared snapshot in place so later legacy rollback rows always win.
            merged.Add(authoritative.FinalResult!);
        }

        if (projectedOperationIds.Count != prepared.Count)
        {
            return LocalPromotionOperationStateInvalid<IReadOnlyList<
                DesignConversionTrainingIntakeLocalPromotionResult>>();
        }
        return OperationResult<IReadOnlyList<
            DesignConversionTrainingIntakeLocalPromotionResult>>.Ok(
            merged.ToArray());
    }

    private static OperationResult<DesignConversionTrainingIntakeLocalPromotionReplayResolution> ResolvePromoteLocalIdempotencyReplay(
        IReadOnlyList<DesignConversionTrainingIntakeLocalPromotionResult> existing,
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        string promotionOutputDirectory,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        LocalPromotionUploaderAuthorityPreflight uploaderAuthorityPreflight,
        string payloadHash)
    {
        if (!HasPromoteLocalIdempotencyBoundary(admissionBoundaryMetadata))
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Ok(
                new DesignConversionTrainingIntakeLocalPromotionReplayResolution(false, null));

        var matches = existing
            .Where(result => HasSamePromoteLocalIdempotencyBoundary(result.BoundaryMetadata, admissionBoundaryMetadata))
            .Where(result => !IsRollbackLocalPromotionRecord(result.BoundaryMetadata))
            .OrderBy(result => ReadMetadata(result.BoundaryMetadata, "training_intake_promote_local_recorded_at_utc"), StringComparer.Ordinal)
            .ThenBy(result => result.TrainingRun.RunId, StringComparer.Ordinal)
            .ToArray();
        if (matches.Length == 0)
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Ok(
                new DesignConversionTrainingIntakeLocalPromotionReplayResolution(false, null));

        var currentPolicyMatches = matches
            .Where(result => string.Equals(
                ReadMetadata(
                    result.BoundaryMetadata,
                    EvaluatedDpoPromotionThresholdPolicyVersionMetadataKey),
                EvaluatedDpoPromotionThresholdPolicyVersion,
                StringComparison.Ordinal))
            .ToArray();
        if (currentPolicyMatches.Length == 0)
        {
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Fail(
                "DesignConversion training intake promote-local idempotency replay was recorded under a different evaluated-DPO threshold policy.",
                TrainingIntakePromoteLocalThresholdPolicyReplayConflictErrorCode);
        }

        var samePayload = currentPolicyMatches.FirstOrDefault(result =>
            string.Equals(
                ReadMetadata(result.BoundaryMetadata, "training_intake_promote_local_idempotency_payload_hash"),
                payloadHash,
                StringComparison.Ordinal));
        if (samePayload is null)
        {
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Fail(
                "DesignConversion training intake promote-local idempotency key was replayed with a different intake, options, or promotion payload.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_IDEMPOTENCY_REPLAY_CONFLICT");
        }
        if (LocalPromotionResultRequiresUploaderAuthorityMatch(samePayload) &&
            !LocalPromotionResultUploaderAuthorityMatches(
                samePayload,
                uploaderAuthorityPreflight))
        {
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
        }

        return OperationResult<DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Ok(
            new DesignConversionTrainingIntakeLocalPromotionReplayResolution(
                true,
                MarkPromoteLocalIdempotencyBoundaryWithPayloadHash(
                    samePayload,
                    intake,
                    options,
                    promotionOutputDirectory,
                    admissionBoundaryMetadata,
                    replayHit: true,
                    createdNewSideEffect: false,
                    operationBacked: IsOperationBackedPromotionResult(samePayload),
                    payloadHash: payloadHash)));
    }

    private static OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackReplayResolution> ResolveRollbackLocalPromotionIdempotencyReplay(
        IReadOnlyList<DesignConversionTrainingIntakeLocalPromotionResult> records,
        string targetRef,
        string requestedByRef,
        string reason,
        DateTimeOffset? requestedAtUtc,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata)
    {
        if (!HasRollbackLocalPromotionIdempotencyBoundary(admissionBoundaryMetadata))
        {
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackReplayResolution>.Ok(
                new DesignConversionTrainingIntakeLocalPromotionRollbackReplayResolution(false, null));
        }

        var matches = (records ?? [])
            .Where(record => IsRollbackLocalPromotionRecord(record.BoundaryMetadata))
            .Where(record => !string.IsNullOrWhiteSpace(ReadMetadata(
                record.BoundaryMetadata,
                "training_intake_rollback_local_idempotency_payload_hash")))
            .Where(record => HasSameRollbackLocalPromotionIdempotencyBoundary(record.BoundaryMetadata, admissionBoundaryMetadata))
            .OrderBy(record => ReadMetadata(record.BoundaryMetadata, "training_intake_rollback_local_recorded_at_utc"), StringComparer.Ordinal)
            .ThenBy(record => ReadMetadata(record.BoundaryMetadata, "local_promotion_rollback_id"), StringComparer.Ordinal)
            .ToArray();
        if (matches.Length == 0)
        {
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackReplayResolution>.Ok(
                new DesignConversionTrainingIntakeLocalPromotionRollbackReplayResolution(false, null));
        }

        var payloadHash = BuildRollbackLocalPromotionIdempotencyPayloadHash(
            targetRef,
            requestedByRef,
            reason,
            requestedAtUtc);
        var samePayload = matches.FirstOrDefault(record =>
            string.Equals(
                ReadMetadata(record.BoundaryMetadata, "training_intake_rollback_local_idempotency_payload_hash"),
                payloadHash,
                StringComparison.Ordinal));
        if (samePayload is null)
        {
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackReplayResolution>.Fail(
                "DesignConversion training intake rollback-local-promotion idempotency key was replayed with a different rollback payload.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_ROLLBACK_LOCAL_IDEMPOTENCY_REPLAY_CONFLICT");
        }

        return OperationResult<DesignConversionTrainingIntakeLocalPromotionRollbackReplayResolution>.Ok(
            new DesignConversionTrainingIntakeLocalPromotionRollbackReplayResolution(
                true,
                MarkRollbackLocalPromotionIdempotencyBoundary(
                    BuildLocalPromotionRollbackResult(samePayload),
                    targetRef,
                    requestedByRef,
                    reason,
                    requestedAtUtc,
                    admissionBoundaryMetadata,
                    replayHit: true,
                    createdNewSideEffect: false)));
    }

    private async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>> StorePromoteLocalIdempotencyResultAsync(
        DesignConversionTrainingIntakeLocalPromotionResult result,
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        string promotionOutputDirectory,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        LocalPromotionOperationContext operationContext,
        CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<DesignConversionTrainingIntakeLocalPromotionResult>();
        if (!HasDurableLocalPromotionMutationEnvelope(operationContext))
        {
            return operationContext.ExistingState.Phase is null
                ? await StoreLegacyPromoteLocalIdempotencyResultAsync(
                    result,
                    intake,
                    options,
                    promotionOutputDirectory,
                    admissionBoundaryMetadata,
                    operationContext.PayloadSha256,
                    ct)
                : LocalPromotionOperationStateInvalid<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var stored = MarkPromoteLocalIdempotencyBoundaryWithPayloadHash(
            result,
            intake,
            options,
            promotionOutputDirectory,
            admissionBoundaryMetadata,
            replayHit: false,
            createdNewSideEffect: true,
            operationBacked: true,
            payloadHash: operationContext.PayloadSha256);
        var activeState = await MarkLocalPromotionActiveStateAsync(stored, ct);
        if (!activeState.IsSuccess)
            return activeState;
        stored = activeState.Value!;

        if (!ValidateCycleAccuracyLineageContract(stored))
            return CycleAccuracyLineageInvalid<DesignConversionTrainingIntakeLocalPromotionResult>();

        var metadata = new Dictionary<string, string>(
            stored.BoundaryMetadata,
            StringComparer.Ordinal)
        {
            ["local_promotion_operation_id"] = operationContext.OperationId,
            ["local_promotion_pair_reservation_id"] =
                operationContext.PairStoreReservationId,
            ["local_promotion_pair_reservation_sha256"] =
                operationContext.PairStoreReservationSha256,
            ["local_promotion_output_namespace_reservation_ref"] =
                operationContext.OutputNamespaceReservationRef,
            ["local_promotion_output_namespace_reservation_sha256"] =
                operationContext.OutputNamespaceReservationSha256,
            ["local_promotion_uploader_envelope_reservation_sha256"] =
                operationContext.UploaderEnvelopeReservationSha256,
            ["local_promotion_uploader_authority_mode"] =
                operationContext.UploaderAuthorityMode,
            ["local_promotion_uploader_configuration_fingerprint_sha256"] =
                operationContext.UploaderConfigurationFingerprintSha256
        };
        stored = stored with { BoundaryMetadata = metadata };
        var snapshotSha256 = BuildLocalPromotionFinalResultSha256(stored);
        metadata["local_promotion_committed_snapshot_sha256"] = snapshotSha256;
        stored = stored with { BoundaryMetadata = metadata };

        var projectionLine = JsonSerializer.Serialize(stored, JsonOptions);
        var projectionBytes = StrictUtf8Encoding.GetByteCount(
            projectionLine + Environment.NewLine);
        if (projectionBytes > MaxTrainingIntakeLocalPromotionJournalRowByteLength ||
            projectionBytes > _trainingIntakeLocalPromotionsMaxBytes)
        {
            return TrainingIntakeLocalPromotionsQuotaExceeded<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var projectionCapacity = await EnsureLocalPromotionProjectionCapacityAsync(
            projectionBytes,
            ct);
        if (!projectionCapacity.IsSuccess)
        {
            return projectionCapacity.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        var artifacts = await CaptureLocalPromotionOperationArtifactsAsync(
            stored,
            operationContext.CanonicalPromotionOutputDirectory,
            operationContext.RunId,
            ct);
        if (!artifacts.IsSuccess)
            return artifacts.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

        var currentJournal = await ReadLocalPromotionOperationJournalAsync(ct);
        if (!currentJournal.IsSuccess)
            return currentJournal.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        var currentState = ResolveLocalPromotionOperationState(
            currentJournal.Value!,
            operationContext.OperationId);
        if (currentState.Phase is null)
        {
            var prepare = await AppendLocalPromotionOperationRecordAsync(
                BuildLocalPromotionOperationRecord(
                    operationContext,
                    LocalPromotionOperationPhase.Prepare,
                    DateTimeOffset.UtcNow),
                ct);
            if (!prepare.IsSuccess)
                return prepare.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
            currentState = currentState with { Prepare = prepare.Value };
        }
        if (currentState.Phase == LocalPromotionOperationPhase.Prepare)
        {
            var intent = await AppendLocalPromotionOperationRecordAsync(
                BuildLocalPromotionOperationRecord(
                    operationContext,
                    LocalPromotionOperationPhase.Intent,
                    DateTimeOffset.UtcNow),
                ct);
            if (!intent.IsSuccess)
                return intent.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
            currentState = currentState with { Intent = intent.Value };
        }
        if (currentState.Phase != LocalPromotionOperationPhase.Intent)
            return LocalPromotionOperationStateInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();

        _runTrainingIntakeLocalPromotionBeforePreparedAppendObserverForTesting?
            .Invoke();
        var prepared = await AppendLocalPromotionOperationRecordAsync(
            BuildLocalPromotionOperationRecord(
                operationContext,
                LocalPromotionOperationPhase.Prepared,
                DateTimeOffset.UtcNow,
                artifacts.Value,
                stored,
                snapshotSha256),
            ct);
        if (!prepared.IsSuccess)
            return prepared.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

        var validated = await ValidatePreparedLocalPromotionOperationAsync(
            prepared.Value!,
            ct);
        if (!validated.IsSuccess)
            return validated;
        var projectionPrefix =
            await ReadLocalPromotionProjectionLogicalPrefixAsync(ct);
        if (!projectionPrefix.IsSuccess)
        {
            return projectionPrefix.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var committedRecord = BuildLocalPromotionOperationRecord(
            operationContext,
            LocalPromotionOperationPhase.Committed,
            DateTimeOffset.UtcNow,
            finalResultSha256: snapshotSha256) with
        {
            ProjectionLogicalPrefixCount = projectionPrefix.Value!.Count,
            ProjectionLogicalPrefixSha256 = projectionPrefix.Value.Sha256
        };
        var committed = await AppendLocalPromotionOperationRecordAsync(
            committedRecord,
            ct);
        if (!committed.IsSuccess)
            return committed.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

        if (_runTrainingIntakeLocalPromotionBeforeIdempotencyAppendCallbackForTesting is not null)
            await _runTrainingIntakeLocalPromotionBeforeIdempotencyAppendCallbackForTesting(ct);
        var repaired = await RepairCommittedLocalPromotionProjectionAsync(
            prepared.Value!,
            ct);
        return repaired.IsSuccess
            ? OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>.Ok(stored)
            : repaired.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
    }

    private static bool HasDurableLocalPromotionMutationEnvelope(
        LocalPromotionOperationContext context)
        => !string.IsNullOrWhiteSpace(context.PairStoreReservationId) &&
           IsSha256Ref(context.PairStoreReservationSha256) &&
           !string.IsNullOrWhiteSpace(
               context.OutputNamespaceReservationRef) &&
           IsSha256Ref(context.OutputNamespaceReservationSha256) &&
           IsSha256Ref(context.UploaderEnvelopeReservationSha256) &&
           !string.IsNullOrWhiteSpace(context.UploaderAuthorityMode) &&
           IsSha256Ref(
               context.UploaderConfigurationFingerprintSha256);

    private async Task<OperationResult<
        DesignConversionTrainingIntakeLocalPromotionResult>>
        StoreLegacyPromoteLocalIdempotencyResultAsync(
            DesignConversionTrainingIntakeLocalPromotionResult result,
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingPipelineOptions options,
            string promotionOutputDirectory,
            IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
            string payloadHash,
            CancellationToken ct)
    {
        var stored = MarkPromoteLocalIdempotencyBoundaryWithPayloadHash(
            result,
            intake,
            options,
            promotionOutputDirectory,
            admissionBoundaryMetadata,
            replayHit: false,
            createdNewSideEffect: true,
            operationBacked: false,
            payloadHash: payloadHash);
        var activeState = await MarkLocalPromotionActiveStateAsync(stored, ct);
        if (!activeState.IsSuccess)
            return activeState;
        stored = activeState.Value!;
        if (!ValidateCycleAccuracyLineageContract(stored))
        {
            return CycleAccuracyLineageInvalid<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var line = JsonSerializer.Serialize(stored, JsonOptions);
        var lineBytes = StrictUtf8Encoding.GetByteCount(
            line + Environment.NewLine);
        var capacity = await EnsureLocalPromotionProjectionCapacityAsync(
            MaxTrainingIntakeLocalPromotionJournalRowByteLength,
            ct);
        if (!capacity.IsSuccess)
            return capacity.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        var projectionJournal = await _localPromotionJournalSet.ReadAsync(ct);
        if (!projectionJournal.IsSuccess)
        {
            return string.Equals(
                projectionJournal.ErrorCode,
                InvalidUtf8ErrorCode,
                StringComparison.Ordinal)
                ? TrainingIntakeLocalPromotionsInvalidUtf8<
                    DesignConversionTrainingIntakeLocalPromotionResult>()
                : projectionJournal.MapError<
                    DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        if (lineBytes > MaxTrainingIntakeLocalPromotionJournalRowByteLength ||
            !TryProjectCommittedAuthorityLength(
                projectionJournal.Value!.ActiveProjectionByteLength,
                lineBytes,
                out var projected) ||
            projected > _trainingIntakeLocalPromotionsMaxBytes)
        {
            return TrainingIntakeLocalPromotionsQuotaExceeded<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        }
        var appended = await _localPromotionJournalSet.AppendLineAsync(
            DesignConversionLocalPromotionJournalKind.Projection,
            line,
            ct);
        if (!appended.IsSuccess)
            return appended.MapError<
                DesignConversionTrainingIntakeLocalPromotionResult>();
        return OperationResult<
            DesignConversionTrainingIntakeLocalPromotionResult>.Ok(stored);
    }

    private OperationResult<DesignConversionDpoPromotionArtifactPaths>
        ResolveTrainingIntakeLocalPromotionArtifactPaths(
            string promotionOutputDirectory,
            string runId)
    {
        var requestedPaths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            _rootDirectory,
            promotionOutputDirectory,
            runId);
        if (!requestedPaths.IsSuccess)
            return requestedPaths;

        var artifactOutputDirectory = Path.Combine(
            requestedPaths.Value!.OutputDirectory,
            BuildTrainingIntakeLocalPromotionArtifactDirectoryName(runId));
        return DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            _rootDirectory,
            artifactOutputDirectory,
            runId);
    }

    private static string BuildTrainingIntakeLocalPromotionArtifactDirectoryName(string runId)
        => $"dpo-{HashText(runId)[..12]}-dpo-policy-checkpoints";

    private static bool LocalPromotionArtifactPathsMatch(
        DesignConversionDpoPromotionArtifactPaths expected,
        DesignConversionDpoPromotionArtifactPaths actual)
        => string.Equals(
            JsonSerializer.Serialize(expected, JsonOptions),
            JsonSerializer.Serialize(actual, JsonOptions),
            StringComparison.Ordinal);

    private async Task<OperationResult<bool>>
        EnsureLocalPromotionProjectionCapacityAsync(
            long reservationBytes,
            CancellationToken ct)
    {
        var ensured = await _localPromotionJournalSet.EnsureCapacityAsync(
            operationReservationBytes: 0L,
            projectionReservationBytes: reservationBytes,
            TrainingIntakeLocalPromotionsQuotaExceededErrorCode,
            TrainingIntakeLocalPromotionsQuotaExceededSafeMessage,
            ct);
        return ensured.IsSuccess
            ? OperationResult<bool>.Ok(true)
            : ensured.MapError<bool>();
    }

    private async Task<OperationResult<bool>>
        CanReserveLocalPromotionProjectionRowWithoutRotationAsync(
            long reservationBytes,
            CancellationToken ct)
    {
        if (reservationBytes < 0)
            return LocalPromotionOperationStateInvalid<bool>();
        if (reservationBytes > MaxTrainingIntakeLocalPromotionJournalRowByteLength)
            return OperationResult<bool>.Ok(false);

        var projectionJournal = await _localPromotionJournalSet.ReadAsync(ct);
        if (!projectionJournal.IsSuccess)
        {
            return string.Equals(
                projectionJournal.ErrorCode,
                InvalidUtf8ErrorCode,
                StringComparison.Ordinal)
                ? TrainingIntakeLocalPromotionsInvalidUtf8<bool>()
                : projectionJournal.MapError<bool>();
        }
        var committedLength = projectionJournal.Value!.ActiveProjectionByteLength;
        try
        {
            var projectionPath = Path.Combine(
                _rootDirectory,
                TrainingIntakeLocalPromotionFileName);
            if (File.Exists(projectionPath))
            {
                committedLength = Math.Max(
                    committedLength,
                    new FileInfo(projectionPath).Length);
            }
        }
        catch (Exception exception) when (exception is
                   IOException or UnauthorizedAccessException or
                   SecurityException or NotSupportedException)
        {
            return LocalPromotionOperationStateInvalid<bool>();
        }

        return OperationResult<bool>.Ok(
            TryProjectCommittedAuthorityLength(
                committedLength,
                reservationBytes,
                out var projected) &&
            projected <= _trainingIntakeLocalPromotionsMaxBytes);
    }

    private async Task<OperationResult<
        DesignConversionTrainingIntakeLocalPromotionReplayResolution>>
        ResolveOperationlessPreflightBlockedLegacyPromoteLocalReplayAsync(
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingPipelineOptions options,
            string promotionOutputDirectory,
            IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
            CancellationToken ct)
    {
        var legacy = await ReadTrainingIntakeLocalPromotionRecordsAsync(ct);
        if (!legacy.IsSuccess)
        {
            return legacy.MapError<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>();
        }

        var legacyPayloadHash = BuildPromoteLocalIdempotencyPayloadHash(
            intake,
            options,
            promotionOutputDirectory,
            BuildBuiltInLocalReceiptOnlyPromotionUploaderAuthorityPreflight());
        return ResolveOperationlessPreflightBlockedLegacyPromoteLocalReplay(
            legacy.Value!.Select(entry => entry.Record).ToArray(),
            intake,
            options,
            promotionOutputDirectory,
            admissionBoundaryMetadata,
            legacyPayloadHash);
    }

    private static OperationResult<
        DesignConversionTrainingIntakeLocalPromotionReplayResolution>
        ResolveOperationlessPreflightBlockedLegacyPromoteLocalReplay(
            IReadOnlyList<DesignConversionTrainingIntakeLocalPromotionResult> existing,
            DesignConversionTrainingIntakeRecord intake,
            DesignConversionTrainingPipelineOptions options,
            string promotionOutputDirectory,
            IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
            string payloadHash)
    {
        if (!HasPromoteLocalIdempotencyBoundary(admissionBoundaryMetadata))
        {
            return OperationResult<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Ok(
                    new DesignConversionTrainingIntakeLocalPromotionReplayResolution(
                        false,
                        null));
        }

        var matches = (existing ?? [])
            .Where(result => HasSamePromoteLocalIdempotencyBoundary(
                result.BoundaryMetadata,
                admissionBoundaryMetadata))
            .Where(result => !IsRollbackLocalPromotionRecord(
                result.BoundaryMetadata))
            .Where(IsOperationlessPreflightBlockedLegacyPromotionReplayCandidate)
            .OrderBy(result => ReadMetadata(
                    result.BoundaryMetadata,
                    "training_intake_promote_local_recorded_at_utc"),
                StringComparer.Ordinal)
            .ThenBy(result => result.TrainingRun.RunId, StringComparer.Ordinal)
            .ToArray();
        if (matches.Length == 0)
        {
            return OperationResult<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Ok(
                    new DesignConversionTrainingIntakeLocalPromotionReplayResolution(
                        false,
                        null));
        }

        var currentPolicyMatches = matches
            .Where(result => string.Equals(
                ReadMetadata(
                    result.BoundaryMetadata,
                    EvaluatedDpoPromotionThresholdPolicyVersionMetadataKey),
                EvaluatedDpoPromotionThresholdPolicyVersion,
                StringComparison.Ordinal))
            .ToArray();
        if (currentPolicyMatches.Length == 0)
        {
            return OperationResult<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Fail(
                    "DesignConversion training intake promote-local idempotency replay was recorded under a different evaluated-DPO threshold policy.",
                    TrainingIntakePromoteLocalThresholdPolicyReplayConflictErrorCode);
        }

        var samePayload = currentPolicyMatches.FirstOrDefault(result =>
            string.Equals(
                ReadMetadata(
                    result.BoundaryMetadata,
                    "training_intake_promote_local_idempotency_payload_hash"),
                payloadHash,
                StringComparison.Ordinal));
        if (samePayload is null)
        {
            return OperationResult<
                DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Fail(
                    "DesignConversion training intake promote-local idempotency key was replayed with a different intake, options, or promotion payload.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_IDEMPOTENCY_REPLAY_CONFLICT");
        }

        return OperationResult<
            DesignConversionTrainingIntakeLocalPromotionReplayResolution>.Ok(
                new DesignConversionTrainingIntakeLocalPromotionReplayResolution(
                    true,
                    MarkPromoteLocalIdempotencyBoundaryWithPayloadHash(
                        samePayload,
                        intake,
                        options,
                        promotionOutputDirectory,
                        admissionBoundaryMetadata,
                        replayHit: true,
                        createdNewSideEffect: false,
                        operationBacked: false,
                        payloadHash: payloadHash)));
    }

    private static bool
        IsOperationlessPreflightBlockedLegacyPromotionReplayCandidate(
            DesignConversionTrainingIntakeLocalPromotionResult result)
        => !result.LocalPromotionReady &&
           result.Publication is null &&
           result.PromotedLocalModel is null &&
           string.IsNullOrWhiteSpace(ReadMetadata(
               result.BoundaryMetadata,
               "local_promotion_operation_id")) &&
           string.IsNullOrWhiteSpace(ReadMetadata(
               result.BoundaryMetadata,
               "training_intake_promote_local_operation_authority")) &&
           !LocalPromotionResultRequiresUploaderAuthorityMatch(result) &&
           (result.BlockReasons.Contains(
                "local_promotion_blocked_training_intake_preflight",
                StringComparer.Ordinal) ||
            string.Equals(
                result.TrainingRun.TrainingExecutionBoundary,
                "blocked_before_runner_by_training_intake_preflight",
                StringComparison.Ordinal));

    private async Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>> MarkLocalPromotionActiveStateAsync(
        DesignConversionTrainingIntakeLocalPromotionResult result,
        CancellationToken ct)
    {
        if (!result.LocalPromotionReady || result.PromotedLocalModel is null)
            return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>.Ok(result);

        var operations = await ReadLocalPromotionOperationJournalAsync(ct);
        if (!operations.IsSuccess)
            return operations.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        var reconciled = await ReconcileCommittedLocalPromotionProjectionsAsync(
            operations.Value!,
            ct);
        if (!reconciled.IsSuccess)
            return reconciled.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();
        var existing = await ReadMergedTrainingIntakeLocalPromotionRecordsAsync(
            operations.Value!,
            ct);
        if (!existing.IsSuccess)
            return existing.MapError<DesignConversionTrainingIntakeLocalPromotionResult>();

        var resolution = ResolveCurrentLocalPromotionActiveState(existing.Value!);
        if (resolution.Kind == DesignConversionLocalPromotionActiveStateKind.Invalid)
        {
            return DesignConversionDpoPromotedParentContinuation
                .StateInvalid<DesignConversionTrainingIntakeLocalPromotionResult>();
        }

        return OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>.Ok(
            MarkLocalPromotionActiveState(result, resolution.Active));
    }

    private static DesignConversionTrainingIntakeLocalPromotionResult MarkLocalPromotionActiveState(
        DesignConversionTrainingIntakeLocalPromotionResult result,
        DesignConversionLocalPromotionActive? prior)
    {
        var activeRef = BuildLocalPromotionActiveRef(result);
        var metadata = new Dictionary<string, string>(result.BoundaryMetadata, StringComparer.Ordinal)
        {
            ["local_promotion_record_kind"] = "promotion",
            ["local_promotion_active_local_model_ref"] = activeRef,
            ["local_promotion_active_model_id"] = result.PromotedLocalModel?.ModelId ?? string.Empty,
            ["local_promotion_active_checkpoint_sha256"] = result.PromotedLocalModel?.CheckpointSha256 ?? string.Empty,
            ["local_promotion_prior_state_recorded"] = bool.TrueString,
            ["local_promotion_prior_state_kind"] = prior is not null ? "local_promotion_ref" : "none",
            ["local_promotion_prior_active_local_model_ref"] = prior?.ActiveLocalModelRef ?? string.Empty,
            ["local_promotion_prior_active_model_id"] = prior?.ActiveModelId ?? string.Empty,
            ["local_promotion_prior_active_checkpoint_sha256"] = prior?.ActiveCheckpointSha256 ?? string.Empty,
            ["local_promotion_rollback_supported"] = (prior is not null).ToString(),
            ["local_promotion_rollback_boundary"] = prior is not null
                ? "actual_local_rollback_via_local_artifact_db_metadata"
                : "explicit_unsupported_nonready_boundary",
            ["local_promotion_rollback_status"] = prior is not null
                ? "ready_restore_prior_active_local_model"
                : "unsupported_no_prior_active_local_model_checkpoint_state",
            ["local_promotion_previous_model_checkpoint_ref_available"] = (prior is not null).ToString(),
            ["local_promotion_restore_previous_state_supported"] = (prior is not null).ToString(),
            ["product_ready_blocked_by_local_rollback_boundary"] = (prior is null).ToString()
        };
        var evidenceRefs = (result.EvidenceRefs ?? [])
            .Append("DESIGN_CONVERSION_LOCAL_PROMOTION_ACTIVE_STATE_RECORDED")
            .Append(prior is not null
                ? "DESIGN_CONVERSION_LOCAL_PROMOTION_PRIOR_ACTIVE_STATE_RECORDED"
                : "DESIGN_CONVERSION_LOCAL_PROMOTION_PRIOR_ACTIVE_STATE_NONE_RECORDED")
            .Concat(prior is not null
                ? ["DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_SUPPORTED_BY_PRIOR_ACTIVE_STATE"]
                : ["DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_UNSUPPORTED_NO_PRIOR_STATE"])
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();
        var warnings = (result.Warnings ?? [])
            .Append(prior is not null
                ? "local_promotion_rollback_metadata_recorded"
                : "local_promotion_rollback_unsupported_no_prior_state")
            .Append(prior is not null
                ? "local_promotion_prior_active_state_recorded"
                : "local_promotion_prior_active_state_none")
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();

        return result with
        {
            EvidenceRefs = evidenceRefs,
            Warnings = warnings,
            BoundaryMetadata = metadata
        };
    }

    internal static DesignConversionLocalPromotionActiveStateResolution ResolveCurrentLocalPromotionActiveState(
        IReadOnlyList<DesignConversionTrainingIntakeLocalPromotionResult> records)
    {
        DesignConversionLocalPromotionActive? state = null;
        var promotions = new List<DesignConversionLocalPromotionActive>();
        var activeRefs = new HashSet<string>(StringComparer.Ordinal);
        var rollbackIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var record in records ?? [])
        {
            if (record is null)
                return DesignConversionLocalPromotionActiveStateResolution.Invalid;

            var recordKind = ReadMetadata(
                record.BoundaryMetadata,
                "local_promotion_record_kind");
            if (!string.IsNullOrEmpty(recordKind) &&
                !string.Equals(recordKind, "promotion", StringComparison.Ordinal) &&
                !string.Equals(recordKind, "rollback", StringComparison.Ordinal))
            {
                return DesignConversionLocalPromotionActiveStateResolution.Invalid;
            }
            if (string.Equals(recordKind, "rollback", StringComparison.Ordinal))
            {
                if (state is null ||
                    !string.Equals(
                        ReadMetadata(record.BoundaryMetadata, "schema_version"),
                        TrainingIntakeLocalPromotionRollbackSchemaVersion,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        ReadMetadata(
                            record.BoundaryMetadata,
                            "local_promotion_rollback_applied"),
                        bool.TrueString,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        ReadMetadata(
                            record.BoundaryMetadata,
                            "local_promotion_prior_state_restored"),
                        bool.TrueString,
                        StringComparison.Ordinal))
                {
                    return DesignConversionLocalPromotionActiveStateResolution.Invalid;
                }

                var rollbackId = ReadMetadata(
                    record.BoundaryMetadata,
                    "local_promotion_rollback_id");
                var targetRef = ReadMetadata(
                    record.BoundaryMetadata,
                    "local_promotion_rollback_target_local_model_ref");
                var previousActiveRef = ReadMetadata(
                    record.BoundaryMetadata,
                    "local_promotion_rollback_previous_active_local_model_ref");
                var restoredRef = ReadMetadata(
                    record.BoundaryMetadata,
                    "local_promotion_rollback_restored_active_local_model_ref");
                var restoredModelId = ReadMetadata(
                    record.BoundaryMetadata,
                    "local_promotion_rollback_restored_active_model_id");
                var restoredCheckpoint = ReadMetadata(
                    record.BoundaryMetadata,
                    "local_promotion_rollback_restored_active_checkpoint_sha256");
                if (string.IsNullOrWhiteSpace(rollbackId) ||
                    !rollbackIds.Add(rollbackId) ||
                    !string.Equals(
                        targetRef,
                        state.ActiveLocalModelRef,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        previousActiveRef,
                        state.ActiveLocalModelRef,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        restoredRef,
                        state.PriorActiveLocalModelRef,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        restoredModelId,
                        state.PriorActiveModelId,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        restoredCheckpoint,
                        state.PriorActiveCheckpointSha256,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        ReadMetadata(
                            record.BoundaryMetadata,
                            "local_promotion_active_local_model_ref"),
                        restoredRef,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        ReadMetadata(
                            record.BoundaryMetadata,
                            "local_promotion_active_model_id"),
                        restoredModelId,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        ReadMetadata(
                            record.BoundaryMetadata,
                            "local_promotion_active_checkpoint_sha256"),
                        restoredCheckpoint,
                        StringComparison.Ordinal))
                {
                    return DesignConversionLocalPromotionActiveStateResolution.Invalid;
                }

                var restoredMatches = promotions
                    .Where(promotion =>
                        string.Equals(
                            promotion.ActiveLocalModelRef,
                            restoredRef,
                            StringComparison.Ordinal) &&
                        string.Equals(
                            promotion.ActiveModelId,
                            restoredModelId,
                            StringComparison.Ordinal) &&
                        string.Equals(
                            promotion.ActiveCheckpointSha256,
                            restoredCheckpoint,
                            StringComparison.Ordinal))
                    .ToArray();
                if (restoredMatches.Length != 1)
                    return DesignConversionLocalPromotionActiveStateResolution.Invalid;

                state = restoredMatches[0];
                continue;
            }

            if (!record.LocalPromotionReady)
            {
                if (string.Equals(recordKind, "promotion", StringComparison.Ordinal) ||
                    record.PromotedLocalModel is not null ||
                    HasLocalPromotionActiveStateClaim(record.BoundaryMetadata))
                {
                    return DesignConversionLocalPromotionActiveStateResolution.Invalid;
                }
                continue;
            }

            if (!string.Equals(recordKind, "promotion", StringComparison.Ordinal) ||
                !TryBuildLocalPromotionActive(record, out var promotion) ||
                promotion is null ||
                !activeRefs.Add(promotion.ActiveLocalModelRef) ||
                !PromotionPriorMatchesCurrent(promotion, state))
            {
                return DesignConversionLocalPromotionActiveStateResolution.Invalid;
            }

            promotions.Add(promotion);
            state = promotion;
        }

        return state is null
            ? DesignConversionLocalPromotionActiveStateResolution.None
            : new DesignConversionLocalPromotionActiveStateResolution(
                DesignConversionLocalPromotionActiveStateKind.Active,
                state);
    }

    private static bool PromotionPriorMatchesCurrent(
        DesignConversionLocalPromotionActive promotion,
        DesignConversionLocalPromotionActive? current)
        => current is null
            ? string.IsNullOrEmpty(promotion.PriorActiveLocalModelRef) &&
              string.IsNullOrEmpty(promotion.PriorActiveModelId) &&
              string.IsNullOrEmpty(promotion.PriorActiveCheckpointSha256)
            : string.Equals(
                  promotion.PriorActiveLocalModelRef,
                  current.ActiveLocalModelRef,
                  StringComparison.Ordinal) &&
              string.Equals(
                  promotion.PriorActiveModelId,
                  current.ActiveModelId,
                  StringComparison.Ordinal) &&
              string.Equals(
                  promotion.PriorActiveCheckpointSha256,
                  current.ActiveCheckpointSha256,
                  StringComparison.Ordinal);

    private static bool HasLocalPromotionActiveStateClaim(
        IReadOnlyDictionary<string, string>? metadata)
        => !string.IsNullOrWhiteSpace(ReadMetadata(
               metadata,
               "local_promotion_active_local_model_ref")) ||
           !string.IsNullOrWhiteSpace(ReadMetadata(
               metadata,
               "local_promotion_active_model_id")) ||
           !string.IsNullOrWhiteSpace(ReadMetadata(
               metadata,
               "local_promotion_active_checkpoint_sha256")) ||
           !string.IsNullOrWhiteSpace(ReadMetadata(
               metadata,
               "local_promotion_prior_state_kind")) ||
           !string.IsNullOrWhiteSpace(ReadMetadata(
               metadata,
               "local_promotion_prior_active_local_model_ref")) ||
           !string.IsNullOrWhiteSpace(ReadMetadata(
               metadata,
               "local_promotion_prior_active_model_id")) ||
           !string.IsNullOrWhiteSpace(ReadMetadata(
               metadata,
               "local_promotion_prior_active_checkpoint_sha256"));

    private static bool TryBuildLocalPromotionActive(
        DesignConversionTrainingIntakeLocalPromotionResult record,
        out DesignConversionLocalPromotionActive? active)
    {
        active = null;
        var model = record.PromotedLocalModel;
        var publication = record.Publication;
        var artifacts = publication?.Manifest.PromotionArtifacts;
        if (model is null ||
            publication is null ||
            artifacts is null ||
            !string.Equals(
                ReadMetadata(record.BoundaryMetadata, "schema_version"),
                TrainingIntakeLocalPromotionSchemaVersion,
                StringComparison.Ordinal) ||
            publication.Decision.Kind !=
                DesignConversionPromotionDecisionKind.Promote ||
            !publication.Decision.AllowsUpload ||
            !publication.Manifest.LocalPromotionReceiptWritten ||
            !string.Equals(
                publication.Manifest.PromotionReceiptKind,
                "local_receipt_only",
                StringComparison.Ordinal) ||
            publication.Manifest.ModelServerUploadAttempted ||
            publication.Manifest.ModelServerPromotionClaimed ||
            publication.PublicationKind !=
                DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt ||
            !string.Equals(
                publication.PublicationStatus,
                DesignConversionPromotionPublicationStatus.NotUploaded,
                StringComparison.Ordinal) ||
            !model.LocalOnly ||
            !model.CheckpointFreshLoadVerified ||
            !model.CheckpointContainsRealTrainedWeights ||
            !model.PromotionManifestClaimed ||
            string.IsNullOrWhiteSpace(record.TrainingRun?.RunId) ||
            string.IsNullOrWhiteSpace(record.PromotionOutputDirectory) ||
            string.IsNullOrWhiteSpace(record.PromotedCheckpointPath) ||
            string.IsNullOrWhiteSpace(model.CheckpointPath) ||
            string.IsNullOrWhiteSpace(artifacts.CheckpointPath) ||
            string.IsNullOrWhiteSpace(artifacts.TokenizerPath) ||
            string.IsNullOrWhiteSpace(artifacts.PolicyPath) ||
            !DesignConversionDpoPolicyBaseMetadata.IsCanonicalSha256(
                model.CheckpointSha256))
        {
            return false;
        }

        var dpoTrainerPolicyCheckpointPromotion =
            model.DpoTrainerPolicyCheckpointConverted ||
            model.DpoTrainerPolicyCheckpointFreshLoaded;
        var dpoPolicyCheckpointFileRef = model.DpoPolicyCheckpointFileRef;
        var hasDpoPolicyCheckpointFileRef =
            !string.IsNullOrWhiteSpace(dpoPolicyCheckpointFileRef);
        if (hasDpoPolicyCheckpointFileRef &&
            !dpoTrainerPolicyCheckpointPromotion)
        {
            return false;
        }
        if (dpoTrainerPolicyCheckpointPromotion &&
            !hasDpoPolicyCheckpointFileRef)
        {
            return false;
        }

        DesignConversionDpoPromotionArtifactAnchors? anchors = null;
        string sourceEncoderContractPath = string.Empty;
        if (dpoTrainerPolicyCheckpointPromotion && hasDpoPolicyCheckpointFileRef)
        {
            if (!model.DpoTrainerPolicyCheckpointConverted ||
                !model.DpoTrainerPolicyCheckpointFreshLoaded ||
                !DesignConversionDpoPromotionArtifactContractCodec
                    .TryReadTrustedAnchorMetadata(
                        record.BoundaryMetadata,
                        out anchors) ||
                anchors is null ||
                !string.Equals(
                    dpoPolicyCheckpointFileRef,
                    $"dpo_policy_checkpoint_file:{anchors.PolicyCheckpointFileName}",
                    StringComparison.Ordinal) ||
                !TryResolveManifestSourceEncoderContractPath(
                    artifacts.PolicyPath,
                    out sourceEncoderContractPath) ||
                PathsEqualForPlatform(artifacts.TokenizerPath, sourceEncoderContractPath) ||
                PathsEqualForPlatform(artifacts.PolicyPath, sourceEncoderContractPath))
            {
                return false;
            }
        }

        var activeRef = BuildLocalPromotionActiveRef(record);
        var activeModelId = ReadMetadata(
            record.BoundaryMetadata,
            "local_promotion_active_model_id");
        var activeCheckpoint = ReadMetadata(
            record.BoundaryMetadata,
            "local_promotion_active_checkpoint_sha256");
        var priorKind = ReadMetadata(
            record.BoundaryMetadata,
            "local_promotion_prior_state_kind");
        var priorRef = ReadMetadata(
            record.BoundaryMetadata,
            "local_promotion_prior_active_local_model_ref");
        var priorModelId = ReadMetadata(
            record.BoundaryMetadata,
            "local_promotion_prior_active_model_id");
        var priorCheckpoint = ReadMetadata(
            record.BoundaryMetadata,
            "local_promotion_prior_active_checkpoint_sha256");
        if (string.IsNullOrWhiteSpace(activeRef) ||
            !string.Equals(
                ReadMetadata(
                    record.BoundaryMetadata,
                    "local_promotion_active_local_model_ref"),
                activeRef,
                StringComparison.Ordinal) ||
            !string.Equals(activeModelId, model.ModelId, StringComparison.Ordinal) ||
            !string.Equals(
                activeCheckpoint,
                model.CheckpointSha256,
                StringComparison.Ordinal) ||
            !string.Equals(
                ReadMetadata(record.BoundaryMetadata, "local_promotion_ready"),
                bool.TrueString,
                StringComparison.Ordinal) ||
            !string.Equals(
                ReadMetadata(
                    record.BoundaryMetadata,
                    "local_promotion_prior_state_recorded"),
                bool.TrueString,
                StringComparison.Ordinal) ||
            priorKind is not "none" and not "local_promotion_ref" ||
            priorKind == "none" &&
            (!string.IsNullOrEmpty(priorRef) ||
             !string.IsNullOrEmpty(priorModelId) ||
             !string.IsNullOrEmpty(priorCheckpoint)) ||
            priorKind == "local_promotion_ref" &&
            (string.IsNullOrWhiteSpace(priorRef) ||
             string.IsNullOrWhiteSpace(priorModelId) ||
             !DesignConversionDpoPolicyBaseMetadata.IsCanonicalSha256(
                 priorCheckpoint)))
        {
            return false;
        }

        active = new DesignConversionLocalPromotionActive(
            activeRef,
            activeModelId,
            activeCheckpoint,
            record.TrainingRun.RunId,
            record.PromotionOutputDirectory,
            record.PromotedCheckpointPath,
            model.CheckpointPath,
            artifacts.CheckpointPath,
            artifacts.TokenizerPath,
            sourceEncoderContractPath,
            artifacts.PolicyPath,
            priorRef,
            priorModelId,
            priorCheckpoint,
            anchors);
        return true;
    }

    private static bool TryResolveManifestSourceEncoderContractPath(
        string policyCheckpointContractPath,
        out string sourceEncoderContractPath)
    {
        sourceEncoderContractPath = string.Empty;
        if (string.IsNullOrWhiteSpace(policyCheckpointContractPath))
            return false;

        try
        {
            var policyPath = Path.GetFullPath(policyCheckpointContractPath);
            var directory = Path.GetDirectoryName(policyPath);
            var policyLeaf = Path.GetFileName(policyPath);
            if (string.IsNullOrWhiteSpace(directory) ||
                string.IsNullOrWhiteSpace(policyLeaf) ||
                !policyLeaf.EndsWith(
                    DesignConversionDpoPromotionArtifactContractCodec
                        .PolicyCheckpointContractSuffix,
                    StringComparison.Ordinal))
            {
                return false;
            }

            var sourceLeaf =
                policyLeaf[..^DesignConversionDpoPromotionArtifactContractCodec
                    .PolicyCheckpointContractSuffix.Length] +
                DesignConversionDpoPromotionArtifactContractCodec
                    .SourceEncoderContractSuffix;
            if (sourceLeaf.Length <=
                    DesignConversionDpoPromotionArtifactContractCodec
                        .SourceEncoderContractSuffix.Length ||
                !string.Equals(
                    Path.GetFileName(sourceLeaf),
                    sourceLeaf,
                    StringComparison.Ordinal))
            {
                return false;
            }

            sourceEncoderContractPath = Path.Combine(directory, sourceLeaf);
            return true;
        }
        catch (Exception exception)
            when (SnapshotExceptionGraphClassifier.IsNonFatal(exception))
        {
            return false;
        }
    }

    private static bool PathsEqualForPlatform(string left, string right)
    {
        if (string.IsNullOrWhiteSpace(left) || string.IsNullOrWhiteSpace(right))
            return false;

        try
        {
            var comparison = OperatingSystem.IsWindows()
                ? StringComparison.OrdinalIgnoreCase
                : StringComparison.Ordinal;
            return string.Equals(
                Path.GetFullPath(left),
                Path.GetFullPath(right),
                comparison);
        }
        catch (Exception exception)
            when (SnapshotExceptionGraphClassifier.IsNonFatal(exception))
        {
            return false;
        }
    }

    private static string BuildLocalPromotionActiveRef(DesignConversionTrainingIntakeLocalPromotionResult result)
    {
        var metadataRef = ReadMetadata(result.BoundaryMetadata, "local_promotion_active_local_model_ref");
        if (!string.IsNullOrWhiteSpace(metadataRef))
            return metadataRef;

        var modelId = result.PromotedLocalModel?.ModelId;
        if (!string.IsNullOrWhiteSpace(modelId))
            return $"local://design-conversion/promoted-local-model/{Uri.EscapeDataString(modelId)}";

        var uploadRef = result.Publication?.Manifest.PromotionUploadRef;
        return string.IsNullOrWhiteSpace(uploadRef) ? string.Empty : uploadRef;
    }

    private static bool MatchesLocalPromotionRef(
        DesignConversionTrainingIntakeLocalPromotionResult record,
        string promotedLocalModelRef)
    {
        if (record is null
            || !record.LocalPromotionReady
            || string.Equals(
                ReadMetadata(record.BoundaryMetadata, "local_promotion_record_kind"),
                "rollback",
                StringComparison.Ordinal))
        {
            return false;
        }

        var requested = promotedLocalModelRef?.Trim();
        if (string.IsNullOrWhiteSpace(requested))
            return false;

        var candidates = new[]
        {
            BuildLocalPromotionActiveRef(record),
            ReadMetadata(record.BoundaryMetadata, "local_promotion_active_local_model_ref"),
            ReadMetadata(record.BoundaryMetadata, "promotion_upload_ref"),
            ReadMetadata(record.BoundaryMetadata, "local_promoted_model_id"),
            ReadMetadata(record.BoundaryMetadata, "local_promoted_checkpoint_sha256"),
            record.PromotedLocalModel?.ModelId,
            record.PromotedLocalModel?.ManifestId,
            record.PromotedLocalModel?.ManifestRef,
            record.PromotedLocalModel?.CheckpointSha256,
            record.Publication?.Manifest.PromotionUploadRef
        };

        return candidates.Any(candidate =>
            !string.IsNullOrWhiteSpace(candidate)
            && string.Equals(candidate, requested, StringComparison.Ordinal));
    }

    private static string BuildLocalPromotionRollbackId(
        string targetRef,
        string priorRef,
        string requestedByRef,
        string reason,
        DateTimeOffset rollbackAt)
        => $"local-promotion-rollback-{HashText(string.Join("|",
        [
            TrainingIntakeLocalPromotionRollbackSchemaVersion,
            targetRef,
            priorRef,
            requestedByRef,
            reason,
            rollbackAt.ToString("O", CultureInfo.InvariantCulture)
        ]))}";

    internal static DesignConversionTrainingIntakeLocalPromotionResult BuildLocalPromotionRollbackRecord(
        DesignConversionTrainingIntakeLocalPromotionResult target,
        string rollbackId,
        string targetRef,
        string previousActiveRef,
        string restoredRef,
        string restoredModelId,
        string restoredCheckpointSha256,
        string requestedByRef,
        string reason,
        DateTimeOffset rollbackAt)
    {
        var metadata = new Dictionary<string, string>(target.BoundaryMetadata, StringComparer.Ordinal)
        {
            ["schema_version"] = TrainingIntakeLocalPromotionRollbackSchemaVersion,
            ["local_promotion_record_kind"] = "rollback",
            ["local_promotion_rollback_id"] = rollbackId,
            ["local_promotion_rollback_applied"] = bool.TrueString,
            ["local_promotion_prior_state_restored"] = bool.TrueString,
            ["local_promotion_no_prior_state_recorded"] = bool.FalseString,
            ["local_promotion_rollback_target_local_model_ref"] = targetRef,
            ["local_promotion_rollback_previous_active_local_model_ref"] = previousActiveRef,
            ["local_promotion_rollback_restored_active_local_model_ref"] = restoredRef,
            ["local_promotion_rollback_restored_active_model_id"] = restoredModelId,
            ["local_promotion_rollback_restored_active_checkpoint_sha256"] = restoredCheckpointSha256,
            ["local_promotion_active_local_model_ref"] = restoredRef,
            ["local_promotion_active_model_id"] = restoredModelId,
            ["local_promotion_active_checkpoint_sha256"] = restoredCheckpointSha256,
            ["local_promotion_rollback_requested_by_ref"] = requestedByRef,
            ["local_promotion_rollback_reason_hash"] = $"sha256:{HashText(reason)}",
            ["local_promotion_rollback_requested_at_utc"] = rollbackAt.ToString("O", CultureInfo.InvariantCulture),
            ["local_promotion_rollback_boundary"] = "actual_local_rollback_via_local_artifact_db_metadata",
            ["local_promotion_rollback_status"] = "restored_prior_active_local_model",
            ["local_promotion_rollback_supported"] = bool.TrueString,
            ["local_promotion_restore_previous_state_supported"] = bool.TrueString,
            ["local_promotion_previous_model_checkpoint_ref_available"] = bool.TrueString,
            ["local_promotion_ready"] = bool.FalseString,
            ["local_promotion_not_ready"] = bool.TrueString,
            ["deployment_verified"] = bool.FalseString,
            ["product_ready"] = bool.FalseString,
            ["product_ready_blocked_by_local_rollback_boundary"] = bool.FalseString
        };
        // Rollback rows remain legacy-journal authority. They must not inherit
        // the committed operation projection identity from their target.
        metadata.Remove("local_promotion_operation_id");
        metadata.Remove("local_promotion_committed_snapshot_sha256");
        var evidenceRefs = (target.EvidenceRefs ?? [])
            .Where(reference => !string.Equals(
                reference,
                "DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_UNSUPPORTED_NONREADY_BOUNDARY",
                StringComparison.Ordinal))
            .Append("DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_RECORD_WRITTEN")
            .Append("DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_APPLIED")
            .Append("DESIGN_CONVERSION_LOCAL_PROMOTION_ROLLBACK_PRIOR_ACTIVE_STATE_RESTORED")
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();
        var warnings = (target.Warnings ?? [])
            .Where(warning => !string.Equals(warning, "local_promotion_rollback_unsupported", StringComparison.Ordinal))
            .Append("local_promotion_rollback_applied")
            .Append("local_promotion_prior_active_state_restored")
            .Append("product_ready=false")
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToArray();

        return target with
        {
            LocalPromotionReady = false,
            PromotedLocalModel = null,
            CycleAccuracyLineage = null,
            EvidenceRefs = evidenceRefs,
            Warnings = warnings,
            BoundaryMetadata = metadata
        };
    }

    private static DesignConversionTrainingIntakeLocalPromotionRollbackResult BuildLocalPromotionRollbackResult(
        DesignConversionTrainingIntakeLocalPromotionResult record)
    {
        var metadata = record.BoundaryMetadata;
        return new DesignConversionTrainingIntakeLocalPromotionRollbackResult(
            RollbackId: ReadMetadata(metadata, "local_promotion_rollback_id"),
            RollbackApplied: IsTruthy(ReadMetadata(metadata, "local_promotion_rollback_applied")),
            PriorStateRestored: IsTruthy(ReadMetadata(metadata, "local_promotion_prior_state_restored")),
            NoPriorStateRecorded: IsTruthy(ReadMetadata(metadata, "local_promotion_no_prior_state_recorded")),
            RolledBackLocalModelRef: ReadMetadata(metadata, "local_promotion_rollback_target_local_model_ref"),
            PreviousActiveLocalModelRef: ReadMetadata(metadata, "local_promotion_rollback_previous_active_local_model_ref"),
            RestoredActiveLocalModelRef: ReadMetadata(metadata, "local_promotion_rollback_restored_active_local_model_ref"),
            RestoredActiveCheckpointSha256: ReadMetadata(metadata, "local_promotion_rollback_restored_active_checkpoint_sha256"),
            EvidenceRefs: record.EvidenceRefs,
            Warnings: record.Warnings,
            BlockReasons: record.BlockReasons,
            BoundaryMetadata: record.BoundaryMetadata);
    }

