    private static IReadOnlyDictionary<string, string> BuildRollbackLocalPromotionIdempotencyMetadata(
        IReadOnlyDictionary<string, string>? source,
        string targetRef,
        string requestedByRef,
        string reason,
        DateTimeOffset? requestedAtUtc,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        bool replayHit,
        bool createdNewSideEffect)
    {
        var metadata = new Dictionary<string, string>(source ?? new Dictionary<string, string>(StringComparer.Ordinal), StringComparer.Ordinal);
        foreach (var pair in admissionBoundaryMetadata ?? new Dictionary<string, string>(StringComparer.Ordinal))
            metadata[pair.Key] = pair.Value;

        if (!HasRollbackLocalPromotionIdempotencyBoundary(admissionBoundaryMetadata))
            return metadata;

        metadata["training_intake_admission_boundary_scope"] =
            "route_admission_plus_local_rollback_replay_cache_no_auth_token_no_full_tenant_isolation";
        metadata["training_intake_rollback_local_replay_cache_boundary"] =
            "tenant_id_idempotency_key_same_target_requester_reason_timestamp_rollback_local_replay_cache_v1";
        metadata["training_intake_replay_cache_checked"] = bool.TrueString;
        metadata["training_intake_idempotency_replay_hit"] = replayHit.ToString();
        metadata["training_intake_idempotency_created_new_side_effect"] = createdNewSideEffect.ToString();
        metadata["training_intake_idempotent_replay_result"] = replayHit.ToString();
        metadata["training_intake_idempotency_side_effect_boundary"] = "rollback_local_promotion_append_only_once";
        metadata["training_intake_rollback_local_idempotency_payload_hash"] =
            BuildRollbackLocalPromotionIdempotencyPayloadHash(targetRef, requestedByRef, reason, requestedAtUtc);
        if (string.IsNullOrWhiteSpace(ReadMetadata(metadata, "training_intake_rollback_local_recorded_at_utc")))
            metadata["training_intake_rollback_local_recorded_at_utc"] = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        metadata["training_intake_local_promotion_record_file"] = TrainingIntakeLocalPromotionFileName;

        return metadata;
    }

    private static bool IsRollbackLocalPromotionRecord(
        IReadOnlyDictionary<string, string>? metadata)
        => string.Equals(
            ReadMetadata(metadata, "local_promotion_record_kind"),
            "rollback",
            StringComparison.Ordinal);

    private static bool HasSameRollbackLocalPromotionIdempotencyBoundary(
        IReadOnlyDictionary<string, string>? existing,
        IReadOnlyDictionary<string, string>? candidate)
        => string.Equals(
               ReadMetadata(existing, "training_intake_tenant_id_ref"),
               ReadMetadata(candidate, "training_intake_tenant_id_ref"),
               StringComparison.Ordinal)
           && string.Equals(
               ReadMetadata(existing, "training_intake_idempotency_key_ref"),
               ReadMetadata(candidate, "training_intake_idempotency_key_ref"),
               StringComparison.Ordinal);

    private static bool HasRollbackLocalPromotionIdempotencyBoundary(
        IReadOnlyDictionary<string, string>? metadata)
        => !string.IsNullOrWhiteSpace(ReadMetadata(metadata, "training_intake_tenant_id_ref"))
           && !string.IsNullOrWhiteSpace(ReadMetadata(metadata, "training_intake_idempotency_key_ref"));

    private static string BuildRollbackLocalPromotionIdempotencyPayloadHash(
        string targetRef,
        string requestedByRef,
        string reason,
        DateTimeOffset? requestedAtUtc)
        => $"sha256:{HashText(string.Join("|",
        [
            TrainingIntakeLocalPromotionRollbackSchemaVersion,
            targetRef,
            requestedByRef,
            $"sha256:{HashText(reason)}",
            BuildRollbackLocalPromotionRequestedAtDiscriminator(requestedAtUtc)
        ]))}";

    private static string BuildRollbackLocalPromotionRequestedAtDiscriminator(
        DateTimeOffset? requestedAtUtc)
        => requestedAtUtc.HasValue
            ? $"requestedAtUtc:explicit:{requestedAtUtc.Value.ToUniversalTime().ToString("O", CultureInfo.InvariantCulture)}"
            : "requestedAtUtc:omitted";

    public async Task<OperationResult<IReadOnlyList<DesignConversionTrainingIntakeLocalPromotionResult>>> ListTrainingIntakeLocalPromotionRecordsAsync(
        CancellationToken ct = default)
    {
        var gateAcquired = false;
        try
        {
            await _recordsMutationContext.RunTrainingIntakeLocalPromotionGate
                .WaitAsync(ct);
            gateAcquired = true;
            await using var mutationLease =
                await AcquireTrainingIntakeLocalPromotionMutationLeaseAsync(ct);
            using var journalMutationLeaseBinding =
                _localPromotionJournalSet.BindMutationLease(mutationLease);
            var recoveredJournals =
                await _localPromotionJournalSet.RecoverAsync(ct);
            if (!recoveredJournals.IsSuccess)
            {
                return recoveredJournals.MapError<IReadOnlyList<
                    DesignConversionTrainingIntakeLocalPromotionResult>>();
            }
            var operations = await ReadLocalPromotionOperationJournalAsync(ct);
            if (!operations.IsSuccess)
                return operations.MapError<IReadOnlyList<
                    DesignConversionTrainingIntakeLocalPromotionResult>>();
            var reconciled = await ReconcileCommittedLocalPromotionProjectionsAsync(
                operations.Value!,
                ct);
            if (!reconciled.IsSuccess)
                return reconciled.MapError<IReadOnlyList<
                    DesignConversionTrainingIntakeLocalPromotionResult>>();
            return await ReadMergedTrainingIntakeLocalPromotionRecordsAsync(
                operations.Value!,
                ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<IReadOnlyList<
                DesignConversionTrainingIntakeLocalPromotionResult>>();
        }
        catch (Exception exception) when (exception is
            IOException or UnauthorizedAccessException or SecurityException)
        {
            return LocalPromotionOperationStateInvalid<IReadOnlyList<
                DesignConversionTrainingIntakeLocalPromotionResult>>();
        }
        finally
        {
            if (gateAcquired)
                _recordsMutationContext.RunTrainingIntakeLocalPromotionGate.Release();
        }
    }

    private async Task<OperationResult<IReadOnlyList<LocalPromotionProjectionJournalEntry>>> ReadTrainingIntakeLocalPromotionRecordsAsync(
        CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<IReadOnlyList<LocalPromotionProjectionJournalEntry>>();

        var journalSet = await _localPromotionJournalSet.ReadAsync(ct);
        if (!journalSet.IsSuccess)
        {
            return string.Equals(
                journalSet.ErrorCode,
                InvalidUtf8ErrorCode,
                StringComparison.Ordinal)
                ? TrainingIntakeLocalPromotionsInvalidUtf8<IReadOnlyList<
                    LocalPromotionProjectionJournalEntry>>()
                : journalSet.MapError<IReadOnlyList<
                    LocalPromotionProjectionJournalEntry>>();
        }
        var lines = journalSet.Value!.ProjectionLines;
        var records = new List<LocalPromotionProjectionJournalEntry>();

        for (var i = 0; i < lines.Count; i++)
        {
            if (StrictUtf8Encoding.GetByteCount(lines[i].Text + "\r\n") >
                MaxTrainingIntakeLocalPromotionJournalRowByteLength)
            {
                return OperationResult<IReadOnlyList<
                    LocalPromotionProjectionJournalEntry>>.Fail(
                    $"DesignConversion training intake local promotion line {i + 1} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_PROMOTION_LINE_INVALID");
            }
            DesignConversionTrainingIntakeLocalPromotionResult? record;
            try
            {
                record = JsonSerializer.Deserialize<DesignConversionTrainingIntakeLocalPromotionResult>(
                    lines[i].Text,
                    JsonOptions);
            }
            catch (JsonException)
            {
                return OperationResult<IReadOnlyList<LocalPromotionProjectionJournalEntry>>.Fail(
                    $"DesignConversion training intake local promotion line {i + 1} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_PROMOTION_LINE_INVALID");
            }
            catch (NotSupportedException)
            {
                return OperationResult<IReadOnlyList<LocalPromotionProjectionJournalEntry>>.Fail(
                    $"DesignConversion training intake local promotion line {i + 1} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_PROMOTION_LINE_INVALID");
            }

            if (record is null)
            {
                return OperationResult<IReadOnlyList<LocalPromotionProjectionJournalEntry>>.Fail(
                    $"DesignConversion training intake local promotion line {i + 1} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_PROMOTION_LINE_INVALID");
            }

            if (!ValidateCycleAccuracyLineageContract(record))
            {
                return OperationResult<IReadOnlyList<LocalPromotionProjectionJournalEntry>>.Fail(
                    $"DesignConversion training intake local promotion line {i + 1} could not be read.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_PROMOTION_LINE_INVALID");
            }

            records.Add(new LocalPromotionProjectionJournalEntry(
                record,
                lines[i].Generation,
                lines[i].Ordinal,
                lines[i].IsActive));
        }

        return OperationResult<IReadOnlyList<LocalPromotionProjectionJournalEntry>>
            .Ok(records.ToArray());
    }

    private static bool HasValidLocalPromotionProjectionPrefixDeclaration(
        LocalPromotionOperationJournalRecord record)
    {
        if (record.Phase != LocalPromotionOperationPhase.Committed)
        {
            return record.ProjectionLogicalPrefixCount == 0L &&
                   record.ProjectionLogicalPrefixSha256 is null;
        }
        if (record.ProjectionLogicalPrefixSha256 is null)
            return record.ProjectionLogicalPrefixCount == 0L;
        return record.ProjectionLogicalPrefixCount >= 0L &&
               IsSha256Ref(record.ProjectionLogicalPrefixSha256);
    }

    private const string DualTargetTeacherExternalMetadataPrefix =
        "dual_target_teacher_external_";
    private const string DualTargetTeacherExternalServerOwnedCommitMetadataKey =
        "dual_target_teacher_external_server_owned_commit_v1";

    private static DesignConversionTrainingIntakeLocalPromotionResult MarkPromoteLocalIdempotencyBoundary(
        DesignConversionTrainingIntakeLocalPromotionResult result,
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        string promotionOutputDirectory,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        bool replayHit,
        bool createdNewSideEffect,
        bool operationBacked)
        => MarkPromoteLocalIdempotencyBoundaryWithPayloadHash(
            result,
            intake,
            options,
            promotionOutputDirectory,
            admissionBoundaryMetadata,
            replayHit,
            createdNewSideEffect,
            operationBacked,
            BuildPromoteLocalIdempotencyPayloadHash(
                intake,
                options,
                promotionOutputDirectory,
                BuildBuiltInLocalReceiptOnlyPromotionUploaderAuthorityPreflight()));

    private static DesignConversionTrainingIntakeLocalPromotionResult
        MarkPromoteLocalIdempotencyBoundaryWithPayloadHash(
        DesignConversionTrainingIntakeLocalPromotionResult result,
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        string promotionOutputDirectory,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        bool replayHit,
        bool createdNewSideEffect,
        bool operationBacked,
        string payloadHash)
    {
        var committedDualTargetExternalConsumption = string.Equals(
            ReadMetadata(
                result.BoundaryMetadata,
                DualTargetTeacherExternalServerOwnedCommitMetadataKey),
            bool.TrueString,
            StringComparison.Ordinal);
        var metadata = new Dictionary<string, string>(result.BoundaryMetadata, StringComparer.Ordinal);
        if (!committedDualTargetExternalConsumption)
        {
            RemoveDualTargetTeacherExternalReservedMetadata(metadata);
        }
        if (!operationBacked)
        {
            RemoveLocalPromotionOperationMetadata(metadata);
        }
        foreach (var pair in admissionBoundaryMetadata ?? new Dictionary<string, string>(StringComparer.Ordinal))
        {
            if (IsDualTargetTeacherExternalReservedMetadataKey(pair.Key))
                continue;
            metadata[pair.Key] = pair.Value;
        }
        metadata[EvaluatedDpoPromotionThresholdPolicyVersionMetadataKey] =
            EvaluatedDpoPromotionThresholdPolicyVersion;

        if (!HasPromoteLocalIdempotencyBoundary(metadata))
            return result with { BoundaryMetadata = metadata };

        metadata["training_intake_admission_boundary_scope"] =
            "route_admission_plus_local_promote_replay_cache_no_auth_token_no_full_tenant_isolation";
        metadata["training_intake_promote_local_replay_cache_boundary"] =
            "tenant_id_idempotency_key_same_intake_run_options_output_promote_local_replay_cache_v1";
        metadata["training_intake_replay_cache_checked"] = bool.TrueString;
        metadata["training_intake_idempotency_replay_hit"] = replayHit.ToString();
        metadata["training_intake_idempotency_created_new_side_effect"] = createdNewSideEffect.ToString();
        metadata["training_intake_idempotent_replay_result"] = replayHit.ToString();
        metadata["training_intake_idempotency_side_effect_boundary"] =
            operationBacked
                ? "promote_local_fenced_operation_journal_then_legacy_projection"
                : committedDualTargetExternalConsumption
                ? "promote_local_external_consumption_committed_then_terminal_append_no_retrain"
                : "promote_local_best_effort_non_atomic_artifacts_then_append";
        metadata["training_intake_promote_local_artifact_append_atomic"] = bool.FalseString;
        metadata["training_intake_promote_local_recoverable_residue_possible"] = bool.TrueString;
        var hadRetryMayRepeatTrainingClaim = result.BoundaryMetadata.ContainsKey(
            "training_intake_promote_local_retry_may_repeat_training");
        var hadNoRetrainClaim = result.BoundaryMetadata.ContainsKey(
            "training_intake_promote_local_no_retrain_claimed");
        if (!replayHit ||
            operationBacked ||
            committedDualTargetExternalConsumption ||
            hadRetryMayRepeatTrainingClaim)
        {
            metadata["training_intake_promote_local_retry_may_repeat_training"] =
                (!operationBacked && !committedDualTargetExternalConsumption)
                .ToString();
        }
        else
        {
            metadata.Remove(
                "training_intake_promote_local_retry_may_repeat_training");
        }
        if (!replayHit ||
            operationBacked ||
            committedDualTargetExternalConsumption ||
            hadNoRetrainClaim)
        {
            metadata["training_intake_promote_local_no_retrain_claimed"] =
                (operationBacked || committedDualTargetExternalConsumption)
                .ToString();
        }
        else
        {
            metadata.Remove("training_intake_promote_local_no_retrain_claimed");
        }
        if (operationBacked)
        {
            metadata["training_intake_promote_local_operation_authority"] =
                TrainingIntakeLocalPromotionOperationFileName;
        }
        metadata["training_intake_promote_local_idempotency_payload_hash"] =
            payloadHash;
        if (string.IsNullOrWhiteSpace(ReadMetadata(
                metadata,
                "training_intake_promote_local_recorded_at_utc")))
        {
            metadata["training_intake_promote_local_recorded_at_utc"] =
                DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        }
        metadata["training_intake_local_promotion_record_file"] = TrainingIntakeLocalPromotionFileName;

        return result with { BoundaryMetadata = metadata };
    }

    private static void RemoveLocalPromotionOperationMetadata(
        IDictionary<string, string> metadata)
    {
        metadata.Remove("local_promotion_operation_id");
        metadata.Remove("local_promotion_pair_reservation_id");
        metadata.Remove("local_promotion_pair_reservation_sha256");
        metadata.Remove("local_promotion_output_namespace_reservation_ref");
        metadata.Remove("local_promotion_output_namespace_reservation_sha256");
        metadata.Remove("local_promotion_uploader_envelope_reservation_sha256");
        metadata.Remove("local_promotion_committed_snapshot_sha256");
        metadata.Remove("training_intake_promote_local_operation_authority");
    }

    private static bool IsOperationBackedPromotionResult(
        DesignConversionTrainingIntakeLocalPromotionResult result)
        => string.Equals(
               ReadMetadata(
                   result.BoundaryMetadata,
                   "training_intake_promote_local_operation_authority"),
               TrainingIntakeLocalPromotionOperationFileName,
               StringComparison.Ordinal) &&
           !string.IsNullOrWhiteSpace(ReadMetadata(
               result.BoundaryMetadata,
               "local_promotion_operation_id")) &&
           IsSha256Ref(ReadMetadata(
               result.BoundaryMetadata,
               "local_promotion_committed_snapshot_sha256"));

    private static DesignConversionTrainingIntakeLocalPromotionResult
        MarkPromoteLocalOperationReplay(
            DesignConversionTrainingIntakeLocalPromotionResult result)
    {
        var metadata = new Dictionary<string, string>(
            result.BoundaryMetadata,
            StringComparer.Ordinal)
        {
            ["training_intake_replay_cache_checked"] = bool.TrueString,
            ["training_intake_idempotency_replay_hit"] = bool.TrueString,
            ["training_intake_idempotency_created_new_side_effect"] =
                bool.FalseString,
            ["training_intake_idempotent_replay_result"] = bool.TrueString
        };
        return result with { BoundaryMetadata = metadata };
    }

    private static bool IsDualTargetTeacherExternalReservedMetadataKey(
        string? key)
        => !string.IsNullOrEmpty(key) &&
           key.StartsWith(
               DualTargetTeacherExternalMetadataPrefix,
               StringComparison.Ordinal);

    private static void RemoveDualTargetTeacherExternalReservedMetadata(
        IDictionary<string, string> metadata)
    {
        foreach (var key in metadata.Keys
                     .Where(IsDualTargetTeacherExternalReservedMetadataKey)
                     .ToArray())
        {
            metadata.Remove(key);
        }
    }

    private static bool HasSamePromoteLocalIdempotencyBoundary(
        IReadOnlyDictionary<string, string>? existing,
        IReadOnlyDictionary<string, string>? candidate)
        => string.Equals(
               ReadMetadata(existing, "training_intake_tenant_id_ref"),
               ReadMetadata(candidate, "training_intake_tenant_id_ref"),
               StringComparison.Ordinal)
           && string.Equals(
               ReadMetadata(existing, "training_intake_idempotency_key_ref"),
               ReadMetadata(candidate, "training_intake_idempotency_key_ref"),
               StringComparison.Ordinal);

    private static bool HasPromoteLocalIdempotencyBoundary(
        IReadOnlyDictionary<string, string>? metadata)
        => !string.IsNullOrWhiteSpace(ReadMetadata(metadata, "training_intake_tenant_id_ref"))
           && !string.IsNullOrWhiteSpace(ReadMetadata(metadata, "training_intake_idempotency_key_ref"));

    private static bool LocalPromotionResultUploaderAuthorityMatches(
        DesignConversionTrainingIntakeLocalPromotionResult result,
        LocalPromotionUploaderAuthorityPreflight current)
        => LocalPromotionUploaderAuthorityMatches(
            ReadMetadata(
                result.BoundaryMetadata,
                "local_promotion_uploader_authority_mode"),
            ReadMetadata(
                result.BoundaryMetadata,
                "local_promotion_uploader_configuration_fingerprint_sha256"),
            current);

    private static bool LocalPromotionResultRequiresUploaderAuthorityMatch(
        DesignConversionTrainingIntakeLocalPromotionResult result)
        => result.LocalPromotionReady ||
           result.Publication is not null ||
           !string.IsNullOrWhiteSpace(ReadMetadata(
               result.BoundaryMetadata,
               "local_promotion_uploader_authority_mode")) ||
           !string.IsNullOrWhiteSpace(ReadMetadata(
               result.BoundaryMetadata,
               "local_promotion_uploader_configuration_fingerprint_sha256"));

    private static bool LocalPromotionUploaderAuthorityMatches(
        string uploaderAuthorityMode,
        string uploaderConfigurationFingerprintSha256,
        LocalPromotionUploaderAuthorityPreflight current)
        => string.Equals(
               uploaderAuthorityMode,
               current.UploaderAuthorityMode,
               StringComparison.Ordinal) &&
           string.Equals(
               uploaderConfigurationFingerprintSha256,
               current.UploaderConfigurationFingerprintSha256,
               StringComparison.Ordinal);

    private static bool IsLocalReceiptPublicationOrRejectedLocalReceipt(
        DesignConversionPromotionPublicationResult publication)
        => publication.UploadReceipt?.PublicationKind ==
               DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt ||
           publication.PublicationKind ==
               DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt ||
           publication.Manifest.LocalPromotionReceiptWritten ||
           string.Equals(
               publication.Manifest.PromotionReceiptKind,
               "local_receipt_only",
               StringComparison.Ordinal) ||
           string.Equals(
               publication.Manifest.PromotionReceiptKind,
               "invalid_local_receipt",
               StringComparison.Ordinal) ||
           (publication.Decision.Reasons ?? [])
           .Any(reason => reason.StartsWith(
               "DESIGN_CONVERSION_PROMOTION_LOCAL_RECEIPT_",
               StringComparison.Ordinal)) ||
           (publication.Decision.EvidenceRefs ?? [])
           .Contains(
               "DESIGN_CONVERSION_PROMOTION_LOCAL_RECEIPT_REJECTED",
               StringComparer.Ordinal);

    private static string BuildPromoteLocalIdempotencyPayloadHash(
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        string promotionOutputDirectory,
        LocalPromotionUploaderAuthorityPreflight uploaderAuthorityPreflight)
        => $"sha256:{HashText(string.Join("|",
        [
            TrainingIntakeLocalPromotionSchemaVersion,
            EvaluatedDpoPromotionThresholdPolicyVersion,
            uploaderAuthorityPreflight.UploaderAuthorityMode,
            uploaderAuthorityPreflight.UploaderConfigurationFingerprintSha256,
            intake.IntakeId,
            string.IsNullOrWhiteSpace(options.RunId) ? BuildTrainingIntakeRunId(intake) : options.RunId,
            JsonSerializer.Serialize(options, JsonOptions),
            NormalizePromotionOutputDirectoryForIdempotency(promotionOutputDirectory)
        ]))}";

    private static string NormalizePromotionOutputDirectoryForIdempotency(string promotionOutputDirectory)
    {
        if (string.IsNullOrWhiteSpace(promotionOutputDirectory))
            return string.Empty;

        try
        {
            return Path.GetFullPath(promotionOutputDirectory);
        }
        catch
        {
            return promotionOutputDirectory.Trim();
        }
    }

    private static string BuildTrainingIntakeId(
        DesignConversionApprovedDpoHandoffArtifact handoff,
        string requestedBy,
        string reason,
        DateTimeOffset requestedAtUtc,
        IReadOnlyDictionary<string, string>? admissionBoundaryMetadata,
        string trainingIntakeSchemaVersion)
    {
        var identityParts = new List<string>
        {
            trainingIntakeSchemaVersion,
            handoff.ArtifactId,
            requestedBy,
            reason,
            requestedAtUtc.ToString("O", CultureInfo.InvariantCulture),
            string.Join(",", (handoff.Rows ?? []).Select(row => row.RecordHash).Order(StringComparer.Ordinal))
        };

        var tenantRef = ReadMetadata(admissionBoundaryMetadata, "training_intake_tenant_id_ref");
        if (!string.IsNullOrWhiteSpace(tenantRef))
            identityParts.Add($"tenant:{tenantRef}");

        return $"training-intake-{HashText(string.Join("|", identityParts))}";
    }

    private async Task<OperationResult<bool>>
        WriteRecordsCoreWithCandidatePayloadCustodyAsync(
            IReadOnlyList<DesignConversionLocalArtifactDbRecord> records,
            int rewrittenRecordIndex,
            CancellationToken ct)
        => await WriteRecordsCoreWithCandidatePayloadCustodyAsync(
            records,
            [rewrittenRecordIndex],
            ct);

    private async Task<OperationResult<bool>>
        WriteRecordsCoreWithCandidatePayloadCustodyAsync(
            IReadOnlyList<DesignConversionLocalArtifactDbRecord> records,
            IReadOnlyList<int> rewrittenRecordIndexes,
            CancellationToken ct,
            IReadOnlySet<string>? knownEligibleRecordIds = null)
    {
        if (rewrittenRecordIndexes.Count == 0)
            return PayloadCustodyFailed<bool>();

        var recordsToWrite = records.ToArray();
        var rewritePlans = new List<CandidatePayloadCustodyRewritePlan>(
            rewrittenRecordIndexes.Count);
        foreach (var rewrittenRecordIndex in rewrittenRecordIndexes
                     .Distinct()
                     .Order())
        {
            if (rewrittenRecordIndex < 0 || rewrittenRecordIndex >= records.Count)
                return PayloadCustodyFailed<bool>();

            var immutableAppendFingerprint =
                GetImmutableAppendFingerprint(records[rewrittenRecordIndex]);
            if (immutableAppendFingerprint is null)
                return PayloadCustodyFailed<bool>();

            string? successorAuthorityIdentitySha256 = null;
            if ((records[rewrittenRecordIndex].DpoCandidates ?? [])
                .Any(candidate => RequiresPayloadCustody(candidate.TrainingRecord)))
            {
                var predecessorCommitment =
                    TryReadCandidatePayloadCustodyCommitment(
                        records[rewrittenRecordIndex]);
                if (!predecessorCommitment.IsSuccess)
                    return predecessorCommitment.MapError<bool>();

                successorAuthorityIdentitySha256 =
                    predecessorCommitment.Value!.AuthorityFingerprintSha256;
                if (!string.Equals(
                        successorAuthorityIdentitySha256,
                        immutableAppendFingerprint,
                        StringComparison.Ordinal))
                {
                    return PayloadCustodyFailed<bool>();
                }
            }

            var rewritten = RebindNormalizedCandidatePayloadCustody(
                records[rewrittenRecordIndex],
                immutableAppendFingerprint);
            if (!rewritten.IsSuccess)
                return rewritten.MapError<bool>();

            var custodyPlan = BuildCandidatePayloadCustodyAppendPlan(
                rewritten.Value!,
                allowApprovedMaterializable: true,
                authorityIdentitySha256Override:
                    successorAuthorityIdentitySha256,
                immutableAppendFingerprintOverride:
                    immutableAppendFingerprint);
            if (!custodyPlan.IsSuccess)
                return custodyPlan.MapError<bool>();

            recordsToWrite[rewrittenRecordIndex] = custodyPlan.Value!.AuthorityRecord;
            rewritePlans.Add(new CandidatePayloadCustodyRewritePlan(
                rewrittenRecordIndex,
                custodyPlan.Value.AuthorityRecord,
                custodyPlan.Value.Draft,
                custodyPlan.Value.Commitment));
        }

        var custodyPlans = rewritePlans
            .Where(plan => plan.Draft is not null && plan.Commitment is not null)
            .ToArray();
        var hasCustodyPlan = custodyPlans.Length > 0;
        if (!hasCustodyPlan)
            return await WriteRecordsCoreAsync(
                recordsToWrite,
                ct,
                knownEligibleRecordIds);

        await using var mutationLease =
            await AcquireRecordsAuthorityMutationLeaseAsync(ct);
        var reconciliation =
            await ReconcileCandidatePayloadCustodyUnderAuthorityLeaseAsync(
                CancellationToken.None);
        if (!reconciliation.IsSuccess)
            return reconciliation.MapError<bool>();

        var receipts = new List<DesignConversionCandidatePayloadCustodyStageReceipt>(
            custodyPlans.Length);
        var authorityCommitted = false;
        try
        {
            foreach (var plan in custodyPlans)
            {
                var prepared = _candidatePayloadCustodyStore.Prepare(
                    plan.Draft!,
                    plan.Commitment!);
                if (!prepared.IsSuccess)
                {
                    var cleanup =
                        await CleanupPreparedCandidatePayloadCustodyUnderAuthorityLeaseAsync(
                            receipts);
                    if (!cleanup.IsSuccess)
                        return cleanup.MapError<bool>();
                    return prepared.MapError<bool>();
                }

                receipts.Add(prepared.Value!);
            }

            // До атомарной замены журнала отмена всё ещё честно прерывает операцию
            // и удаляет подготовленные custody-данные. После замены сам writer
            // отключает caller-token и завершает только восстановимые хвосты.
            var written = await WriteRecordsCoreAsync(
                recordsToWrite,
                ct,
                knownEligibleRecordIds);
            if (!written.IsSuccess)
            {
                var cleanup =
                    await CleanupPreparedCandidatePayloadCustodyUnderAuthorityLeaseAsync(
                        receipts);
                if (!cleanup.IsSuccess)
                    return cleanup.MapError<bool>();
                return written;
            }

            authorityCommitted = true;
            foreach (var receipt in receipts)
            {
                var committed = _candidatePayloadCustodyStore.Commit(receipt);
                if (!committed.IsSuccess)
                {
                    // Журнал уже стал властью, поэтому сбой публикации подготовленного
                    // payload остаётся задачей повторного reconciliation. Возвращать
                    // отказ здесь означало бы ложно сообщить, что commit не состоялся.
                    return OperationResult<bool>.Ok(false);
                }
            }

            return written;
        }
        catch
        {
            if (authorityCommitted)
            {
                // После атомарной замены нельзя запускать cleanup по caller-сценарию
                // или превращать восстановимый хвост custody в отказ всей операции.
                return OperationResult<bool>.Ok(false);
            }

            if (!authorityCommitted && receipts.Count > 0)
            {
                var cleanup =
                    await CleanupPreparedCandidatePayloadCustodyUnderAuthorityLeaseAsync(
                        receipts);
                if (!cleanup.IsSuccess)
                    return cleanup.MapError<bool>();
            }

            throw;
        }
    }

    private async Task<OperationResult<bool>>
        CleanupPreparedCandidatePayloadCustodyUnderAuthorityLeaseAsync(
            IReadOnlyList<DesignConversionCandidatePayloadCustodyStageReceipt> receipts)
    {
        foreach (var receipt in receipts)
        {
            var cleanup =
                await CleanupPreparedCandidatePayloadCustodyUnderAuthorityLeaseAsync(
                    receipt);
            if (!cleanup.IsSuccess)
                return cleanup;
        }

        return OperationResult<bool>.Ok(true);
    }

    private static OperationResult<CandidatePayloadCustodyAppendPlan>
        BuildCandidatePayloadCustodyAppendPlan(
            DesignConversionLocalArtifactDbRecord record,
            bool allowApprovedMaterializable = false,
            string? authorityIdentitySha256Override = null,
            string? immutableAppendFingerprintOverride = null)
    {
        var custodyEntries = new List<DesignConversionCandidatePayloadCustodyEntry>();
        foreach (var candidate in record.DpoCandidates ?? [])
        {
            var trainingRecord = candidate.TrainingRecord;
            if (!RequiresPayloadCustody(trainingRecord))
            {
                if (trainingRecord.PayloadCustodySecret is not null)
                    return PayloadCustodyFailed<CandidatePayloadCustodyAppendPlan>();
                continue;
            }

            var materialized = ValidateAndMaterializePayloadCustody(trainingRecord);
            var custodyPersistable =
                IsReviewPendingTeacherPayloadCustodyPersistable(
                    trainingRecord) ||
                (allowApprovedMaterializable &&
                 IsApprovedTeacherPayloadCustodyMaterializable(
                     trainingRecord));
            if (!materialized.IsSuccess || !custodyPersistable)
            {
                return PayloadCustodyFailed<CandidatePayloadCustodyAppendPlan>();
            }

            var payload = trainingRecord.PayloadCustodySecret!;
            custodyEntries.Add(new DesignConversionCandidatePayloadCustodyEntry(
                trainingRecord.RecordId,
                payload.TrainingRecordBindingSha256,
                payload.GovernanceSha256,
                payload.PromptSha256,
                payload.ChosenResponseSha256,
                payload.RejectedResponseSha256,
                payload));
        }

        var redacted = ClearCandidatePayloadCustody(record);
        if (custodyEntries.Count == 0)
        {
            return OperationResult<CandidatePayloadCustodyAppendPlan>.Ok(
                new CandidatePayloadCustodyAppendPlan(redacted, null, null));
        }

        var authorityIdentitySha256 =
            string.IsNullOrWhiteSpace(authorityIdentitySha256Override)
                ? ReadMetadata(
                    record.Metadata,
                    ImmutableAppendFingerprintMetadataKey)
                : authorityIdentitySha256Override;
        var draft = DesignConversionCandidatePayloadCustodyStore.CreateDraft(
            record.RecordId,
            authorityIdentitySha256,
            custodyEntries);
        if (!draft.IsSuccess)
            return draft.MapError<CandidatePayloadCustodyAppendPlan>();

        var metadata = new Dictionary<string, string>(redacted.Metadata, StringComparer.Ordinal)
        {
            [DesignConversionCandidatePayloadCustodyStore.TransactionMetadataKey] =
                draft.Value!.TransactionId,
            [DesignConversionCandidatePayloadCustodyStore.ManifestMetadataKey] =
                draft.Value.ManifestSha256,
            [DesignConversionCandidatePayloadCustodyStore.BindingSetMetadataKey] =
                draft.Value.BindingSetSha256,
            [DesignConversionCandidatePayloadCustodyStore.EntryCountMetadataKey] =
                custodyEntries.Count.ToString(CultureInfo.InvariantCulture)
        };
        var authority = redacted with { Metadata = metadata };
        metadata[ImmutableAppendFingerprintMetadataKey] =
            immutableAppendFingerprintOverride ??
            BuildImmutableAppendFingerprint(authority);
        authority = authority with { Metadata = metadata };
        var commitment = DesignConversionCandidatePayloadCustodyStore.BindAuthority(
            draft.Value,
            metadata[ImmutableAppendFingerprintMetadataKey]);
        if (!commitment.IsSuccess)
            return commitment.MapError<CandidatePayloadCustodyAppendPlan>();

        return OperationResult<CandidatePayloadCustodyAppendPlan>.Ok(
            new CandidatePayloadCustodyAppendPlan(
                authority,
                draft.Value,
                commitment.Value));
    }

    private async Task<OperationResult<bool>>
        ReconcileCandidatePayloadCustodyUnderAuthorityLeaseAsync(
            CancellationToken ct)
    {
        var state = await ResolveCurrentAuthorityStateForAppendAsync(ct);
        if (!state.IsSuccess)
            return state.MapError<bool>();

        var authorities = new Dictionary<
            string,
            DesignConversionCandidatePayloadCustodyCommitment>(StringComparer.Ordinal);
        foreach (var authorityState in state.Value!.RecordsById.Values)
        {
            if (authorityState.Count != 1)
                return PayloadCustodyFailed<bool>();
            DesignConversionLocalArtifactDbRecord? record;
            try
            {
                record = JsonSerializer.Deserialize<DesignConversionLocalArtifactDbRecord>(
                    authorityState.CurrentRecordJson,
                    JsonOptions);
            }
            catch (JsonException)
            {
                return PayloadCustodyFailed<bool>();
            }
            if (record is null)
                return PayloadCustodyFailed<bool>();

            var requiredBindings = (record.DpoCandidates ?? [])
                .Select(static candidate => candidate.TrainingRecord)
                .Where(RequiresPayloadCustody)
                .Select(trainingRecord => ReadMetadata(
                    trainingRecord.Provenance.Metadata,
                    DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey))
                .Order(StringComparer.Ordinal)
                .ToArray();
            if (requiredBindings.Length == 0)
                continue;

            var commitment = TryReadCandidatePayloadCustodyCommitment(
                record,
                requiredBindings);
            if (!commitment.IsSuccess ||
                !authorities.TryAdd(commitment.Value!.TransactionId, commitment.Value))
            {
                return PayloadCustodyFailed<bool>();
            }
        }

        return _candidatePayloadCustodyStore.Reconcile(authorities);
    }

    private async Task<OperationResult<bool>> EnsureCandidatePayloadCustodyReconciledAsync(
        CancellationToken ct)
    {
        try
        {
            await _recordsMutationContext.Gate.WaitAsync(ct);
        }
        catch (OperationCanceledException)
        {
            return Cancelled<bool>();
        }

        try
        {
            await using var mutationLease =
                await AcquireRecordsAuthorityMutationLeaseAsync(ct);
            return await ReconcileCandidatePayloadCustodyUnderAuthorityLeaseAsync(
                CancellationToken.None);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return Cancelled<bool>();
        }
        catch (IOException)
        {
            return PayloadCustodyFailed<bool>();
        }
        catch (UnauthorizedAccessException)
        {
            return PayloadCustodyFailed<bool>();
        }
        finally
        {
            _recordsMutationContext.Gate.Release();
        }
    }

    private static OperationResult<DesignConversionCandidatePayloadCustodyCommitment>
        TryReadCandidatePayloadCustodyCommitment(
            DesignConversionLocalArtifactDbRecord record,
            IReadOnlyList<string>? knownBindings = null)
    {
        var bindings = knownBindings?.Order(StringComparer.Ordinal).ToArray() ??
            (record.DpoCandidates ?? [])
                .Select(static candidate => candidate.TrainingRecord)
                .Where(RequiresPayloadCustody)
                .Select(trainingRecord => ReadMetadata(
                    trainingRecord.Provenance.Metadata,
                    DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey))
                .Order(StringComparer.Ordinal)
                .ToArray();
        if (bindings.Length == 0 || bindings.Distinct(StringComparer.Ordinal).Count() != bindings.Length ||
            !int.TryParse(
                ReadMetadata(record.Metadata,
                    DesignConversionCandidatePayloadCustodyStore.EntryCountMetadataKey),
                NumberStyles.None,
                CultureInfo.InvariantCulture,
                out var entryCount) ||
            entryCount != bindings.Length)
        {
            return PayloadCustodyFailed<DesignConversionCandidatePayloadCustodyCommitment>();
        }

        return OperationResult<DesignConversionCandidatePayloadCustodyCommitment>.Ok(
            new DesignConversionCandidatePayloadCustodyCommitment(
                ReadMetadata(record.Metadata,
                    DesignConversionCandidatePayloadCustodyStore.TransactionMetadataKey),
                ReadMetadata(record.Metadata,
                    DesignConversionCandidatePayloadCustodyStore.ManifestMetadataKey),
                ReadMetadata(record.Metadata,
                    DesignConversionCandidatePayloadCustodyStore.BindingSetMetadataKey),
                record.RecordId,
                ReadMetadata(record.Metadata, ImmutableAppendFingerprintMetadataKey),
                bindings));
    }

    private Task<OperationResult<DesignConversionLocalArtifactDbRecord>>
        MaterializeCandidatePayloadCustodyForAuthorityRewriteAsync(
            DesignConversionLocalArtifactDbRecord record)
    {
        var candidates = new List<DesignConversionLocalArtifactDbDpoCandidate>();
        foreach (var candidate in record.DpoCandidates ?? [])
        {
            var trainingRecord = candidate.TrainingRecord;
            if (!RequiresPayloadCustody(trainingRecord))
            {
                candidates.Add(candidate);
                continue;
            }

            var materialized = MaterializeCandidatePayloadCustodyFromCommitted(
                record,
                trainingRecord);
            if (!materialized.IsSuccess)
            {
                return Task.FromResult(
                    materialized.MapError<DesignConversionLocalArtifactDbRecord>());
            }

            candidates.Add(candidate with { TrainingRecord = materialized.Value! });
        }

        return Task.FromResult(
            OperationResult<DesignConversionLocalArtifactDbRecord>.Ok(
                record with { DpoCandidates = candidates.ToArray() }));
    }

    private OperationResult<DesignConversionDpoTrainingRecord>
        MaterializeCandidatePayloadCustodyFromCommitted(
            DesignConversionLocalArtifactDbRecord localRecord,
            DesignConversionDpoTrainingRecord trainingRecord)
    {
        if (!RequiresPayloadCustody(trainingRecord))
            return OperationResult<DesignConversionDpoTrainingRecord>.Ok(
                trainingRecord);

        if (trainingRecord.PayloadCustodySecret is not null)
        {
            var validation = ValidateAndMaterializePayloadCustody(trainingRecord);
            if (!validation.IsSuccess)
                return validation.MapError<DesignConversionDpoTrainingRecord>();

            return OperationResult<DesignConversionDpoTrainingRecord>.Ok(
                validation.Value!);
        }

        var bindingSha256 = ReadMetadata(
            trainingRecord.Provenance.Metadata,
            DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey);
        var commitment = TryReadCandidatePayloadCustodyCommitment(localRecord);
        if (!commitment.IsSuccess)
            return commitment.MapError<DesignConversionDpoTrainingRecord>();

        var evidence =
            _candidatePayloadCustodyStore.ResolveCommitted(commitment.Value!);
        if (!evidence.IsSuccess)
            return evidence.MapError<DesignConversionDpoTrainingRecord>();

        var secretEnvelope =
            _candidatePayloadCustodyStore.ResolveSecretEnvelope(
                evidence.Value!);
        if (!secretEnvelope.IsSuccess)
            return secretEnvelope.MapError<DesignConversionDpoTrainingRecord>();

        var entry = DesignConversionCandidatePayloadCustodyStore.FindExactEntry(
            secretEnvelope.Value!,
            evidence.Value!,
            bindingSha256);
        if (entry is null || !string.Equals(
                entry.TrainingRecordId,
                trainingRecord.RecordId,
                StringComparison.Ordinal))
        {
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();
        }

        var recordWithSecret = trainingRecord with
        {
            PayloadCustodySecret = entry.Secret
        };
        var committedValidation =
            ValidateAndMaterializePayloadCustody(recordWithSecret);
        if (!committedValidation.IsSuccess)
            return committedValidation.MapError<DesignConversionDpoTrainingRecord>();

        return OperationResult<DesignConversionDpoTrainingRecord>.Ok(
            committedValidation.Value!);
    }

    private static OperationResult<bool> ValidateCandidatePayloadsBeforeNormalization(
        DesignConversionLocalArtifactDbRecord record)
    {
        foreach (var candidate in record.DpoCandidates ?? [])
        {
            var trainingRecord = candidate.TrainingRecord;
            if (!RequiresPayloadCustody(trainingRecord))
            {
                if (trainingRecord.PayloadCustodySecret is not null)
                    return PayloadCustodyFailed<bool>();
                continue;
            }

            var validation = ValidateAndMaterializePayloadCustody(trainingRecord);
            if (!validation.IsSuccess)
                return validation.MapError<bool>();
        }

        return OperationResult<bool>.Ok(true);
    }

    private static OperationResult<DesignConversionLocalArtifactDbRecord>
        RebindNormalizedCandidatePayloadCustody(
            DesignConversionLocalArtifactDbRecord record,
            string? immutableAppendFingerprintOverride = null)
    {
        var candidates = new List<DesignConversionLocalArtifactDbDpoCandidate>();
        foreach (var candidate in record.DpoCandidates ?? [])
        {
            var trainingRecord = candidate.TrainingRecord;
            if (!RequiresPayloadCustody(trainingRecord))
            {
                if (trainingRecord.PayloadCustodySecret is not null)
                    return PayloadCustodyFailed<DesignConversionLocalArtifactDbRecord>();
                candidates.Add(candidate);
                continue;
            }

            var payload = trainingRecord.PayloadCustodySecret;
            if (payload is null)
                return PayloadCustodyFailed<DesignConversionLocalArtifactDbRecord>();

            var governanceSha256 =
                DesignConversionDpoGenerator.BuildPayloadCustodyGovernanceSha256(
                    trainingRecord);
            var bindingSha256 = DesignConversionDpoGenerator.BuildPayloadCustodyBinding(
                trainingRecord,
                payload.PromptSha256,
                payload.ChosenResponseSha256,
                payload.RejectedResponseSha256,
                governanceSha256);
            var metadata = new Dictionary<string, string>(
                trainingRecord.Provenance.Metadata,
                StringComparer.Ordinal)
            {
                [DesignConversionDpoGenerator.PayloadCustodyGovernanceSha256MetadataKey] =
                    governanceSha256,
                [DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey] =
                    bindingSha256
            };
            var reboundPayload = payload.Rebind(
                governanceSha256,
                bindingSha256);
            var reboundTrainingRecord = trainingRecord with
            {
                Provenance = trainingRecord.Provenance with { Metadata = metadata },
                PayloadCustodySecret = reboundPayload
            };
            var validation = ValidateAndMaterializePayloadCustody(reboundTrainingRecord);
            if (!validation.IsSuccess)
                return validation.MapError<DesignConversionLocalArtifactDbRecord>();

            candidates.Add(candidate with { TrainingRecord = reboundTrainingRecord });
        }

        var reboundRecord = record with { DpoCandidates = candidates.ToArray() };
        var recordMetadata = new Dictionary<string, string>(
            reboundRecord.Metadata,
            StringComparer.Ordinal)
        {
            [ImmutableAppendFingerprintMetadataKey] =
                immutableAppendFingerprintOverride ??
                BuildImmutableAppendFingerprint(reboundRecord)
        };
        return OperationResult<DesignConversionLocalArtifactDbRecord>.Ok(
            reboundRecord with { Metadata = recordMetadata });
    }

    private static DesignConversionLocalArtifactDbRecord ClearCandidatePayloadCustody(
        DesignConversionLocalArtifactDbRecord record)
        => record with
        {
            DpoCandidates = (record.DpoCandidates ?? [])
                .Select(candidate => candidate with
                {
                    TrainingRecord = candidate.TrainingRecord with
                    {
                        PayloadCustodySecret = null
                    }
                })
                .ToArray()
        };

    private static bool RequiresPayloadCustody(
        DesignConversionDpoTrainingRecord record)
        => IsTruthy(ReadMetadata(
            record.Provenance.Metadata,
            DesignConversionDpoGenerator.PayloadCustodyRequiredMetadataKey));

    private static bool IsReviewPendingTeacherPayloadCustodyPersistable(
        DesignConversionDpoTrainingRecord record)
    {
        if (!IsTeacherPayloadCustodyBaseAllowed(record))
            return false;

        var metadata = record.Provenance.Metadata;
        if (!IsTruthy(ReadMetadata(metadata, "runtime_created_dpo_candidate")) ||
            !IsTruthy(ReadMetadata(metadata, "runtime_teacher_authored_candidate")) ||
            !string.Equals(
                ReadMetadata(metadata, "approval_status"),
                "pending",
                StringComparison.OrdinalIgnoreCase) ||
            !string.Equals(
                ReadMetadata(metadata, "review_status"),
                RuntimeCandidateReviewPendingStatus,
                StringComparison.Ordinal) ||
            IsTruthy(ReadMetadata(metadata, "approved_for_training")))
        {
            return false;
        }

        return DesignConversionTrainingMeasurementGatePolicy
            .GetRecordBlockReasons(record)
            .All(IsAllowedReviewPendingPayloadCustodyBlockReason);
    }

    private static bool IsTeacherPayloadCustodyMaterializable(
        DesignConversionDpoTrainingRecord record)
        => IsReviewPendingTeacherPayloadCustodyPersistable(record) ||
           IsApprovedTeacherPayloadCustodyMaterializable(record);

    private static bool IsApprovedTeacherPayloadCustodyMaterializable(
        DesignConversionDpoTrainingRecord record)
    {
        if (!IsTeacherPayloadCustodyBaseAllowed(record))
            return false;

        var metadata = record.Provenance.Metadata;
        if (!IsTruthy(ReadMetadata(metadata, "runtime_created_dpo_candidate")) ||
            !IsTruthy(ReadMetadata(metadata, "runtime_teacher_authored_candidate")) ||
            !string.Equals(
                ReadMetadata(metadata, "approval_status"),
                "approved",
                StringComparison.OrdinalIgnoreCase) ||
            !string.Equals(
                ReadMetadata(metadata, "review_status"),
                RuntimeCandidateReviewApprovedStatus,
                StringComparison.Ordinal) ||
            !IsTruthy(ReadMetadata(metadata, "approved_for_training")) ||
            string.IsNullOrWhiteSpace(ReadMetadata(metadata, "approved_by_ref")) ||
            string.IsNullOrWhiteSpace(ReadMetadata(metadata, "approval_reason")) ||
            string.IsNullOrWhiteSpace(ReadMetadata(metadata, "approved_at_utc")))
        {
            return false;
        }

        var blockReasons = DesignConversionTrainingMeasurementGatePolicy
            .GetRecordBlockReasons(record);
        return blockReasons.Count == 0 ||
               blockReasons.All(IsAllowedApprovedTeacherPayloadCustodyBlockReason);
    }

    private static bool IsTeacherPayloadCustodyBaseAllowed(
        DesignConversionDpoTrainingRecord record)
        => record is not null &&
           record.License.AllowsTraining &&
           !record.License.ContainsUserPrivateData &&
           !record.Quarantine.IsQuarantined;

    private static bool IsAllowedReviewPendingPayloadCustodyBlockReason(
        string reason)
        => string.Equals(
               reason,
               "approval_missing",
               StringComparison.Ordinal) ||
           string.Equals(
               reason,
               "not_training_grade",
               StringComparison.Ordinal) ||
           string.Equals(
               reason,
               "provider_missing",
               StringComparison.Ordinal);

    private static bool IsAllowedApprovedTeacherPayloadCustodyBlockReason(
        string reason)
        => string.Equals(
            reason,
            "not_training_grade",
            StringComparison.Ordinal);

    private static bool IsLegacyTeacherHashRefOnlyRecord(
        DesignConversionDpoTrainingRecord record)
        => IsTruthy(ReadMetadata(
               record.Provenance.Metadata,
               "runtime_teacher_authored_candidate"))
           && !RequiresPayloadCustody(record);

    internal static OperationResult<DesignConversionDpoTrainingRecord>
        ValidateAndMaterializePayloadCustody(
            DesignConversionDpoTrainingRecord record)
    {
        var payload = record.PayloadCustodySecret;
        if (payload is null)
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!IsTeacherPayloadCustodyMaterializable(record))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!string.Equals(
                payload.Version,
                DesignConversionDpoGenerator.PayloadCustodyVersion,
                StringComparison.Ordinal))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!HasPayloadCustodyMetadata(record, payload))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!string.Equals(
                payload.PromptSha256,
                DesignConversionDpoGenerator.Sha256Ref(payload.Prompt),
                StringComparison.Ordinal))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!string.Equals(
                payload.ChosenResponseSha256,
                DesignConversionDpoGenerator.Sha256Ref(payload.ChosenResponse),
                StringComparison.Ordinal))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!string.Equals(
                payload.RejectedResponseSha256,
                DesignConversionDpoGenerator.Sha256Ref(payload.RejectedResponse),
                StringComparison.Ordinal))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!IsExactCandidatePayloadScalarAllowed(payload.Prompt))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!IsExactCandidatePayloadScalarAllowed(payload.ChosenResponse))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!IsExactCandidatePayloadScalarAllowed(payload.RejectedResponse))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!string.Equals(
                payload.GovernanceSha256,
                DesignConversionDpoGenerator.BuildPayloadCustodyGovernanceSha256(record),
                StringComparison.Ordinal))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!string.Equals(
                payload.TrainingRecordBindingSha256,
                DesignConversionDpoGenerator.BuildPayloadCustodyBinding(
                    record,
                    payload.PromptSha256,
                    payload.ChosenResponseSha256,
                    payload.RejectedResponseSha256,
                    payload.GovernanceSha256),
                StringComparison.Ordinal))
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();

        if (!TryMaterializePreferenceResponse(
                payload.ChosenResponse,
                record.Chosen,
                out var chosen) ||
            !TryMaterializePreferenceResponse(
                payload.RejectedResponse,
                record.Rejected,
                out var rejected))
        {
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();
        }

        var materialized = record with
        {
            Chosen = chosen!,
            Rejected = rejected!,
            PayloadCustodySecret = payload
        };
        var canonical = DesignConversionTrainingPipeline.ToCanonicalTrainingItem(
            materialized);
        if (!string.Equals(canonical.Prompt, payload.Prompt, StringComparison.Ordinal) ||
            !string.Equals(
                canonical.ChosenResponse,
                payload.ChosenResponse,
                StringComparison.Ordinal) ||
            !string.Equals(
                canonical.RejectedResponse,
                payload.RejectedResponse,
                StringComparison.Ordinal))
        {
            return PayloadCustodyFailed<DesignConversionDpoTrainingRecord>();
        }

        return OperationResult<DesignConversionDpoTrainingRecord>.Ok(materialized);
    }

    private static bool IsExactCandidatePayloadScalarAllowed(string value)
    {
        try
        {
            if (StrictUtf8Encoding.GetByteCount(value ?? string.Empty) > 4 * 1024 * 1024)
                return false;
        }
        catch (EncoderFallbackException)
        {
            return false;
        }

        var redactions = new SortedSet<string>(StringComparer.Ordinal);
        var sanitized = DesignConversionDpoLeakageGuard.SanitizeScalar(
            value,
            "candidate_payload_custody",
            redactions);
        return redactions.Count == 0 && string.Equals(sanitized, value, StringComparison.Ordinal);
    }

    private static bool HasPayloadCustodyMetadata(
        DesignConversionDpoTrainingRecord record,
        DesignConversionDpoPayloadCustodySecret payload)
    {
        var metadata = record.Provenance.Metadata;
        return RequiresPayloadCustody(record)
               && string.Equals(
                   ReadMetadata(metadata, DesignConversionDpoGenerator.PayloadCustodyVersionMetadataKey),
                   payload.Version,
                   StringComparison.Ordinal)
               && string.Equals(
                   ReadMetadata(metadata, DesignConversionDpoGenerator.PayloadCustodyPromptSha256MetadataKey),
                   payload.PromptSha256,
                   StringComparison.Ordinal)
               && string.Equals(
                   ReadMetadata(metadata, DesignConversionDpoGenerator.PayloadCustodyChosenSha256MetadataKey),
                   payload.ChosenResponseSha256,
                   StringComparison.Ordinal)
               && string.Equals(
                   ReadMetadata(metadata, DesignConversionDpoGenerator.PayloadCustodyRejectedSha256MetadataKey),
                   payload.RejectedResponseSha256,
                   StringComparison.Ordinal)
               && string.Equals(
                   ReadMetadata(metadata, DesignConversionDpoGenerator.PayloadCustodyGovernanceSha256MetadataKey),
                   payload.GovernanceSha256,
                   StringComparison.Ordinal)
               && string.Equals(
                   ReadMetadata(metadata, DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey),
                   payload.TrainingRecordBindingSha256,
                   StringComparison.Ordinal);
    }

    private static bool TryMaterializePreferenceResponse(
        string json,
        DesignConversionImprovementOutput visible,
        out DesignConversionImprovementOutput? materialized)
    {
        materialized = null;
        try
        {
            using var document = JsonDocument.Parse(json);
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object ||
                root.EnumerateObject().Count() != 2 ||
                !root.TryGetProperty("html", out var htmlElement) ||
                !root.TryGetProperty("css", out var cssElement) ||
                htmlElement.ValueKind != JsonValueKind.String ||
                cssElement.ValueKind != JsonValueKind.String)
            {
                return false;
            }

            materialized = visible with
            {
                Html = htmlElement.GetString() ?? string.Empty,
                Css = cssElement.GetString() ?? string.Empty
            };
            return !string.IsNullOrWhiteSpace(materialized.Html) ||
                   !string.IsNullOrWhiteSpace(materialized.Css);
        }
        catch (JsonException)
        {
            return false;
        }
    }

    private static OperationResult<T> PayloadCustodyFailed<T>()
        => OperationResult<T>.Fail(
            "DesignConversion teacher-authored payload custody verification failed.",
            "DESIGN_CONVERSION_DPO_PAYLOAD_CUSTODY_FAILED");

    private OperationResult<bool> PersistFinalTrainingIntakeDpoPairsBeforeRunner(
        IReadOnlyList<DpoPair> pairs,
        CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<bool>();
        if (pairs is null)
        {
            return OperationResult<bool>.Fail(
                "DesignConversion training-intake DPO records are required before pair-store persistence.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_DPO_PAIR_RECORDS_REQUIRED");
        }

        foreach (var pair in pairs)
        {
            if (ct.IsCancellationRequested)
                return Cancelled<bool>();

            if (pair is null)
            {
                return OperationResult<bool>.Fail(
                    "DesignConversion training-intake DPO pair is invalid.",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_DPO_PAIR_NOT_TRAINABLE");
            }
            var stored = _trainingIntakeDpoPairStore.Add(pair);
            if (!stored.IsSuccess)
                return stored.MapError<bool>();
        }

        return OperationResult<bool>.Ok(true);
    }

    private sealed record ProjectedDualTargetTeacherExternalConsumption(
        DesignConversionDpoTrainingContentAuthority
            .DualTargetTeacherAggregateCommitment Commitment,
        DpoPairAtomicGroupEnvelope Group,
        DpoPairAtomicGroupReceipt Receipt,
        DesignConversionExpectedExternalGroupIdentity ExpectedGroup);

    private sealed record PreparedDualTargetTeacherExternalConsumption(
        ProjectedDualTargetTeacherExternalConsumption Projection,
        FileDpoPairStore.ExternalConsumptionTransactionHandle Transaction)
    {
        internal DesignConversionDpoTrainingContentAuthority
            .DualTargetTeacherAggregateCommitment Commitment =>
            Projection.Commitment;
        internal DpoPairAtomicGroupEnvelope Group => Projection.Group;
        internal DpoPairAtomicGroupReceipt Receipt => Projection.Receipt;
        internal DesignConversionExpectedExternalGroupIdentity ExpectedGroup =>
            Projection.ExpectedGroup;
    }

    private OperationResult<ProjectedDualTargetTeacherExternalConsumption?>
        ProjectDualTargetTeacherExternalConsumption(
            DesignConversionPreparedTrainingRecordExecution prepared,
            CancellationToken ct)
    {
        if (ct.IsCancellationRequested)
            return Cancelled<ProjectedDualTargetTeacherExternalConsumption?>();

        var trainRecords = prepared.Pipeline.Batches
            .SelectMany(static batch => batch.Records)
            .ToArray();
        var firstRequestId = trainRecords.FirstOrDefault()?
            .TeacherProvenance?.RequestId;
        var isDualTargetTeacherCandidate = trainRecords.Length == 2 &&
            !string.IsNullOrWhiteSpace(firstRequestId) &&
            trainRecords.All(record => string.Equals(
                record.TeacherProvenance?.RequestId,
                firstRequestId,
                StringComparison.Ordinal));
        if (!isDualTargetTeacherCandidate)
        {
            return OperationResult<
                ProjectedDualTargetTeacherExternalConsumption?>.Ok(null);
        }

        var aggregate = DesignConversionDpoTrainingContentAuthority
            .ProjectDualTargetTeacherAggregate(
                prepared.Build.AllRecords,
                prepared.Pipeline.Batches,
                prepared.Pipeline.FinalOptimizer);
        if (!aggregate.IsSuccess || aggregate.Value is null)
        {
            return aggregate.MapError<
                ProjectedDualTargetTeacherExternalConsumption?>();
        }

        var group = aggregate.Value.ProjectExternalAtomicGroup();
        if (!group.IsSuccess || group.Value is null)
        {
            return group.MapError<
                ProjectedDualTargetTeacherExternalConsumption?>();
        }

        var expectedGroup =
            DesignConversionExpectedExternalGroupIdentity.Create(group.Value);
        if (!expectedGroup.IsSuccess || expectedGroup.Value is null)
        {
            return expectedGroup.MapError<
                ProjectedDualTargetTeacherExternalConsumption?>();
        }

        return OperationResult<
            ProjectedDualTargetTeacherExternalConsumption?>.Ok(
                new ProjectedDualTargetTeacherExternalConsumption(
                    aggregate.Value,
                    group.Value,
                    new DpoPairAtomicGroupReceipt(
                        group.Value.GroupCommitmentSha256,
                        group.Value.RequestId,
                        Array.AsReadOnly(expectedGroup.Value
                            .OrderedPairIds.ToArray())),
                    expectedGroup.Value));
    }

    private OperationResult<PreparedDualTargetTeacherExternalConsumption?>
        PrepareDualTargetTeacherExternalConsumptionBeforeRunner(
            DesignConversionPreparedTrainingRecordExecution prepared,
            CancellationToken ct)
    {
        var projected = ProjectDualTargetTeacherExternalConsumption(
            prepared,
            ct);
        if (!projected.IsSuccess)
            return projected.MapError<PreparedDualTargetTeacherExternalConsumption?>();
        if (projected.Value is not { } projectedExternal)
        {
            return OperationResult<
                PreparedDualTargetTeacherExternalConsumption?>.Ok(null);
        }

        if (_trainingIntakeDpoPairStore is not
            IDpoPairExternalConsumptionTransactionCoordinator coordinator)
        {
            return OperationResult<
                PreparedDualTargetTeacherExternalConsumption?>.Fail(
                    "External atomic DPO pair-group consumption is unavailable.",
                    "DPO_PAIR_EXTERNAL_CONSUMPTION_UNAVAILABLE");
        }

        if (ct.IsCancellationRequested)
            return Cancelled<PreparedDualTargetTeacherExternalConsumption?>();
        var receipt = _trainingIntakeDpoPairStore.AddAtomicGroup(
            projectedExternal.Group);
        if (!receipt.IsSuccess || receipt.Value is null)
        {
            return receipt.MapError<
                PreparedDualTargetTeacherExternalConsumption?>();
        }
        if (!MatchesStoredDualTargetTeacherAtomicGroup(
                projectedExternal.Group,
                receipt.Value))
        {
            return OperationResult<
                PreparedDualTargetTeacherExternalConsumption?>.Fail(
                    "The stored DesignConversion DPO group identity is invalid.",
                    LegalTrainingTeacherAdmissionAuthority
                        .TrainingContentInvalidErrorCode);
        }

        if (ct.IsCancellationRequested)
            return Cancelled<PreparedDualTargetTeacherExternalConsumption?>();
        var committedProjection = projectedExternal with
        {
            Receipt = receipt.Value
        };
        var transaction = coordinator.PrepareExternalConsumptionTransaction(
            receipt.Value,
            DesignConversionMachine.DomainTag);
        if (!transaction.IsSuccess || transaction.Value is null)
        {
            return transaction.MapError<
                PreparedDualTargetTeacherExternalConsumption?>();
        }
        var transactionSnapshot = transaction.Value.Read();
        if (!transactionSnapshot.IsSuccess || transactionSnapshot.Value is null)
        {
            return transactionSnapshot.MapError<
                PreparedDualTargetTeacherExternalConsumption?>();
        }
        if (transactionSnapshot.Value.State !=
                FileDpoPairStore.DpoExternalConsumptionState.Reserved &&
            transactionSnapshot.Value.State !=
                FileDpoPairStore.DpoExternalConsumptionState.AggregateBound)
        {
            // В исполнитель можно передавать только новую или ещё не начатую
            // привязку группы. Готовая либо оборванная транзакция должна
            // остановиться здесь: проверки привязки группы и начала изменения
            // данных (Bind/Begin) ниже всё равно остаются последней защитой от
            // гонок прямо перед изменением данных.
            return OperationResult<
                PreparedDualTargetTeacherExternalConsumption?>.Fail(
                    "External atomic DPO pair-group consumption requires recovery before runner invocation.",
                    "DPO_TRANSACTION_RECOVERY_REQUIRED");
        }
        if (!committedProjection.ExpectedGroup.Matches(
                transactionSnapshot.Value,
                allowReserved: true,
                allowAggregateBound: true))
        {
            return OperationResult<
                PreparedDualTargetTeacherExternalConsumption?>.Fail(
                    "The prepared DesignConversion DPO group identity is invalid.",
                    LegalTrainingTeacherAdmissionAuthority
                        .TrainingContentInvalidErrorCode);
        }

        return OperationResult<
            PreparedDualTargetTeacherExternalConsumption?>.Ok(
                new PreparedDualTargetTeacherExternalConsumption(
                    committedProjection,
                    transaction.Value));
    }

    private static bool MatchesStoredDualTargetTeacherAtomicGroup(
        DpoPairAtomicGroupEnvelope group,
        DpoPairAtomicGroupReceipt receipt)
        => string.Equals(
               receipt.GroupCommitmentSha256,
               group.GroupCommitmentSha256,
               StringComparison.Ordinal) &&
           string.Equals(
               receipt.RequestId,
               group.RequestId,
               StringComparison.Ordinal) &&
           receipt.OrderedPairIds.SequenceEqual(
               group.Children.Select(static child => child.PairId),
               StringComparer.Ordinal);

    private static OperationResult<bool>
        ValidateCommittedDualTargetTeacherExternalConsumption(
        PreparedDualTargetTeacherExternalConsumption prepared,
        DesignConversionExternalConsumptionCommitEvidence committed)
    {
        var durable = prepared.Transaction.Read();
        if (!durable.IsSuccess || durable.Value is null)
            return durable.MapError<bool>();
        if (!string.Equals(
                committed.TransactionId,
                prepared.Transaction.TransactionId,
                StringComparison.Ordinal))
        {
            return OperationResult<bool>.Ok(false);
        }

        return ValidateCommittedDualTargetTeacherExternalConsumption(
            prepared.Projection,
            durable.Value,
            committed);
    }

    private static OperationResult<bool>
        ValidateCommittedDualTargetTeacherExternalConsumption(
            ProjectedDualTargetTeacherExternalConsumption projected,
            FileDpoPairStore.ExternalConsumptionSnapshot snapshot,
            DesignConversionExternalConsumptionCommitEvidence committed)
    {
        var matches = MatchesStoredDualTargetTeacherAtomicGroup(
                projected.Group,
                projected.Receipt) &&
            snapshot.State ==
                FileDpoPairStore.DpoExternalConsumptionState.Committed &&
            snapshot.ConsumerKind == DpoExternalConsumerKind
                .DesignConversionDualTargetTeacherAggregate &&
            string.Equals(
                snapshot.Domain,
                DesignConversionMachine.DomainTag,
                StringComparison.Ordinal) &&
            string.Equals(
               committed.GroupCommitmentSha256,
               projected.Group.GroupCommitmentSha256,
               StringComparison.Ordinal) &&
            string.Equals(
               committed.RequestId,
               projected.Group.RequestId,
               StringComparison.Ordinal) &&
            string.Equals(
               committed.ParentBatchSha256,
               projected.Commitment.ParentContent.Sha256,
               StringComparison.Ordinal) &&
            string.Equals(
               committed.ParentContentSha256,
               projected.Commitment.ParentContent.Rows.Single().Sha256,
               StringComparison.Ordinal) &&
            string.Equals(
               committed.RequestId,
               projected.Commitment.ParentProvenance.RequestId,
               StringComparison.Ordinal) &&
            committed.OrderedPairIds.SequenceEqual(
               projected.ExpectedGroup.OrderedPairIds,
               StringComparer.Ordinal) &&
            committed.OrderedContentSha256s.SequenceEqual(
               projected.ExpectedGroup.OrderedContentSha256s,
                StringComparer.Ordinal) &&
            string.Equals(snapshot.TransactionId, committed.TransactionId,
                StringComparison.Ordinal) &&
            string.Equals(snapshot.GroupCommitmentSha256,
                committed.GroupCommitmentSha256, StringComparison.Ordinal) &&
            string.Equals(snapshot.RequestId, committed.RequestId,
                StringComparison.Ordinal) &&
            string.Equals(snapshot.ParentBatchSha256,
                committed.ParentBatchSha256, StringComparison.Ordinal) &&
            string.Equals(snapshot.ParentContentSha256,
                committed.ParentContentSha256, StringComparison.Ordinal) &&
            string.Equals(snapshot.ParentProvenanceSha256,
                committed.ParentProvenanceSha256, StringComparison.Ordinal) &&
            snapshot.OrderedPairIds.SequenceEqual(
                committed.OrderedPairIds, StringComparer.Ordinal) &&
            snapshot.OrderedContentSha256s.SequenceEqual(
                committed.OrderedContentSha256s, StringComparer.Ordinal) &&
            string.Equals(snapshot.ResultSha256, committed.ResultSha256,
                StringComparison.Ordinal) &&
            string.Equals(snapshot.CheckpointSha256,
                committed.CheckpointSha256, StringComparison.Ordinal) &&
            string.Equals(snapshot.ManifestSha256, committed.ManifestSha256,
                StringComparison.Ordinal);
        return OperationResult<bool>.Ok(matches);
    }

    private static OperationResult<DesignConversionExternalConsumptionCommitEvidence>
        MaterializeCommittedExternalConsumptionEvidence(
            FileDpoPairStore.ExternalConsumptionSnapshot snapshot)
    {
        if (snapshot is null ||
            snapshot.State !=
                FileDpoPairStore.DpoExternalConsumptionState.Committed ||
            snapshot.ConsumerKind != DpoExternalConsumerKind
                .DesignConversionDualTargetTeacherAggregate ||
            !string.Equals(
                snapshot.Domain,
                DesignConversionMachine.DomainTag,
                StringComparison.Ordinal) ||
            !TrainingSourceProvenance.IsCanonicalSha256(
                snapshot.TransactionId) ||
            !TrainingSourceProvenance.IsCanonicalSha256(
                snapshot.GroupCommitmentSha256) ||
            string.IsNullOrWhiteSpace(snapshot.RequestId) ||
            !TrainingSourceProvenance.IsCanonicalSha256(
                snapshot.ParentBatchSha256) ||
            !TrainingSourceProvenance.IsCanonicalSha256(
                snapshot.ParentContentSha256) ||
            !TrainingSourceProvenance.IsCanonicalSha256(
                snapshot.ParentProvenanceSha256) ||
            !TrainingSourceProvenance.IsCanonicalSha256(
                snapshot.ResultSha256) ||
            !TrainingSourceProvenance.IsCanonicalSha256(
                snapshot.CheckpointSha256) ||
            !TrainingSourceProvenance.IsCanonicalSha256(
                snapshot.ManifestSha256) ||
            snapshot.OrderedPairIds is not { Count: 2 } ||
            snapshot.OrderedContentSha256s is not { Count: 2 } ||
            snapshot.OrderedPairIds.Any(static value =>
                !TrainingSourceProvenance.IsCanonicalSha256(value)) ||
            snapshot.OrderedContentSha256s.Any(static value =>
                !TrainingSourceProvenance.IsCanonicalSha256(value)))
        {
            return OperationResult<DesignConversionExternalConsumptionCommitEvidence>
                .Fail(
                    "The committed external DesignConversion DPO group identity is invalid.",
                    LegalTrainingTeacherAdmissionAuthority
                        .TrainingContentInvalidErrorCode);
        }

        return OperationResult<DesignConversionExternalConsumptionCommitEvidence>
            .Ok(new DesignConversionExternalConsumptionCommitEvidence(
                snapshot.TransactionId,
                snapshot.GroupCommitmentSha256,
                snapshot.RequestId,
                snapshot.ParentBatchSha256,
                snapshot.ParentContentSha256,
                snapshot.ParentProvenanceSha256,
                Array.AsReadOnly(snapshot.OrderedPairIds.ToArray()),
                Array.AsReadOnly(snapshot.OrderedContentSha256s.ToArray()),
                snapshot.ResultSha256,
                snapshot.CheckpointSha256,
                snapshot.ManifestSha256));
    }

    private static DesignConversionTrainingIntakeRunResult
        MarkCommittedDualTargetTeacherExternalConsumption(
            DesignConversionTrainingIntakeRunResult trainingRun,
            ProjectedDualTargetTeacherExternalConsumption projected,
            DesignConversionExternalConsumptionCommitEvidence committed)
    {
        var inheritedMetadata = new Dictionary<string, string>(
            trainingRun.BoundaryMetadata,
