    private static bool CachedRunReplayMetadataMatches(
        IReadOnlyDictionary<string, string>? metadata,
        string key,
        string expected)
    {
        var actual = ReadMetadata(metadata, key);
        return string.IsNullOrWhiteSpace(actual) ||
               string.Equals(actual, expected, StringComparison.Ordinal);
    }

    private static bool CachedRunReplayMetadataExactlyMatches(
        IReadOnlyDictionary<string, string>? metadata,
        string key,
        string expected)
    {
        var actual = ReadMetadata(metadata, key);
        return !string.IsNullOrWhiteSpace(actual) &&
               string.Equals(actual, expected, StringComparison.Ordinal);
    }

    private static string BuildTrainingIntakeRunCurrentRecordsSnapshotSha256(
        IReadOnlyList<DesignConversionDpoTrainingRecord> snapshotRecords)
        => DesignConversionDpoGenerator.Sha256Ref(string.Join(
            "|",
            snapshotRecords
                .Select(DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash)
                .Order(StringComparer.Ordinal)));

    private static string BuildTrainingIntakeRunCurrentOptionsSnapshotSha256(
        DesignConversionTrainingPipelineOptions snapshotOptions)
        => DesignConversionDpoGenerator.Sha256Ref(
            JsonSerializer.Serialize(snapshotOptions));

    private static OperationResult<T> LegalTeacherConfigurationRequired<T>()
        => OperationResult<T>.Fail(
            "Server-owned legal teacher admission configuration is required.",
            LegalTrainingTeacherAdmissionAuthority.ConfigurationRequiredErrorCode);

    private static OperationResult<bool> ValidateTrainingIntakePreflightId(string intakeId)
    {
        if (string.IsNullOrWhiteSpace(intakeId))
            return OperationResult<bool>.Fail(
                "DesignConversion training intake preflight requires an intake id.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PREFLIGHT_ID_REQUIRED");
        if (ContainsForbiddenTrainingIntakePayload(intakeId))
            return OperationResult<bool>.Fail(
                "DesignConversion training intake preflight id contains raw or private payload markers.",
                "DESIGN_CONVERSION_TRAINING_INTAKE_PREFLIGHT_ID_UNSANITIZED");
        return OperationResult<bool>.Ok(true);
    }

    private sealed class LocalTrainingLeaseTransferGuard(
        ServerOwnedLegalTrainingTeacherAdmissionLease trainingLease) : IDisposable
    {
        private ServerOwnedLegalTrainingTeacherAdmissionLease? _trainingLease =
            trainingLease;

        internal void TransferOwnership()
            => Interlocked.Exchange(ref _trainingLease, null);

        public void Dispose()
            => Interlocked.Exchange(ref _trainingLease, null)?.Dispose();
    }

    internal static void CompleteContinuationOwnedResult<T>(
        T? callbackProducedValue,
        OperationResult<T>? returnedResult,
        ExceptionDispatchInfo? invocationException)
        where T : class, IDisposable
    {
        ExceptionDispatchInfo? cleanupException = null;
        var adopted = invocationException is null &&
                      returnedResult is { IsSuccess: true } &&
                      ReferenceEquals(
                          returnedResult.Value,
                          callbackProducedValue);
        if (callbackProducedValue is not null && !adopted)
        {
            try
            {
                callbackProducedValue.Dispose();
            }
            catch (Exception exception)
            {
                cleanupException = ExceptionDispatchInfo.Capture(exception);
            }
        }

        invocationException?.Throw();
        cleanupException?.Throw();
    }
}
